    ["01-2"] = {name="杜隆塔尔", nameA="杜隆塔尔 {a:367}／{a:362}", shortA="杜隆塔尔 {a:367} +", tips={{k="取捨", text="做新的背包。收集帆布脚料以及其他提拉加德城堡目标。"}, {k="取捨", text="上交背信弃义的人类来解锁海底沉船。与沃纳尔大师 一起进行。"}, {k="取捨", text="保存暗影裂口地下城链。如果您计划运行怒焰裂谷，请从萨尔中获取隐藏的敌人（ → →）。从北部的火刃氏族营地获取 的徽章。"}, {k="提醒", text="12级以下？执行保卫商路、 骷髅石或下面任务中的前几个威胁。", s={{"12级以下？"}, {"执行保卫商路、 骷髅石或下面任务中的前几个威胁"}}}}, danger={[1]="提拉加德城堡中的楼梯和门口可以将水手从楼上拉下来。首先清理外墙和入口。", [2]="海巨人在北岸的纳迦地区漫步。在拉一只之前清除附近的小怪。如果遇到麻烦，请沿着海岸撤退。"}, grind={[1]={mob="库尔提拉斯水兵", note="提拉加德城堡处有密集的普通小怪。拉到外面以避免大厅里的添加。收集帆布脚料以获得新包。"}, [2]={mob="钢鬃卫兵", note="普通小怪聚集在剃刀岭以西。沿着营地边缘行驶并注意巡逻。与野猪人的进犯配对。"}, [3]={mob="尘风雷巫", note="普通小怪聚集在杜隆塔尔北部。使用盖子将脚轮拉近。做保卫商路或者在奥格瑞玛之前磨到12。"}}, supply={[1]={npc="特莱耶克"}, [2]={npc="旅店老板格罗斯克"}, [3]={npc="沃克"}, [4]={npc="旅店老板格罗斯克"}, [5]={npc="格劳特"}, [6]={npc="多拉斯"}}, steps={[1]={npc="乌克尔", tgt="乌克尔", desc="在从试炼谷到森金村的路上寻找乌克尔。"}, [2]={hint="与森金村的加德林大师谈一谈。"}, [3]={npc="加德林大师", tgt="加德林大师"}, [4]={npc="拉尔·猎齿", tgt="拉尔·猎齿"}, [5]={npc="维尔林·长牙", tgt="维尔林·长牙"}, [6]={npc="沃纳尔大师", tgt="沃纳尔大师"}, [7]={npc="加德林大师", tgt="加德林大师"}, [8]={npc="加德林大师", tgt="加德林大师"}, [9]={npc="加德林大师", tgt="加德林大师"}, [10]={npc="维尔林·长牙", tgt="维尔林·长牙"}, [11]={npc="克萨尔迪", tgt="克萨尔迪"}, [12]={npc="沃纳尔大师", tgt="沃纳尔大师"}, [13]={npc="帕祖拉", tgt="帕祖拉", tag="可选", desc="仅当您可以获得分解材料时才做这个任务。"}, [14]={text="先到剃刀岭报到"}, [15]={hint="在杜隆塔尔南部消灭6只脊影爬行者和6只脊影潜伏者，然后向剃刀岭的加索克报到。"}, [16]={hint="将日记交给剃刀岭附近的布拉克。", tag="可选"}, [17]={npc="布拉克", tgt="布拉克", tag="可选"}, [18]={npc="布拉克", tgt="布拉克", tag="可选"}, [19]={hint="在布拉克的基础营火旁坐下休息，直到获得\"强化休息\"增益。", tag="可选"}, [20]={npc="布拉克", tgt="布拉克", tag="可选"}, [21]={npc="布拉克", tgt="布拉克", tag="可选"}, [22]={npc="布拉克", tgt="布拉克", tag="可选", desc="先学习剥皮。上交处：奥格瑞玛。"}, [23]={hint="和剃刀岭的奥戈尼尔·魂痕谈一谈。"}, [24]={hint="把乌克尔的货物交给剃刀岭的旅店老板格罗斯克。"}, [25]={npc="奥戈尼尔·魂痕", tgt="奥戈尼尔·魂痕"}, [26]={npc="加索克", tgt="加索克"}, [27]={npc="旅店老板格罗斯克", tgt="旅店老板格罗斯克"}, [28]={text="在剃刀岭处，将您的炉石与旅店老板格罗斯克 (51.51, 41.64) 绑定。"}, [29]={npc="加索克", tgt="加索克"}, [30]={npc="奥戈尼尔·魂痕", tgt="奥戈尼尔·魂痕"}, [31]={npc="厨师托尔卡", tgt="厨师托尔卡"}, [3