    ["01-3"] = {name="纳拉其营地", tips={{k="交通", text="来自另一个起始区？前往血蹄村，然后沿着红云台地路向南行驶至纳拉其营地。请参阅上面的交通说明。"}, {k="取捨", text="在一个刺刃峡谷循环上执行力量仪祭、 刺鬃酋长和斗猪。如果您抢劫了地图，请接受 纳拉其营地的危机。"}, {k="提醒", text="6级以下？沿着刺刃峡谷的边缘杀死斗猪或刺背野猪人，然后前往血蹄村。", s={{"6级以下？"}, {"沿着刺刃峡谷的边缘杀死斗猪或刺背野猪人，然后前往血蹄村"}}}}, danger={[1]="野猪人聚集在刺刃峡谷的狭窄坡道上。在拉动刺鬃酋长之前清除它。向红云台地撤退。"}, grind={[1]={mob="平原陆行鸟", note="纳拉其营地的东南井附近有密集的、大部分是中立的普通生物。在开始狩猎期间一次拉一个敌人。"}, [2]={mob="山狮", note="红云台地的南坡上有密集的、大部分是中立的普通生物。一次拉一个敌人以获得继续狩猎所需的毛皮。"}, [3]={mob="刺背斗猪", note="普通小怪聚集在刺背野猪人和刺刃峡谷之间。首先清理边缘。与斗猪和力量仪祭配对。"}}, supply={[1]={npc="布隆克·钢怒"}, [2]={npc="穆恩丹·秋谷"}, [3]={npc="卡文尼·柔风"}}, steps={[1]={npc="纳拉其营地礼品券", npcObj=true, tag="可选、需要游戏内检查", desc="持有试炼谷礼品券才接。右键单击您的比赛的起始券。地图上没有接送。"}, [2]={hint="将纳拉其营地礼品券交给沃恩·星眼。", tag="可选", desc="持有试炼谷礼品券才接。"}, [3]={npc="沃恩·星眼", tgt="沃恩·星眼", tag="可选", desc="持有试炼谷礼品券才接。"}, [4]={npc="格鲁尔·鹰风", tgt="格鲁尔·鹰风"}, [5]={npc="鹰风酋长", tgt="鹰风酋长"}, [6]={hint="纳拉其营地的格鲁尔·鹰风要求你带给他7片平原陆行鸟的羽毛和7块平原陆行鸟肉。"}, [7]={hint="鹰风酋长要求你去纳拉其营地东南方的水井处寻找他的母亲。"}, [8]={npc="鹰风酋长的母亲", tgt="鹰风酋长的母亲"}, [9]={npc="鹰风酋长的母亲", tgt="鹰风酋长的母亲"}, [10]={hint="在井边拿一只水罐。", desc="从鹰风酋长的母亲旁边的井中获取水罐。"}, [11]={npc="格鲁尔·鹰风", tgt="格鲁尔·鹰风"}, [12]={npc="鹰风酋长", tgt="鹰风酋长"}, [13]={npc="格鲁尔·鹰风", tgt="格鲁尔·鹰风"}, [14]={npc="鹰风酋长", tgt="鹰风酋长"}, [15]={npc="卫兵维萨罗·风羽", tgt="卫兵维萨罗·风羽"}, [16]={hint="纳拉其营地的格鲁尔·鹰风要求你带给他10张山狮皮。"}, [17]={hint="找到居住在纳拉其营地正南方山中的灰舌先知。"}, [18]={npc="灰舌先知", tgt="灰舌先知"}, [19]={npc="灰舌先知", tgt="灰舌先知"}, [20]={npc="灰舌先知", tgt="灰舌先知", tag="可选", desc="接香后10分钟内带到东南祭坛。", star={"烧焦的皮革包"}}, [21]={hint="在十分钟内，赶在阴燃熏香化为灰烬之前，将它带到东南方山丘里的安瑟与穆莎的神龛！", tag="可选", desc="接香后10分钟内带到东南祭坛。"}, [22]={npc="仪式火焰", npcObj=true, tag="可选", desc="接香后10分钟内带到东南祭坛。", star={"烧焦的皮革包"}}, [23]={npc="格鲁尔·鹰风", tgt="格鲁尔·鹰风"}, [24]={npc="格鲁尔·鹰风", tgt="格鲁尔·鹰风"}, [25]={hint="杀掉刺刃峡谷的刺背野猪人并带回12条刺背腰带，把它们交给纳拉其营地的鹰风酋长。"}, [26]={hint="把刺鬃酋长的头颅交给红云台地的卫兵维萨罗·风羽。"}, [27]={hint="纳拉其营地的格鲁尔·鹰风要求你去干掉斗猪，并带给他4块斗猪头和4块斗猪肋排。"}, [28]={npc="沾满泥土的地图", npcObj=true, tag="可选", desc="从刺背野猪人中拾取沾满泥土的地图并右键单击它。"}, [29]={npc="鹰风酋长", tgt="鹰