    ["01-4"] = {name="莫高雷", nameA="莫高雷 {a:222}", tips={{k="取捨", text="执行幻象仪祭 ( → →)、智慧仪祭 和雷霆崖之旅 。 最后一站是解锁和飞行点。"}, {k="取捨", text="在接受下一个任务之前，先交出每个井任务。 仅限牛头人。如果您已经达到 12 级，请跳过蛮鬃水井链。仅限牛头人。", s={{"在接受下一个任务之前，先交出每个井任务。 仅限牛头人。如果您已经达到 12 级，请跳过蛮鬃水井链。仅限牛头人。", {race={"Tauren"}}}}}, {k="取捨", text="运行怒焰裂谷吗？从雷霆崖中的拉哈罗拾取试探敌人 和寻找背包 。"}, {k="提醒", text="12 级需要经验吗？在北部莫高雷磨掉鹰身女妖，或者前往赤色石或风险投资公司矿洞。有关 10 级解锁的信息，请参阅下面的职业任务。", s={{"12 级需要经验吗？"}, {"在北部莫高雷磨掉鹰身女妖，或者前往赤色石或风险投资公司矿洞"}, {"有关 10 级解锁的信息，请参阅下面的职业任务"}}}}, danger={[1]="巡逻队和矿工可以在创业公司矿洞内齐心协力。首先清理外面，抓住剪贴板，然后离开隧道。"}, grind={[1]={mob="草原捕食者", note="血蹄村以北分散的普通生物。在草丛中一次拉一个敌人并留意漫游者。拾取马兹拉纳其材料。"}, [2]={mob="风险投资公司主官", note="普通小怪聚集在风险投资公司矿洞周围。从外面拉出来并注意工人和巡逻人员。与矿井任务配对。"}, [3]={mob="风怒女族长", note="莫高雷西北的鹰身女妖营地有密集的普通小怪。沿着边缘拉动以避免脚轮。如果接近12级就在这里磨。"}}, supply={[1]={npc="旅店老板考乌斯"}, [2]={npc="哈兰特·铁枝"}, [3]={npc="旅店老板考乌斯"}, [4]={npc="肯纳·鹰眼"}, [5]={npc="塔尔"}}, steps={[1]={hint="将补给包交给血蹄村附近的卡加·狂野之蹄。", tag="可选"}, [2]={npc="卡加·狂野之蹄", tgt="卡加·狂野之蹄", tag="可选"}, [3]={npc="卡加·狂野之蹄", tgt="卡加·狂野之蹄", tag="可选"}, [4]={hint="在卡加的基础营火旁坐下休息，直到获得\"强化休息\"增益。", tag="可选"}, [5]={npc="卡加·狂野之蹄", tgt="卡加·狂野之蹄", tag="可选"}, [6]={npc="卡加·狂野之蹄", tgt="卡加·狂野之蹄", tag="可选"}, [7]={npc="卡加·狂野之蹄", tgt="卡加·狂野之蹄", tag="可选", desc="接受之前先了解剥皮。一旦满足技能要求就上交。"}, [8]={hint="顺着离开纳拉其营地的路将鹰风图腾带给血蹄村的贝恩·血蹄。"}, [9]={npc="贝恩·血蹄", tgt="贝恩·血蹄"}, [10]={hint="将一捆毛皮带给血蹄村的旅店老板考乌斯。", tag="可选"}, [11]={npc="旅店老板考乌斯", tgt="旅店老板考乌斯", tag="可选"}, [12]={text="将您的炉石与血蹄村 (45.93, 64.16) 中的旅店老板考乌斯绑定。"}, [13]={npc="贝恩·血蹄", tgt="贝恩·血蹄"}, [14]={hint="和血蹄村的扎尔曼·双月谈一谈。"}, [15]={npc="扎尔曼·双月", tgt="扎尔曼·双月"}, [16]={npc="扎尔曼·双月", tgt="扎尔曼·双月"}, [17]={npc="哈肯·风之图腾", tgt="哈肯·风之图腾"}, [18]={npc="茂尔·祈雨", tgt="茂尔·祈雨"}, [19]={npc="贝恩·血蹄", tgt="贝恩·血蹄"}, [20]={npc="卫兵萨拉莫尼·野蹄", tgt="卫兵萨拉莫尼·野蹄"}, [21]={npc="穆尔·雷角", tgt="穆尔·雷角"}, [22]={npc="克朗·石蹄", tgt="克朗·石蹄", tag="可选"}, [23]={hint="为塔恩·石蹄在决斗中击败3名玩家或新手战士。", tag="可选"}, [24]={npc="克朗·石蹄", tgt="克朗·石蹄", tag="可选"}, [25]={npc="阿哈布·麦蹄", tgt="阿哈布·麦蹄", tag="可选"}, [26]={hint="前往血蹄村与派尔·沉默行者交谈，学习烹饪手艺。", tag="可