    ["01-5"] = {name="丧钟镇", tips={{k="交通", text="来自另一个起始区？在布瑞尔以南的齐柏林飞艇塔下车，沿路向西行驶至丧钟镇。请参阅上面的交通说明。"}, {k="提醒", text="从地窖内的 突然醒来 开始（仅限亡灵）。从暗影牧师萨维斯 (30.84, 66.20) 拾取 无脑的僵尸。如果他没有任务，就沿着布瑞尔的路走。", s={{"从地窖内的 突然醒来 开始（仅限亡灵）", {race={"Scourge"}}}, {"从暗影牧师萨维斯 (30.84, 66.20) 拾取 无脑的僵尸"}, {"如果他没有任务，就沿着布瑞尔的路走"}}}, {k="提醒", text="将响尾蛇骷髅杀死至 3 级，然后接受玛拉的遗愿 。前往第 6 级的布瑞尔或完成本部分后。", s={{"将响尾蛇骷髅杀死至 3 级，然后接受玛拉的遗愿"}, {"前往第 6 级的布瑞尔或完成本部分后"}}}}, danger={[1]="夜行蜘蛛洞穴中狭窄的隧道可以从两侧拉动蜘蛛群。进去之前清理入口。"}, grind={[1]={mob="丑陋的僵尸", note="丧钟镇以北密集，大部分为中立普通生物。在无脑的僵尸 1-2 级期间一次拉一个敌人。"}, [2]={mob="夜行蜘蛛", note="夜行蜘蛛洞穴里面有密集的普通小怪。从入口处分阶段清理，以避免额外的拉力。与洞穴任务配对。"}, [3]={mob="血色新兵", note="东部血色营地中密集的普通怪物。沿着边缘清理以避免拉动狂热者。与臂章任务配对。"}}, supply={[1]={npc="铁匠兰德"}, [2]={npc="乔舒·基恩"}, [3]={npc="乔舒·基恩"}}, steps={[1]={npc="管理员摩尔多", tgt="管理员摩尔多"}, [2]={hint="和暗影牧师萨维斯谈一谈。"}, [3]={npc="暗影牧师萨维斯", tgt="暗影牧师萨维斯"}, [4]={npc="暗影牧师萨维斯", tgt="暗影牧师萨维斯"}, [5]={hint="暗影牧师萨维斯让你杀掉8个无脑的僵尸和8个丑陋的僵尸。"}, [6]={npc="暗影牧师萨维斯", tgt="暗影牧师萨维斯"}, [7]={npc="新兵艾尔雷斯", tgt="新兵艾尔雷斯"}, [8]={hint="新兵艾尔雷斯需要6只食腐狼的爪子和6只夜行蝙蝠翼。"}, [9]={npc="新兵艾尔雷斯", tgt="新兵艾尔雷斯"}, [10]={npc="暗影牧师萨维斯", tgt="暗影牧师萨维斯"}, [11]={npc="亡灵卫兵萨尔坦", tgt="亡灵卫兵萨尔坦"}, [12]={npc="执行官阿伦", tgt="执行官阿伦"}, [13]={npc="新兵艾尔雷斯", tgt="新兵艾尔雷斯"}, [14]={npc="阿拉米斯·锤手", tgt="阿拉米斯·锤手"}, [15]={hint="杀掉12个断骨骷髅，然后回到丧钟镇的暗影牧师萨维斯那里。"}, [16]={hint="在丧钟镇及临近地区搜寻6件破烂装备，把它们交给亡灵卫兵萨尔坦。"}, [17]={hint="执行官阿伦要你去杀掉10只小夜行蜘蛛和8只夜行蜘蛛。"}, [18]={hint="将塞缪尔·菲普斯的遗骸带到玛拉的坟墓去，然后回到新兵艾尔雷斯那里。"}, [19]={hint="为丧钟镇的阿拉米斯·锤手解救夜行蜘蛛洞穴中的6名落网的受害者。"}, [20]={npc="暗影牧师萨维斯", tgt="暗影牧师萨维斯"}, [21]={npc="亡灵卫兵萨尔坦", tgt="亡灵卫兵萨尔坦"}, [22]={npc="执行官阿伦", tgt="执行官阿伦"}, [23]={npc="新兵艾尔雷斯", tgt="新兵艾尔雷斯"}, [24]={npc="阿拉米斯·锤手", tgt="阿拉米斯·锤手"}, [25]={npc="执行官阿伦", tgt="执行官阿伦"}, [26]={hint="从血色信徒和血色新兵身上收集12枚血色十字军臂章，把它们交给执行官阿伦。"}, [27]={npc="执行官阿伦", tgt="执行官阿伦"}, [28]={npc="执行官阿伦", tgt="执行官阿伦"}, [29]={hint="到十字军营地去杀掉信使迈文·考加尔，将你发现的情报交给执行官阿伦。"}, [30]={npc="执行官阿伦", tgt="执行官阿伦"}, [31]={npc="执行官阿伦", tgt="执行官阿伦"}, [32]={npc="暗影牧师萨维斯", tgt="暗影牧师萨维斯", desc="先上交无脑的僵尸。替代。拾音器：新兵艾尔雷斯 (30.86, 