    ["01-6"] = {name="提瑞斯法林地", nameA="提瑞斯法林地 {a:159}", tips={{k="提醒", text="如果你还没有接受 重要情报，请从布瑞尔旅店开始，领取第一批任务。", s={{"如果你还没有接受 重要情报，请从布瑞尔旅店开始，领取第一批任务"}}}, {k="取捨", text="在东南环路完成猩红、蜘蛛和坟墓苔藓目标。将北岸鱼人与阿加曼德任务配对。交出附近的任务，前往 12 级的十字路口。"}, {k="取捨", text="从旅馆旁的 死亡之寒 供应商处购买粗线。如果您仍然需要 被遗忘者的皮 的北岸鱼人皮，请在下次海岸之旅时完成它。"}, {k="取捨", text="完成两个本地银色黎明任务即可解锁班达里安堡 （仅限兽人、巨魔和亡灵）。一些后续产品仅是亡灵。如果您直接前往十字路口，请在完成两个本地任务后离开。", s={{"完成两个本地银色黎明任务即可解锁班达里安堡 （仅限兽人、巨魔和亡灵）", {race={"Orc", "Troll", "Scourge"}}}, {"一些后续产品仅是亡灵", {race={"Scourge"}}}, {"如果您直接前往十字路口，请在完成两个本地任务后离开"}}}, {k="提醒", text="12级以下？执行 与血色十字军的战争、 家族墓穴 或银色黎明任务 银色特使、 诅咒神教 和 战争的残迹，具体取决于可用性和您所在的位置。", s={{"12级以下？"}, {"执行 与血色十字军的战争、 家族墓穴 或银色黎明任务 银色特使、 诅咒神教 和 战争的残迹，具体取决于可用性和您所在的位置"}}}}, danger={[1]="留意东南墓地中的僵尸和游荡的灵魂。沿着边缘清理，这样你就不会被困住。"}, grind={[1]={mob="血色传教士", note="布瑞尔西南方向散布普通脚轮。在第一个血色十字军任务中一次将一个敌人从边缘拉出来。"}, [2]={mob="游荡的幽灵", note="普通生物与血腥僵尸聚集在东南墓地中。留意巡逻。将巡查后方与墓地草药任务配对。"}, [3]={mob="黑暗新教徒", note="东南方银色黎明任务附近有密集的普通生物。每次从营地边缘拉出一名敌人，以避免黑暗执法者。从11磨到12。"}}, supply={[1]={npc="旅店老板瑞尼"}, [2]={npc="亚伯·温特斯"}, [3]={npc="旅店老板瑞尼"}, [4]={npc="温特斯夫人"}, [5]={npc="多拉斯"}}, steps={[1]={npc="亡灵卫兵希米尔", tgt="亡灵卫兵希米尔"}, [2]={npc="葛尔多", tgt="葛尔多"}, [3]={hint="从位于布瑞尔西边、丧钟镇北边的农场中偷10颗南瓜来，把它们交给布瑞尔的药剂师乔汉。"}, [4]={hint="收集3根阴暗草，把它们交给布瑞尔墓地的初级药剂师霍兰德。"}, [5]={hint="把血色十字军文件交给布瑞尔的执行官塞加德。"}, [6]={npc="执行官塞加德", tgt="执行官塞加德"}, [7]={npc="药剂师乔汉", tgt="药剂师乔汉"}, [8]={npc="初级药剂师霍兰德", tgt="初级药剂师霍兰德"}, [9]={text="将您的炉石与布瑞尔 (61.72, 52.05) 中的旅店老板瑞尼绑定。"}, [10]={npc="药剂师乔汉", tgt="药剂师乔汉"}, [11]={hint="将斑纹南瓜带给被关在恐惧之末旅店地下室中的血色十字军俘虏。"}, [12]={npc="血色十字军俘虏", tgt="血色十字军俘虏"}, [13]={npc="亡灵卫兵迪林格尔", tgt="亡灵卫兵迪林格尔"}, [14]={npc="执政官塞弗伦", tgt="执政官塞弗伦"}, [15]={npc="药剂师乔汉", tgt="药剂师乔汉"}, [16]={npc="初级药剂师霍兰德", tgt="初级药剂师霍兰德"}, [17]={npc="执行官塞加德", tgt="执行官塞加德"}, [18]={npc="执行官塞加德", tgt="执行官塞加德"}, [19]={npc="执行官塞加德", tgt="执行官塞加德"}, [20]={npc="通缉！", npcObj=true}, [21]={text="布瑞尔外和西边的血色营地"}, [22]={hint="给布瑞尔的亡灵卫兵迪林格尔带回7只腐烂的爪子。"}, [23]={hint="杀死腐皮盗墓贼和混血腐皮豺狼人。"}, [24]={hint="布瑞尔镇里的药剂师乔汉要求你收集5瓶黑暗犬的血液。"}, [25]={hint="收集