    ["01-7"] = {tips={{k="交通", text="来自另一个起始区？在观天者台地南码头的莫高雷（34.30, 25.80）登上Skycutter。在瓦拉纳尔西码头（57.90, 80.90）下车，沿路向北至森达尔林地。"}, {k="提醒", text="沿着瓦拉纳尔的道路向北行驶至森达尔林地。其他部落种族可以做共享支线任务。该插件隐藏了种族锁定步骤和缺少先决条件的步骤。在 1-3 级，在聚会和村庄任务之前杀死幼年的 vuldren 和卷蝇。还低于12吗？完成于血蹄村。", s={{"沿着瓦拉纳尔的道路向北行驶至森达尔林地"}, {"其他部落种族可以做共享支线任务"}, {"该插件隐藏了种族锁定步骤和缺少先决条件的步骤"}, {"在 1-3 级，在聚会和村庄任务之前杀死幼年的 vuldren 和卷蝇"}, {"还低于12吗？"}, {"完成于血蹄村"}}}, {k="取捨", text="沿着岛链从森达尔林地穿过申达尔村和瓦拉纳尔到达阿基尔神殿。 12级以下？在登上齐柏林飞艇之前完成果园或影风森林支线任务。"}, {k="取捨", text="一起接学徒和强盗任务。如果您是 Skyborne，请添加角鹰兽骚扰 (角鹰兽的袭扰)。 《Prideclaws 的问题》奖励简易皮背包。多管闲事的法师向德鲁伊提供变幻潮汐神像。萨满从火焰的召唤获得蓄能烈焰图腾。", s={{"一起接学徒和强盗任务"}, {"如果您是 Skyborne，请添加角鹰兽骚扰 (角鹰兽的袭扰)", {race={"天裔精靈"}}}, {"《Prideclaws 的问题》奖励简易皮背包"}, {"多管闲事的法师向德鲁伊提供变幻潮汐神像", {class={"DRUID"}}}, {"萨满从火焰的召唤获得蓄能烈焰图腾", {class={"SHAMAN"}}}}}, {k="提醒", text="离岛两个衔接任务 下一步、大地之环 显示为 13 级，7 级就能接，主线跑完就接。", s={{"离岛两个衔接任务 下一步、大地之环 显示为 13 级，7 级就能接，主线跑完就接"}}}}, danger={[1]="从森达尔林地瞭望台跳下之前，请将您的种族显示在操作栏上。跳跃后立即使用。", [2]="奥拉凯斯风暴追击者与影风森林阵营的步兵混在一起。一次从边缘拉一个，避开中间。"}, grind={[1]={mob="幼年瓦尔德伦", note="森达尔林地中普通小怪密集。一次拉一名敌人并留意附近的敌人群。在开始处附近进行 1-2 级研磨。"}, [2]={mob="高地强盗", note="普通小怪密集在申达尔高地。将强盗从营地边缘拉出来以避免成群结队。与犯罪元素和偷窃的风石配对。"}, [3]={mob="奥拉凯斯逐暴者", note="影风森林中普通小怪密集。从边缘拉动以避免步兵。与 Unwanted 和 Unworthy 配对或磨至 12。"}}, supply={[1]={npc="费夫拉斯·天锤"}, [2]={npc="乌阿莉亚·日冠"}, [3]={npc="乌阿莉亚·日冠"}, [4]={npc="泽风岛平民"}, [5]={npc="艾迪·三铸"}, [6]={npc="泽风岛平民"}, [7]={npc="贝兰迪尔·远航"}, [8]={npc="多纳尔·微风"}, [9]={npc="塔莉亚·明空"}, [10]={npc="多纳尔·微风"}, [11]={npc="安特拉瑞娅·凝云"}, [12]={npc="塔尔"}}, steps={[1]={npc="收藏家达莉亚", tgt="艾莉·远心"}, [2]={hint="在森达尔林地与寻天者罗里安交谈。"}, [3]={npc="艾莉·远心", tgt="寻天者罗里安"}, [4]={npc="艾莉·远心", tgt="寻天者罗里安"}, [5]={npc="法罗恩·秋风", tgt="埃拉特雷尔·轻羽"}, [6]={npc="米莉亚尔·唤雾", tgt="米莉亚尔·唤雾"}, [7]={npc="哈兰·鹰眼", tgt="哈兰·鹰眼"}, [8]={hint="在森达尔林地消灭8只幼年瓦尔德伦。"}, [9]={hint="在森达尔林地消灭8只烦人的卷云蝇。"}, [10]={hint="从森达尔林地的瞭望塔顶跳下，使用你的踏空而行能力减缓下落速度。", desc="从瞭望塔跳下，然后在着陆前使用踏空而行。"}, [11]={hint="与哈兰·鹰眼交谈，借用他的天赋去观察远处的锚点水晶塔。"}, [12]={npc="艾莉·远心", tgt="寻天者罗里安"}, [13]={npc="法罗恩·秋风", tgt="埃拉特雷尔·轻羽"}, [14]={npc="艾莉·