    ["05-d2"] = {name="Hall of Thanes", entrance="铁炉堡 27.63, 47.83", pickup="铁炉堡之旅仅用于有组织的成就跑。从幽暗城出发，穿过银松、希尔斯布莱德和阿拉希，然后向南穿过湿地和丹奥加兹进入丹莫罗。 部落必备拾音器未经验证。", pickupS={{"铁炉堡之旅仅用于有组织的成就跑"}, {"从幽暗城出发，穿过银松、希尔斯布莱德和阿拉希，然后向南穿过湿地和丹奥加兹进入丹莫罗"}, {"部落必备拾音器未经验证"}}, tips={{k="動線", text="入口 → 安威玛尔之眠的法德林 → 黑铁召唤师的玛格马图斯 → 巡逻的掠夺者 → 皇家金库中的杜根。"}, {k="說明", text="地下地图、旧铁炉堡入侵、永不安息的亡者、远古的宿怨、重要的传家宝、谅解条约 是联盟任务，部落接不到。", s={{"地下地图、旧铁炉堡入侵、永不安息的亡者、远古的宿怨、重要的传家宝、谅解条约 是联盟任务，部落接不到"}}}, {k="說明", text="奔跑以获得战利品或成就。 Boss 包括法德林·安威玛尔、玛格马图斯、劫掠者和杜根·挽锤。", s={{"奔跑以获得战利品或成就"}, {"Boss 包括法德林·安威玛尔、玛格马图斯、劫掠者和杜根·挽锤"}}}, {k="說明", text="部落上交位置未经验证。", s={{"部落上交位置未经验证"}}}, {k="取捨", text="练级时跳过。对于遗产成就，请在进入之前组建您的团队。联盟资本守卫和 PvP 规则使进入更加困难。"}, {k="說明", text="从铁炉堡王座室的侧门前往旧铁炉堡，然后沿着通道到达地牢门户。 暴风雪确认部落可以通过联盟进入领地。", s={{"从铁炉堡王座室的侧门前往旧铁炉堡，然后沿着通道到达地牢门户"}, {"暴风雪确认部落可以通过联盟进入领地"}}}}, steps={[1]={text="Hall of Thanes 入口"}}},
    ["05-d1"] = {name="怒焰裂谷", entrance="奥格瑞玛 52.60, 49.00", pickup="解锁、十字路口、飞行点，从拉哈罗飞往雷霆崖转寻找背包 和试探敌人，然后在奥格瑞玛转隐藏的敌人 和隐藏的敌人 转萨尔。在暗影裂口中拾取饥饿者塔拉加曼。如果您已解锁幽暗城，请在穿越过程中从瓦里玛萨斯获取 毁灭之力。", pickupS={{"解锁、十字路口、飞行点，从拉哈罗飞往雷霆崖转寻找背包 和试探敌人，然后在奥格瑞玛转隐藏的敌人 和隐藏的敌人 转萨尔"}, {"在暗影裂口中拾取饥饿者塔拉加曼"}, {"如果您已解锁幽暗城，请在穿越过程中从瓦里玛萨斯获取 毁灭之力"}}, tips={{k="動線", text="清除入口处的穴居人→走第一个大厅的右侧坡道到奥格弗林特和玛尔·恐怖图腾→穿过熔岩桥到达饥饿者塔拉加曼→清除火刃氏族邪教徒→巴扎兰上右侧坡道，然后在尽头祈求者耶戈什。"}, {k="取捨", text="进入前解锁 隐藏的敌人。运行一次怒焰裂谷并在暗影裂口附近交出 饥饿者塔拉加曼。保存雷霆崖和幽暗城任务交接单，以供路线上的城市参观之用。"}, {k="說明", text="进入奥格瑞玛中的暗影裂口，沿着通道向下到达蓝色地牢传送门。", s={{"进入奥格瑞玛中的暗影裂口，沿着通道向下到达蓝色地牢传送门"}}}}, steps={[1]={npc="拉哈罗", tgt="拉哈罗"}, [2]={npc="拉哈罗", tgt="拉哈罗"}, [3]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯", tag="可选", desc="如果您跳过了幽暗城，请让您的小组共享 毁灭之力。否则，请共享其他四个。"}, [4]={npc="萨尔", tgt="萨尔"}, [5]={hint="将军官的徽章交给奥格瑞玛的萨尔。"}, [6]={npc="萨尔", tgt="萨尔"}, [7]={npc="萨尔", tgt="萨尔", preText="隐藏的敌人"}, [8]={hint="将军官的徽章交给尼尔鲁·火刃并与他谈一谈，看看他是否相信你是火刃氏族中的一员，然后回到奥格瑞玛的萨尔那里。"}, [9]={npc="萨尔", tgt="萨尔"}, [10]={npc="萨尔", tgt="萨尔", preText="隐藏的敌人"}, [11]={npc="尼尔鲁·火刃", tgt="尼尔鲁·火刃"}, [12]={text="怒焰裂谷 入口"}, [13]={hint="在奥格瑞玛找到怒焰裂谷，杀掉8个怒焰穴居人和8个怒焰萨满祭司，然后向雷霆崖的拉哈罗复命。", desc="位置：沿着斜坡到达第一个穴居人大厅。杀死萨满和穴居人。", spot="沿着斜坡到达第一个穴居人大厅。杀死萨满和穴居人。"}, [14]={hint="在怒焰裂谷搜寻玛尔·恐怖图腾的尸体以及他留下的东西。", desc="位置：在第一个穴居人大厅里走右边的坡道。找到奥格弗林特后面的尸体。", spot="在第一个穴居人大厅里走右边的坡道。找到奥格弗林特后面的尸体。"}, [15]={npc="玛尔·恐怖图腾", tgt="玛尔·恐怖图腾", tag="需要游戏内检查", spot="首个穴居人大厅右岔上坡，奥格弗林特后方遗体"}, [16]={npc="玛尔·恐怖图腾", tgt="玛尔·恐怖图腾", tag="需要游戏内检查", preText="寻找背包"}, [17]={hint="进入怒焰裂谷，杀死饥饿者塔拉加曼，然后把他的心脏交给奥格瑞玛的尼尔鲁·火刃。", desc="位置：返回主路径。 饥饿者塔拉加曼位于熔岩十字路口的平台上。", spot="返回主路径。 饥饿者塔拉加曼位于熔岩十字路口的平台上。"}, [18]={hint="将《暗影法术研究》和《扭曲虚空的魔法》这两本书交给幽暗城的瓦里玛萨斯。", tag="可选", desc="位置：穿过熔岩桥，清除火刃氏族邪教分子，走向最后的 Boss。", spot="穿过熔岩桥，清除火刃氏族邪教分子，走向最后的 Boss。"}, [19]={hint="杀死巴扎兰和祈求者耶戈什，然后回到奥格瑞玛的萨尔那里。", desc="位置：走巴扎兰的右侧坡道，然后返回祈求者耶戈什的主路。", spot="走巴扎兰的右侧坡道，然后返回祈求者耶戈什的主路。"}, [20]={npc="尼尔鲁·火刃", tgt="尼尔鲁·火刃"}, [21]={npc="萨尔", tgt="萨尔"}, [22]={npc="萨尔", tgt="萨尔", preText="隐藏的敌人"}, [23]={hint="与奥格瑞玛的尼尔鲁·火刃谈一谈。"}, [24]={npc="尼尔鲁·火刃", tgt=