    ["02-9"] = {name="银松森林", tips={{k="交通", text="第一次访问时步行前往坟墓并解锁飞行点。返回途中使用炉石返回十字路口。如果您的炉石处于冷却状态，请乘坐奥格瑞玛飞艇。"}, {k="取捨", text="解锁 调查安伯米尔 和 Forever quest 监视道路，然后在一个循环中在安伯米尔中执行这两项操作。在杀死法师之前交出 调查安伯米尔 法师的头领。"}, {k="取捨", text="在焚木村中一起做99和致命的配方。转入 99，然后乘坐 阿鲁高的愚行 和 阻止蔓延 并在格雷迈恩之墙完成这两个任务。"}, {k="取捨", text="回到 20 级的贫瘠之地。 如果你还没有开始护送 护送埃兰德、伏击 焚木村中的伏击 和影牙城堡链，请跳过它们。当您从坟墓飞回时，请上交任何正在进行的幽暗城任务，例如 致命的配方 或 腐皮豺狼人的产生。"}, {k="取捨", text="在第 19 级接受 前往希尔斯布莱德丘陵 并将其保存为希尔斯布莱德丘陵中的塔伦米尔。首先返回贫瘠之地以避免单独旅行。"}, {k="提醒", text="20级以下？完成单人任务并杀死格雷迈恩之墙（大约 43、81）或安伯米尔（大约 63、65）的普通生物。如果您有群组，请运行影牙城堡。任务乌尔之书需要16级，而除掉阿鲁高和影牙城堡里的亡灵哨兵需要18级。", s={{"20级以下？"}, {"完成单人任务并杀死格雷迈恩之墙（大约 43、81）或安伯米尔（大约 63、65）的普通生物"}, {"如果您有群组，请运行影牙城堡"}, {"任务乌尔之书需要16级，而除掉阿鲁高和影牙城堡里的亡灵哨兵需要18级"}}}}, danger={[1]="24-25级精英阿鲁高之子巡逻队银松森林。对他们敬而远之。如果有人发现你，请远离树林。", [2]="阿鲁高的儿子也在从焚木村到格雷迈恩之墙的道路上巡逻。伏击后离开，不要沿着墙追小怪。"}, grind={[1]={mob="达拉然咒术师", note="安伯米尔之外正常范围的生物密度适中。先清理路边。利用地形将怪物从门口吸引开。"}, [2]={mob="达拉然巫师", note="安伯米尔之外、达拉然任务区域附近的正常远程生物的中等密度。一次拉一个敌人并注意守卫。"}, [3]={mob="病怏怏的难民", note="格雷迈恩之墙旁有密集的普通生物。一次从路边拉出一个敌人。杀死敌人直到达到 20 级再离开。"}}, supply={[1]={npc="卡洛斯·拉佐克"}, [2]={npc="旅店老板拜特斯"}, [3]={npc="塞巴斯蒂安·米洛奇"}, [4]={npc="旅店老板拜特斯"}, [5]={npc="艾德温·哈里"}, [6]={npc="帕崔斯·杜耶尔"}, [7]={npc="旅店老板瑞尼"}, [8]={npc="旅店老板瑞尼"}, [9]={npc="迈克尔·加勒特"}, [10]={npc="托马斯·莫丹"}, [11]={npc="艾泽基尔·格瑞乌斯"}}, steps={[1]={text="在杜隆塔尔齐柏林飞艇塔，用弗雷萨 (50.82, 13.54) 确认提瑞斯法林地路线。在布瑞尔以南下车，沿路前往幽暗城。将您的壁炉放在十字路口上。"}, [2]={text="从迈克尔·加勒特（63.25, 48.56）学习幽暗城的飞行点。如果解锁，则飞往坟墓。否则离开城市并走提瑞斯法的西南路进入银松森林。"}, [3]={text="在墓地接载 → 北部农场"}, [4]={text="从卡洛斯·拉佐克 (45.62, 42.60) 学习坟墓飞行点。保留当前的壁炉。"}, [5]={hint="和瑟伯切尔的茉拉·符文图腾谈一谈。"}, [6]={npc="茉拉·符文图腾", tgt="茉拉·符文图腾"}, [7]={hint="将药剂师乔汉的研究成果带给银松森林的药剂师伦弗利尔。", tag="可选"}, [8]={npc="药剂师伦弗利尔", tgt="药剂师伦弗利尔", tag="可选"}, [9]={hint="把克拉莉斯的坠饰放在银松森林尤瑞夫的坟墓上。", tag="可选"}, [10]={npc="尤瑞夫的墓碑", npcObj=true, tag="可选"}, [11]={npc="达拉尔·道恩维沃尔", tgt="达拉尔·道恩维沃尔"}, [12]={npc="高级执行官哈德瑞克", tgt="高级执行官哈德瑞克"}, [13]={npc="高级执行官哈德瑞克", tgt="高级执行官哈德瑞克"}, [14]={npc="药剂师伦弗利尔", tgt="药剂师伦弗利尔"}, [15]={npc="暗影牧师奥利斯特", tgt="暗