    ["05-d5"] = {name="死亡矿井", entrance="西部荒野 38.20, 77.50", pickup="在前往银松的路上，从提瑞斯法的班达里安堡处的丹妮莎·莫尔搭乘 外交风波，并完成银松和芬里斯岛先决条件。 20级时，从墓穴中的卢米娜处拿走月吻之刃，并从特雷文那里得到笔记。这些任务适用于亡灵圣骑士。乘坐棘齿城船前往藏宝海湾，然后向北穿过荆棘谷进入暮色森林，向西到达月溪镇。", pickupS={{"在前往银松的路上，从提瑞斯法的班达里安堡处的丹妮莎·莫尔搭乘 外交风波，并完成银松和芬里斯岛先决条件"}, {"20级时，从墓穴中的卢米娜处拿走月吻之刃，并从特雷文那里得到笔记"}, {"这些任务适用于亡灵圣骑士"}, {"乘坐棘齿城船前往藏宝海湾，然后向北穿过荆棘谷进入暮色森林，向西到达月溪镇"}}, tips={{k="動線", text="矿洞隧道→拉克佐→斯尼德和木材→基尔尼格的锻造→爆破通往码头的门→重拳先生→绿皮队长→艾德温·范克里夫。 曲奇位于下层甲板。如果您只需要木材，请在斯尼德之后离开。"}, {k="取捨", text="如果您只是练级，请跳过此行。对于 月吻之刃，到达斯尼德的房间并收集木材（仅限亡灵圣骑士）。如果团队想要从最终老板那里获得战利品，请继续前进。", s={{"如果您只是练级，请跳过此行"}, {"对于 月吻之刃，到达斯尼德的房间并收集木材（仅限亡灵圣骑士）", {race={"Scourge"}, class={"PALADIN"}}}, {"如果团队想要从最终老板那里获得战利品，请继续前进"}}}, {k="說明", text="进入月溪镇（42.40, 70.40）的矿井建筑，下楼，沿着隧道到达38.20, 77.50的传送门。 联盟迪菲亚任务对部落不可用。", s={{"进入月溪镇（42.40, 70.40）的矿井建筑，下楼，沿着隧道到达38.20, 77.50的传送门"}, {"联盟迪菲亚任务对部落不可用"}}}}, steps={[1]={npc="丹妮莎·莫尔", tgt="丹妮莎·莫尔"}, [2]={hint="前往银松森林的瑟伯切尔，与特雷凡·罗尔谈谈失踪的大地之环旅客。"}, [3]={npc="特雷凡·罗尔", tgt="特雷凡·罗尔"}, [4]={npc="特雷凡·罗尔", tgt="特雷凡·罗尔", preText="外交风波"}, [5]={hint="与亡灵卫兵巴尔德伦交谈，询问最近经过瑟伯切尔的那两名神秘大地之环旅客。"}, [6]={npc="亡灵卫兵巴尔德伦", tgt="亡灵卫兵巴尔德伦"}, [7]={npc="亡灵卫兵巴尔德伦", tgt="亡灵卫兵巴尔德伦", preText="古怪的二人组"}, [8]={hint="调查东边的芬里斯岛，查明大地之环旅队的下落。"}, [9]={npc="被烧焦的残骸", npcObj=true}, [10]={npc="被烧焦的残骸", npcObj=true, preText="悲惨的命运"}, [11]={hint="前往北方的芬里斯城堡展开调查，设法寻找大地之环队伍中失踪的成员。"}, [12]={npc="卢米娜·风歌", tgt="卢米娜·风歌"}, [13]={npc="卢米娜·风歌", tgt="卢米娜·风歌", preText="进入芬里斯城堡"}, [14]={hint="从腐皮豺狼人手中夺回芬里斯岛钥匙，解救卢米娜·风歌。"}, [15]={npc="卢米娜·风歌", tgt="卢米娜·风歌"}, [16]={npc="卢米娜·风歌", tgt="卢米娜·风歌", desc="Skyborne：按照银松森林中坟墓的班级步骤进行操作。", preText="卢米娜·风歌"}, [17]={hint="陪同卢米娜·风歌，助她逃离芬里斯城堡。", desc="Skyborne：按照银松森林中坟墓的班级步骤进行操作。"}, [18]={npc="卢米娜·风歌", tgt="卢米娜·风歌", desc="Skyborne：按照银松森林中坟墓的班级步骤进行操作。"}, [19]={npc="卢米娜·风歌", tgt="卢米娜·风歌", preText="塑风者之怒"}, [20]={hint="到瑟伯切尔与卢米娜·风歌交谈。"}, [21]={npc="卢米娜·风歌", tgt="卢米娜·风歌"}, [22]={npc="卢米娜·风歌", tgt="卢米娜·风歌", desc="接受后与特雷凡·罗尔对话。获取一份武器笔记并将任务保留在您的日志中。", preText="血债"}, [23]={text="死亡矿井 入口"}, [24]={hint="到瑟伯切尔与特雷凡·罗尔交谈，并带回他所需的材料。", desc="掉落率：仅来自地精木雕者的白石橡木。位置：通过拉克佐。在杂物间用斯尼德杀死木匠。", spot="通过拉克佐。在杂物间用斯尼德杀死木匠。"}, [25]={npc="特雷凡·罗尔", tgt="特雷凡·罗尔", desc="带上纸币，白石橡木，附魔银锭和净化过的科尔宝石。"}}},
    ["05-d4"] = {name="哀嚎洞穴", entrance="贫瘠之地 46.00, 36.30", pickup="在十字路口与汤加完成 遗忘之池 → 死水绿洲 → 变异的生物，然后在雷霆崖参观哈缪尔、奈良和扎马。先交迅猛龙角，然后再取棘齿城中的智慧饮料和港口的麻烦。在洞穴入口上方的壁架上找到纳尔帕克和厄布鲁。", pickupS={{"在十字路口与汤加完成 遗忘之池 → 死水绿洲 → 变异的生物，然后在雷霆崖参观哈缪尔、奈良和扎马"}, {"先交迅猛龙角，然后再取棘齿城中的智慧饮料和港口的麻烦"}, {"在洞穴入口上方的壁架上找到纳尔帕克和厄布鲁"}}, tips={{k="動線", text="入口浅滩的Anacondra→河西的Cobrahn→东边的Pythas、斯卡姆、Serpentis和Verdan→在所有四个Fanglord之后返回入口，护送门徒并杀死Mutanus。收集毒蛇花、 变异皮革和哀嚎香精，同时清除两翼的偏差。"}, {k="取捨", text="交出迅猛龙角来解锁智慧饮料。如果你错过了一个任务，不要让队伍在门口等着。如果十字路口绿洲链做好了，就从哈缪尔·符文图腾继续。"}, {k="說明", text="从甜水绿洲 (47.70, 35.00) 进入外部洞穴，然后沿着隧道到达传送门。首先在外部入口上方的凹室中领取纳尔帕克和厄布鲁的任务。", s={{"从甜水绿洲 (47.70, 35.00) 进入外部洞穴，然后沿着隧道到达传送门"}, {"首先在外部入口上方的凹室中领取纳尔帕克和厄布鲁的任务"}}}}, steps={[1]={npc="图加·符文图腾", tgt="图加·符文图腾"}, [2]={hint="向图加·符文图腾报告你的发现。"}, [3]={npc="图加·符文图腾", tgt="图加·符文图腾"}, [4]={npc="图加·符文图腾", tgt="图加·符文图腾", preText="遗忘之池"}, [5]={hint="调查死水绿洲，然后返回十字路口向图加·符文图腾报告。"}, [6]={npc="图加·符文图腾", tgt="图加·符文图腾"}, [7]={npc="图加·符文图腾", tgt="图加·符文图腾", preText="死水绿洲"}, [8]={hint="收集8块变异的钳嘴龟壳，把它们交给十字路口的图加。", tag="目标：绿洲钳嘴龟 / 绿洲钳嘴龟幼体"}, [9]={npc="图加·符文图腾", tgt="图加·符文图腾"}, [10]={npc="图加·符文图腾", tgt="图加·符文图腾", preText="变异的生物"}, [11]={hint="和哈缪尔·符文图腾谈一谈。"}, [12]={npc="大德鲁伊哈缪尔·符文图腾", tgt="大德鲁伊哈缪尔·符文图腾"}, [13]={npc="大德鲁伊哈缪尔·符文图腾", tgt="大德鲁伊哈缪尔·符文图腾", preText="哈缪尔·符文图腾"}, [14]={hint="和纳拉·蛮鬃谈一谈。"}, [15]={npc="纳拉·蛮鬃", tgt="纳拉·蛮鬃"}, [16]={npc="纳拉·蛮鬃", tgt="纳拉·蛮鬃", preText="纳拉·蛮鬃"}, [17]={npc="药剂师扎玛", tgt="药剂师扎玛"}, [18]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯"}, [19]={hint="从赤鳞镰爪龙身上收集5根完整的迅猛龙角，把它们交给棘齿城的米希瑞克斯。"}, [20]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯"}, [21]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯", preText="迅猛龙角"}, [22]={npc="起重机操作员比戈弗兹", tgt="起重机操作员比戈弗兹"}, [23]={npc="纳尔帕克", tgt="纳尔帕克"}, [24]={npc="厄布鲁", tgt="厄布鲁"}, [25]={hint="棘齿城的起重机操作员比戈弗兹让你从疯狂的马格利什那儿取回一瓶99年波尔多陈酿，疯狂的马格利什就藏在哀嚎洞穴里。"}, [26]={text="哀嚎洞穴 入口"}, [27]={hint="为雷霆崖的药剂师扎玛收集10朵毒蛇花。", desc="毒蛇花生长在副本门前的外洞。位置：沿着浅溪流，沿着两岸聚集毒蛇花。", spot="沿着浅溪流，沿着两岸聚集毒蛇花。"}, [28]={hint="哀嚎洞穴的纳尔帕克想要20张变异皮革。", desc="变异杀戮者在副本门前的外洞。位置：浅叉和两侧翼处的杀伤偏差。战利品会随着你的走而隐藏起来。", spot="浅叉和两侧翼处的杀伤偏差。战利品会随着你的走而隐藏起来。"}, [29]={hint="哀嚎洞穴的厄布鲁要求你杀掉7只变异破坏者、7只剧毒飞蛇、7只变异蹒跚者和7只变异尖牙风蛇。", desc="位置：清除浅叉，然后消灭西翼和东翼的所有四个小怪。", spot="清除浅叉，然后消灭西翼和东翼的所有四个小怪。"}, [30]={hint="收集6份哀嚎香精，把它们交给棘齿城的麦伯克·米希瑞克斯。", desc="外面有别针标记吞噬灵质。里面的渗液也算。可在副本门外击杀吞噬软浆怪。位置：如果你缺少哀嚎香精，就沿着溪流寻找软泥。", spot="如果你缺少哀嚎香精，就沿着溪流寻找软泥。"}, [31]={hint="将考布莱恩宝石、安娜科德拉宝石、皮萨斯宝石和瑟芬迪斯宝石交给雷霆崖的纳拉·蛮鬃。", desc="位置：在浅滩中找到 Anacondra，Cobrahn 位于西边，另外两个 Boss 位于东边。", spot="在浅滩中找到 Anacondra，Cobrahn 位于西边，另外两个 Boss 位于东边。"}, [32]={npc="发光的碎片", npcObj=true, tag="需要游戏内检查", desc="四德鲁伊之后回到弟子。护送他并杀死穆塔努斯以获得碎片。"}, [33]={npc="纳尔帕克", tgt="纳尔帕克"}, [34]={npc="厄布鲁", tgt="厄布鲁"}, [35]={npc="起重机操作员比戈弗兹", tgt="起重机操作员比戈弗兹"}, [36]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯"}, [37]={hint="寻找更多有关这块噩梦碎片的信息。"}, [38]={npc="菲拉·古风", tgt="菲拉·古风"}, [39]={npc="菲拉·古风", tgt="菲拉·古风", preText="发光的碎片"}, [40]={hint="把噩梦碎片交给长者高地的哈缪尔·符文图腾。"}, [41]={npc="大德鲁伊哈缪尔·符文图腾", tgt="大德鲁伊哈缪尔·符文图腾"}, [42]={npc="纳拉·蛮鬃", tgt="纳拉·蛮鬃"}, [43]={npc="药剂师扎玛", tgt="药剂师扎玛"}}},
    ["02-11"] = {name="石爪山脉", tips={{k="交通", text="解锁、飞行点以及在首次访问烈日石居时设置您的炉石。经南山口折返后，返回烈日石居并飞往棘齿城。"}, {k="取捨", text="在暗色湖处拾取盖亚种子并在石爪峰处进行塞纳留斯的遗产。交出种子，然后在一个循环中完成所有四个烧焦谷目标。在前往乱风岗的途中，在大升降梯处交纳 召回卫兵。"}, {k="取捨", text="在碎木岗哨腿上杀死奥达努斯以获得 。仅当您计划重新访问狂风峭壁时才继续 新的指示 - 格雷苏。这节省了往返棘齿城的时间。"}, {k="取捨", text="贝瑟莱斯和土灵的觉醒涉及精英。任务 金吉尔的森林魔法 会派你追击几种野兽并在南端返回。仅当您已经拥有材料时才将其上交。"}, {k="提醒", text="25级以下？杀死焦黑谷边缘的血怒鹰身女妖或火元素（大约 32、64）。首先一次拉一个敌人。", s={{"25级以下？"}, {"杀死焦黑谷边缘的血怒鹰身女妖或火元素（大约 32、64）"}, {"首先一次拉一个敌人"}}}}, danger={[1]="贝瑟莱斯是蛛网小径附近的精英蜘蛛。首先清除小蜘蛛。如果您没有群组，请跳过它。", [2]="滚岩峡谷的洞穴很狭窄。在打开桶召唤高戈罗克之前，清理从入口到桶的路径。"}, grind={[1]={mob="血怒鹰身人", note="烧焦谷东入口处普通生物的密度适中。消灭外面的单打，监视巡逻，然后从 23 开始磨练。"}, [2]={mob="血怒唤风者", note="烧焦谷东部有密集的普通脚轮。利用悬崖进行视线拉动，以避免整个巢穴。与烧焦谷任务配对。"}}, supply={[1]={npc="萨尔姆"}, [2]={npc="旅店老板杰卡"}, [3]={npc="波兰德"}, [4]={npc="旅店老板杰卡"}, [5]={npc="格劳纳尔"}, [6]={npc="基达"}}, steps={[1]={text="从十字路口沿西北路朝 Stonetalon 方向行驶。停在贫瘠之地的希雷斯·碎石 (35.26, 27.88)。"}, [2]={hint="找到石爪山的希雷斯·碎石并和她谈一谈。", tag="如果在十字路口接受、可选"}, [3]={npc="希雷斯·碎石", tgt="希雷斯·碎石", tag="如果在十字路口接受、可选"}, [4]={npc="希雷斯·碎石", tgt="希雷斯·碎石"}, [5]={text="穿过石爪南部到达玛拉卡金，然后上坡经过蜘蛛到达狂风峭壁。"}, [6]={hint="把达索克的亲笔信交给金吉尔，他住在石爪山的洞穴中。", tag="如果棘齿城 / 陶拉祖营地支线接受"}, [7]={npc="巫医金吉尔", tgt="巫医金吉尔", tag="如果棘齿城 / 陶拉祖营地支线接受"}, [8]={npc="辛吉拉", tgt="辛吉拉"}, [9]={npc="巫医金吉尔", tgt="巫医金吉尔", tag="可选"}, [10]={npc="通缉：贝瑟莱斯", npcObj=true, tag="可选"}, [11]={hint="和狂风峭壁的菲兹克斯谈一谈。", tag="如果棘齿城 / 陶拉祖营地支线接受"}, [12]={npc="菲兹克斯", tgt="菲兹克斯", tag="如果棘齿城 / 陶拉祖营地支线接受"}, [13]={npc="菲兹克斯", tgt="菲兹克斯"}, [14]={hint="玛拉卡金的辛吉拉要求你杀死10只深苔爬行者和7只深苔毒蜘蛛。"}, [15]={hint="收集15颗深苔蜘蛛的卵，把它们交给棘齿城的麦伯克·米希瑞克斯。", tag="如果棘齿城 / 陶拉祖营地支线接受"}, [16]={hint="杀死15个风险投资公司樵夫，然后向石爪山与贫瘠之地交界处的希雷斯·碎石复命。"}, [17]={hint="为石爪山的菲兹克斯偷来超级收割机6000型的设计图。", desc="设计图由风险投资公司操作员掉落。"}, [18]={npc="菲兹克斯", tgt="菲兹克斯"}, [19]={npc="菲兹克斯", tgt="菲兹克斯"}, [20]={hint="杀掉贝瑟莱斯，然后把贝瑟莱斯的牙齿交给烈日石居的马格兰。", tag="可选", desc="贝瑟莱斯是精英。如果你打不过她就跳过吧。"}, [21]={text="沿着路一直走到烈日石居。从萨尔姆 (45.12, 59.84) 学习飞行点并将您的炉石与旅店老板杰卡 (47.47, 62.13) 绑定。保存它直到南部通道任务交接完成。"}, [22]={npc="马格兰", tgt="马格兰", tag="可选"}, [23]={npc="塔姆拉·荒原", tgt="塔姆拉·荒原"}, [24]={npc="布莱林·火拳", tgt="布莱林·火拳"}, [25]={npc="马格兰", tgt="马格兰"}, [26]={npc="苏纳曼", tgt="苏纳曼"}, [27]={npc="马格兰", tgt="马格兰"}, [28]={npc="马格兰", tgt="马格兰"}, [29]={npc="摩罗加尔", tgt="摩罗加尔", tag="可选"}, [30]={text="绕暗色湖和石爪峰向北环行。原路返回，在烈日石居交出种子，然后向西行驶。"}, [31]={hint="烈日石居的塔姆拉·荒原想让你去收集10枚盖亚之种。"}, [32]={hint="为石爪峰附近的布莱林·火拳杀死4名塞纳留斯的儿子，4名塞纳留斯的女儿以及4名塞纳里奥植物学家。"}, [33]={hint="玛拉卡金的巫医金吉尔需要5瓶石爪苔液、5根夜行虎须、30颗巨角鹿的眼球和1块灵龙的鳞片。", tag="可选", desc="抢夺塞纳留斯的遗产运行时的眼睛。其余的不要单独耕种。"}, [34]={npc="塔姆拉·荒原", tgt="塔姆拉·荒原"}, [35]={npc="塔姆拉·荒原", tgt="塔姆拉·荒原"}, [36]={npc="布莱林·火拳", tgt="布莱林·火拳"}, [37]={npc="布莱林·火拳", tgt="布莱林·火拳", tag="可选"}, [38]={text="从烈日石居向西进入烧焦谷。杀死鹰身女妖和火元素，收集闪闪发光的日光石，并检查一圈的土丘。"}, [39]={hint="烈日石居的马格兰要你去杀掉7个血怒鹰身人、7个血怒伏击者、7个血怒杀戮者和7个血怒游荡者。"}, [40]={hint="把15块闪光的太阳石带给摩罗加尔。"}, [41]={hint="将10块焚火余烬交给烈日石居的苏纳曼。"}, [42]={hint="将10枚盖亚之种种植在盖亚土堆中，然后与烈日石居的塔姆拉谈一谈。", desc="在已筹集的盖亚土堆上使用任务种子。"}, [43]={text="返回东部烈日石居进行任务交接。保留您的壁炉，等待玛拉卡金和山口返回。"}, [44]={npc="马格兰", tgt="马格兰"}, [45]={npc="摩罗加尔", tgt="摩罗加尔"}, [46]={npc="苏纳曼", tgt="苏纳曼"}, [47]={npc="塔姆拉·荒原", tgt="塔姆拉·荒原"}, [48]={npc="马格兰", tgt="马格兰", tag="精英、可选"}, [49]={hint="烈日石居的马格兰要你去杀掉血怒撕裂者，然后把她的遗体带回来作为证据。", tag="精英、可选", desc="血怒撕裂者是26级精英。带一组。"}, [50]={npc="马格兰", tgt="马格兰", tag="精英、可选"}, [51]={text="烧焦谷任务交接后，走东南路。完成可选的滚岩峡谷任务或直接前往玛拉卡金和贫瘠之地通行证。保留你的壁炉，以供通行证任务交接后使用。"}, [52]={hint="深入滚岩峡谷的洞穴中，为烈日石居的摩罗加尔取回10块共鸣水晶以供研究。", tag="可选"}, [53]={npc="摩罗加尔", tgt="摩罗加尔", tag="可选"}, [54]={npc="摩罗加尔", tgt="摩罗加尔", tag="可选"}, [55]={hint="使用魔化共鸣水晶打开共鸣桶，然后杀死高戈罗克。将这个消息告诉摩罗加尔，并把魔化共鸣水晶还给他。", tag="可选", desc="这会召唤一个20级精英。如果你是独奏，请跳过。"}, [56]={npc="摩罗加尔", tgt="摩罗加尔", tag="可选"}, [57]={npc="辛吉拉", tgt="辛吉拉"}, [58]={npc="巫医金吉尔", tgt="巫医金吉尔", tag="可选"}, [59]={npc="希雷斯·碎石", tgt="希雷斯·碎石"}, [60]={npc="希雷斯·碎石", tgt="希雷斯·碎石", tag="如果您有足够的经验，请跳过回程、可选"}, [61]={hint="杀死伐木机XT:4和XT:9，然后向石爪山与贫瘠之地交界处的希雷斯·碎石复命。", tag="如果您有足够的经验，请跳过回程、可选、目标：XT:4/XT:9"}, [62]={npc="希雷斯·碎石", tgt="希雷斯·碎石", tag="如果您有足够的经验，请跳过回程、可选"}, [63]={npc="希雷斯·碎石", tgt="希雷斯·碎石", tag="雷霆崖先决条件、可选"}, [64]={text="在山口转向塞雷斯后，前往太阳岩静修处。从塔姆飞往棘齿城寻找鸡蛋和信件。如果你的壁炉已倒塌，请跑到十字路口并从那里飞走。"}, [65]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯", tag="如果棘齿城 / 陶拉祖营地支线接受"}, [66]={hint="将密封的信封交给贫瘠之地的斯布特瓦夫。"}, [67]={npc="斯布特瓦夫", tgt="斯布特瓦夫"}, [68]={npc="斯布特瓦夫", tgt="斯布特瓦夫", tag="以后顺路做、可选"}, [69]={text="如果进行可选的无辜之血导入并持有长者，则从棘齿城飞往雷霆崖。如果您沿途无法解锁雷霆崖，请跳过绕路并飞往奥格瑞玛。"}, [70]={hint="与雷霆崖的玛加萨谈一谈。", tag="雷霆崖先决条件、可选"}, [71]={npc="玛加萨·野性图腾", tgt="玛加萨·野性图腾", tag="雷霆崖先决条件、可选"}, [72]={npc="玛加萨·野性图腾", tgt="玛加萨·野性图腾", tag="雷霆崖先决条件、可选"}, [73]={hint="和预见之池的药剂师扎玛谈一谈。", tag="雷霆崖先决条件、可选"}, [74]={npc="药剂师扎玛", tgt="药剂师扎玛", tag="雷霆崖先决条件、可选"}, [75]={npc="药剂师扎玛", tgt="药剂师扎玛", tag="雷霆崖先决条件、可选"}, [76]={npc="维尼克斯", tgt="维尼克斯", tag="可选", desc="先完成这个，然后在银松做谢尔索斯号角以获得进入地牢的另一条路。"}, [77]={hint="掉落自：风险投资公司砍树工、风险投资公司操作员、风险投资公司樵夫", tag="可选", desc="先完成这个，然后在银松做谢尔索斯号角以获得进入地牢的另一条路。"}, [78]={npc="维尼克斯", tgt="维尼克斯", tag="可选", desc="先完成这个，然后在银松做谢尔索斯号角以获得进入地牢的另一条路。"}, [79]={npc="乌尔库", tgt="乌尔库"}, [80]={hint="完成任务目标。"}, [81]={npc="乌尔库", tgt="乌尔库"}, [82]={text="完成可选的雷霆崖任务后，飞往奥格瑞玛。在弗雷萨的平台 (50.82, 13.54) 登上提瑞斯法飞艇。在布瑞尔南下车，前往幽暗城，然后继续前往塔伦米尔。"}}},
    ["02-12"] = {name="希尔斯布莱德丘陵", tips={{k="交通", text="第一次参观时，从墓地步行至塔伦米尔。 解锁、飞行点与扎瑞斯并与 Shay 设置炉石。离开时，从幽暗城步行至布瑞尔外的南塔，乘坐奥格瑞玛飞艇。"}, {k="取捨", text="在西侧环路沿希尔斯布莱德之战 收集 受难药剂 和 痛苦药剂。交出 来解锁 死亡的纪念品，然后在杀死人类时掠夺头骨。"}, {k="取捨", text="围绕亡灵哨兵玛索吉一起做 支援斥候 和 苦楚药剂。如果您有无辜者之血，请继续前往敦霍尔德城堡的郊区。使用 希尔斯布莱德之战 开始收集头骨，而不是像永远经验那样等到循环结束。"}, {k="取捨", text="如果目标丢失并且您需要原路返回，请跳过 危险！。 丹加洛克对于 希尔斯布莱德之战 来说很拥挤，所以稍后再单独使用。如果您赶时间，请跳过 宝贵制高点 链。高级山狮在其西山脊巡逻。"}, {k="取捨", text="如果您在烈日石居接受了 塔伦米尔之旅，请在敦霍尔德城堡完成 无辜者之血。前往乱风岗的途中经过雷霆崖时，交纳返回雷霆崖。"}, {k="取捨", text="完成 苦楚药剂 → 苦楚药剂，然后在塔伦米尔路段的幽暗城中接取 苦楚药剂 并在希尔斯布莱德海岸进行。"}, {k="取捨", text="在敦霍尔德城堡和通缉：辛迪加成员 处执行拯救行动 。请参阅奥特兰克山脉部分了解这两个任务。 拯救行动在 29 级解锁秘密潜入 。"}, {k="提醒", text="在第 27 层，在灰谷之前短暂停留在乱风岗处。 27岁以下，碾磨希尔斯布莱德农场（大约33、42）的农民或敦霍尔德城堡（大约77、43）外的普通辛迪加小怪。和一群人一起，你可以做丹加洛克。", s={{"在第 27 层，在灰谷之前短暂停留在乱风岗处"}, {"27岁以下，碾磨希尔斯布莱德农场（大约33、42）的农民或敦霍尔德城堡（大约77、43）外的普通辛迪加小怪"}, {"和一群人一起，你可以做丹加洛克"}}}}, danger={[1]="丹加洛克步枪手、牧师和登山者在楼梯上相互协助。与你的团队一起清理外面，然后再去找队长。", [2]="沿着雪人洞穴上方的小路将瓶子放置在西峰。如果看到更高级别的山狮，请沿着斜坡绕行，而不是直接爬上去。"}, grind={[1]={mob="希尔斯布莱德农夫", note="希尔斯布莱德农场东侧的普通生物密度适中。避免农舍附近的包裹。边走边收集希尔斯布莱德人类头骨。"}, [2]={note="农场中部的正常生物密度适中。寻找沿着田野巡逻的步兵。避免购买既有议员又有农民的房屋。"}, [3]={mob="老灰熊", note="敦霍尔德城堡以北的树林里有稀疏的普通小怪。避开要塞的包裹。沿着东线返回的路上，收获了一些猎物。"}}, supply={[1]={npc="扎瑞斯"}, [2]={npc="旅店老板沙恩"}, [3]={npc="旅店老板沙恩"}, [4]={npc="凯伦·苏萨隆"}, [5]={npc="高顿·温德哈姆"}, [6]={npc="托马斯·莫丹"}, [7]={npc="艾泽基尔·格瑞乌斯"}}, steps={[1]={text="如果您从烈日石居抵达，则从幽暗城开始。如果解锁，则飞往塔伦米尔。否则飞到墓地，沿着南路向东进入希尔斯布莱德，然后走北岔路。如果需要，可以从幽暗城步行。如果还在卡利姆多，先在奥格瑞玛外面登上飞艇。"}, [2]={text="抵达后，学习扎瑞斯的飞行点 (60.14, 18.62) 并将您的炉石与旅店老板沙恩 (62.78, 19.03) 绑定。"}, [3]={hint="将伦弗利尔的研究成果交给希尔斯布莱德山脚下塔伦米尔的药剂师林度恩。"}, [4]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [5]={hint="把扎玛的信带给塔伦米尔的林度恩。", tag="可选"}, [6]={npc="药剂师林度恩", tgt="药剂师林度恩", tag="可选"}, [7]={npc="药剂师林度恩", tgt="药剂师林度恩", tag="需要任务 塔伦米尔之旅、可选"}, [8]={text="在塔伦米尔接载 → 熊、蜘蛛、狮子和西边的农场"}, [9]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [10]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [11]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [12]={npc="危险！", npcObj=true, tag="可选"}, [13]={hint="塔伦米尔的药剂师林度恩要你去收集10个灰熊的舌头和一些食苔蛛的毒液。"}, [14]={hint="收集10瓶山地狮的血液，把它们交给塔伦米尔的药剂师林度恩。"}, [15]={hint="杀掉6个希尔斯布莱德雇农和6个希尔斯布莱德农夫，还有农夫雷恩和农夫盖兹，然后返回塔伦米尔向达萨利亚报告。"}, [16]={text="经过第一个西环路后，前往塔伦米尔或沿主路返回。"}, [17]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [18]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [19]={npc="亡灵卫兵沙穆萨", tgt="亡灵卫兵沙穆萨"}, [20]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [21]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [22]={hint="把受难药剂交给乌比。"}, [23]={npc="乌比", tgt="乌比"}, [24]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [25]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [26]={text="第二个农场环路 → 敦霍尔德和泥头花 → 西部铁匠铺"}, [27]={hint="把痛苦药剂喂给小狗斯坦雷。"}, [28]={npc="斯坦利", tgt="斯坦利"}, [29]={hint="杀死15个希尔斯布莱德农民，然后回到塔伦米尔向达萨利亚汇报。"}, [30]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [31]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [32]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [33]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [34]={hint="为塔伦米尔的药剂师林度恩收集5瓶无辜者之血。", tag="可选"}, [35]={hint="高级执行官达萨利亚要求你，将最新的命令送去交给驻扎在塔伦米尔以南、丹加洛克外围的亡灵哨兵玛索吉。"}, [36]={npc="亡灵哨兵玛索吉", tgt="亡灵哨兵玛索吉"}, [37]={npc="亡灵哨兵玛索吉", tgt="亡灵哨兵玛索吉", tag="完成任务 支援斥候、可选"}, [38]={hint="收集6朵泥头花，把它们交给塔伦米尔的药剂师林度恩。"}, [39]={hint="杀掉铁匠维林坦和4个希尔斯布莱德见习铁匠，并从那里抢回一箱铁材，然后向塔伦米尔的达萨利亚汇报。"}, [40]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [41]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [42]={npc="药剂师林度恩", tgt="药剂师林度恩", tag="可选"}, [43]={npc="药剂师林度恩", tgt="药剂师林度恩", tag="首先完成无辜者之血。上交处：乱风岗。、可选"}, [44]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [45]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [46]={text="市政厅 → 矿井 → 交于塔伦米尔"}, [47]={hint="杀掉波恩塞德镇长和5个希尔斯布莱德议员，摧毁《希尔斯布莱德宣言》，偷取希尔斯布莱德城镇文档，然后回到塔伦米尔向达萨利亚汇报。"}, [48]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [49]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [50]={hint="杀死工头邦德斯和10个希尔斯布莱德矿工，然后回到塔伦米尔向达萨利亚汇报。"}, [51]={hint="塔伦米尔的高级执行官达萨利亚悬赏通缉书记员赫拉斯·怀特斯蒂德、平民维尔克斯、矿工哈克特和农夫卡拉巴。", tag="可选"}, [52]={hint="塔伦米尔的亡灵卫兵沙穆萨想要30个希尔斯布莱德人类颅骨。"}, [53]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [54]={npc="亡灵卫兵沙穆萨", tgt="亡灵卫兵沙穆萨"}, [55]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚", tag="可选"}, [56]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚", tag="集团、可选"}, [57]={hint="到丹加洛克去杀掉10个巡山人、8个火枪手、4个牧师，还有达伦·铁山上尉，然后回到塔伦米尔向达萨利亚汇报。", tag="集团、可选"}, [58]={hint="亡灵哨兵玛索吉要你带上三只药剂师小瓶，将它们分别放置在希尔斯布莱德丘陵周围的山峰上，然后回去向他复命。", tag="高级怪物。、可选"}, [59]={npc="亡灵哨兵玛索吉", tgt="亡灵哨兵玛索吉", tag="可选"}, [60]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚", tag="集团、可选"}, [61]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚", tag="需要任务 希尔斯布莱德之战、可选"}, [62]={text="从塔伦米尔飞往幽暗城，交纳苦楚药剂和达萨利亚的奖状（如果有）。将您的炉石绑定到塔伦米尔。"}, [63]={hint="把泥头花药交给幽暗城的大药剂师法拉尼尔。"}, [64]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔"}, [65]={hint="把达萨利亚的奖状交给幽暗城的瓦里玛萨斯。", tag="可选"}, [66]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯", tag="可选"}, [67]={hint="到希尔斯布莱德丘陵的塔伦米尔去，把赞吉尔的药剂样品交给瑟尔格·希诺特。"}, [68]={npc="瑟尔格·希诺特", tgt="瑟尔格·希诺特"}, [69]={npc="瑟尔格·希诺特", tgt="瑟尔格·希诺特", desc="继续连锁治愈赞吉尔之触。"}, [70]={hint="等待瑟尔格·希诺特完成解药。", desc="继续连锁治愈赞吉尔之触。"}, [71]={npc="瑟尔格·希诺特", tgt="瑟尔格·希诺特", desc="继续连锁治愈赞吉尔之触。"}, [72]={npc="优美的信件", npcObj=true, tag="可选", desc="您的训练师开始优美的信件。在通道中的盒子上使用侦测陷阱。"}, [73]={hint="把拉文霍德徽记交给拉文霍德庄园的法拉德，庄园就坐落在希尔斯布莱德的群山之中。", tag="可选", desc="您的训练师开始优美的信件。在通道中的盒子上使用侦测陷阱。"}, [74]={npc="法拉德", tgt="法拉德", tag="可选", desc="您的训练师开始优美的信件。在通道中的盒子上使用侦测陷阱。"}, [75]={npc="拉文霍德卫兵", tgt="拉文霍德卫兵", tag="可选", desc="可重复的声誉追求。如果你正在练级，请跳过。"}, [76]={hint="掉落自：辛迪加刺客、辛迪咒术师、辛迪加劫匪", tag="可选", desc="可重复的声誉追求。如果你正在练级，请跳过。"}, [77]={npc="拉文霍德卫兵", tgt="拉文霍德卫兵", tag="可选", desc="可重复的声誉追求。如果你正在练级，请跳过。"}, [78]={npc="麦洛克斯", tgt="麦洛克斯", tag="可选", desc="与敦霍尔德任务一起做这个任务。"}, [79]={hint="潜入希尔斯布莱德丘陵的敦霍尔德城堡，找到并杀死托马斯领主，然后回去向麦洛克斯复命。", tag="可选", desc="与敦霍尔德任务一起做这个任务。"}, [80]={npc="麦洛克斯", tgt="麦洛克斯", tag="可选", desc="与敦霍尔德任务一起做这个任务。"}, [81]={npc="秘密投放点", npcObj=true, tag="可选", desc="秘密投放点村外。分钟。 1级；建议23+。单独使用维尼克斯的炸药。"}, [82]={hint="找到影牙城堡内的谢尔索斯号角。然后，将它送回至焚木村附近C的秘密投放点。你必须独自完成这项任务。", tag="可选", desc="秘密投放点村外。分钟。 1级；建议23+。单独使用维尼克斯的炸药。"}, [83]={npc="秘密投放点", npcObj=true, tag="可选", desc="秘密投放点村外。分钟。 1级；建议23+。单独使用维尼克斯的炸药。"}, [84]={hint="Log", tag="可选", desc="等待邮箱中的后续，然后返回秘密投放点。"}, [85]={npc="秘密投放点", npcObj=true, tag="可选", desc="等待邮箱中的后续，然后返回秘密投放点。"}, [86]={npc="秘密投放点", npcObj=true, tag="可选", desc="25级以上。先学习消失和扰乱。带着邀请返回银松。"}, [87]={hint="找到血色修道院内的波斯卡之眼。然后将它送回至焚木村附近C的秘密投放点。你必须独自完成这项任务。", tag="可选", desc="25级以上。先学习消失和扰乱。带着邀请返回银松。"}, [88]={npc="秘密投放点", npcObj=true, tag="可选", desc="25级以上。先学习消失和扰乱。带着邀请返回银松。"}, [89]={hint="Log", tag="可选", desc="仅在收到后续信件后才返回。"}, [90]={npc="秘密投放点", npcObj=true, tag="可选", desc="仅在收到后续信件后才返回。"}, [91]={hint="用塔伦米尔的井水装满空的红色水囊，然后把它交给贫瘠之地的布瑞恩。", desc="将乱风岗的完整水袋保留在千针石林中。"}, [92]={npc="艾萨莱斯特", tgt="艾萨莱斯特"}, [93]={hint="完成任务目标。"}, [94]={npc="艾萨莱斯特", tgt="艾萨莱斯特"}, [95]={npc="安娜斯塔西娅·哈特威尔", tgt="安娜斯塔西娅·哈特威尔", tag="可选"}, [96]={hint="和迪诺谈一谈。", tag="可选"}, [97]={npc="迪诺", tgt="迪诺", tag="可选"}, [98]={text="在飞艇管理员萨匹塔的西站台 (60.74, 58.87) 在布瑞尔以南登上乱风岗的奥格瑞玛齐柏林飞艇。当乱风岗完成后，到了 29 级，直接从奥格瑞玛到碎木岗哨。"}}},
    ["05-d7"] = {name="Excavation Site: Wetlands", nameA="{a:16732}", entrance="湿地 (瓦拉里尔的搜寻), 47.79, 56.16.", pickup="在 24 级，从 Stonetalon 飞往奥格瑞玛，然后从博斯坦乘坐暗影裂口乘坐 口味的变迁。在塔伦米尔之后，在落锤镇从萨鲁克领取龙喉氏族的流言。穿过萨多尔大桥，经过丹莫德，然后沿着瑟根石附近的山路到达亡灵卫兵密探。进入前接受撬开龙喉。", pickupS={{"在 24 级，从 Stonetalon 飞往奥格瑞玛，然后从博斯坦乘坐暗影裂口乘坐 口味的变迁"}, {"在塔伦米尔之后，在落锤镇从萨鲁克领取龙喉氏族的流言"}, {"穿过萨多尔大桥，经过丹莫德，然后沿着瑟根石附近的山路到达亡灵卫兵密探"}, {"进入前接受撬开龙喉"}}, tips={{k="動線", text="从东入口向西穿过沼泽到达盐脊 → 沿着茂密的小路寻找丛林猛禽和暗齿 → 清除西南营地的龙喉 → 激活挖掘地点的面板并从遗迹守卫者中掠夺遗物。"}, {k="取捨", text="完整的运行涵盖了肉、龙喉派遣和最终 Boss 的遗物。保存上次上交的卡利姆多以便下次奥格瑞玛或雷霆崖访问。"}, {k="說明", text="蓝色副本入口位于维尔加挖掘场东南的高坡。集合石、亡灵卫兵密探和副本入口分别在不同位置。", s={{"蓝色副本入口位于维尔加挖掘场东南的高坡"}, {"集合石、亡灵卫兵密探和副本入口分别在不同位置"}}}}, steps={[1]={npc="博斯坦", tgt="博斯坦"}, [2]={npc="萨鲁克", tgt="萨鲁克"}, [3]={hint="前往湿地，在龙喉营地上方的山头与亡灵卫兵密探接头。"}, [4]={npc="亡灵卫兵密探", tgt="亡灵卫兵密探"}, [5]={npc="亡灵卫兵密探", tgt="亡灵卫兵密探", preText="龙喉氏族的流言"}, [6]={text="Excavation Site: Wetlands 入口"}, [7]={hint="进入湿地的挖掘场，带回灌木丛迅猛龙肉。", desc="位置：经过盐脊的湖，走暗齿前面的灌木丛小道并杀死猛禽。", spot="经过盐脊的湖，走暗齿前面的灌木丛小道并杀死猛禽。"}, [8]={hint="剿灭挖掘场内的龙喉部队，并将搜获的一切物品带给场外的亡灵卫兵密探。", desc="位置：通过暗齿并清除挖掘营地的龙喉部队。", spot="通过暗齿并清除挖掘营地的龙喉部队。"}, [9]={npc="泰坦圣物", npcObj=true, tag="需要游戏内检查", desc="从遗迹守卫者中拾取泰坦圣物并右键单击它以开始任务。"}, [10]={npc="亡灵卫兵密探", tgt="亡灵卫兵密探"}, [11]={npc="博斯坦", tgt="博斯坦"}, [12]={hint="将泰坦圣物带到雷霆崖的长者高地，找人了解它的来历。", desc="从遗迹守卫者中拾取泰坦圣物并右键单击它以开始任务。"}, [13]={npc="巴珊娜·符文图腾", tgt="巴珊娜·符文图腾"}, [14]={npc="巴珊娜·符文图腾", tgt="巴珊娜·符文图腾", desc="在上古知识之后，检查巴莎娜是否再次给你圣物。", preText="长者的智慧"}, [15]={hint="将这件泰坦圣物带给莫高雷西北部观天者台地的穆恩·大地之怒。", desc="在上古知识之后，检查巴莎娜是否再次给你圣物。"}, [16]={npc="阿拉娜·风暴行者", tgt="Muln Earthfury", desc="在上古知识之后，检查巴莎娜是否再次给你圣物。"}}},
    ["05-d6"] = {name="影牙城堡", entrance="银松森林 44.70, 67.80", pickup="在银松之前，在药房领取 乌尔之书，然后在墓地从哈德雷克和达拉尔领取 影牙城堡里的亡灵哨兵 和 除掉阿鲁高。术士可以拾取陶拉祖营地以东的 索兰鲁克宝珠。 亡灵圣骑士应该跟随死亡矿井链从 外交风波 到 月吻之刃 并保持 月吻之刃 活跃。前往希尔斯布莱德途中，返回东部王国后飞至坟墓，然后向南走。", pickupS={{"在银松之前，在药房领取 乌尔之书，然后在墓地从哈德雷克和达拉尔领取 影牙城堡里的亡灵哨兵 和 除掉阿鲁高"}, {"术士可以拾取陶拉祖营地以东的 索兰鲁克宝珠", {class={"WARLOCK"}}}, {"亡灵圣骑士应该跟随死亡矿井链从 外交风波 到 月吻之刃 并保持 月吻之刃 活跃", {race={"Scourge"}, class={"PALADIN"}}}, {"前往希尔斯布莱德途中，返回东部王国后飞至坟墓，然后向南走"}}, tips={{k="動線", text="杀死雷希戈尔并释放阿达曼特→在庭院右侧找到文森特→宴会厅和城墙→芬鲁斯放书的房间→清除塔楼到狼王南杜斯→杀死楼上的阿鲁高并检查他的桌子。"}, {k="取捨", text="在地牢外交出 乌尔之书 和 除掉阿鲁高。将 影牙城堡里的亡灵哨兵 交给里面的文森特。如果您的团队在 22 级之前遇到困难，请先尝试洛丹伦废墟或哀嚎洞穴。"}, {k="說明", text="从瑟伯切尔向南，沿焚木村北坡进入城堡。过外门，副本入口就在庭院旁。想打达拉然城的隐藏首领，就从阿鲁高的桌上拿黑色圣典，再用安伯米尔大厅的地脉装置制成达拉然巨著。", s={{"从瑟伯切尔向南，沿焚木村北坡进入城堡"}, {"过外门，副本入口就在庭院旁"}, {"想打达拉然城的隐藏首领，就从阿鲁高的桌上拿黑色圣典，再用安伯米尔大厅的地脉装置制成达拉然巨著"}}}}, steps={[1]={npc="看守者贝尔杜加", tgt="看守者贝尔杜加"}, [2]={npc="高级执行官哈德瑞克", tgt="高级执行官哈德瑞克"}, [3]={npc="达拉尔·道恩维沃尔", tgt="达拉尔·道恩维沃尔"}, [4]={npc="杜安·卡汉", tgt="杜安·卡汉", tag="可选", desc="在上交之前拾取黑暗深渊中的其他 3 个碎片。"}, [5]={text="影牙城堡 入口"}, [6]={hint="找到亡灵哨兵阿达曼特和亡灵哨兵文森特。", desc="位置：雷希戈尔之后，打开牢房并跟随死亡猎手走上右边的楼梯。", spot="雷希戈尔之后，打开牢房并跟随死亡猎手走上右边的楼梯。"}, [7]={npc="亡灵哨兵文森特", tgt="亡灵哨兵文森特", tag="需要游戏内检查", spot="庭院右侧，亡灵哨兵文森特"}, [8]={hint="把乌尔之书交给幽暗城炼金区里的看守者贝尔杜加。", desc="位置：爬上塔楼。检查芬鲁斯房间左边书柜的底部。", spot="爬上塔楼。检查芬鲁斯房间左边书柜的底部。"}, [9]={hint="找到3块索兰鲁克宝珠的碎片和1块索兰鲁克宝珠的大碎片，把它们交给贫瘠之地的杜安·卡汉。", tag="可选", desc="位置：在塔路上杀死暗影之牙黑暗之魂。仅在术士任务中进行掠夺。", spot="在塔路上杀死暗影之牙黑暗之魂。仅在术士任务中进行掠夺。"}, [10]={hint="杀死阿鲁高，把他的头带给瑟伯切尔的达拉尔·道恩维沃尔。", desc="位置：在狼王南杜斯之后上楼并在他的房间里杀死阿鲁高。", spot="在狼王南杜斯之后上楼并在他的房间里杀死阿鲁高。"}, [11]={hint="到瑟伯切尔与特雷凡·罗尔交谈，并带回他所需的材料。", tag="可选", desc="位置：看看阿鲁高房间的桌子上。仅当使用月之亲吻之刃时才进行掠夺。", spot="看看阿鲁高房间的桌子上。仅当使用月之亲吻之刃时才进行掠夺。"}, [12]={npc="达拉尔·道恩维沃尔", tgt="达拉尔·道恩维沃尔"}, [13]={npc="看守者贝尔杜加", tgt="看守者贝尔杜加"}, [14]={npc="杜安·卡汉", tgt="杜安·卡汉", tag="可选", desc="拾取黑暗深渊中的全部 3 个小碎片，然后在贫瘠之地上交。"}}},
    ["02-13"] = {name="千针石林", tips={{k="交通", text="从奥格瑞玛飞往陶拉祖营地，然后乘坐贫瘠之地南端的大升降梯。 解锁乱风岗首次访问。仅当您有 神圣之火 时才绕道至雷霆崖。"}, {k="取捨", text="将烈日石居的信交给大帝升降梯的守卫。将板条箱、三个鹰身女妖类型和耐力的试炼一起放在乱风岗的西边。"}, {k="取捨", text="视频先介绍了灰谷，然后才提到千针石林绕道。在灰谷链条之前的乱风岗处停止。保存完整的闪光平地循环以供稍后访问千针石林。"}, {k="取捨", text="跳过拉克塔·风歌护航、豹笼和西部巡逻后续行动，除非你有帮助或已经通过目标。"}, {k="提醒", text="剃刀沼泽入口位于贫瘠之地南端，大升降梯之前。如果你在经验上落后，就磨掉乱风岗以西的尖啸鹰身女妖（大约 27、51）。", s={{"剃刀沼泽入口位于贫瘠之地南端，大升降梯之前"}, {"如果你在经验上落后，就磨掉乱风岗以西的尖啸鹰身女妖（大约 27、51）"}}}}, danger={[1]="电梯坠落是致命的。在穿过乱风岗桥或使用北部电梯之前等待站台。", [2]="打开鹰身女妖洞穴中的板条箱会生成敌人。清除附近的小怪并确保你有一条出路。"}, grind={[1]={mob="杂毛土狼", note="乱风岗以西的山谷中普通生物的密度中等。一次将一名敌人拉到谷底并跳过鹰身女妖营地绕道。"}, [2]={mob="尖啸的鹰身人", note="鹰身女妖西部斜坡上正常生物的密度中等。在执行鹰身女妖任务时，消灭边缘孤独的鹰身女妖。"}}, supply={[1]={npc="奈瑟"}, [2]={npc="旅店老板埃比克瓦"}, [3]={npc="斯塔恩"}, [4]={npc="旅店老板埃比克瓦"}, [5]={npc="斯塔恩"}, [6]={npc="莫塔尔"}, [7]={npc="欧姆萨·雷角"}}, steps={[1]={text="确认奥格瑞玛飞艇位于飞艇管理员萨匹塔布瑞尔（60.74, 58.87）以南的西平台。落地后输入奥格瑞玛。如果转返回雷霆崖则飞经雷霆崖，否则直接飞陶拉祖营地。如果仍在塔伦米尔，请先飞往幽暗城。"}, [2]={hint="把林度恩的毒药交给雷霆崖的药剂师扎玛。", tag="如果在塔伦米尔接受、可选"}, [3]={npc="药剂师扎玛", tgt="药剂师扎玛", tag="如果在塔伦米尔接受、可选"}, [4]={text="沿着贫瘠之地南部的道路前往伟大的升降梯并与北侧的守卫交谈。"}, [5]={hint="马格兰希望你将信送到贫瘠之地升降梯的瑞什·远行者手中。", tag="如果在烈日石居接受"}, [6]={npc="瑞什·远行者", tgt="瑞什·远行者", tag="如果在烈日石居接受"}, [7]={npc="卫兵穆赫·月角", tgt="卫兵穆赫·月角"}, [8]={hint="把紧急信件交给乱风岗的峭壁卫兵图林·长角。"}, [9]={npc="峭壁卫兵图林·长角", tgt="峭壁卫兵图林·长角"}, [10]={text="把伟大的升降梯拿下来。沿着山谷向东行驶，乘坐乱风岗缆车向上。了解奈瑟的飞行点 (45.14, 49.11)。保留你的壁炉。"}, [11]={npc="峭壁卫兵图林·长角", tgt="峭壁卫兵图林·长角"}, [12]={npc="哈加尔·雷蹄", tgt="哈加尔·雷蹄"}, [13]={npc="詹迪亚", tgt="詹迪亚"}, [14]={npc="詹迪亚", tgt="詹迪亚", desc="劳恩·峭壁行者也提供此任务（46.14, 51.71）。"}, [15]={npc="艾鲁", tgt="艾鲁"}, [16]={npc="通缉：阿纳克·恐怖图腾", npcObj=true}, [17]={text="清理乱风岗以北的半人马营地，然后前往多恩和风蛇巢穴。"}, [18]={hint="杀掉12个加拉克斥候、10个加拉克争斗者和6个加拉克逐风者，然后向乱风岗的峭壁卫兵图林·长角复命。"}, [19]={npc="多恩·平原行者", tgt="多恩·平原行者"}, [20]={hint="如果你有坚定的信仰，就从那个可以俯瞰千针石林的木板跳下去。", desc="从多恩面前的木板上跳下来。成功的跳跃会将你传送回来。"}, [21]={npc="多恩·平原行者", tgt="多恩·平原行者"}, [22]={npc="多恩·平原行者", tgt="多恩·平原行者"}, [23]={hint="把异型卵交给乱风岗的哈加尔·雷蹄。"}, [24]={npc="峭壁卫兵图林·长角", tgt="峭壁卫兵图林·长角"}, [25]={npc="哈加尔·雷蹄", tgt="哈加尔·雷蹄"}, [26]={npc="峭壁卫兵图林·长角", tgt="峭壁卫兵图林·长角"}, [27]={npc="哈加尔·雷蹄", tgt="哈加尔·雷蹄"}, [28]={text="清除尖叫的鹰身女妖并向西提供补给箱。沿着山谷穿过风巢到达白沙岗哨。"}, [29]={hint="将8份失窃的乱风岗补给品带给乱风岗的詹迪亚。", desc="从乱风岗向西走，爬上鹰身女妖斜坡，到达 阻止尖啸 洞穴中的板条箱。对象 670338 的三个游戏内生成点。"}, [30]={hint="消灭5名尖啸鹰身人、5名尖啸游荡者以及5名尖啸唤风者。"}, [31]={hint="把格林卡的爪子交给千针石林的多恩·平原行者。", desc="先清理山洞。打破后面的板条箱来生成格林卡·血啸。"}, [32]={hint="将10颗双足飞龙的蛋交给乱风岗的艾鲁。"}, [33]={npc="波卡·雨山", tgt="波卡·雨山", tag="护航、可选"}, [34]={hint="护送波卡·雨山走出风巢，然后和白沙岗哨的莫特加·火鬃谈一谈。", tag="护航、可选", desc="在风巢，在护送Pao'ka之前，在出口附近拾取鸡蛋并清除蝎狮。"}, [35]={npc="莫特加·火鬃", tgt="莫特加·火鬃", tag="护航、可选"}, [36]={hint="向莫特加·火鬃汇报你的发现。"}, [37]={npc="莫特加·火鬃", tgt="莫特加·火鬃"}, [38]={npc="莫特加·火鬃", tgt="莫特加·火鬃", tag="如果飞往雷霆崖则接受、可选"}, [39]={npc="维兹罗", tgt="维兹罗", tag="精英、可选"}, [40]={hint="杀了那头野兽，把超适应齿轮和钥匙交给维兹罗。", tag="精英、可选", desc="组团吧只要你打开笼子，精英就会发起攻击。"}, [41]={npc="维兹罗", tgt="维兹罗", tag="精英、可选"}, [42]={npc="暗杀指令", npcObj=true, tag="从巡逻空投开始、可选", desc="加拉克信使在营地之间巡逻。掠夺并使用暗杀指令。"}, [43]={hint="将暗杀计划通知给白沙岗哨的卡纳提·灰云。", tag="从巡逻空投开始、可选", desc="加拉克信使在营地之间巡逻。掠夺并使用暗杀指令。"}, [44]={npc="卡纳提·灰云", tgt="卡纳提·灰云", tag="从巡逻空投开始、可选"}, [45]={npc="卡纳提·灰云", tgt="卡纳提·灰云", tag="从巡逻空投开始、可选"}, [46]={hint="保护卡纳提·灰云免受半人马的袭击。", tag="从巡逻空投开始、可选", desc="在接受之前治愈并饮酒。攻击立即开始。"}, [47]={npc="卡纳提·灰云", tgt="卡纳提·灰云", tag="从巡逻空投开始、可选"}, [48]={text="沿西坡道上黑云峰到达注意处，然后向北穿过桥梁。"}, [49]={hint="在黑云峰拿到三封密信。", desc="走 31.5, 36.7 处的坡道上桥。在所有三个营地中搜索笔记。"}, [50]={hint="杀死阿纳克·恐怖图腾，并向乱风岗的峭壁卫兵图林·长角出示证据。"}, [51]={npc="拉克塔·风歌", tgt="拉克塔·风歌", tag="如果时间允许的话、可选"}, [52]={hint="护送拉克塔·风歌离开恐怖图腾营地，然后与乱风岗的萨利亚谈一谈。", tag="如果时间允许的话、可选", desc="先清理笼子区域和桥梁，然后护送拉科塔下山。"}, [53]={hint="收集10支火岩龙舌兰，然后去找雷霆崖长者高地的玛加萨·恐怖图腾。", tag="如果时间允许的话、可选"}, [54]={text="返回乱风岗进行任务交接。将耐力的试炼交给哨所东北方向的多恩。"}, [55]={npc="峭壁卫兵图林·长角", tgt="峭壁卫兵图林·长角"}, [56]={npc="詹迪亚", tgt="詹迪亚"}, [57]={npc="詹迪亚", tgt="詹迪亚"}, [58]={npc="艾鲁", tgt="艾鲁"}, [59]={npc="多恩·平原行者", tgt="多恩·平原行者"}, [60]={npc="峭壁卫兵图林·长角", tgt="峭壁卫兵图林·长角"}, [61]={npc="萨利亚", tgt="萨利亚", tag="可选"}, [62]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="如果你看到它、可选"}, [63]={hint="把罗卡里姆的碎片交给千针石林的多恩·平原行者。", tag="如果你看到它、可选", desc="在西山谷和风巢附近寻找罗卡里姆。"}, [64]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="如果你看到它、可选"}, [65]={text="如果您已准备好神圣之火 且雷霆崖已解锁，请从乱风岗飞往那里。否则跳过下一次上交并继续。"}, [66]={npc="玛加萨·野性图腾", tgt="玛加萨·野性图腾", tag="交房地址：雷霆崖、可选"}, [67]={npc="布瑞恩", tgt="布瑞恩"}, [68]={npc="布瑞恩", tgt="布瑞恩", desc="在碎木岗哨取水。返回贫瘠之地。"}, [69]={text="从乱风岗或雷霆崖出发。如果碎木岗哨被锁定，则飞往十字路口并向北跑，经过莫尔山城墙进入灰谷，然后沿着东边的路到达Splintertree。"}}},
    ["02-14"] = {name="灰谷", tips={{k="交通", text="解锁碎木岗哨，然后是佐拉姆加前哨站。飞往裂树、烈日石居或十字路口以获得出色的任务交接，或者从佐拉姆加尔直接前往奥格瑞玛。将炉石设置为塔伦米尔。"}, {k="取捨", text="从碎木岗哨开始做三个循环：南边的奔跑者，西南方的湖元素，以及北边的萨特。在佐拉姆加尔一起施展熊怪和洞穴咒语。"}, {k="取捨", text="三兽巡逻。仅当你遇到他们时才杀死他们。稍后交易丢失的页面而不是种植它们。"}, {k="取捨", text="在 29 级，如果您已经前往十字路口和奥格瑞玛，请选择 疯狂的虫群。在奥格瑞玛上交 疯狂的虫群，然后在微光平原上交 疯狂的虫群 解锁 疯狂的虫群。如果链条不碍事，请跳过链条。"}, {k="提醒", text="30级以下？磨碎色狼（大约 67、57）或蓟毛熊怪（大约 32、38）。如果您的团队准备好了，请在 Zoram Strand 上运行黑暗深渊。否则，继续追问。", s={{"30级以下？"}, {"磨碎色狼（大约 67、57）或蓟毛熊怪（大约 32、38）"}, {"如果您的团队准备好了，请在 Zoram Strand 上运行黑暗深渊"}, {"否则，继续追问"}}}}, danger={[1]="阿斯特兰纳是一个联盟城镇，路边有40级哨兵。在前往佐拉姆加尔的路上绕过它。", [2]="熊怪可以堵塞蓟毛要塞中的狭窄通道。在打开箱子或开始护送鲁尔之前清理出一条逃生路线。"}, grind={[1]={mob="魔草巡影者", note="萨特营地外正常生物的密度中等。沿着边缘清理，注意巡逻队和附近的色狼，并收集萨特之角。"}, [2]={mob="幽爪前锋", note="碎木岗哨北部树林中普通生物的密度中等。如果跳过色狼营地，则在飞行点附近的空旷地带一次拉一名敌人。"}, [3]={mob="萨维亚潜行者", note="萨维亚处普通生物的中等密度。留意潜行的暴徒和巡逻队。首先清除外部并完成第 29 关，同时收集萨特之角。"}}, supply={[1]={npc="乌尔格拉"}, [2]={npc="旅店老板凯利斯克"}, [3]={npc="布克拉姆"}, [4]={npc="旅店老板凯利斯克"}, [5]={npc="布克拉姆"}, [6]={npc="安德鲁克"}, [7]={npc="维克塔"}}, steps={[1]={text="从碎木岗哨 (73.18, 61.59) 的乌尔格拉学习飞行点。保留您的塔伦米尔壁炉以供退货。如果您想在灰谷中绑定，请参阅旅店老板凯利斯克 (73.99, 60.65)。"}, [2]={hint="与灰谷碎木哨岗的塞娜尼·雷心谈一谈。", tag="如果棘齿城 / 陶拉祖营地支线接受"}, [3]={npc="塞娜尼·雷心", tgt="塞娜尼·雷心", tag="如果棘齿城 / 陶拉祖营地支线接受"}, [4]={npc="塞娜尼·雷心", tgt="塞娜尼·雷心"}, [5]={hint="完成任务目标。", desc="交 灰谷狩猎，然后做 灰谷狩猎，然后再从掉落物中开始三个狩猎任务。"}, [6]={npc="塞娜尼·雷心", tgt="塞娜尼·雷心"}, [7]={npc="马斯托克·维尔西斯", tgt="马斯托克·维尔西斯"}, [8]={npc="皮克希尔", tgt="皮克希尔"}, [9]={npc="库莱比", tgt="库莱比"}, [10]={npc="古尔达·怒痕", tgt="古尔达·怒痕", tag="检查您是否已经有缺失的页面、可选"}, [11]={text="杀死碎木岗哨以南的灰谷先驱者，然后向西南方向前往湖边。"}, [12]={npc="沙普塔隆的爪子", npcObj=true, tag="如果看到目标就接受、可选", desc="杀死沙普塔隆并右键单击背包中的爪子开始任务。"}, [13]={hint="将沙普塔隆的爪子交给灰谷碎木哨岗的塞娜尼·雷心。", tag="如果看到目标就接受、可选", desc="杀死沙普塔隆并右键单击背包中的爪子开始任务。"}, [14]={hint="杀掉9个灰谷先驱者，然后回到碎木哨岗的库莱比那里。"}, [15]={npc="战歌斥候", tgt="战歌斥候", tag="需要战歌报告、可选", desc="打开报告集，然后与侦察员交易战歌报告。"}, [16]={hint="完成任务目标。", tag="需要战歌报告、可选"}, [17]={npc="战歌斥候", tgt="战歌斥候", tag="需要战歌报告、可选"}, [18]={npc="托雷克", tgt="托雷克", tag="护航、可选"}, [19]={hint="保护在银翼哨站与杜瑞尔·月火作战的托雷克，然后向慰籍之林的埃尔托格·怒齿汇报胜利的消息。", tag="护航、可选", desc="在托雷克等候您的团队。 当您接受护送时，战斗开始。"}, [20]={hint="清除位于碎木哨岗西南和石爪小径正东的密斯特拉湖一带的12个污浊的水元素。"}, [21]={npc="被污染的水球", npcObj=true, tag="如果掉落，请执行以下操作、可选", desc="在湖边找到泰德雷斯。右键单击被污染的水球即可启动。"}, [22]={hint="将被污染的水球交给灰谷碎木哨岗的马斯托克·维尔西斯。", tag="如果掉落，请执行以下操作、可选", desc="在湖边找到泰德雷斯。右键单击被污染的水球即可启动。"}, [23]={npc="乌萨苟斯的爪子", npcObj=true, tag="如果掉落，请执行以下操作、可选", desc="杀死乌萨苟斯并在你的包里右键单击他的爪子开始任务。"}, [24]={hint="将乌萨苟斯的爪子交给灰谷碎木哨岗的的塞娜尼·雷心。", tag="如果掉落，请执行以下操作、可选", desc="杀死乌萨苟斯并在你的包里右键单击他的爪子开始任务。"}, [25]={npc="萨杜布拉的头颅", npcObj=true, tag="如果掉落，请执行以下操作、可选", desc="杀死萨杜布拉并在你的包里右键单击她的头开始任务。"}, [26]={hint="将萨杜布拉的头颅交给灰谷碎木哨岗的的塞娜尼·雷心。", tag="如果掉落，请执行以下操作、可选", desc="杀死萨杜布拉并在你的包里右键单击她的头开始任务。"}, [27]={text="沿着湖东北方向碎木岗哨行驶。回去的路上击杀奥达努斯并清理色狼营地。"}, [28]={hint="将奥达努斯的头颅带给石爪峰的布莱林·火拳。", tag="如果在烈日石居接受、可选"}, [29]={hint="为碎木哨岗的皮克希尔收集16只萨特的角。"}, [30]={npc="战歌侦查骑兵", tgt="战歌侦查骑兵", tag="需要战歌报告、可选"}, [31]={hint="完成任务目标。", tag="需要战歌报告、可选"}, [32]={npc="战歌侦查骑兵", tgt="战歌侦查骑兵", tag="需要战歌报告、可选"}, [33]={npc="库莱比", tgt="库莱比"}, [34]={npc="马斯托克·维尔西斯", tgt="马斯托克·维尔西斯"}, [35]={npc="皮克希尔", tgt="皮克希尔"}, [36]={npc="埃尔托格·怒齿", tgt="埃尔托格·怒齿", tag="护送后上交、可选"}, [37]={npc="塞娜尼·雷心", tgt="塞娜尼·雷心", tag="一旦你抓住了就上交、可选"}, [38]={npc="塞娜尼·雷心", tgt="塞娜尼·雷心", tag="一旦你抓住了就上交、可选"}, [39]={npc="塞娜尼·雷心", tgt="塞娜尼·雷心", tag="一旦你抓住了就上交、可选"}, [40]={npc="塞娜尼·雷心", tgt="塞娜尼·雷心", tag="一旦你抓住了就上交、可选"}, [41]={hint="完成任务目标。", tag="一旦你抓住了就上交、可选"}, [42]={npc="塞娜尼·雷心", tgt="塞娜尼·雷心", tag="一旦你抓住了就上交、可选"}, [43]={npc="马斯托克·维尔西斯", tgt="马斯托克·维尔西斯", tag="如果您抢劫水地球仪，请接受、可选"}, [44]={npc="马斯托克·维尔西斯", tgt="马斯托克·维尔西斯", tag="如果您抢劫水地球仪，请接受、可选"}, [45]={hint="找到丢失的12页伐木机操作指南，把它们合并为第1、2、3章。然后带着这些书页回到碎木岗哨去找古尔达·怒痕。", tag="需要所有页面、可选", desc="不要种植缺失的页面。使用包中的页面来组装章节。"}, [46]={npc="古尔达·怒痕", tgt="古尔达·怒痕", tag="需要所有页面、可选"}, [47]={text="如果解锁，则飞往佐拉姆加前哨站。第一次访问时，走灰谷的路向西，避开阿斯特兰纳的联盟守卫，然后继续前往海岸。从安德鲁克 (12.24, 33.80) 学习飞行点。"}, [48]={hint="将被污染的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。", tag="如果您有水 Globe 引导任务、可选"}, [49]={npc="耶努萨克雷", tgt="耶努萨克雷", tag="如果您有水 Globe 引导任务、可选"}, [50]={npc="战歌信使", tgt="战歌信使", tag="需要战歌报告、可选"}, [51]={hint="完成任务目标。", tag="需要战歌报告、可选"}, [52]={npc="战歌信使", tgt="战歌信使", tag="需要战歌报告、可选"}, [53]={npc="卡拉恩·阿玛卡", tgt="卡拉恩·阿玛卡"}, [54]={npc="米苏瓦", tgt="米苏瓦"}, [55]={npc="玛鲁凯", tgt="玛鲁凯", tag="低级小怪可获得额外经验、可选"}, [56]={hint="将20颗怒尾纳迦的头颅交给佐拉姆海岸的玛鲁凯。", tag="低级小怪可获得额外经验、可选"}, [57]={npc="玛鲁凯", tgt="玛鲁凯", tag="低级小怪可获得额外经验、可选"}, [58]={text="沿东路行驶至蓟皮村。杀死熊怪并掠夺村庄北部洞穴中的护身符。"}, [59]={hint="杀死12个蓟皮复仇者和12个蓟皮萨满祭司。他们大部分都位于佐拉姆海岸东部的蓟皮村里。任务完成后回到灰谷佐拉姆加前哨站的卡拉恩·阿玛卡那里复命。"}, [60]={hint="将8个巨魔符咒交给佐拉姆加前哨站的米苏瓦。"}, [61]={npc="鲁尔·雪蹄", tgt="鲁尔·雪蹄", tag="护航、可选"}, [62]={hint="护送鲁尔，然后与慰藉之林的雅玛·雪蹄谈一谈。", tag="护航、可选", desc="怪物会在入口和内部生成。在接受之前清除通道。"}, [63]={npc="卡拉恩·阿玛卡", tgt="卡拉恩·阿玛卡"}, [64]={npc="米苏瓦", tgt="米苏瓦"}, [65]={npc="卡拉恩·阿玛卡", tgt="卡拉恩·阿玛卡", tag="返回东部营地、可选"}, [66]={hint="把卡拉恩的旗子插到污林图腾堆中。不要让熊怪摧毁这面旗子。击败穆戈特酋长，将穆戈特的图腾交给佐拉姆加的卡拉恩·阿玛卡。", tag="返回东部营地、可选", desc="在插旗之前清理该区域。准备好控制波浪。"}, [67]={npc="卡拉恩·阿玛卡", tgt="卡拉恩·阿玛卡", tag="返回东部营地、可选"}, [68]={npc="穆格拉什", tgt="穆格拉什", tag="团体护送、可选"}, [69]={hint="在穆格拉什寻找火盆的过程中保证他的安全。帮助他扑灭火盆，然后在与纳迦作战时保护他。", tag="团体护送、可选"}, [70]={npc="战歌信使", tgt="战歌信使", tag="团体护送、可选"}, [71]={text="如果您需要上交鲁尔的自由或在那里有其他任务，请从佐拉姆加前哨站飞往碎木岗哨。如果绑定在那里并准备好，则取而代之的是壁炉。如果您跳过了护送并且没有任务交接，请直接从佐拉姆加尔飞往下一站。"}, [72]={npc="雅玛·雪蹄", tgt="雅玛·雪蹄", tag="如果护送完成、可选"}, [73]={text="如果 奥达努斯 已完成或者您计划继续 新的指示，请从佐拉姆加尔或 Splintertree 飞往烈日石居 (45.12, 59.84)。如果石爪山畅通无阻，请跳过此行。"}, [74]={npc="布莱林·火拳", tgt="布莱林·火拳", tag="如果在烈日石居接受、可选"}, [75]={hint="把新的指令带给石爪山的菲兹克斯。", tag="如果接受并返回狂风峭壁、可选"}, [76]={npc="菲兹克斯", tgt="菲兹克斯", tag="如果接受并返回狂风峭壁、可选"}, [77]={npc="菲兹克斯", tgt="菲兹克斯", tag="如果接受并返回狂风峭壁、可选"}, [78]={hint="将格雷苏的机械臂带给石爪山脉的菲兹克斯。", tag="如果接受并返回狂风峭壁、可选", desc="走狂风峭壁以北的匝道到达站台。别往湖里看。格雷苏在高架上。"}, [79]={npc="菲兹克斯", tgt="菲兹克斯", tag="如果接受并返回狂风峭壁、可选"}, [80]={npc="布莱林·火拳", tgt="布莱林·火拳", tag="稍后或与一群人一起、可选"}, [81]={hint="到石爪峰上的洞穴中去，使用守门人的钥匙拿到能打开石爪峰顶的猛禽洞穴储藏室的物品。", tag="稍后或与一群人一起、可选", desc="守卫和洞穴暴民挤在一起。如果您在附近，请与一群人一起去。前三个引脚标记缓存。最后一个标记为 Talon Den Hoard。"}, [82]={npc="猛禽洞穴储藏室", npcObj=t