"可选"}, [145]={hint="给十字路口的基尔哈拉带去12缕欢笑姐妹的头发。", tag="可选"}, [146]={npc="基尔哈拉", tgt="基尔哈拉", tag="可选"}, [147]={npc="基尔哈拉", tgt="基尔哈拉", tag="可选"}, [148]={hint="完成任务目标。", tag="可选"}, [149]={npc="基尔哈拉", tgt="基尔哈拉", tag="可选"}, [150]={text="上交战歌报告后，返回十字路口并飞往奥格瑞玛。否则从碎木岗哨、佐拉姆加前哨站或烈日石居出发。训练30级技能，然后从弗雷萨的平台（50.82, 13.54）获取提瑞斯法飞艇。在布瑞尔下车，前往幽暗城。仅当您没有幽暗城任务或训练时，才可以使用炉石返回塔伦米尔。"}}},
    ["05-d8"] = {name="黑暗深渊", entrance="灰谷 16.50, 11.00", pickup="在烈日石居接受来自苏纳曼的 帮助耶努萨克雷 并将其保存为佐拉姆加尔的耶努萨克雷。术士可以在贫瘠之地拿索兰鲁克宝珠。 亡灵圣骑士应该将坟墓中的 月吻之刃 保留在他们的日志中。在佐拉姆海岸拾取 阿库麦尔水晶 和 废墟之间。如果你在外层洞穴中抢劫了纸条，请在进入之前将其在前哨站上交。 亡灵圣骑士可以拿走 寻找科尔宝石。", pickupS={{"在烈日石居接受来自苏纳曼的 帮助耶努萨克雷 并将其保存为佐拉姆加尔的耶努萨克雷"}, {"术士可以在贫瘠之地拿索兰鲁克宝珠"}, {"亡灵圣骑士应该将坟墓中的 月吻之刃 保留在他们的日志中"}, {"在佐拉姆海岸拾取 阿库麦尔水晶 和 废墟之间"}, {"如果你在外层洞穴中抢劫了纸条，请在进入之前将其在前哨站上交"}, {"亡灵圣骑士可以拿走 寻找科尔宝石"}}, tips={{k="動線", text="沿着被淹没的洞穴到达加摩拉的水池，在水下侧洞中找到Thaelrid→经过萨利维丝和格里哈斯特到达暮光营地的洛古斯·杰特。术士在那里掠夺碎片。使用桥下的石头找到阿夸尼斯和他的地球仪 → 凯里斯 → 让团队做好准备，然后点燃阿库麦尔的所有四个火盆。"}, {k="取捨", text="执行 阿库麦尔水晶 并在外洞中寻找一趟纸条。如果纸条没有掉落，就继续做其他任务。 亡灵圣骑士与 寻找科尔宝石 可以在同一回合中完成它。", s={{"执行 阿库麦尔水晶 并在外洞中寻找一趟纸条"}, {"如果纸条没有掉落，就继续做其他任务"}, {"亡灵圣骑士与 寻找科尔宝石 可以在同一回合中完成它", {race={"Scourge"}, class={"PALADIN"}}}}}, {k="說明", text="游泳位于佐拉姆海岸西北端的废墟中。沿着水下通道穿过洞穴到达地牢入口。克尔里斯周围的火盆每个都会引发一道波。 光明一次一个。", s={{"游泳位于佐拉姆海岸西北端的废墟中"}, {"沿着水下通道穿过洞穴到达地牢入口"}, {"克尔里斯周围的火盆每个都会引发一道波"}, {"光明一次一个"}}}}, steps={[1]={npc="苏纳曼", tgt="苏纳曼"}, [2]={hint="与灰谷的耶努萨克雷谈一谈。"}, [3]={npc="耶努萨克雷", tgt="耶努萨克雷"}, [4]={npc="耶努萨克雷", tgt="耶努萨克雷", desc="先到佐拉姆加前哨站领取。"}, [5]={hint="收集20颗阿库麦尔蓝宝石，把它们交给灰谷的耶努萨克雷。", desc="先到佐拉姆加前哨站领取。"}, [6]={npc="潮湿的便笺", npcObj=true, tag="可选", desc="前置任务：帮助耶努萨克雷；同时让 阿库麦尔水晶 保持已接。若刷不到便笺，整组不必等待。", preText="帮助耶努萨克雷"}, [7]={hint="把潮湿的便笺交给灰谷的耶努萨克雷。", tag="可选", desc="前置任务：帮助耶努萨克雷；同时让 阿库麦尔水晶 保持已接。若刷不到便笺，整组不必等待。"}, [8]={npc="耶努萨克雷", tgt="耶努萨克雷", tag="可选", desc="前置任务：帮助耶努萨克雷；同时让 阿库麦尔水晶 保持已接。若刷不到便笺，整组不必等待。"}, [9]={npc="耶努萨克雷", tgt="耶努萨克雷", tag="可选", desc="上交潮湿的便笺（上古之神的仆从），然后从同一个NPC处接受。", preText="上古之神的仆从"}, [10]={npc="耶努萨克雷", tgt="耶努萨克雷"}, [11]={npc="乌瑞克·霜帷", tgt="乌瑞克·霜帷", tag="可选", desc="拿一把月吻之刃。在上交之前先在此处获取净化过的科尔宝石。"}, [12]={hint="给灰谷的乌瑞克·霜帷带去一枚科尔宝石。", tag="可选"}, [13]={npc="乌瑞克·霜帷", tgt="乌瑞克·霜帷", tag="可选"}, [14]={text="黑暗深渊 入口"}, [15]={npc="银月守卫塞尔瑞德", tgt="银月守卫塞尔瑞德", tag="需要游戏内检查", desc="在暮光祭坛前的海龟池旁的被淹没的通道中找到 Thaelrid。"}, [16]={hint="杀掉黑暗深渊里的洛古斯·杰特，然后向灰谷的耶努萨克雷复命。", tag="可选", desc="位置：经过格里哈斯特的被淹没的洞穴，在暮光营地找到洛古斯·杰特。", spot="经过格里哈斯特的被淹没的洞穴，在暮光营地找到洛古斯·杰特。"}, [17]={hint="找到3块索兰鲁克宝珠的碎片和1块索兰鲁克宝珠的大碎片，把它们交给贫瘠之地的杜安·卡汉。", tag="可选", desc="位置：杀死暮光营地的助手进入圣所并掠夺三块碎片。", spot="杀死暮光营地的助手进入圣所并掠夺三块碎片。"}, [18]={hint="把暮光领主克尔里斯的头颅交给雷霆崖的巴珊娜·符文图腾。", desc="位置：上岸进入月球圣所。在暮光祭坛处杀死凯里斯。顺序：对于步骤 18-19，先进入水下，然后进入保护区。", spot="上岸进入月球圣所。在暮光祭坛处杀死凯里斯。"}, [19]={hint="把深渊之核交给灰谷佐拉姆加前哨站里的耶努萨克雷。", desc="位置：俯冲在祭坛废墟的桥下。使用深渊之石作为核心。顺序：在点击石头召唤阿奎尼斯男爵进行第 19 步之前先分组。", spot="俯冲在祭坛废墟的桥下。使用深渊之石作为核心。"}, [20]={npc="奇怪的水球", npcObj=true, tag="需要游戏内检查", desc="杀死阿奎尼斯男爵，掠夺地球仪，然后右键单击它开始任务。"}, [21]={npc="耶努萨克雷", tgt="耶努萨克雷"}, [22]={npc="耶努萨克雷", tgt="耶努萨克雷"}, [23]={npc="耶努萨克雷", tgt="耶努萨克雷", tag="可选"}, [24]={hint="把奇怪的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。"}, [25]={npc="耶努萨克雷", tgt="耶努萨克雷"}, [26]={npc="巴珊娜·符文图腾", tgt="巴珊娜·符文图腾"}}},
    ["03-15"] = {name="希尔斯布莱德丘陵", tips={{k="取捨", text="31级以下？在希尔斯布莱德洞穴中杀死雪人。"}, {k="取捨", text="完成上一轮任务即可解锁达拉然巡逻队和地缚护腕任务。在西侧环路进行。如果通过则接取城市关键任务，如果您愿意，可以跳过达拉然城。"}, {k="取捨", text="完成拯救行动来解锁秘密潜入。将其保存为奥特兰克山脉。如果您还没有完成早期任务，请跳过沿海苦楚药剂分支。"}, {k="提醒", text="赫尔库拉的坟墓位于联盟镇南海镇附近。从城外过来。", s={{"赫尔库拉的坟墓位于联盟镇南海镇附近"}, {"从城外过来"}}}, {k="提醒", text="将 30-32 级腿与阿拉希高地中的落锤镇结合起来。需要经验吗？在希尔斯布莱德西山麓（45、29 左右）杀死普通雪人，或者在落锤镇追上。", s={{"将 30-32 级腿与阿拉希高地中的落锤镇结合起来"}, {"需要经验吗？"}, {"在希尔斯布莱德西山麓（45、29 左右）杀死普通雪人，或者在落锤镇追上"}}}}, danger={[1]="55级联盟守卫巡逻南海镇。绕过城镇到达赫尔库拉的复仇的坟墓。", [2]="雪人洞穴入口处的重生很密集。清理外部，同时寻找赫尔库拉的魔棒。进入前保留逃生路线。"}, grind={[1]={mob="洞穴雪人", note="西雪人洞外的斜坡上有密集的普通怪物。一次将一名敌人从入口处拉开。从 30 级开始。"}, [2]={mob="凶恶的雪人", note="洞穴入口处密集的普通怪物与洞穴雪人混在一起。首先清除 31-32 级经验的外边缘。"}}, supply={[1]={npc="扎瑞斯"}, [2]={npc="旅店老板沙恩"}, [3]={npc="旅店老板沙恩"}, [4]={npc="凯伦·苏萨隆"}, [5]={npc="高顿·温德哈姆"}, [6]={npc="托马斯·莫丹"}, [7]={npc="艾泽基尔·格瑞乌斯"}}, steps={[1]={text="如果您在碎木岗哨之后乘坐齐柏林飞艇，请从布瑞尔的南塔前往幽暗城。如果在卡利姆多搭乘航线，则飞往奥格瑞玛，火车，然后乘坐飞艇。 如果需要，解锁幽暗城的飞行点和迈克尔·加勒特 (63.25, 48.56)。"}, [2]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", tag="需要幽暗城先决条件、可选"}, [3]={text="从幽暗城飞往塔伦米尔。"}, [4]={text="了解塔伦米尔飞行点（60.14, 18.62）并绑定您的炉石。"}, [5]={npc="学徒塞万德", tgt="学徒塞万德"}, [6]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [7]={npc="看守者贝瓦里尔", tgt="看守者贝瓦里尔"}, [8]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [9]={npc="塔隆", tgt="塔隆"}, [10]={text="山麓洞穴 → 达拉然营地"}, [11]={hint="从雪怪手上拿回赫尔库拉的魔棒，把它交给塔伦米尔的学徒塞万德。", desc="找到南海镇外面的墓碑。避开联盟守卫。"}, [12]={npc="学徒塞万德", tgt="学徒塞万德"}, [13]={npc="学徒塞万德", tgt="学徒塞万德"}, [14]={hint="去找到那些叛徒，夺回神器，然后向我复命，<name>。"}, [15]={hint="收集10个用旧的石雕，把它们带给塔伦米尔的看守者贝尔杜加。"}, [16]={hint="为塔伦米尔的大法师沃迪恩·伍德格莱尔取得达拉然下水道钥匙。"}, [17]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [18]={npc="看守者贝瓦里尔", tgt="看守者贝瓦里尔"}, [19]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [20]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [21]={npc="看守者贝瓦里尔", tgt="看守者贝瓦里尔"}, [22]={hint="消灭6个达拉然召唤师和8个元素奴仆，然后回到塔伦米尔去见大法师沃迪恩·伍德格莱尔。"}, [23]={hint="为塔伦米尔的看守者贝瓦里尔收集4个地缚护腕。", desc="杀死达拉然附近的被奴役元素以获得护腕。"}, [24]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [25]={npc="看守者贝瓦里尔", tgt="看守者贝瓦里尔"}, [26]={text="碧玉矿洞和南海镇附近的海岸"}, [27]={hint="将泥头花水、1瓶强效巨魔之血药水、5片刺脊纳迦的鳞片和5颗碎鳍鱼人的眼球交给塔伦米尔的药剂师林度恩。", tag="可选"}, [28]={hint="将埃希尔之焰、沃拉兹之焰和尤基尔之焰的力量注入赫尔库拉的魔棒。"}, [29]={npc="赫尔库拉的墓地", npcObj=true}, [30]={npc="药剂师林度恩", tgt="药剂师林度恩", tag="可选"}, [31]={npc="药剂师林度恩", tgt="药剂师林度恩", tag="可选"}, [32]={hint="将一桶矿工烈酒交给塔伦米尔的药剂师林度恩。", tag="可选"}, [33]={npc="药剂师林度恩", tgt="药剂师林度恩", tag="可选"}, [34]={npc="药剂师林度恩", tgt="药剂师林度恩", tag="可选"}, [35]={hint="把被污染的酒桶放在被俘农夫房间的地毯上。", tag="可选"}, [36]={npc="布满灰尘的毯子", npcObj=true, tag="可选"}, [37]={npc="索瑞克", tgt="索瑞克", desc="在穿越到东部王国之前开始狂暴姿态。询问城市战士培训师。"}, [38]={hint="和克兰诺克·马克雷德谈一谈。", desc="在穿越到东部王国之前开始狂暴姿态。询问城市战士培训师。"}, [39]={npc="克兰诺克·马克雷德", tgt="克兰诺克·马克雷德", desc="在穿越到东部王国之前开始狂暴姿态。询问城市战士培训师。"}, [40]={npc="克兰诺克·马克雷德", tgt="克兰诺克·马克雷德", desc="在踏上炉排之前先储备一下。学完狂暴姿态。"}, [41]={hint="杀掉比格维尔，然后向勇士岛的克兰诺克·马克雷德回复。", desc="在踏上炉排之前先储备一下。学完狂暴姿态。"}, [42]={npc="克兰诺克·马克雷德", tgt="克兰诺克·马克雷德", desc="在踏上炉排之前先储备一下。学完狂暴姿态。"}, [43]={npc="克兰诺克·马克雷德", tgt="克兰诺克·马克雷德", tag="可选", desc="与狂暴姿态分开启动旋风斩武器链。"}, [44]={hint="和捕风者巴斯拉谈一谈。", tag="可选", desc="与狂暴姿态分开启动旋风斩武器链。"}, [45]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="与狂暴姿态分开启动旋风斩武器链。"}, [46]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="在荆棘谷获取血顶獠牙并在落锤镇附近获取护身符。返回巴斯拉。"}, [47]={hint="击败堕落的水之魂，把堕落水之魂的护腕和剩余的最纯净的水放在银松森林的圣泉火盆上。", desc="先在碎木岗哨处进行送水。如果您的 Sapta 过期，请联系 Tiev。"}, [48]={npc="圣泉火盆", npcObj=true, tag="需要游戏内检查", desc="先在碎木岗哨处进行送水。如果您的 Sapta 过期，请联系 Tiev。"}, [49]={npc="圣泉火盆", npcObj=true, tag="需要游戏内检查"}, [50]={hint="和银松森林的水之魂谈一谈。"}, [51]={npc="水之魂", tgt="水之魂"}, [52]={npc="水之魂", tgt="水之魂", desc="当您返回卡利姆多时，请在微光平原上交。"}, [53]={npc="甘鲁尔·血眼", tgt="甘鲁尔·血眼", tag="可选", desc="奥格瑞玛引导任务。拿这个或者寻找斯坦哈德，或者直接去棘齿城。"}, [54]={hint="与棘齿城的斯坦哈德·法尔杉谈一谈。", tag="可选", desc="奥格瑞玛引导任务。拿这个或者寻找斯坦哈德，或者直接去棘齿城。"}, [55]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", tag="可选", desc="奥格瑞玛引导任务。拿这个或者寻找斯坦哈德，或者直接去棘齿城。"}, [56]={npc="凯伦丁·哈加尔", tgt="凯伦丁·哈加尔", tag="可选", desc="幽暗城引导任务。拿这个或者寻找斯坦哈德，或者直接去棘齿城。"}, [57]={hint="在棘齿城找到斯坦哈德·法尔杉。", tag="可选", desc="幽暗城引导任务。拿这个或者寻找斯坦哈德，或者直接去棘齿城。"}, [58]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", tag="可选", desc="幽暗城引导任务。拿这个或者寻找斯坦哈德，或者直接去棘齿城。"}, [59]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉"}, [60]={hint="和幽暗城的约拉·安尼森谈一谈。"}, [61]={npc="约拉·安尼森", tgt="约拉·安尼森"}, [62]={npc="约拉·安尼森", tgt="约拉·安尼森", desc="抢劫西南希尔斯布莱德海岸的书和南方千针石林的手稿。"}, [63]={hint="给幽暗城的约拉·安尼森带回发霉的书籍和破损的手稿。", desc="抢劫西南希尔斯布莱德海岸的书和南方千针石林的手稿。"}, [64]={npc="约拉·安尼森", tgt="约拉·安尼森", desc="抢劫西南希尔斯布莱德海岸的书和南方千针石林的手稿。"}, [65]={npc="约拉·安尼森", tgt="约拉·安尼森", desc="从龙喉白骨卫士或暗影卫士身上拾取 3 根权杖。将书/棒带到棘齿城。"}, [66]={hint="将翻修过的书籍和3根导能魔棒交给棘齿城的斯坦哈德·法尔杉。", desc="从龙喉白骨卫士或暗影卫士身上拾取 3 根权杖。将书/棒带到棘齿城。"}, [67]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", desc="从龙喉白骨卫士或暗影卫士身上拾取 3 根权杖。将书/棒带到棘齿城。"}, [68]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", desc="在棘齿城塔旁的圆圈处使用阴谋之书。杀死地狱猎手。"}, [69]={hint="召唤地狱猎犬并打败它，然后把阴谋之书交给棘齿城的斯坦哈德·法尔杉。", desc="在棘齿城塔旁的圆圈处使用阴谋之书。杀死地狱猎手。"}, [70]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", desc="在棘齿城塔旁的圆圈处使用阴谋之书。杀死地狱猎手。"}, [71]={text="从塔伦米尔向东穿过索拉丁之墙进入阿拉希高地。"}}},
    ["05-d10"] = {name="达拉然城", entrance="奥特兰克山脉 8.46, 59.21", pickup="从塔伦米尔中的梅里萨拉中取出 墓穴骑士，从幽暗城中的马丁·费尔本中取出 力量之源。 30级时，从Wordeen拿走入室偷窃和城市大门钥匙。沿着洛丹米尔湖向东南方向前往拘留营，获取鸡血石和钥匙。在塔伦米尔交回，然后做 达拉然巡逻队 并采取 喋血街头。沿着湖岸到莫德拉的图像，采取 动乱之源，并保留下水道钥匙。", pickupS={{"从塔伦米尔中的梅里萨拉中取出 墓穴骑士，从幽暗城中的马丁·费尔本中取出 力量之源"}, {"30级时，从Wordeen拿走入室偷窃和城市大门钥匙"}, {"沿着洛丹米尔湖向东南方向前往拘留营，获取鸡血石和钥匙"}, {"在塔伦米尔交回，然后做 达拉然巡逻队 并采取 喋血街头"}, {"沿着湖岸到莫德拉的图像，采取 动乱之源，并保留下水道钥匙"}}, tips={{k="動線", text="在下水道入口处接起妖精任务→杀死Atrexis，然后可选择进入Lynn的符文室→走正确的道路到街道并掠夺建筑核心→在城堡左侧的楼上拿到书→通往紫罗兰客厅的门户以获得大法师的影魔。把书交给入口处的雷克西。"}, {k="取捨", text="部落先决条件从 30 级开始。在组建团队之前完成访问任务。检查谁拥有钥匙，并获取自己的钥匙以供以后运行。如果您的团队需要被无视的琳恩，请从影牙城堡中携带达拉然巨著。"}, {k="說明", text="莫德拉的图像和地牢入口位于不同的位置。从洛丹米尔湖下水道一侧接近。派系限制适用于室外城门和 NPC 通道。", s={{"莫德拉的图像和地牢入口位于不同的位置"}, {"从洛丹米尔湖下水道一侧接近"}, {"派系限制适用于室外城门和 NPC 通道"}}}}, steps={[1]={npc="马丁·费尔本", tgt="马丁·费尔本"}, [2]={npc="梅里萨拉", tgt="梅里萨拉"}, [3]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [4]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [5]={hint="去找到那些叛徒，夺回神器，然后向我复命，<name>。"}, [6]={hint="为塔伦米尔的大法师沃迪恩·伍德格莱尔取得达拉然下水道钥匙。"}, [7]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [8]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [9]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔", preText="入室偷窃、城市大门钥匙"}, [10]={hint="消灭6个达拉然召唤师和8个元素奴仆，然后回到塔伦米尔去见大法师沃迪恩·伍德格莱尔。"}, [11]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [12]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔", preText="达拉然巡逻队、城市大门钥匙"}, [13]={hint="沿着洛丹米尔湖，寻找潜入达拉然的路线。"}, [14]={npc="大法师茉德拉的影像", tgt="大法师茉德拉的影像"}, [15]={npc="大法师茉德拉的影像", tgt="大法师茉德拉的影像", desc="接受即可获取达拉然下水道钥匙 (277507)。肮脏的钥匙是先决条件。", preText="喋血街头"}, [16]={text="达拉然城 入口"}, [17]={npc="Rexxie Copperclutch", tag="需要游戏内检查", desc="在下水道右侧的格栅后面寻找妖精。"}, [18]={hint="在达拉然城击败墓穴骑士阿特雷克斯，向塔伦米尔的梅里萨拉复命。", desc="位置：沿着主下水道隧道到达空旷区域并杀死Atrexis。", spot="沿着主下水道隧道到达空旷区域并杀死Atrexis。"}, [19]={hint="在达拉然城，为幽暗城的马丁·费尔本收集6个开裂的哨兵核心。", desc="位置：经过坟墓骑士后，前往右侧的街道。杀死破碎哨兵。", spot="经过坟墓骑士后，前往右侧的街道。杀死破碎哨兵。"}, [20]={hint="在达拉然城，为下水道入口附近的雷克希·铜抓取回《达拉然的建立》。", desc="位置：上城堡台阶左侧建筑物的楼上。检查雕像后面。", spot="上城堡台阶左侧建筑物的楼上。检查雕像后面。"}, [21]={npc="Rexxie Copperclutch", tag="需要游戏内检查"}, [22]={hint="在达拉然城，为塔伦米尔的大法师沃迪恩·伍德格莱尔收集奥术微粒。", desc="位置：使用紫罗兰城堡传送门前往紫罗兰客厅。杀死大法师的影魔。", spot="使用紫罗兰城堡传送门前往紫罗兰客厅。杀死大法师的影魔。"}, [23]={npc="梅里萨拉", tgt="梅里萨拉"}, [24]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [25]={npc="马丁·费尔本", tgt="马丁·费尔本"}, [26]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔", desc="部落 ：转到外面湖边的图像。跟随你的任务标记。", preText="动乱之源"}, [27]={hint="与达拉然附近的<name>法师茉德拉的影像对话。", desc="部落 ：转到外面湖边的图像。跟随你的任务标记。"}, [28]={npc="大法师茉德拉的影像", tgt="大法师茉德拉的影像", desc="部落 ：转到外面湖边的图像。跟随你的任务标记。"}}},
    ["05-d9"] = {name="血色修道院 墓地", entrance="提瑞斯法林地 85.20, 32.10", pickup="途中解锁塔伦米尔，然后从幽暗城沿着北路穿过提瑞斯法到达修道院。首先完成剃刀沼泽任务 蝙蝠的粪便。如果您在千针石林之后运行 RFK，请将 狂热之心 保存到奥特兰克山脉腿并立即在墓地中执行 Vorrel。在药剂室见法拉内尔。离开墓地后，前往奥特兰克湖岸和塔伦米尔。", pickupS={{"途中解锁塔伦米尔，然后从幽暗城沿着北路穿过提瑞斯法到达修道院"}, {"首先完成剃刀沼泽任务 蝙蝠的粪便"}, {"如果您在千针石林之后运行 RFK，请将 狂热之心 保存到奥特兰克山脉腿并立即在墓地中执行 Vorrel"}, {"在药剂室见法拉内尔"}, {"离开墓地后，前往奥特兰克湖岸和塔伦米尔"}}, tips={{k="動線", text="在入口大厅清除十字军并掠夺红心→杀死维沙斯并在架子上找到沃雷尔→穿过开阔的墓地并下降到血法师萨尔诺斯。"}, {k="取捨", text="墓地很容易早期分组。即使你还没有完成 蝙蝠的粪便，也可以做 Vorrel。"}, {k="說明", text="从最左边的入口走。墓地不需要猩红钥匙。", s={{"从最左边的入口走"}, {"墓地不需要猩红钥匙"}}}}, steps={[1]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", tag="可选", desc="仅当先执行剃刀沼泽时才接起。适合微光平底鞋腿。"}, [2]={hint="帮幽暗城的大药剂师法拉尼尔带回一堆沼泽蝙蝠的粪便。", tag="可选", desc="此步骤位于剃刀沼泽中。"}, [3]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", tag="可选"}, [4]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", tag="可选", desc="请参阅 蝙蝠的粪便 的剃刀沼泽。四个翅膀中的红心都会掉落，因此请在跑步前拾取。", preText="蝙蝠的粪便"}, [5]={text="血色修道院 墓地 入口"}, [6]={npc="沃瑞尔·森加斯", tgt="沃瑞尔·森加斯", tag="需要游戏内检查", desc="在第一个审讯室的架子上找到沃雷尔。"}, [7]={hint="幽暗城的大药剂师法拉尼尔需要20颗狂热之心。", tag="可选", desc="位置：从入口大厅到审讯室，清除活生生的血色十字军。", spot="从入口大厅到审讯室，清除活生生的血色十字军。"}, [8]={hint="把沃瑞尔·森加斯的结婚戒指还给塔伦米尔的莫尼卡·森古特斯。", desc="房间里可能还有另一位精英。等她巡逻到码头。"}, [9]={npc="莫尼卡·森古特斯", tgt="莫尼卡·森古特斯"}, [10]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", tag="可选", desc="收集全部 20 个，然后交到幽暗城。"}}},
    ["03-16"] = {name="阿拉希高地", nameA="阿拉希高地 {a:321}", tips={{k="取捨", text="清除落锤镇附近的猛禽和辛迪加小怪以及东南方的枯木小怪。如果你已经达到32级，请保存后面的短兵相接和迅猛龙的狡诈任务以供回访。"}, {k="取捨", text="病房补给和丝质缝合线是《永远》中的新增内容。交出 丝滑缝合 来解锁 。如果您已经达到 32 级，请保存它们以供下次访问。"}, {k="提醒", text="32级以下？在前往千针石林之前杀死村外的普通枯木巨魔（大约 68、69）。远离拥挤的营地。", s={{"32级以下？"}, {"在前往千针石林之前杀死村外的普通枯木巨魔（大约 68、69）"}, {"远离拥挤的营地"}}}}, danger={[1]="枯木巫医在小屋内治疗，更高级别的猎头者则站在外面。从字段边缘清除并保存中断。"}, grind={[1]={mob="枯木掷斧者", note="枯木村之外密集的正常范围生物。从任务区域附近的斜坡上一次拉出一名敌人。研磨至32。"}, [2]={mob="枯木巫医", note="东部密实脚轮枯木村。 中断治愈并清除建筑物周围。留意更高级别的枯木猎头者。"}}, supply={[1]={npc="尤尔达"}, [2]={npc="旅店老板埃德瓦"}, [3]={npc="穆塔"}, [4]={npc="旅店老板埃德瓦"}, [5]={npc="格劳德"}}, steps={[1]={hint="杀掉8个石拳食人魔和10个石拳执行者，然后去阿拉希高地的落锤村哨所找杜拉姆法尔。"}, [2]={text="到达落锤镇 (73.02, 32.70) 后了解尤尔达的飞行点。"}, [3]={npc="杜拉姆法尔", tgt="杜拉姆法尔"}, [4]={npc="戈穆尔", tgt="戈穆尔"}, [5]={hint="和落锤村的托尔甘交谈。"}, [6]={npc="托尔甘", tgt="托尔甘"}, [7]={npc="托尔甘", tgt="托尔甘"}, [8]={npc="托尔甘", tgt="托尔甘"}, [9]={npc="杜拉姆法尔", tgt="杜拉姆法尔"}, [10]={npc="格里高利·维克托医生", tgt="格里高利·维克托医生"}, [11]={hint="从高地阔步龙和高地长尾龙身上取得10个高地迅猛龙的眼球，把它们交给落锤村的托尔甘。"}, [12]={hint="帮落锤村的托尔甘找10枚血石护符。"}, [13]={npc="托尔甘", tgt="托尔甘"}, [14]={npc="托尔甘", tgt="托尔甘"}, [15]={npc="托尔甘", tgt="托尔甘"}, [16]={hint="把迅猛龙利爪护符交给戈穆尔。"}, [17]={npc="戈穆尔", tgt="戈穆尔"}, [18]={npc="戈穆尔", tgt="戈穆尔"}, [19]={hint="和托尔甘谈一谈。"}, [20]={npc="托尔甘", tgt="托尔甘"}, [21]={hint="杀死10名枯木掷斧者、10名枯木猎头者和8个枯木巫医，然后回到落锤村哨所的杜拉姆法尔那里。"}, [22]={hint="将12份外科蛛丝交给阿拉希高地落锤镇的格里高利·维克托医生。"}, [23]={npc="杜拉姆法尔", tgt="杜拉姆法尔"}, [24]={npc="格里高利·维克托医生", tgt="格里高利·维克托医生"}, [25]={npc="格里高利·维克托医生", tgt="格里高利·维克托医生", desc="将 丝滑缝合 交给同一位医生即可解锁补给任务。"}, [26]={hint="去格沙克农场的乔雷尔的实验室拿一箱包装好的补剂，带给落锤镇的格里高利·维克托医生。"}, [27]={npc="格里高利·维克托医生", tgt="格里高利·维克托医生"}, [28]={text="飞往幽暗城训练并清理行李。乘坐布瑞尔以南的齐柏林飞艇前往奥格瑞玛。如果解锁，则飞往乱风岗。否则飞往陶拉祖营地，乘坐 Great 升降梯下来，然后乘坐乱风岗缆车上去。"}}},
    ["05-d13"] = {name="血色修道院 大教堂", entrance="提瑞斯法林地 85.20, 32.10", pickup="从落锤镇飞往幽暗城。 35 级时，使用图书馆和军械库管理大教堂。在希尔斯布莱德腿上，检查皇家区中的瓦里玛萨斯是否有 33 级的 深入血色修道院。低于 35？保存奥特兰克山脉返回的运行。带上猩红钥匙并完成图书馆和军械库的杀戮。", pickupS={{"从落锤镇飞往幽暗城"}, {"35 级时，使用图书馆和军械库管理大教堂"}, {"在希尔斯布莱德腿上，检查皇家区中的瓦里玛萨斯是否有 33 级的 深入血色修道院"}, {"低于 35？"}, {"保存奥特兰克山脉返回的运行"}, {"带上猩红钥匙并完成图书馆和军械库的杀戮"}}, tips={{k="動線", text="穿过喷泉庭院，登上台阶→在大教堂杀死莫格莱尼→等待怀特迈恩复活他→杀死两人。"}, {k="取捨", text="还需要 Loksey 或赫洛德吗？在返回城镇之前返回相应的侧翼。"}, {k="說明", text="带上猩红钥匙，或者使用潜行者和 仰望星空 开锁打开门。", s={{"带上猩红钥匙，或者使用潜行者和 仰望星空 开锁打开门"}}}}, steps={[1]={text="前置：深入血色修道院"}, [2]={text="血色修道院 大教堂 入口"}, [3]={hint="杀掉大检察官怀特迈恩、血色十字军指挥官莫格莱尼、血色十字军勇士赫洛德和驯犬者洛克希，然后向幽暗城的瓦里玛萨斯回报。", desc="首先清理房间周围。怀特迈恩复活了莫格莱尼。位置：穿过喷泉庭院，登上台阶。杀死两个大教堂首领。顺序：杀死莫格莱尼→怀特迈恩复活他→与两人战斗。", spot="穿过喷泉庭院，登上台阶。杀死两个大教堂首领。"}, [4]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯", desc="四个 Boss 全部清点后，到幽暗城的皇家区处交任务。"}}},
    ["05-d12"] = {name="血色修道院 武器库", entrance="提瑞斯法林地 85.20, 32.10", pickup="从落锤镇飞往幽暗城并将 Armoury 与图书馆配对。在第 33 级，从皇家区中的瓦里玛萨斯拾取 深入血色修道院。如果您已经拥有它，请保持其激活状态并带上猩红钥匙。沿着北路穿过提瑞斯法到达修道院。", pickupS={{"从落锤镇飞往幽暗城并将 Armoury 与图书馆配对"}, {"在第 33 级，从皇家区中的瓦里玛萨斯拾取 深入血色修道院"}, {"如果您已经拥有它，请保持其激活状态并带上猩红钥匙"}, {"沿着北路穿过提瑞斯法到达修道院"}}, tips={{k="動線", text="打开军械库门→沿着军营和大厅到达赫洛德→在他死后清除猩红学员。"}, {k="取捨", text="如果有人拥有猩红钥匙，请直接前往军械库。"}, {k="說明", text="带上猩红钥匙，或者使用潜行者和 仰望星空 开锁打开门。", s={{"带上猩红钥匙，或者使用潜行者和 仰望星空 开锁打开门"}}}}, steps={[1]={text="前置：深入血色修道院"}, [2]={text="血色修道院 武器库 入口"}, [3]={text="杀死赫洛德以获得深入血色修道院 。近战应该在旋风斩期间退出。"}, [4]={text="保留深入血色修道院为大教堂。完成四个 Boss 后，将其交到幽暗城。", desc="继续军械库后的任务并继续前往大教堂。"}}},
    ["05-d11"] = {name="血色修道院 图书馆", entrance="提瑞斯法林地 85.20, 32.10", pickup="从落锤镇飞往幽暗城搭乘图书馆。首先在乱风岗处执行 Dorn 的 信仰的试炼 → 耐力的试炼 → 力量的试炼 链。如果您已经完成了烈日石居，请使用南灰谷隧道前往 Braug，然后查看幽暗城中的 Parqual。兽人、牛头人和巨魔可以在雷霆崖中拿取 堕落者纲要。法师可以在微光平原和蕨墙村完成塔贝萨和提尔斯的先决条件，然后在下次访问东部王国时获得这本书。", pickupS={{"从落锤镇飞往幽暗城搭乘图书馆"}, {"首先在乱风岗处执行 Dorn 的 信仰的试炼 → 耐力的试炼 → 力量的试炼 链"}, {"如果您已经完成了烈日石居，请使用南灰谷隧道前往 Braug，然后查看幽暗城中的 Parqual"}, {"兽人、牛头人和巨魔可以在雷霆崖中拿取 堕落者纲要", {race={"Orc", "Tauren", "Troll"}}}, {"法师可以在微光平原和蕨墙村完成塔贝萨和提尔斯的先决条件，然后在下次访问东部王国时获得这本书", {class={"MAGE"}}}}, tips={{k="動線", text="穿过画廊从左边的小房间拿书→杀死驯犬者洛克希→从Doan之前的最后一个走廊和书架上收集书籍→杀死奥法师杜安并从他身后的保险箱中掠夺猩红钥匙。"}, {k="取捨", text="获得猩红钥匙来打开军械库和大教堂。在同一次任务中拿起任务书。"}, {k="說明", text="Quest 深入血色修道院 跨越三个翼楼。请参阅大教堂部分以了解完整的清理和上交。", s={{"Quest 深入血色修道院 跨越三个翼楼"}, {"请参阅大教堂部分以了解完整的清理和上交"}}}}, steps={[1]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选", desc="如果您在乱风岗做这个任务，请跳过。"}, [2]={hint="如果你有坚定的信仰，就从那个可以俯瞰千针石林的木板跳下去。", tag="可选", desc="如果您在乱风岗做这个任务，请跳过。"}, [3]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选", desc="如果您在乱风岗做这个任务，请跳过。"}, [4]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选", preText="信仰的试炼"}, [5]={hint="把格林卡的爪子交给千针石林的多恩·平原行者。", tag="可选"}, [6]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选"}, [7]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选", preText="耐力的试炼"}, [8]={hint="把罗卡里姆的碎片交给千针石林的多恩·平原行者。", tag="可选"}, [9]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选"}, [10]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选", preText="力量的试炼"}, [11]={hint="找到连接石爪山和灰谷的石爪小径里的布劳格·幽魂。", tag="可选"}, [12]={npc="布劳格·幽魂", tgt="布劳格·幽魂", tag="可选"}, [13]={npc="布劳格·幽魂", tgt="布劳格·幽魂", tag="可选", desc="在山洞里找到这本书，然后返回布劳格。", preText="知识试炼"}, [14]={hint="找到《巨龙的遗产》，把它还给位于灰谷和石爪山之间的石爪小径里的布劳格·幽魂。", tag="可选", desc="在山洞里找到这本书，然后返回布劳格。"}, [15]={npc="布劳格·幽魂", tgt="布劳格·幽魂", tag="可选", desc="在山洞里找到这本书，然后返回布劳格。"}, [16]={npc="布劳格·幽魂", tgt="布劳格·幽魂", tag="可选", preText="知识试炼"}, [17]={hint="成功回答布劳格·幽魂的问题，然后和他再次对话。他会一直在石爪山等你回答问题。", tag="可选"}, [18]={npc="布劳格·幽魂", tgt="布劳格·幽魂", tag="可选"}, [19]={npc="布劳格·幽魂", tgt="布劳格·幽魂", tag="可选", preText="知识试炼"}, [20]={hint="找到幽暗城的帕科瓦·芬塔拉斯。", tag="可选"}, [21]={npc="帕科瓦·芬塔拉斯", tgt="帕科瓦·芬塔拉斯", tag="可选"}, [22]={npc="帕科瓦·芬塔拉斯", tgt="帕科瓦·芬塔拉斯", tag="可选", preText="知识试炼"}, [23]={npc="圣者图希克", tgt="圣者图希克"}, [24]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯", desc="33级以上。如果这次你太低了，稍后再捡起来并再次杀死洛克西。"}, [25]={npc="迪诺", tgt="迪诺", tag="可选", desc="通过奥格瑞玛。替代： 奥松·格鲁尔 25.70,14.19； 安娜斯塔西娅·哈特威尔 85.14,10.03。"}, [26]={hint="和塔贝萨谈一谈。", tag="可选"}, [27]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [28]={npc="塔贝萨", tgt="塔贝萨", tag="可选", preText="沼泽之旅"}, [29]={hint="和闪光平原的大法师提尔斯谈一谈。", tag="可选"}, [30]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选"}, [31]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选", preText="隐藏的秘密"}, [32]={hint="找到提尔斯保险箱的解封咒语，然后向提尔斯复命。", tag="可选"}, [33]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选"}, [34]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选", preText="解封咒语"}, [35]={text="血色修道院 图书馆 入口"}, [36]={hint="找到《亡灵的起源》，把它交给幽暗城的帕科瓦·芬塔拉斯。", tag="可选", desc="位置：检查靠近画廊起点的左边小房间里的桌子。", spot="检查靠近画廊起点的左边小房间里的桌子。"}, [37]={hint="从血色修道院里找到《堕落者纲要》，把它交给雷霆崖的圣者图希克。", desc="位置：通过洛克西。最后一个转弯后检查多安大厅入口处的书柜。", spot="通过洛克西。最后一个转弯后检查多安大厅入口处的书柜。"}, [38]={hint="将《能量仪祭》交给尘泥沼泽的塔贝萨。", tag="可选", desc="位置：检查最后一个大厅入口处左侧书架上伸出的书。", spot="检查最后一个大厅入口处左侧书架上伸出的书。"}, [39]={text="杀死驯犬者洛克希以获得深入血色修道院 。"}, [40]={text="杀死奥法师杜安并从他身后的保险箱中拾取猩红钥匙。"}, [41]={npc="帕科瓦·芬塔拉斯", tgt="帕科瓦·芬塔拉斯", tag="可选"}, [42]={npc="圣者图希克", tgt="圣者图希克"}, [43]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}}},
    ["03-17"] = {name="千针石林", nameA="千针石林 {a:484}／{a:439}", shortA="千针石林 {a:484} +", tips={{k="取捨", text="在循环之前完成所有六个闪光平原任务。在您下次访问棘齿城时进行 交付。然后从码头管理员迪兹维格领取给克拉维尔的零件 并在下次访问闪光平原时在赛道上交。"}, {k="取捨", text="保存流放者马特克为卡加斯，兄弟为葬影村，奈辛瓦里（赫米特·奈辛瓦里）为格罗姆戈尔和藏宝海湾腿。"}, {k="提醒", text="如果您尚未上交 疯狂的虫群，请跳过 疯狂的虫群。该视频警告蜂巢深处存在更高级别的生物。在入口附近杀掉，然后离开。如果您完成了 虫群的样本，请在前往蕨墙村的途中将其交到十字路口。", s={{"如果您尚未上交 疯狂的虫群，请跳过 疯狂的虫群"}, {"该视频警告蜂巢深处存在更高级别的生物"}, {"在入口附近杀掉，然后离开"}, {"如果您完成了 虫群的样本，请在前往蕨墙村的途中将其交到十字路口"}}}, {k="提醒", text="将这个级别 32-34 的腿与葬影村结合起来。 33级以下？在赛马场以南（大约 76、85）磨碎海龟、秃鹫和蝎子，然后前往凄凉之地。", s={{"将这个级别 32-34 的腿与葬影村结合起来"}, {"33级以下？"}, {"在赛马场以南（大约 76、85）磨碎海龟、秃鹫和蝎子，然后前往凄凉之地"}}}}, danger={[1]="高级异种蜥蜴聚集在微光平原蜂巢的后面。经过疯狂的虫群后，原路返回到入口处。"}, grind={[1]={mob="盐石水晶蜥蜴", note="微光平原赛马场以南有密集的普通怪物。在 32 层的开放盐滩上击杀单打。"}, [2]={mob="盐壳掘地龟", note="盐滩东边的正常生物密度适中。与蜥蜴交替并收集硬化龟甲。"}, [3]={mob="恐蝎", note="赛道东南方的普通生物密度适中。在地面上盘旋并观察其他野兽。如果需要，请收集含盐的蝎毒。"}}, supply={[1]={npc="奈瑟"}, [2]={npc="旅店老板埃比克瓦"}, [3]={npc="斯塔恩"}, [4]={npc="旅店老板埃比克瓦"}, [5]={npc="斯塔恩"}, [6]={npc="莫塔尔"}, [7]={npc="赛恩格"}, [8]={npc="瑞兹尼克"}, [9]={npc="赛恩格"}}, steps={[1]={text="学习奈瑟的乱风岗飞行点 (45.14, 49.11)，然后沿着东南方向进入微光平原。"}, [2]={npc="峭壁卫兵图林·长角", tgt="峭壁卫兵图林·长角"}, [3]={npc="摩克塔·克林", tgt="摩克塔·克林", tag="可选"}, [4]={npc="菲兹尔·铜栓", tgt="菲兹尔·铜栓"}, [5]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓"}, [6]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [7]={npc="赛道管理员泽尔林", tgt="赛道管理员泽尔林"}, [8]={npc="普兹克", tgt="普兹克"}, [9]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [10]={hint="为闪光平原的菲兹尔·铜栓带去6份含盐的蝎毒。"}, [11]={hint="收集9块硬化龟壳，把它们交给闪光平原的维兹尔·铜栓。"}, [12]={hint="收集30个火箭车零件，把它们交给闪光平原的克拉维尔·浓须。"}, [13]={hint="为闪光平原的赛道管理员泽尔林杀死10条盐石蜥蜴、10条盐石水晶蜥蜴和6条盐石凝视者。"}, [14]={hint="给闪光平原的普兹克找10根空心秃鹫骨。"}, [15]={npc="菲兹尔·铜栓", tgt="菲兹尔·铜栓"}, [16]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓"}, [17]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [18]={npc="赛道管理员泽尔林", tgt="赛道管理员泽尔林"}, [19]={npc="普兹克", tgt="普兹克"}, [20]={npc="菲兹尔·铜栓", tgt="菲兹尔·铜栓"}, [21]={npc="普兹克", tgt="普兹克", tag="如果经过棘齿城、可选"}, [22]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须", tag="如果经过棘齿城、可选"}, [23]={text="如果您选择了码头管理员迪兹维格，请绕道前往棘齿城。"}, [24]={hint="和棘齿城的加兹鲁维谈一谈。", tag="如果经过棘齿城、可选"}, [25]={hint="把克拉维尔的零件订单交给棘齿城的码头管理员迪兹维格。", tag="如果经过棘齿城、可选"}, [26]={npc="加兹鲁维", tgt="加兹鲁维", tag="如果经过棘齿城、可选"}, [27]={npc="码头管理员迪兹维格", tgt="码头管理员迪兹维格", tag="如果经过棘齿城、可选"}, [28]={npc="加兹鲁维", tgt="加兹鲁维", tag="可选"}, [29]={npc="破碎的异种蝎壳", npcObj=true, tag="如果 疯狂的虫群 期间掉落则接受、可选", desc="在疯狂的虫群期间拾取破碎的异种蝎壳。右键单击它开始任务。"}, [30]={hint="收集1颗异种蝎的心脏、5只异种蝎的爪子和3个完整的异种蝎壳，把它们和你手中的这个破碎的异种蝎壳一起交给十字路口的科兰。", tag="和疯狂的虫群一起做、可选"}, [31]={hint="杀掉5只异种搜寻者、5只异种筑巢蝎和5只异种侵略者，然后向千针石林的摩克塔·克林复命。", tag="可选"}, [32]={npc="摩克塔·克林", tgt="摩克塔·克林", tag="可选"}, [33]={hint="把水灵碎片交给贫瘠之地的水之先知伊斯伦。", desc="完成任务即可获得水之图腾。"}, [34]={npc="水之先知伊斯伦", tgt="水之先知伊斯伦", desc="完成任务即可获得水之图腾。"}, [35]={npc="希尔恩·火结", tgt="希尔恩·火结", desc="在奥格瑞玛中启动 空气的召唤 或在雷霆崖中获取 空气的召唤 引导任务。"}, [36]={hint="到千针石林去找普拉特·白云。", desc="在奥格瑞玛中启动 空气的召唤 或在雷霆崖中获取 空气的召唤 引导任务。"}, [37]={npc="普拉特·白云", tgt="普拉特·白云", desc="在奥格瑞玛中启动 空气的召唤 或在雷霆崖中获取 空气的召唤 引导任务。"}, [38]={npc="普拉特·白云", tgt="普拉特·白云", tag="可选", desc="保存奥特兰克的最终 Boss 笔记。 劳恩·峭壁行者也提供它（46.14, 51.71）。"}, [39]={hint="在剃刀沼泽击败卡尔加·刺肋，收集有关野猪人计划的情报。", tag="可选", desc="保留剃刀沼泽最终 Boss 的纸条，以便交纳奥特兰克。"}, [40]={text="到达微光平原后，原路返回并乘坐电梯前往乱风岗。飞往烈日石居，然后向西南穿过烧焦谷进入凄凉之地。"}}},
    ["05-d14"] = {name="剃刀沼泽", entrance="贫瘠之地（1413），荆棘通道的副本入口附近，约 42.30, 89.90。", pickup="在前往千针石林的途中运行剃刀沼泽。在棘齿城中，拿起 蓝叶薯 和 gopher 工具。在前往希尔斯布莱德的途中，在幽暗城的法拉内尔接载 蝙蝠的粪便。如果运行前经过雷霆崖，则从Auld获取奥尔德的报复。从乱风岗出发，乘坐伟大的升降梯回到贫瘠之地，然后沿着西荆棘小路到达传送门。", pickupS={{"在前往千针石林的途中运行剃刀沼泽"}, {"在棘齿城中，拿起 蓝叶薯 和 gopher 工具"}, {"在前往希尔斯布莱德的途中，在幽暗城的法拉内尔接载 蝙蝠的粪便"}, {"如果运行前经过雷霆崖，则从Auld获取奥尔德的报复"}, {"从乱风岗出发，乘坐伟大的升降梯回到贫瘠之地，然后沿着西荆棘小路到达传送门"}}, tips={{k="動線", text="使用地鼠蓝叶薯沿着荆棘路径→鲁古格在小路上→贾格巴→拉姆牙→洞穴中的蝙蝠鸟粪→查尔加的小屋以获取她的心脏和任务战利品→返回威利克斯的帐篷并护送他到入口。"}, {k="取捨", text="杀死最后的boss和前厅的蝙蝠来解锁狂热之心和剃刀高地后续。如果时间紧迫，可以先做地鼠或沿路线护送。"}, {k="說明", text="剃刀沼泽是大升降梯的西边。 剃刀高地是东。 Forever客户端将入口标记为42.30, 89.90。从主干道沿着西荆棘隧道到达地牢入口。", s={{"剃刀沼泽是大升降梯的西边"}, {"剃刀高地是东"}, {"Forever客户端将入口标记为42.30, 89.90"}, {"从主干道沿着西荆棘隧道到达地牢入口"}}}}, steps={[1]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯", desc="进入前由棘齿城 NPC 获取箱子、命令棒和手册。"}, [2]={npc="奥尔德·石塔", tgt="奥尔德·石塔"}, [3]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", desc="转入解锁血色修道院任务 狂热之心。"}, [4]={npc="鲁迦·狂暴图腾", tgt="鲁迦·狂暴图腾", tag="可选"}, [5]={hint="收集5根颤抖的触角，把它们带给贫瘠之地陶拉祖营地的鲁迦。", tag="可选"}, [6]={npc="鲁迦·狂暴图腾", tgt="鲁迦·狂暴图腾", tag="可选"}, [7]={npc="鲁迦·狂暴图腾", tgt="鲁迦·狂暴图腾", tag="可选", preText="巨人旷野的试炼"}, [8]={hint="与贫瘠之地的索恩格瑞姆·火眼谈一谈。", tag="可选"}, [9]={npc="索恩格瑞姆·火眼", tgt="索恩格瑞姆·火眼", tag="可选"}, [10]={npc="索恩格瑞姆·火眼", tgt="索恩格瑞姆·火眼", tag="可选", desc="携带 15 个黑铁锭、10 个蓝铜粉和 10 个铁锭。最后一个垫子：RFK。", preText="巨人旷野的试炼、和索恩格瑞姆交谈"}, [11]={npc="希尔恩·火结", tgt="希尔恩·火结", tag="副本前置链"}, [12]={npc="普拉特·白云", tgt="普拉特·白云", tag="副本前置链"}, [13]={npc="普拉特·白云", tgt="普拉特·白云", tag="可选", desc="30级图腾链。备用拾音器：劳恩·峭壁行者 (46.14, 51.71)。"}, [14]={text="剃刀沼泽 入口"}, [15]={hint="找到一个开孔的箱子。", desc="位置：挖掘沿着荆棘路径或护送威利克斯返回时拾取块茎。", spot="挖掘沿着荆棘路径或护送威利克斯返回时拾取块茎。"}, [16]={hint="为索恩格瑞姆收集15根烟雾铁锭、10份蓝铜粉、10块铁锭和1瓶燃素。", tag="可选", desc="位置：走早期的小路到鲁古格。先清除他的添加。", spot="走早期的小路到鲁古格。先清除他的添加。"}, [17]={npc="进口商威利克斯", tgt="进口商威利克斯", tag="需要游戏内检查", desc="从地下城内的NPC开始护送。"}, [18]={hint="护送进口商威利克斯逃出剃刀沼泽。", desc="从地下城内的NPC开始护送。位置：在最后一个 Boss 旁边的帐篷里找到威利克斯，并护送他回到入口。顺序：在开始护送之前完成步骤 17-20。", spot="在最后一个 Boss 旁边的帐篷里找到威利克斯，并护送他回到入口。"}, [19]={npc="进口商威利克斯", tgt="进口商威利克斯", tag="需要游戏内检查", desc="从地下城内的NPC开始护送。", spot="副本入口处，护送终点"}, [20]={hint="帮幽暗城的大药剂师法拉尼尔带回一堆沼泽蝙蝠的粪便。", desc="位置：在最终 Boss 面前杀死洞穴中的蝙蝠。", spot="在最终 Boss 面前杀死洞穴中的蝙蝠。"}, [21]={hint="把卡尔加·刺肋的心脏交给雷霆崖的奥尔德·石塔。", desc="位置：离开蝙蝠洞，爬上平台，在最后一个小屋里杀死查尔加。", spot="离开蝙蝠洞，爬上平台，在最后一个小屋里杀死查尔加。"}, [22]={hint="在剃刀沼泽击败卡尔加·刺肋，收集有关野猪人计划的情报。", tag="可选", desc="位置：在执行第 18 步时，在最后一个小屋中杀死 Charlga。顺序：通过第 18 步抢劫这个。", spot="在执行第 18 步时，在最后一个小屋中杀死 Charlga。"}, [23]={npc="小卷轴", npcObj=true, tag="可选、需要游戏内检查", desc="掠夺并使用卡尔加·刺肋中的小卷轴。保存为幽暗城。"}, [24]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯"}, [25]={npc="奥尔德·石塔", tgt="奥尔德·石塔"}, [26]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", desc="在幽暗城上交，然后接受狂热之心 。"}, [27]={hint="把小卷轴交给幽暗城的瓦里玛萨斯。", tag="可选"}, [28]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯", tag="可选"}, [29]={npc="索恩格瑞姆·火眼", tgt="索恩格瑞姆·火眼", tag="可选"}, [30]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="在奥特兰克交回。如果您的日志显示乱风岗，请参阅 Rau (46.14, 51.71)。"}}},
    ["03-18"] = {name="凄凉之地", nameA="凄凉之地 {a:2408}", tips={{k="取捨", text="一起做公路抢劫和集骨者。在前往毕比小屋的路上点击篝火。所有三个任务都是 40 级，并且需要 30 级。将\"逃亡\"任务保存为藏宝海湾。"}, {k="取捨", text="在南路做吉尔吉斯任务吉尔吉斯部族和偷取物资。如果您选择了 Magram 或声誉错误，请跳过这两个版本以及葬影村 Gelkis 后续版本。"}, {k="取捨", text="在葬影村海岸环线上，一起完成水上任务和古书。在雷斧堡垒处，首先执行圣光节杖和埃鲁索斯之手。如果经验不足，请在第二次访问时提交。"}, {k="取捨", text="如果大篷车不在，就继续前进。不要等待护送。保存 荆棘谷狩猎 前往荆棘谷的下一站。"}, {k="提醒", text="34级以下？在前往荆棘谷之前，杀死科多兽坟场周围的普通半人马（大约 56、60-68）或西海岸的滑刃纳迦（35.91, 28.84）。", s={{"34级以下？"}, {"在前往荆棘谷之前，杀死科多兽坟场周围的普通半人马（大约 56、60-68）或西海岸的滑刃纳迦（35.91, 28.84）"}}}}, danger={[1]="西海岸的纳迦位于水下玛库拉附近。将脚轮拉到海滩上，以避免在水下伤害两个背包。"}, grind={[1]={note="科多兽坟场以东的普通生物稀疏。留意其他食腐鸟。在墓地任务循环中捡起一点经验。"}, [2]={mob="滑刃纳迦", note="西海岸密集的普通怪物。挑选单身人士并留意附近的女巫。与其他沿海任务配对。"}, [3]={mob="滑刃巫师", note="西海岸纳迦地区南端的普通施法者密度适中。将它们拉到岸上以避免马库拉小怪。"}}, supply={[1]={npc="萨隆"}, [2]={npc="旅店老板希科瓦"}, [3]={npc="海维拉尼"}, [4]={npc="旅店老板希科瓦"}, [5]={npc="图克"}}, steps={[1]={npc="费古尔·双刃", tgt="费古尔·双刃"}, [2]={npc="古尔达·蛮鬃", tgt="古尔达·蛮鬃"}, [3]={npc="古尔达·蛮鬃", tgt="古尔达·蛮鬃"}, [4]={npc="纳塔卡·长角", tgt="纳塔卡·长角"}, [5]={hint="将峭壁卫兵图林·长角的报告交给凄凉之地幽灵岗哨的纳塔卡·长角。"}, [6]={npc="纳塔卡·长角", tgt="纳塔卡·长角"}, [7]={npc="斯米德·瑟卡布斯库", tgt="斯米德·瑟卡布斯库"}, [8]={hint="将科多兽诱引器和5头被驯服的科多兽交给瑟卡布斯库的营地中的斯米德·瑟卡布斯库。"}, [9]={npc="斯米德·瑟卡布斯库", tgt="斯米德·瑟卡布斯库"}, [10]={text="沿着南路行驶，经过格尔基斯村。学习萨隆的飞行点（21.60, 74.13）并将您的炉石绑定到葬影村中。"}, [11]={npc="鲁恩·蛮鬃", tgt="鲁恩·蛮鬃"}, [12]={npc="泰迦·慧鬃", tgt="泰迦·慧鬃"}, [13]={npc="麦拉斯", tgt="麦拉斯"}, [14]={npc="杜泽加尔", tgt="杜泽加尔"}, [15]={npc="阿卡莱", tgt="阿卡莱"}, [16]={text="海岸→雷斧堡垒→色狼向东"}, [17]={npc="拉克摩尔的日志", npcObj=true}, [18]={npc="阿佐尔·奥达蒙特", tgt="阿佐尔·奥达蒙特"}, [19]={npc="恶魔之皮", npcObj=true, tag="如果掉落，请执行以下操作、可选", desc="右键单击恶魔之皮以启动链。如果没有掉落就继续。"}, [20]={hint="把恶魔之皮拿给凄凉之地的玛乌林·碎骨看看。", tag="如果掉落，请执行以下操作、可选"}, [21]={npc="玛乌林·碎骨", tgt="玛乌林·碎骨", tag="如果掉落，请执行以下操作、可选"}, [22]={hint="拿到圣光节杖，并将它交给艾瑟雷索塔里的阿佐尔·奥达蒙特。"}, [23]={hint="在雷斧堡垒中找到恶魔之盒，把它和恶魔之锄一起交给葬影村的泰迦·慧鬃。", desc="使用雷斧堡垒中的红色水晶上的镐。为盒子杀灵。"}, [24]={npc="阿佐尔·奥达蒙特", tgt="阿佐尔·奥达蒙特"}, [25]={npc="阿佐尔·奥达蒙特", tgt="阿佐尔·奥达蒙特"}, [26]={npc="玛乌林·碎骨", tgt="玛乌林·碎骨", tag="可选"}, [27]={hint="在凄凉之地的萨格隆击败各种怨怒萨特，然后返回葬影村的阿卡莱身边。"}, [28]={hint="给凄凉之地的玛乌林·碎骨带回一张巡影者的头皮。", tag="可选"}, [29]={npc="玛乌林·碎骨", tgt="玛乌林·碎骨", tag="可选"}, [30]={npc="玛乌林·碎骨", tgt="玛乌林·碎骨", tag="可选"}, [31]={hint="把戴兹帕可汗的头颅交给凄凉之地的费古尔·双刃。"}, [32]={npc="费古尔·双刃", tgt="费古尔·双刃"}, [33]={npc="费古尔·双刃", tgt="费古尔·双刃"}, [34]={npc="比布里·弗斯巴克", tgt="比布里·弗斯巴克"}, [35]={hint="和吉尔吉斯部族建立良好的关系，然后和智者乌泰克谈一谈。"}, [36]={npc="智者乌泰克", tgt="智者乌泰克"}, [37]={npc="智者乌泰克", tgt="智者乌泰克"}, [38]={hint="收集15只半人马的耳朵，把它们交给凄凉之地的费古尔·双刃。"}, [39]={hint="消灭凄凉之地任意氏族的半人马，收集5枚雕刻半人马图腾，再交给幽灵岗哨的古尔达·蛮鬃。"}, [40]={hint="把6包粗制干肉交给吉尔吉斯村的智者乌泰克。"}, [41]={npc="费古尔·双刃", tgt="费古尔·双刃"}, [42]={npc="古尔达·蛮鬃", tgt="古尔达·蛮鬃"}, [43]={npc="智者乌泰克", tgt="智者乌泰克"}, [44]={npc="熄灭的营火", npcObj=true, desc="单击科多兽坟场西北方向的熄灭的营火。需要30级。"}, [45]={hint="从科多墓地收集10根科多兽骨，把它们交给兽人小屋的比布里·弗斯巴克。"}, [46]={npc="比布里·弗斯巴克", tgt="比布里·弗斯巴克"}, [47]={hint="在凄凉之地寻找对遭劫的营地有所了解的人士。"}, [48]={npc="比布里·弗斯巴克", tgt="比布里·弗斯巴克"}, [49]={npc="比布里·弗斯巴克", tgt="比布里·弗斯巴克", desc="公路抢劫案发生后在此接客。在藏宝海湾旅店上交。"}, [50]={text="西海岸纳迦和岛屿，然后返回葬影村"}, [51]={hint="与葬影村的吉纳泽林谈话，然后将2条血肚鱼交给纳塔卡·长角。", desc="与葬影村中的吉纳泽林对话以获得两条鱼。与西海岸任务配对。"}, [52]={hint="找到10块软壳蚌肉，把它们交给葬影村的麦拉斯。"}, [53]={hint="杀死7个滑刃侍从、7个滑刃纳迦，以及5个滑刃巫师，然后与葬影村的杜泽加尔谈谈。"}, [54]={hint="拿到上古之书，将其交给艾瑟雷索塔中的阿佐尔·奥达蒙特。"}, [55]={hint="给凄凉之地的玛乌林·碎骨带回一块神谕水晶。", tag="可选"}, [56]={hint="找到拉克摩尔的银钥匙和金钥匙。找到并打开拉克摩尔的箱子。", desc="从马库拉和纳迦那里拾取银色和金钥匙，然后游到岛屿宝箱。"}, [57]={npc="拉克摩尔的箱子", npcObj=true}, [58]={npc="阿佐尔·奥达蒙特", tgt="阿佐尔·奥达蒙特"}, [59]={npc="纳塔卡·长角", tgt="纳塔卡·长角"}, [60]={npc="玛乌林·碎骨", tgt="玛乌林·碎骨", tag="可选"}, [61]={npc="玛乌林·碎骨", tgt="玛乌林·碎骨", tag="可选"}, [62]={hint="与凄凉之地的塔卡塔·钢刃谈一谈。", tag="可选"}, [63]={npc="塔卡塔·钢刃", tgt="塔卡塔·钢刃", tag="可选"}, [64]={text="使用您的炉石返回葬影村。"}, [65]={npc="麦拉斯", tgt="麦拉斯"}, [66]={npc="杜泽加尔", tgt="杜泽加尔"}, [67]={npc="泰迦·慧鬃", tgt="泰迦·慧鬃"}, [68]={npc="阿卡莱", tgt="阿卡莱"}, [69]={npc="泽弗洛斯特", tgt="泽弗洛斯特", tag="可选", desc="奥格瑞玛引导任务。拿这个或者奥拉赫宝珠，或者直接去棘齿城。"}, [70]={hint="与贫瘠之地的梅纳拉·沃伦德谈一谈。", tag="可选", desc="奥格瑞玛引导任务。拿这个或者奥拉赫宝珠，或者直接去棘齿城。"}, [71]={npc="梅纳拉·