    ["05-d16"] = {name="The Drowned City", entrance="荆棘谷 21.50, 27.70", pickup="跟随第一次荆棘谷访问：在格罗姆高采取 暗礁海 并完成暗礁目标，然后上交 古老的古拉巴什传说。在藏宝海湾从克拉兹克采取 可疑的盐水先知 和 盐水先知船长。在祖尔昆达取得 古老的古拉巴什传说 的拓片。回到格罗姆戈尔，拿起 定位失落之城 和 水中的敌人，在西海岸都做，然后采取 沉没之城 和 唯一的好盐鳞……。如果你已经解锁了雷霆崖，请在跑步前飞到那里，然后沿着莫高雷路到马祖康在观天者台地。返回格罗姆高并从西海岸游至水下传送门。", pickupS={{"跟随第一次荆棘谷访问：在格罗姆高采取 暗礁海 并完成暗礁目标，然后上交 古老的古拉巴什传说"}, {"在藏宝海湾从克拉兹克采取 可疑的盐水先知 和 盐水先知船长"}, {"在祖尔昆达取得 古老的古拉巴什传说 的拓片"}, {"回到格罗姆戈尔，拿起 定位失落之城 和 水中的敌人，在西海岸都做，然后采取 沉没之城 和 唯一的好盐鳞……"}, {"如果你已经解锁了雷霆崖，请在跑步前飞到那里，然后沿着莫高雷路到马祖康在观天者台地"}, {"返回格罗姆高并从西海岸游至水下传送门"}}, tips={{k="動線", text="祖拉莱→瓦尔塔卡→德雷德莱斯船长→不死髓→毒蛇明洛斯。在入口水池左侧、瓦尔塔卡左侧、船边的头骨和敏洛丝后面进行拓片。从海盗那里掠夺文物。 原始元素和吉尔是可选的。"}, {k="取捨", text="在游出之前完成格罗姆戈尔的两个先决条件，这样你就可以做比船部分更多的事情。如果不碍事，请跳过单个莫高雷上交。"}, {k="說明", text="副本门在格罗姆高以西的水下洞窟。带水下呼吸药剂，或请有技能的队友施放。", s={{"副本门在格罗姆高以西的水下洞窟"}, {"带水下呼吸药剂，或请有技能的队友施放"}}}}, steps={[1]={npc="肯维雷", tgt="肯维雷", desc="如果您在 Grom'gol 和藏宝海湾腿上做这个任务，请跳过。"}, [2]={hint="给格罗姆高营地里的肯维雷带回一块石板碎片。", desc="如果您在 Grom'gol 和藏宝海湾腿上做这个任务，请跳过。"}, [3]={npc="肯维雷", tgt="肯维雷", desc="如果您在 Grom'gol 和藏宝海湾腿上做这个任务，请跳过。"}, [4]={npc="肯维雷", tgt="肯维雷", preText="暗礁海"}, [5]={hint="使用兽皮和木炭，拓印巨魔传说第三章石板。"}, [6]={npc="肯维雷", tgt="肯维雷"}, [7]={npc="肯维雷", tgt="肯维雷", preText="古老的古拉巴什传说"}, [8]={hint="探索暗礁海并找到洞穴入口。"}, [9]={npc="肯维雷", tgt="肯维雷"}, [10]={npc="指挥官阿格罗戈什", tgt="指挥官阿格罗戈什", desc="暗礁海之后，在访问肯维雷时与指挥官确认。", preText="暗礁海、古老的古拉巴什传说"}, [11]={hint="从盐鳞游击者那里收集10把盐鳞三叉戟。", tag="目标：盐鳞游击者", desc="暗礁海之后，在访问肯维雷时与指挥官确认。"}, [12]={npc="指挥官阿格罗戈什", tgt="指挥官阿格罗戈什", desc="暗礁海之后，在访问肯维雷时与指挥官确认。"}, [13]={npc="肯维雷", tgt="肯维雷", preText="定位失落之城"}, [14]={npc="指挥官阿格罗戈什", tgt="指挥官阿格罗戈什", preText="水中的敌人、定位失落之城"}, [15]={npc="克拉兹克", tgt="克拉兹克"}, [16]={npc="克拉兹克", tgt="克拉兹克"}, [17]={npc="马祖康", tgt="马祖康", tag="可选", desc="马祖康位于莫高雷中的观天者台地处。如果您的交通工具已解锁，请前往。"}, [18]={text="The Drowned City 入口"}, [19]={hint="使用兽皮和木炭，拓印在沉没之城找到的石板。", desc="位置：水池左边，瓦尔塔卡左边，德雷德莱斯船长的头骨，最后一个 Boss 后面。顺序：沿途参观四个地标拓片。", spot="水池左边，瓦尔塔卡左边，德雷德莱斯船长的头骨，最后一个 Boss 后面。"}, [20]={hint="在沉没之城消灭瓦尔塔卡。", desc="先杀掉boss旁边的牧师。观察你在水下的呼吸。位置：经过祖拉莱，在被淹没的档案中找到两个女祭司旁边的boss。", spot="经过祖拉莱，在被淹没的档案中找到两个女祭司旁边的boss。"}, [21]={hint="从沉没之城的盐水先知海盗手中收集10个注入巫毒的神器。", desc="如果您仍然需要掉落物，请继续清除船只周围的海盗。位置：清除船只旁的盐湖海盗并掠夺文物。顺序：使用步骤 21 清除该区域。", spot="清除船只旁的盐湖海盗并掠夺文物。"}, [22]={hint="在沉没之城消灭3个盐水先知验尸官和德雷德莱斯船长。", desc="位置：清理船长附近通道沿线的验尸官。顺序：杀死船长后点击发光珍珠。", spot="清理船长附近通道沿线的验尸官。"}, [23]={hint="从沉没之城找回一个远古古拉巴什神像。", tag="可选", desc="位置：通过船长和珍珠屏障，然后杀死不死髓。", spot="通过船长和珍珠屏障，然后杀死不死髓。"}, [24]={npc="肯维雷", tgt="肯维雷"}, [25]={npc="指挥官阿格罗戈什", tgt="指挥官阿格罗戈什"}, [26]={npc="克拉兹克", tgt="克拉兹克"}, [27]={npc="克拉兹克", tgt="克拉兹克"}, [28]={npc="马祖康", tgt="马祖康", tag="可选"}, [29]={npc="肯维雷", tgt="肯维雷", tag="可选", desc="如果您已经飞往奥格瑞玛，请提交。这可以等到运行之后。", preText="沉没之城"}, [30]={hint="把石板拓片交给杜隆塔尔森金村的加德林大师。", tag="可选", desc="如果您已经飞往奥格瑞玛，请提交。这可以等到运行之后。"}, [31]={npc="加德林大师", tgt="加德林大师", tag="可选", desc="如果您已经飞往奥格瑞玛，请提交。这可以等到运行之后。"}}},
    ["05-d15"] = {name="诺莫瑞根", entrance="荆棘谷 27.60, 77.48", pickup="在藏宝海湾之前，先访问荣誉谷中的索维克和诺格。从棘齿城乘船或从格罗姆戈尔飞往藏宝海湾。用斯库提完成主工程师斯库提→出发！诺莫瑞根！并保留地精传送器进入。", pickupS={{"在藏宝海湾之前，先访问荣誉谷中的索维克和诺格"}, {"从棘齿城乘船或从格罗姆戈尔飞往藏宝海湾"}, {"用斯库提完成主工程师斯库提→出发！"}, {"诺莫瑞根！"}, {"并保留地精传送器进入"}}, tips={{k="動線", text="向左下坡到达清洁区→从右侧宿舍护送克努比→电刑器6000型→群体打击者9-60→Thermaplugg，然后在保险箱上使用他的代码。如果您抢劫脏兮兮的戒指，请在清洁区使用 Sparklematic。"}, {k="取捨", text="如果装备或任务经验值得的话就跑。将任务提交与您的藏宝海湾任务配对以节省路途。"}, {k="說明", text="使用传送器到达丹莫罗的设施，然后沿着地下走廊到达地牢入口。跳过铁炉堡。如果传送器被锁定，请先完成斯库提的链条。", s={{"使用传送器到达丹莫罗的设施，然后沿着地下走廊到达地牢入口"}, {"跳过铁炉堡"}, {"如果传送器被锁定，请先完成斯库提的链条"}}}}, steps={[1]={npc="诺格", tgt="诺格"}, [2]={npc="索维克", tgt="索维克", preText="设备之战"}, [3]={hint="和藏宝海湾的斯库提谈一谈。"}, [4]={npc="斯库提", tgt="斯库提"}, [5]={npc="斯库提", tgt="斯库提", preText="主工程师斯库提"}, [6]={hint="等斯库提调整好地精传送器。"}, [7]={npc="斯库提", tgt="斯库提"}, [8]={text="诺莫瑞根 入口"}, [9]={hint="从诺莫瑞根拿到钻探设备蓝图和瑟玛普拉格的保险箱密码，把它们交给奥格瑞玛的诺格。", desc="让某人在战斗中按下避难所旁边的按钮来控制炸弹。位置：沿着车间隧道到达圆形房间。杀死最后一个boss并打开保险箱。", spot="沿着车间隧道到达圆形房间。杀死最后一个boss并打开保险箱。"}, [10]={npc="克努比", tgt="克努比", tag="需要游戏内检查", desc="在洁净区附近找到克努比。先清理护送路线。"}, [11]={hint="将克努比护送到出口，然后向藏宝海湾的斯库提汇报。", desc="位置：在清洁区宿舍领取克努比。护送他到正门。顺序：执行步骤 9-10，然后再深入寻找最终 Boss。", spot="在清洁区宿舍领取克努比。护送他到正门。"}, [12]={npc="脏兮兮的戒指", npcObj=true, tag="可选、需要游戏内检查", desc="带上3个银色并跟随机器的对话。"}, [13]={hint="想方法把脏兮兮的戒指弄干净。", tag="可选", desc="带上3个银色并跟随机器的对话。位置：左转并向下到达清洁区。找到墙边的 Sparklematic。顺序：首先从黑铁密探中拾取戒指。", spot="左转并向下到达清洁区。找到墙边的 Sparklematic。"}, [14]={npc="超级清洁器5200型", npcObj=true, tag="可选、需要游戏内检查", desc="带上3个银色并跟随机器的对话。", spot="入门左转下坡，清洁区墙边的清洁器"}, [15]={npc="超级清洁器5200型", npcObj=true, tag="可选、需要游戏内检查", preText="脏兮兮的戒指"}, [16]={npc="斯库提", tgt="斯库提"}, [17]={npc="诺格", tgt="诺格"}, [18]={hint="你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。", tag="可选"}, [19]={npc="诺格", tgt="诺格", tag="可选"}}},
    ["03-20"] = {name="尘泥沼泽", nameA="尘泥沼泽 {a:496}", tips={{k="取捨", text="进入村庄前，在同一个被烧毁的旅店接黑色盾牌、可疑的蹄印和帕瓦尔·雷瑟上尉。"}, {k="取捨", text="出城前带上 3 个舒心草。如果您有月钢宽剑，请上交。购买或制作它会少走一些弯路。如果通过则在棘齿城处交伊格纳兹的逃亡，或者保存或跳过。"}, {k="提醒", text="蕨墙村和葬影村一起回归覆盖第 37-38 层。如果你已经交了凄凉之地任务，杀死尘泥沼泽北部的普通蜘蛛和猛禽直到38。", s={{"蕨墙村和葬影村一起回归覆盖第 37-38 层"}, {"如果你已经交了凄凉之地任务，杀死尘泥沼泽北部的普通蜘蛛和猛禽直到38"}}}}, danger={[1]="毒蜘蛛和猛禽巡逻队在北部沼泽地重叠。一次从边缘拉出一名敌人，并避开巡逻队在灌木丛中相遇的地方。"}, grind={[1]={mob="枯藤沼泽兽", note="北部沼泽中密集的普通生物与其他凋灵生物一起。一次将一名敌人从干燥的地面上拖出，以到达下一站的水平。"}, [2]={mob="暗牙毒蜘蛛", note="北部沼泽东部地区普通生物的密度中等。留意毒药伤害和猛禽巡逻。如果正在种植凋灵生物，请移至此处。"}, [3]={mob="血沼尖啸龙", note="沿着北部沼泽的林线有密集的普通生物。沿着海岸一次拉一名敌人，并留意鳄鱼和其他猛禽。 38点出发。"}}, supply={[1]={npc="沙尔迪"}, [2]={npc="克伦卡"}, [3]={npc="奥克玛尔"}, [4]={npc="萨纳拉"}, [5]={npc="巴莱·洛克维"}}, steps={[1]={npc="科兰", tgt="科兰", tag="可选"}, [2]={text="从陶拉祖营地向东进入尘泥沼泽。首先在路边被烧毁的旅馆停下来。"}, [3]={npc="黑色盾牌", npcObj=true}, [4]={npc="蹄印", npcObj=true}, [5]={npc="塞拉摩卫兵徽章", npcObj=true}, [6]={nodeA="{a:496}", desc="解锁、飞行点和沙尔迪。"}, [7]={text="保留您的葬影村壁炉，以备下一段返回时使用。"}, [8]={hint="把被熏黑的铁盾牌带给蕨墙村的克罗格。"}, [9]={hint="把树荫旅店的可疑蹄印报告给蕨墙村的克罗格。"}, [10]={hint="把雷瑟的徽章带给蕨墙村的克罗格。"}, [11]={npc="克罗格", tgt="克罗格"}, [12]={npc="克罗格", tgt="克罗格"}, [13]={npc="克罗格", tgt="克罗格"}, [14]={npc="克罗格", tgt="克罗格"}, [15]={hint="把被熏黑的铁盾牌拿给蕨墙村的杜高尔看一看。"}, [16]={npc="杜高尔", tgt="杜高尔"}, [17]={npc="杜高尔", tgt="杜高尔"}, [18]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛"}, [19]={npc="马德克拉什", tgt="马德克拉什"}, [20]={npc="奥格隆", tgt="奥格隆"}, [21]={hint="和奥格隆一起去和雷瑟谈一谈，然后回到蕨墙村见克罗格。"}, [22]={npc="克罗格", tgt="克罗格"}, [23]={hint="杀掉9个塞拉摩间谍，然后回到蕨墙村去见纳泽尔·血矛。"}, [24]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛"}, [25]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛"}, [26]={text="北路护航→水光庄园→海岸"}, [27]={npc="伊格纳兹", tgt="伊格纳兹", tag="经过棘齿城时转入、可选"}, [28]={hint="护送伊格纳兹，然后和棘齿城的麦伯克·米希瑞克斯谈一谈。", tag="可选"}, [29]={npc="沼泽之眼加尔", tgt="沼泽之眼加尔"}, [30]={hint="为尘泥沼泽的\"沼泽之眼\"加尔收集3棵舒心草。"}, [31]={npc="沼泽之眼加尔", tgt="沼泽之眼加尔"}, [32]={npc="沼泽之眼加尔", tgt="沼泽之眼加尔"}, [33]={npc="松软的泥土", npcObj=true}, [34]={hint="收集40颗黑雾蜘蛛的眼球，把它们交给水光庄园的\"沼泽之眼\"加尔。"}, [35]={hint="把间谍的报告交给蕨墙村的纳泽尔·血矛。"}, [36]={hint="为蕨墙村的杜高尔收集6个酸性毒囊。"}, [37]={hint="把指挥官的文件交给蕨墙村的纳泽尔·血矛。"}, [38]={hint="尘泥沼泽北部的马德克拉什要你去抓12条泥鳍小鱼。"}, [39]={npc="沼泽之眼加尔", tgt="沼泽之眼加尔"}, [40]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛"}, [41]={npc="杜高尔", tgt="杜高尔"}, [42]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛"}, [43]={npc="马德克拉什", tgt="马德克拉什"}, [44]={npc="杜高尔", tgt="杜高尔"}, [45]={hint="和蕨墙村的克罗格谈一谈。"}, [46]={npc="克罗格", tgt="克罗格"}, [47]={npc="克罗格", tgt="克罗格", tag="可选"}, [48]={text="可选的回程和跨区域任务"}, [49]={npc="沼泽之眼加尔", tgt="沼泽之眼加尔", tag="需要月钢宽剑、可选"}, [50]={hint="给尘泥沼泽的加尔找一把月光剑。", tag="需要月钢宽剑、可选", desc="请携带月钢宽剑上交。"}, [51]={npc="沼泽之眼加尔", tgt="沼泽之眼加尔", tag="需要月钢宽剑、可选"}, [52]={npc="松软的泥土", npcObj=true, tag="可选"}, [53]={hint="把兽人的头颅交给蕨墙村的纳泽尔·血矛。", tag="可选"}, [54]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛", tag="可选"}, [55]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛", tag="可选"}, [56]={npc="迪诺", tgt="迪诺", tag="可选", desc="通过奥格瑞玛。替代： 奥松·格鲁尔 25.70,14.19； 安娜斯塔西娅·哈特威尔 85.14,10.03。"}, [57]={hint="和塔贝萨谈一谈。", tag="可选"}, [58]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [59]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="保留 10 个图腾捆绑包。将它们组合在外禁锢法阵处。"}, [60]={hint="将电能草莓和1颗翡翠交给尘泥沼泽的塔贝萨。", tag="可选", desc="保留 10 个图腾捆绑包。将它们组合在外禁锢法阵处。"}, [61]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="保留 10 个图腾捆绑包。将它们组合在外禁锢法阵处。"}, [62]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [63]={hint="和闪光平原的大法师提尔斯谈一谈。", tag="可选"}, [64]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选"}, [65]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选", desc="瞄准鸡和/beckon。当它变成人类后与它交谈。"}, [66]={hint="找到提尔斯保险箱的解封咒语，然后向提尔斯复命。", tag="可选", desc="瞄准鸡和/beckon。当它变成人类后与它交谈。"}, [67]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选", desc="瞄准鸡和/beckon。当它变成人类后与它交谈。"}, [68]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选", desc="组队前往图书馆并在书架上找到这本书。"}, [69]={hint="将《能量仪祭》交给尘泥沼泽的塔贝萨。", tag="可选", desc="组队前往图书馆并在书架上找到这本书。进入血色修道院后走图书馆区。"}, [70]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="组队前往图书馆并在书架上找到这本书。"}, [71]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="回去复命前完成两条魔杖材料链。", star={"冰怒魔杖 / 虚空灵力魔杖 / 怒火魔杖"}}, [72]={hint="等塔贝萨的仪式完成后，和她谈一谈。", tag="可选", desc="回去复命前完成两条魔杖材料链。"}, [73]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="回去复命前完成两条魔杖材料链。", star={"冰怒魔杖 / 虚空灵力魔杖 / 怒火魔杖"}}, [74]={text="返回蕨墙村并飞往葬影村。如果该航线不可用，请在十字路口改签航班。保留您的壁炉，等待玛诺洛克集会所返回。"}}},
    ["03-21"] = {name="凄凉之地", nameA="凄凉之地 {a:2408}", tips={{k="取捨", text="视频中包含了这次回程。如果 37 级缺少经验，请执行东南半人马任务和附近的燃烧军团传送门。交出埃鲁索斯之手来解锁 燃烧军团的传送门。使用箱子为幽灵电浆引出鬼魂，然后一次杀死它们。"}, {k="取捨", text="现在接受盎格库尔 并在斯通纳德腿上进行。在村庄将其上交以解锁 杰恩可汗，您可以将其保存以供日后使用。"}, {k="提醒", text="38级以下？杀死玛诺洛克集会所边缘周围（50.40, 70.40周围）的普通恶魔。如果击杀速度很慢，请切换到科多兽坟场东南方向的半人马。", s={{"38级以下？"}, {"杀死玛诺洛克集会所边缘周围（50.40, 70.40周围）的普通恶魔"}, {"如果击杀速度很慢，请切换到科多兽坟场东南方向的半人马"}}}}, danger={[1]="精英领主在玛诺洛克集会所以南漫游。对于经验或材料，请前往东侧的法师猎人。"}, grind={[1]={mob="次级地狱火", note="玛诺洛克集会所以北普通小怪密集。留意附近的恶魔。术士可以收集次级地狱火石换取魔化金线血袍。"}, [2]={note="玛诺洛克集会所同外缘的普通脚轮密度适中。利用地形将它们从背包中拉开。与小型地狱火交替使用。"}, [3]={mob="法师猎手", note="玛诺洛克集会所以东的正常生物密度适中。挑掉边缘的单打并避开南边的精英领主。如果外环很拥挤，请使用此位置。"}}, supply={[1]={npc="萨隆"}, [2]={npc="旅店老板希科瓦"}, [3]={npc="海维拉尼"}, [4]={npc="旅店老板希科瓦"}, [5]={npc="图克"}}, steps={[1]={npc="泰迦·慧鬃", tgt="泰迦·慧鬃"}, [2]={text="从葬影村开始，先转到幽灵岗哨。沿南路行驶至玛诺洛克集会所。"}, [3]={npc="霍恩尼兹", tgt="霍恩尼兹"}, [4]={npc="智者乌泰克", tgt="智者乌泰克", tag="Gelkis 链有先决条件、可选"}, [5]={hint="放逐6个玛诺洛克集会所的传送门，然后回到葬影村的泰迦·慧鬃那里。", desc="在大厅的传送门上使用大河的埃鲁索斯之手驱逐六只恶魔。"}, [6]={hint="把幽灵磁铁箱和8份幽灵电浆交给凄凉之地的霍恩尼兹。", desc="将板条箱放在白骨之谷中。退后一步，将鬼魂一一拉开。"}, [7]={npc="霍恩尼兹", tgt="霍恩尼兹"}, [8]={npc="泰迦·慧鬃", tgt="泰迦·慧鬃"}, [9]={npc="迪诺", tgt="迪诺", tag="可选", desc="通过奥格瑞玛。替代： 奥松·格鲁尔 25.70,14.19； 安娜斯塔西娅·哈特威尔 85.14,10.03。"}, [10]={hint="和塔贝萨谈一谈。", tag="可选"}, [11]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [12]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [13]={hint="将一颗地狱火宝珠交给尘泥沼泽的塔贝萨。", tag="可选"}, [14]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [15]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="补充生命值和法力，然后要求塔贝萨开始驱魔。"}, [16]={hint="杀死宝珠之魔，然后与塔贝萨谈一谈。", tag="可选", desc="补充生命值和法力，然后要求塔贝萨开始驱魔。"}, [17]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="补充生命值和法力，然后要求塔贝萨开始驱魔。"}, [18]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="确认您的团队正在使用通往黑曜石哨兵的入口。"}, [19]={hint="找到一个黑曜石能量源，将其交给尘泥沼泽的塔贝萨。", tag="可选", desc="确认您的团队正在使用通往黑曜石哨兵的入口。从奥达曼后门进入，找黑曜石哨兵。"}, [20]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="确认您的团队正在使用通往黑曜石哨兵的入口。"}, [21]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="在接受之前先补充你的法力。当您接受时，计时器开始计时。"}, [22]={hint="在限定时间内杀死12只法力怒灵。", tag="可选", desc="在接受之前先补充你的法力。当您接受时，计时器开始计时。"}, [23]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="在接受之前先补充你的法力。当您接受时，计时器开始计时。"}, [24]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [25]={hint="完成任务目标。", tag="可选"}, [26]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [27]={text="使用炉石返回到 Shadowprey（如果绑定在那里）。否则跑回飞行大师那里。飞往奥格瑞玛火车。"}}},
    ["03-22"] = {name="奥特兰克山脉", tips={{k="取捨", text="检查塔伦米尔中的 拯救行动 和 通缉：辛迪加成员。一次性完成敦霍尔德城堡的两个先决条件。在奥特兰克中，交出 秘密潜入 来解锁 ，然后在辛迪加营地寻找高迪尔和瓦杜斯。"}, {k="提醒", text="使用这条腿和落锤镇达到 40 级。到达时检查你的经验。如果你只是矮，在前往落锤镇之前杀死普通的辛迪加怪物（58.44, 70.00）。", s={{"使用这条腿和落锤镇达到 40 级"}, {"到达时检查你的经验"}, {"如果你只是矮，在前往落锤镇之前杀死普通的辛迪加怪物（58.44, 70.00）"}}}}, danger={[1]="精英食人魔就在奥特兰克废墟里面。沿着外面的道路与普通的野兽战斗，直到你的队伍到达。"}, grind={[1]={mob="辛迪加间谍", note="辛迪加营地外密集的普通小怪。留意潜行的怪物和巫师。在落锤镇之前选择一点经验的单打。"}, [2]={note="奥特兰克废墟外的山路沿线正常小怪密集。呆在外面，避开精英，并在路线上保持单独的磨练。"}}, supply={[1]={npc="扎瑞斯"}, [2]={npc="旅店老板沙恩"}, [3]={npc="旅店老板沙恩"}, [4]={npc="凯伦·苏萨隆"}, [5]={npc="高顿·温德哈姆"}, [6]={npc="托马斯·莫丹"}, [7]={npc="艾泽基尔·格瑞乌斯"}}, steps={[1]={text="在奥格瑞玛外登上提瑞斯法飞艇。从布瑞尔南塔出发，前往幽暗城，飞往塔伦米尔并绑定您的炉石。"}, [2]={npc="梅里萨拉", tgt="梅里萨拉", tag="团体推荐、可选"}, [3]={npc="克鲁斯克", tgt="克鲁斯克"}, [4]={npc="通缉", npcObj=true, desc="通缉海报也提供了此任务（62.57, 20.66）。"}, [5]={hint="塔伦米尔的克鲁斯克要你把德鲁尔和托格萨从敦霍尔德城堡救出来。", desc="从敦霍尔德守卫手中抢走两把钥匙，然后释放两名囚犯。"}, [6]={hint="杀死10个辛迪加潜行者和10个辛迪加哨兵，然后回到塔伦米尔向高级执行官达萨利亚报告。"}, [7]={npc="克鲁斯克", tgt="克鲁斯克"}, [8]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [9]={npc="克鲁斯克", tgt="克鲁斯克"}, [10]={npc="通缉", npcObj=true, desc="通缉海报也提供了此任务（62.57, 20.66）。"}, [11]={hint="把关于高迪尔下落的消息带回来给塔伦米尔的克鲁斯克。"}, [12]={hint="塔伦米尔的梅里萨拉要你去杀掉14个破碎岭虐待者。", tag="团体推荐、可选", desc="在进入奥特兰克废墟之前，先集结精英 Crushridge Maulers。"}, [13]={npc="克鲁斯克", tgt="克鲁斯克"}, [14]={npc="梅里萨拉", tgt="梅里萨拉", tag="团体推荐、可选"}, [15]={npc="梅里萨拉", tgt="梅里萨拉", tag="可选"}, [16]={npc="克鲁斯克", tgt="克鲁斯克"}, [17]={hint="救出高迪尔，然后回到塔伦米尔去见克鲁斯克。"}, [18]={hint="杀了瓦杜斯男爵，把他的头带给塔伦米尔的高级执行官达萨利亚。", desc="检查高迪尔附近是否有瓦尔杜斯，然后搜索更北边的辛迪加营地。"}, [19]={npc="高迪尔", tgt="高迪尔"}, [20]={npc="高迪尔", tgt="高迪尔"}, [21]={hint="把高迪尔收集的消息带给塔伦米尔的克鲁斯克。"}, [22]={npc="克鲁斯克", tgt="克鲁斯克"}, [23]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [24]={hint="干掉塔尔格、玛克拉克和戈洛姆斯，把他们的头带给塔伦米尔的梅里萨拉。", tag="可选"}, [25]={npc="梅里萨拉", tgt="梅里萨拉", tag="可选"}, [26]={npc="梅里萨拉", tgt="梅里萨拉", tag="团体推荐、可选"}, [27]={hint="杀了玛格索尔，带着他的脑袋和意志之冠去塔伦米尔见梅里萨拉。", tag="团体推荐、可选"}, [28]={npc="梅里萨拉", tgt="梅里萨拉", tag="团体推荐、可选"}, [29]={npc="梅里萨拉", tgt="梅里萨拉", tag="团体推荐、可选"}, [30]={hint="把意志之冠交给幽暗城的沙琳德拉。", tag="团体推荐、可选"}, [31]={npc="沙琳德拉", tgt="沙琳德拉", tag="团体推荐、可选"}, [32]={npc="麦洛克斯", tgt="麦洛克斯", tag="可选", desc="需要24个；任务等级 36。在这次奥特兰克之旅中完成它。"}, [33]={hint="从巴顿身上偷走巴顿的侦察报告，然后把它交给拉文霍德庄园的麦洛克斯。", tag="可选、目标：巴顿", desc="需要24个；任务等级 36。在这次奥特兰克之旅中完成它。"}, [34]={npc="麦洛克斯", tgt="麦洛克斯", tag="可选", desc="需要24个；任务等级 36。在这次奥特兰克之旅中完成它。"}, [35]={npc="麦洛克斯", tgt="麦洛克斯", tag="可选", desc="从储物柜里抢走制服。继续伪装在斯托姆加德等待后续行动。"}, [36]={hint="从诺斯弗德农场弄一套辛迪加制服，用来潜入激流堡。", tag="可选", desc="从储物柜里抢走制服。继续伪装在斯托姆加德等待后续行动。"}, [37]={npc="辛迪加储物箱", npcObj=true, tag="可选", desc="从储物柜里抢走制服。继续伪装在斯托姆加德等待后续行动。"}, [38]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="携带 RFK 纸条。如果您的日志显示乱风岗，请将其转入 Rau (46.14, 51.71)。"}, [39]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="在 元素救兵 之后，参见 Bath'rah。如果您在乱风岗上交，请从 Rau 领取。"}, [40]={hint="与千针石林的普拉特·白云交谈。", tag="可选", desc="元素救兵后接受。"}, [41]={npc="普拉特·白云", tgt="普拉特·白云", tag="可选", desc="元素救兵后接受。"}, [42]={npc="普拉特·白云", tgt="普拉特·白云", tag="可选", desc="如果巴斯拉提供的话，请接受。在 25/27 站获取火/土；返回空气和水。"}, [43]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选、需要游戏内检查", desc="如果巴斯拉提供这个支线任务，就接受它。可以等到练级后。"}, [44]={hint="Return to Rau Cliffrunner in Thousand Needles at Freewind Post.", tag="可选、需要游戏内检查", desc="如果巴斯拉提供这个支线任务，就接受它。可以等到练级后。"}, [45]={npc="劳恩·峭壁行者", tgt="劳恩·峭壁行者", tag="可选、需要游戏内检查", desc="如果巴斯拉提供这个支线任务，就接受它。可以等到练级后。"}, [46]={text="经过辛迪加营地后，向东穿过索拉丁之墙回到阿拉希高地。"}}},
    ["03-23"] = {name="阿拉希高地", nameA="阿拉希高地 {a:321}", tips={{k="取捨", text="回访时一起完成后来的石拳、猛禽和辛迪加任务。如果您错过了之前的同名任务，请跳过后续任务。单击循环中 禁锢之石 的棋子，并将弗兹鲁克 (打开钥匙之石) 保存为一组。"}, {k="取捨", text="在法迪尔海湾领取打捞、水下宝藏和船长任务。完成解锁并获得护目镜。在同一趟水下进行 深海打捞 和 船长的复仇。将 保存为藏宝海湾，并在稍后访问法迪尔海湾时上交 。"}, {k="取捨", text="该视频将激流堡视为可选。首先做落锤镇附近的晶体和物镜。跳过激流堡任务 阿拉索符印 - 托卡拉尔 以节省旅行时间。"}, {k="提醒", text="当您经过斯通纳德时，解锁为飞行点。将悲伤沼泽任务保存到斯通纳德支线。", s={{"当您经过斯通纳德时，解锁为飞行点"}, {"将悲伤沼泽任务保存到斯通纳德支线"}}}, {k="提醒", text="40级以下？杀死落锤镇以东的枯须峡谷中的普通狗头人（大约 84、31）。一旦它们变成灰色，就切换到村外的普通枯木巨魔（大约 68、69）。", s={{"40级以下？"}, {"杀死落锤镇以东的枯须峡谷中的普通狗头人（大约 84、31）"}, {"一旦它们变成灰色，就切换到村外的普通枯木巨魔（大约 68、69）"}}}}, danger={[1]="激流堡守卫聚集在大门处。在交回印记链之前将它们分开拉动，并避免从建筑物内骚扰两个包。", [2]="水下生物守卫着法迪尔海湾残骸。进入前，戴上宝物狩猎护目镜并注意呼吸。"}, grind={[1]={mob="枯须勘探员", note="枯须峡谷深处、落锤镇东边的普通生物密度中等。分阶段清理狭窄的洞穴。留意罕见的地占师弗林塔格。"}, [2]={mob="枯须掘地工", note="干须隧道中密集的普通生物与探矿者混杂在一起。与水晶任务配对。出去时注意重生。"}, [3]={mob="水浪流放者", note="落锤镇西北部有密集的普通水元素。他们的等级比狗头人稍高，一直到 40 级。战士可以为他们的旋风斩武器收集护身符。"}}, supply={[1]={npc="尤尔达"}, [2]={npc="旅店老板埃德瓦"}, [3]={npc="穆塔"}, [4]={npc="旅店老板埃德瓦"}, [5]={npc="格劳德"}}, steps={[1]={npc="密斯莱尔水晶碎块", npcObj=true}, [2]={npc="托尔甘", tgt="托尔甘"}, [3]={npc="杜拉姆法尔", tgt="杜拉姆法尔"}, [4]={npc="托尔甘", tgt="托尔甘", tag="可选"}, [5]={hint="前往阿拉希高地的落锤镇，与森谷谈一谈。"}, [6]={npc="森古", tgt="森古"}, [7]={npc="森古", tgt="森古", tag="可选"}, [8]={hint="收集密斯莱尔之尘。"}, [9]={npc="虹光水晶碎块", npcObj=true}, [10]={npc="虹光水晶碎块", npcObj=true}, [11]={hint="从高地猎兽龙身上获取12颗迅猛龙的心脏，把它们交给托尔甘。"}, [12]={hint="杀死10个石拳蛮兵和4个石拳法师，然后向落锤村哨所的杜拉姆法尔复命。"}, [13]={hint="取回玛雷兹·考尔的血石宝珠，把它交给落锤村的托尔甘。", tag="可选"}, [14]={npc="托尔甘", tgt="托尔甘"}, [15]={npc="杜拉姆法尔", tgt="杜拉姆法尔"}, [16]={npc="托尔甘", tgt="托尔甘", tag="可选"}, [17]={npc="托尔甘", tgt="托尔甘"}, [18]={hint="把托尔甘的宝珠交给戈穆尔。"}, [19]={npc="戈穆尔", tgt="戈穆尔"}, [20]={npc="戈穆尔", tgt="戈穆尔"}, [21]={hint="和托尔甘谈一谈。"}, [22]={npc="托尔甘", tgt="托尔甘"}, [23]={npc="杜拉姆法尔", tgt="杜拉姆法尔", tag="可选"}, [24]={npc="科林法尔", tgt="科林法尔", tag="可选"}, [25]={hint="杀死15个石拳萨满祭司和10个石拳领主，然后向落锤村哨所的杜拉姆法尔复命。", tag="可选"}, [26]={hint="杀死奥卡拉尔，将他的头颅带给落锤村哨所的科林法尔。", tag="可选"}, [27]={npc="杜拉姆法尔", tgt="杜拉姆法尔", tag="可选"}, [28]={npc="科林法尔", tgt="科林法尔", tag="可选"}, [29]={hint="帮落锤村的森古拿回激流堡符印。", tag="可选"}, [30]={npc="森古", tgt="森古", tag="可选"}, [31]={npc="森古", tgt="森古", tag="可选"}, [32]={hint="从激流堡的守卫者那里取回11块符印碎片，把它们交给落锤村的托尔甘。", tag="可选"}, [33]={npc="托尔甘", tgt="托尔甘", tag="可选"}, [34]={npc="托尔甘", tgt="托尔甘", tag="可选"}, [35]={hint="把修复的索拉丁符印交给落锤村的森古。", tag="可选"}, [36]={npc="森古", tgt="森古", tag="可选"}, [37]={hint="从西禁锢之石、东禁锢之石和外禁锢之石中搜集烈焰钥匙、海浪钥匙和雷霆钥匙。"}, [38]={npc="内禁锢之石", npcObj=true}, [39]={npc="内禁锢之石", npcObj=true, tag="团体推荐、可选"}, [40]={hint="找到并杀死弗兹鲁克，然后把秩序魔棒带到阿拉希高地的钥匙之石旁。", tag="团体推荐、可选"}, [41]={npc="钥匙之石", npcObj=true, tag="团体推荐、可选"}, [42]={npc="钥匙之石", npcObj=true, tag="团体推荐、可选"}, [43]={hint="和落锤村的萨鲁克谈一谈。", tag="团体推荐、可选"}, [44]={npc="萨鲁克", tgt="萨鲁克", tag="团体推荐、可选"}, [45]={npc="萨鲁克", tgt="萨鲁克", tag="可选", desc="在落锤镇交接 密斯莱尔的盟友，然后从萨鲁克领取。保存为荒芜之地。"}, [46]={text="法迪尔海湾"}, [47]={npc="哨兵鲁鲁", tgt="哨兵鲁鲁"}, [48]={hint="和法迪尔海湾的奥布里船长交谈。"}, [49]={npc="沙克斯·奥布里", tgt="沙克斯·奥布里"}, [50]={npc="菲兹索普教授", tgt="菲兹索普教授"}, [51]={hint="护送菲兹索普教授到洞穴里去并平安返回。", desc="教授周围干净。护送他进入山洞，然后返回藏宝海湾。"}, [52]={npc="德拉克里格博士", tgt="德拉克里格博士"}, [53]={npc="大副尼兹利克斯", tgt="大副尼兹利克斯"}, [54]={npc="斯迪加特船长", tgt="斯迪加特船长"}, [55]={npc="德拉克里格博士", tgt="德拉克里格博士"}, [56]={hint="大副尼兹利克斯让你从处女号和银松之魂号中取回航海图和航海日志。"}, [57]={hint="法迪尔海湾的斯迪加特船长要你去杀掉10个刺脊袭击者和3个刺脊巫师。"}, [58]={hint="法迪尔海湾的德拉克里格博士要你去收集10块精灵宝石并在完成任务后归还寻宝潜水镜。", desc="接受护目镜 水下宝藏。佩戴它们来观赏水下宝石。与 深海打捞 和 船长的复仇 配对。"}, [59]={npc="大副尼兹利克斯", tgt="大副尼兹利克斯"}, [60]={npc="斯迪加特船长", tgt="斯迪加特船长"}, [61]={npc="德拉克里格博士", tgt="德拉克里格博士"}, [62]={npc="德拉克里格博士", tgt="德拉克里格博士"}, [63]={hint="把精灵宝石交给奥布里船长。"}, [64]={npc="沙克斯·奥布里", tgt="沙克斯·奥布里"}, [65]={npc="沙克斯·奥布里", tgt="沙克斯·奥布里"}, [66]={npc="托尔甘", tgt="托尔甘"}, [67]={npc="巴斯拉的大锅炉", npcObj=true, tag="可选", desc="如果需要，可以在 AH 上购买饰物。使用同一个坩埚来接受并上交。"}, [68]={hint="掉落自：枯须狗头人、枯须勘探员、枯须掘地工", tag="可选", desc="如果需要，可以在 AH 上购买饰物。使用同一个坩埚来接受并上交。"}, [69]={npc="巴斯拉的大锅炉", npcObj=true, tag="可选", desc="如果需要，可以在 AH 上购买饰物。使用同一个坩埚来接受并上交。"}, [70]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选"}, [71]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="40级精英任务。在触发之前先分组。"}, [72]={hint="将旋风之心带给捕风者巴斯拉。", tag="可选", desc="40级精英任务。在触发之前先分组。"}, [73]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="40级精英任务。在触发之前先分组。"}, [74]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", star={"旋风之斧 / 旋风之剑 / 旋风之锤"}}, [75]={hint="完成任务目标。", tag="可选"}, [76]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", star={"旋风之斧 / 旋风之剑 / 旋风之锤"}}, [77]={npc="辛迪加储物箱", npcObj=true, tag="可选", desc="进入前请穿上制服。避免战斗以保持伪装。"}, [78]={hint="While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal.", tag="可选", desc="进入前请穿上制服。避免战斗以保持伪装。"}, [79]={npc="安娜斯塔西娅·米勒", tgt="安娜斯塔西娅·米勒", tag="可选", desc="进入前请穿上制服。避免战斗以保持伪装。"}, [80]={npc="安娜斯塔西娅·米勒", tgt="安娜斯塔西娅·米勒", tag="可选"}, [81]={hint="Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal.", tag="可选", desc="通过激流堡在房子楼上找到阿纳斯塔西娅的藏品。"}, [82]={npc="安娜斯塔西娅·米勒", tgt="安娜斯塔西娅·米勒", tag="可选"}, [83]={npc="安娜斯塔西娅·米勒", tgt="安娜斯塔西娅·米勒", tag="可选", desc="货物由两名守卫看管。"}, [84]={hint="Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor.", tag="可选", desc="货物由两名守卫看管。"}, [85]={npc="麦洛克斯", tgt="麦洛克斯", tag="可选", desc="货物由两名守卫看管。"}, [86]={text="返回落锤镇。如果洛格玛和斯通纳德已解锁，请飞往洛格玛。首次访问时，请飞往斯通纳德。如果斯通纳德被锁定，则飞往格罗姆戈尔并向北穿过暮色森林，绕过夜色镇的守卫。向东经逆风小径进入悲伤沼泽。如果格罗姆高被锁定，请从布瑞尔南边的塔楼拿走它的齐柏林飞艇。", tag="尚未解锁这个飞行点，第一次请走过去。"}}},
    ["05-d17"] = {name="剃刀高地", entrance="贫瘠之地（1413），荆棘隧道深处的传送门，约49.10, 93.40。", pickup="从落锤镇飞往幽暗城。在微光平原部分，运行剃刀沼泽并掠夺 邪恶的盟友。在奥特兰克 - 落锤镇部分，转入幽暗城中的瓦里玛萨斯，然后从安德鲁那里拿走 寒冰之王。从提瑞斯法乘坐齐柏林飞艇到奥格瑞玛，然后飞往雷霆崖，在西北莫高雷看到苏塔拉·平原行者，票价为凛风之眼。飞往陶拉祖营地，然后向南前往入口外的麦雷姆·月歌。从爆破引线港出发，您还可以乘船前往热砂港，然后向北前往千针石林。", pickupS={{"从落锤镇飞往幽暗城"}, {"在微光平原部分，运行剃刀沼泽并掠夺 邪恶的盟友"}, {"在奥特兰克 - 落锤镇部分，转入幽暗城中的瓦里玛萨斯，然后从安德鲁那里拿走 寒冰之王"}, {"从提瑞斯法乘坐齐柏林飞艇到奥格瑞玛，然后飞往雷霆崖，在西北莫高雷看到苏塔拉·平原行者，票价为凛风之眼"}, {"飞往陶拉祖营地，然后向南前往入口外的麦雷姆·月歌"}, {"从爆破引线港出发，您还可以乘船前往热砂港，然后向北前往千针石林"}}, tips={{k="動線", text="清除火眼莫德雷斯附近奔尼斯特拉兹的牢房→交出誓言石并护送他到神像，如果遇到腐烂的普雷莫尔→走螺旋坡道到Amnennar并在附近寻找Coldbringer's Eye。"}, {k="取捨", text="与 40 级以上的团队一起跑完整个地下城。杀死 凛风之眼 和 寒冰之王 的最终 boss。在 34 岁时，接起眼球任务并在通过时在外面做 邪恶之地。"}, {k="說明", text="五人地下城。无需钥匙。走大升降梯以北的东路。 剃刀沼泽在西边。从河林出发，从爆破引线港乘船到热砂港，然后向北行驶。", s={{"五人地下城"}, {"无需钥匙"}, {"走大升降梯以北的东路"}, {"剃刀沼泽在西边"}, {"从河林出发，从爆破引线港乘船到热砂港，然后向北行驶"}}}, {k="提醒", text="五人地下城。无需钥匙。走大升降梯以北的东路。 剃刀沼泽在西边。从河林出发，从爆破引线港乘船到热砂港，然后向北行驶。", s={{"五人地下城"}, {"无需钥匙"}, {"走大升降梯以北的东路"}, {"剃刀沼泽在西边"}, {"从河林出发，从爆破引线港乘船到热砂港，然后向北行驶"}}}}, steps={[1]={npc="小卷轴", npcObj=true, tag="需要游戏内检查", desc="如果您已经从剃刀沼泽中的 Charlga 处抢劫了小卷轴，请跳过。"}, [2]={hint="把小卷轴交给幽暗城的瓦里玛萨斯。"}, [3]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯"}, [4]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯", desc="邪恶的盟友 后，在此接载。目标在剃刀高地外面的荆棘丛中。", preText="邪恶的盟友"}, [5]={npc="安德鲁·布隆奈尔", tgt="安德鲁·布隆奈尔", desc="在幽暗城的魔法区的37 级接受。"}, [6]={npc="苏塔拉·平原行者", tgt="苏塔拉·平原行者", desc="永恒版新增任务。"}, [7]={npc="麦雷姆·月歌", tgt="麦雷姆·月歌", desc="从南贫瘠之地的米里亚姆（49.01, 94.94）接受。进入前请清理外部。"}, [8]={hint="把玛克林大使的头颅交给幽暗城的瓦里玛萨斯。"}, [9]={hint="杀掉8个剃刀沼泽护卫者、8个剃刀沼泽织棘者和8个亡首教徒，然后向剃刀高地入口处的麦雷姆·月歌复命。"}, [10]={npc="麦雷姆·月歌", tgt="麦雷姆·月歌"}, [11]={text="剃刀高地 入口"}, [12]={npc="奔尼斯特拉兹", tgt="奔尼斯特拉兹", tag="需要游戏内检查", desc="在单元格中找到奔尼斯特拉兹。每个人都要在护送前完成宣誓。"}, [13]={hint="如果你同意帮助奔尼斯特拉兹，就再跟他谈谈，并将誓言石还给他。", desc="位置：在火眼莫德雷斯附近的单元格中找到奔尼斯特拉兹。顺序：在开始护送之前让每个人上交誓言石。", spot="在火眼莫德雷斯附近的单元格中找到奔尼斯特拉兹。"}, [14]={npc="奔尼斯特拉兹", tgt="奔尼斯特拉兹", tag="需要游戏内检查", spot="火眼莫德雷斯附近的牢房，贝尼斯特拉兹"}, [15]={npc="奔尼斯特拉兹", tgt="奔尼斯特拉兹", tag="需要游戏内检查", desc="等待整个队伍出发，然后靠近 NPC。", preText="剃刀高地的亡灵天灾"}, [16]={hint="保护奔尼斯特拉兹来到剃刀高地的野猪人神像处。", desc="位置：护送奔尼斯特拉兹从牢房到偶像并保护他。", spot="护送奔尼斯特拉兹从牢房到偶像并保护他。"}, [17]={npc="奔尼斯特拉兹的火盆", npcObj=true, tag="需要游戏内检查", spot="神像旁，贝尼斯塔兹的火盆"}, [18]={hint="安德鲁·布隆奈尔要你杀了寒冰之王亚门纳尔并将其头骨带回来。", desc="位置：离开牢房，沿着螺旋坡道到达阿门纳尔。", spot="离开牢房，沿着螺旋坡道到达阿门纳尔。"}, [19]={hint="从剃刀高地夺回凛风之眼。", desc="位置：在阿门纳尔的巢穴中找到寒冰之眼。顺序：与步骤 17 相同的区域。", spot="在阿门纳尔的巢穴中找到寒冰之眼。"}, [20]={npc="苏塔拉·平原行者", tgt="苏塔拉·平原行者"}, [21]={npc="安德鲁·布隆奈尔", tgt="安德鲁·布隆奈尔"}, [22]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯"}}},
    ["03-24"] = {tips={{k="取捨", text="第一次访问时，清除洛格玛周围的农场、豺狼人、河岸和野兽。将乔格扎克 (再也没有暮光！) 及其后续内容保存为一组。立即领取博尔德罗克野猪和采石场任务。保存 42+ 暮光和博尔德罗克和爆破引线港返回的沿海任务。"}, {k="取捨", text="解锁洛格玛的飞行点将行程缩短至卡加斯和斯通纳德。请参阅 Toka 了解补给品。"}, {k="提醒", text="任务交接后低于41级？杀死纳佐克农场（70.62, 33.08）以南的普通野猪或洛格玛以南的野兽（大约61、50）。保存后面的博尔德罗克暮光任务以获取爆破引线港返回。", s={{"任务交接后低于41级？"}, {"杀死纳佐克农场（70.62, 33.08）以南的普通野猪或洛格玛以南的野兽（大约61、50）"}, {"保存后面的博尔德罗克暮光任务以获取爆破引线港返回"}}}}, danger={[1]="法霍尔德斥候和牧师在洛格玛以南漫游。拉动单独的侦察兵以避免引入牧师。", [2]="阳光林地的暮光祭祀洞很窄。在扰乱仪式圈之前清理入口。留意在你身后重生的暗影法师。"}, grind={[1]={mob="低地秃鹰", note="洛格玛以南有密集的普通小怪。沿路挑单，躲避41-42级的精英猛兽，收集羽毛制作箭羽的羽毛。"}, [2]={mob="法霍德斥候", note="洛格玛以南的法霍尔德侦察区有密集的普通怪物。沿河清理教教他们规矩，并避免将牧师和斥候拉到一起。"}, [3]={mob="法霍德牧师", note="南岸西端正常脚轮密度适中。 中断可以治疗并阻止侦察兵的追击。在教教他们规矩的西腿这里磨。"}}, supply={[1]={npc="格拉克纳"}, [2]={npc="旅店老板托卡"}, [3]={npc="古尔多克"}, [4]={npc="纳鲁克"}, [5]={npc="玛卡"}, [6]={npc="布雷依克"}, [7]={npc="苏塔佐尔"}}, steps={[1]={nodeA="{a:75}", desc="如果从沼泽陆路过来，则为解锁、飞行点和布雷依克。否则跳过。"}, [2]={text="如果您已解锁洛格玛，请从斯通纳德起飞。第一次来时，从悲伤沼泽进入河林，沿着南侧道路经过泰拉尔之望（2548约60、64），然后向北前往洛格玛（视频26:56-27:13）。如果您是从落锤镇飞来的，请直接找飞行管理员。", tag="尚未解锁这个飞行点，第一次请走过去。"}, [3]={node="洛格玛", desc="解锁、飞行点和格拉克纳。"}, [4]={text="将您的炉石与旅店老板托卡 (57.58, 45.47) 绑定。"}, [5]={hint="向河林洛格玛哨所的克罗姆罗什复命。"}, [6]={hint="在河林的洛格玛找到塔恩加尼。"}, [7]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [8]={npc="塔恩加尼", tgt="塔恩加尼"}, [9]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [10]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [11]={npc="古尔多克", tgt="克雷扎·暗棘"}, [12]={npc="塔恩加尼", tgt="塔恩加尼"}, [13]={text="南部农场和西南豺狼人"}, [14]={hint="消灭12名草甸溪农场雇农，然后带着你胜利的消息向克罗姆罗什复命。", tag="目标：草甸溪农场雇农"}, [15]={hint="从草甸溪的联盟农场偷取6个饲料袋，然后向克罗姆罗什复命。"}, [16]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [17]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [18]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [19]={hint="将偷来的饲料交给洛格玛的戈尔格。"}, [20]={npc="戈尔格", tgt="戈尔格"}, [21]={npc="戈尔格", tgt="戈尔格"}, [22]={hint="在训练场喂饱8名洛格玛受训者。", tag="目标：洛格玛受训者"}, [23]={npc="戈尔格", tgt="戈尔格"}, [24]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [25]={hint="在河流以南消灭8个法霍德牧师和12个法霍德斥候。", tag="目标：法霍德牧师 / 法霍德斥候"}, [26]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [27]={npc="特兰古尔", tgt="特兰古尔"}, [28]={npc="特兰古尔", tgt="特兰古尔"}, [29]={text="河滨伐木场和阳光林地"}, [30]={hint="从特纳的伐木场的伐木工那里，为洛格玛的克雷扎·暗棘夺回10把木匠的斧头。", tag="目标：特纳磨坊伐木工"}, [31]={hint="从特纳的伐木场的农夫木柴堆中收集一捆木材，然后把它们削成20把简易穿刺长矛。"}, [32]={npc="古尔多克", tgt="克雷扎·暗棘"}, [33]={npc="古尔多克", tgt="克雷扎·暗棘", desc="借来的剑之后，在这里接受。在爆破引线港中为弗里兹保存剑。"}, [34]={npc="塔恩加尼", tgt="塔恩加尼"}, [35]={npc="塔恩加尼", tgt="塔恩加尼"}, [36]={hint="刺穿10只淡水鳄，然后回到洛格玛的特兰古尔那里。", tag="目标：淡水鳄"}, [37]={npc="塔恩加尼", tgt="塔恩加尼"}, [38]={hint="为洛格玛的特兰古尔消灭阳光林地中的8名暮光袭击者和8名暮光新教徒。", tag="目标：暮光袭击者/暮光暗影法师/暮光新教徒"}, [39]={hint="为洛格玛的特兰古尔从阳光林地的暮光暗影法师身上夺取3封暮光信件。", tag="目标：暮光暗影法师"}, [40]={npc="特兰古尔", tgt="特兰古尔"}, [41]={npc="特兰古尔", tgt="特兰古尔"}, [42]={npc="特兰古尔", tgt="特兰古尔"}, [43]={hint="说服阳光林地的一名暮光之锤矿工，让他泄露秘密。"}, [44]={npc="棍趾", tgt="棍趾"}, [45]={npc="棍趾", tgt="棍趾"}, [46]={hint="为棍趾在阳光林地下方的洞穴中寻找失踪的食人魔。"}, [47]={npc="强化蛮兵", tgt="暮光蛮兵"}, [48]={npc="强化蛮兵", tgt="暮光蛮兵"}, [49]={npc="棍趾", tgt="棍趾"}, [50]={hint="消灭5名强化蛮兵和10名暮光仪式师，然后回到阳光林地的棍趾那里。", tag="目标：强化蛮兵/暮光仪式师"}, [51]={hint="摧毁在阳光林地下方洞穴中发现的5个暮光仪式法阵。"}, [52]={npc="棍趾", tgt="棍趾"}, [53]={npc="棍趾", tgt="棍趾"}, [54]={npc="棍趾", tgt="棍趾", tag="团体推荐、可选"}, [55]={hint="在阳光林地的洞穴中消灭乔格扎克，并为棍趾收集他们的头颅。", tag="团体推荐、可选、目标：乔格扎克", desc="乔格扎克是克利尔伍德洞穴的 41 级精英。"}, [56]={npc="棍趾", tgt="棍趾", tag="团体推荐、可选"}, [57]={npc="棍趾", tgt="棍趾", tag="团体推荐、可选"}, [58]={hint="将乔格的徽记交给洛格玛的特兰古尔。", tag="团体推荐、可选"}, [59]={npc="特兰古尔", tgt="特兰古尔", tag="团体推荐、可选"}, [60]={npc="特兰古尔", tgt="特兰古尔", tag="团体推荐、可选"}, [61]={text="在洛格玛周围狩猎"}, [62]={npc="被剔骨的残骸", tgt="被剔骨的残骸", desc="单击南面野兽中间地面上的被啃咬的尸体。"}, [63]={hint="将啃过的颅骨交给洛格玛的涅扎·血吻。"}, [64]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [65]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [66]={hint="将完整的陆行鸟喙交给洛格玛的涅扎·血吻。", tag="目标：游荡的陆行鸟"}, [67]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [68]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [69]={hint="将6根平原秃鹰羽毛交给洛格玛的涅扎·血吻。", tag="目标：低地秃鹰"}, [70]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [71]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [72]={hint="将4份林地毒蛇毒液样本交给洛格玛的涅扎·血吻。", tag="目标：林地毒蛇"}, [73]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [74]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [75]={hint="收集6张珍贵的狮皮，交给洛格玛的涅扎·血吻。", tag="目标：狂野平原族长/狂野平原女