tag="可选"}, [113]={npc="卡尔·噬灵", tgt="卡尔·噬灵", tag="可选"}, [114]={hint="与棘齿城的斯坦哈德·法尔杉谈一谈。", tag="可选"}, [115]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", tag="可选"}, [116]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", desc="交入本地导入，然后从 Strahad 接听。"}, [117]={hint="与棘齿城的斯坦哈德·法尔杉谈一谈，学习召唤地狱战马的能力。", desc="交入本地导入，然后从 Strahad 接听。"}, [118]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", desc="交入本地导入，然后从 Strahad 接听。"}, [119]={text="如果解锁，请从洛格玛飞往卡加斯。第一次访问时，使用暮光营地以北的西山口进入荒芜之地，然后向西北到达卡加斯（视频27:55-28:03）。保留您的洛格玛壁炉以供退货。", tag="尚未解锁这个飞行点，第一次请走过去。"}}},
    ["03-25"] = {name="荒芜之地", nameA="荒芜之地 {a:340}", tips={{k="取捨", text="岩石元素与荒芜之地的试剂 重叠。在战斗前完成这两个任务。边走边拾取 30 个郊狼下巴，并在达到目标等级后继续前进。"}, {k="取捨", text="仅当您有冰霜之油、 发条式同步协调陀螺仪和药水时才执行 至关重要的冷却剂 - 卢希恩的药水。为更高级别或群组保存破碎的联盟 。"}, {k="提醒", text="视频列车在 40 级城市之旅中行驶。如果你达到了 40 级并且可以负担得起，请在经过时拜访你的种族的骑术训练师。请参阅下面的职业任务和 40 级骑行说明。", s={{"视频列车在 40 级城市之旅中行驶"}, {"如果你达到了 40 级并且可以负担得起，请在经过时拜访你的种族的骑术训练师"}, {"请参阅下面的职业任务和 40 级骑行说明"}}}, {k="提醒", text="42级以下？杀死荒芜之地西南部（6.65, 73.85 附近）的普通巨型岩石元素。如果那个地方很拥挤，请切换到卡加斯东南山脊上的土狼和秃鹰。", s={{"42级以下？"}, {"杀死荒芜之地西南部（6.65, 73.85 附近）的普通巨型岩石元素"}, {"如果那个地方很拥挤，请切换到卡加斯东南山脊上的土狼和秃鹰"}}}}, danger={[1]="39-40 级精英石窟先知和斗士在东部漫游荒芜之地。避开奥达曼时，对他们敬而远之。"}, grind={[1]={mob="巨型石元素", note="卡加斯以南的悬崖边有密集的普通小怪。沿着岩石清理外面并留意火肠食人魔。如果在 42 之前太难，请切换到山脊。"}, [2]={note="卡加斯东南山脊上的普通生物密度适中。避免精英和稀有巡逻。在 41 级单独刷，或者如果元素拥挤的话切换到这里。"}, [3]={mob="巨型秃鹫", note="卡加斯东南的斜坡上普通生物的密度中等。与山脊小怪交替。如果需要的话，拿起秃鹰的翅膀或砂囊。"}}, supply={[1]={npc="格里克"}, [2]={npc="旅店老板舒尔卡"}, [3]={npc="斯兰达"}, [4]={npc="旅店老板舒尔卡"}, [5]={npc="格劳尔"}}, steps={[1]={nodeA="{a:340}", desc="解锁、飞行点和格里克。"}, [2]={text="如果需要，请留下来培训技能或学习骑术。随后飞回卡加斯。"}, [3]={npc="加卡尔", tgt="加卡尔"}, [4]={npc="尼卡·血痕", tgt="尼卡·血痕"}, [5]={npc="尼卡·血痕", tgt="尼卡·血痕"}, [6]={npc="高恩", tgt="高恩", tag="可选"}, [7]={text="岩石元素和中央生物循环"}, [8]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯"}, [9]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯", tag="需要材料、可选"}, [10]={hint="找到冰霜之油，把它交给荒芜之地的鲁特维尔·沃拉图斯。", tag="需要材料、可选", desc="将冰霜之油带到鲁特维尔·沃拉图斯。在这里交付。冰霜之油可由炼金术士制作。"}, [11]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯", tag="需要材料、可选"}, [12]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯", tag="需要材料、可选"}, [13]={hint="给荒芜之地的鲁特维尔·沃拉图斯带去一个发条式同步协调陀螺仪。", tag="需要材料、可选", desc="首先获得一个发条式同步协调陀螺仪。工程师可以制作它。"}, [14]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯", tag="需要材料、可选"}, [15]={npc="卢希恩·枪穗", tgt="卢希恩·枪穗", tag="需要材料、可选"}, [16]={hint="为荒芜之地的卢希恩·枪穗找到一瓶次级隐形药水和一瓶治疗药水。", tag="需要材料、可选"}, [17]={npc="卢希恩·枪穗", tgt="卢希恩·枪穗", tag="需要材料、可选"}, [18]={hint="收集10块小石头碎块，把它们交给荒芜之地的鲁特维尔·沃拉图斯。"}, [19]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯"}, [20]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯"}, [21]={hint="把菲兹尔·铜栓的信带给荒芜之地的流放者马特克。"}, [22]={npc="流放者马特克", tgt="流放者马特克"}, [23]={npc="流放者马特克", tgt="流放者马特克"}, [24]={npc="里格弗兹", tgt="里格弗兹"}, [25]={hint="找到迷失者塞尔杜林。", tag="可选"}, [26]={npc="迷失者塞尔杜林", tgt="迷失者塞尔杜林", tag="可选"}, [27]={npc="迷失者塞尔杜林", tgt="迷失者塞尔杜林", tag="可选"}, [28]={hint="收集3块大石片，把它们交给荒芜之地的鲁特维尔·沃拉图斯。"}, [29]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯"}, [30]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯"}, [31]={hint="收集5个石缚护腕，把它们交给荒芜之地的鲁特维尔·沃拉图斯。", desc="农场石缚护腕，来自西南部的普通大型岩石元素。"}, [32]={hint="收集10块精铁碎片，把它们交给荒芜之地的流放者马特克。"}, [33]={hint="给里格弗兹带去4只秃鹫的翅膀。"}, [34]={hint="把破损的卷轴碎片、弄皱的卷轴碎片和烧焦的卷轴碎片带给迷失者塞尔杜林。", tag="可选"}, [35]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯"}, [36]={npc="流放者马特克", tgt="流放者马特克"}, [37]={npc="里格弗兹", tgt="里格弗兹"}, [38]={npc="迷失者塞尔杜林", tgt="迷失者塞尔杜林", tag="可选"}, [39]={hint="前往荒芜之地取回加卡尔需要的试剂，然后回到卡加斯把试剂交给他。"}, [40]={hint="带30块山狗的颚骨去见卡加斯的尼卡·血痕。"}, [41]={hint="杀掉索格伦，把大地印章交给卡加斯的高恩。", tag="团体推荐、可选"}, [42]={npc="加卡尔", tgt="加卡尔"}, [43]={npc="尼卡·血痕", tgt="尼卡·血痕"}, [44]={npc="高恩", tgt="高恩", tag="团体推荐、可选"}, [45]={npc="加卡尔", tgt="加卡尔", tag="仅适用于奥达曼运行、可选"}, [46]={text="如果您知道骑术，请从卡加斯飞往格罗姆戈尔，然后再飞往藏宝海湾。否则请拜访您的种族骑术教练。如果您在奥格瑞玛或幽暗城附近，请乘坐格罗姆戈尔齐柏林飞艇。"}}},
    ["05-d18"] = {name="奥达曼", entrance="荒芜之地（1418），关于42.60, 10.80。沿着地下挖掘地点前进。后门坐标未知。", pickup="从卡加斯接近奥达曼。在奥特兰克和落锤镇赛段，从幽暗城的帕特里克那里获得 寻找宝物。从落锤镇或格罗姆戈尔飞往卡加斯，做贾卡尔的 荒芜之地的试剂 → 奥达曼的蘑菇，然后参观里格弗兹和塞尔杜林。法师可以从35级开始完成塔贝萨的尘泥先决条件。对于项链链，在第一次运行时掠夺破碎的项链，在访问奥格瑞玛时将其交给德兰，然后通过卡加斯返回。", pickupS={{"从卡加斯接近奥达曼"}, {"在奥特兰克和落锤镇赛段，从幽暗城的帕特里克那里获得 寻找宝物"}, {"从落锤镇或格罗姆戈尔飞往卡加斯，做贾卡尔的 荒芜之地的试剂 → 奥达曼的蘑菇，然后参观里格弗兹和塞尔杜林"}, {"法师可以从35级开始完成塔贝萨的尘泥先决条件", {class={"MAGE"}}}, {"对于项链链，在第一次运行时掠夺破碎的项链，在访问奥格瑞玛时将其交给德兰，然后通过卡加斯返回"}}, tips={{k="動線", text="正门→鲁维罗什→从遗骸中掠夺日志。在下次运行之前返回卡加斯进行翻译。法师可以从后门到达黑曜石哨兵。第二个挖掘地点→加尔甘→格瑞姆洛克→阿扎达斯→诺甘农圆盘。"}, {k="取捨", text="优先考虑 奥达曼的蘑菇、 寻找宝物 和 能量石。在 40 级时，获得圆盘和袋子。项链至少需要两次，所以如果练级很快就跳过它。"}, {k="說明", text="五人地下城。 34级，在幽暗城走寻找宝物，穿过荒芜之地时做外洞。最终boss的目标是达到42级。使用前门进行完全清除或项链，或使用后门进行后半部分或法师任务。如果您的地图仅标记了地表洞穴，请沿着主隧道前往传送门。", s={{"五人地下城"}, {"34级，在幽暗城走寻找宝物，穿过荒芜之地时做外洞"}, {"最终boss的目标是达到42级"}, {"使用前门进行完全清除或项链，或使用后门进行后半部分或法师任务"}, {"如果您的地图仅标记了地表洞穴，请沿着主隧道前往传送门"}}}, {k="提醒", text="五人地下城。 34级，在幽暗城走寻找宝物，穿过荒芜之地时做外洞。最终boss的目标是达到42级。使用前门进行完全清除或项链，或使用后门进行后半部分或法师任务。如果您的地图仅标记了地表洞穴，请沿着主隧道前往传送门。", s={{"五人地下城"}, {"34级，在幽暗城走寻找宝物，穿过荒芜之地时做外洞"}, {"最终boss的目标是达到42级"}, {"使用前门进行完全清除或项链，或使用后门进行后半部分或法师任务"}, {"如果您的地图仅标记了地表洞穴，请沿着主隧道前往传送门"}}}}, steps={[1]={npc="帕特里克·加瑞特", tgt="帕特里克·加瑞特", desc="在第 33 层的幽暗城中拾取。箱子位于传送门外。"}, [2]={npc="里格弗兹", tgt="里格弗兹", desc="在同一次旅行中从影炉矮人那里拾取能量石。"}, [3]={npc="迷失者塞尔杜林", tgt="迷失者塞尔杜林", desc="Theldurin位于荒芜之地南部。如果你是路过的就接受吧。"}, [4]={npc="加卡尔", tgt="加卡尔", desc="如果您在卡加斯提交了此任务，请直接领取 奥达曼的蘑菇。"}, [5]={hint="前往荒芜之地取回加卡尔需要的试剂，然后回到卡加斯把试剂交给他。"}, [6]={npc="加卡尔", tgt="加卡尔"}, [7]={npc="加卡尔", tgt="加卡尔", desc="荒芜之地的试剂 转弯后，在卡加斯的 Jarkal 接载。", preText="荒芜之地的试剂"}, [8]={npc="迪诺", tgt="迪诺", desc="35 岁时，在布雷肯沃尔和暗影掠食之间做这个任务。如果上交则跳过。"}, [9]={hint="和塔贝萨谈一谈。"}, [10]={npc="塔贝萨", tgt="塔贝萨"}, [11]={npc="塔贝萨", tgt="塔贝萨"}, [12]={hint="将一颗地狱火宝珠交给尘泥沼泽的塔贝萨。"}, [13]={npc="塔贝萨", tgt="塔贝萨"}, [14]={npc="塔贝萨", tgt="塔贝萨", preText="地狱火宝珠"}, [15]={hint="杀死宝珠之魔，然后与塔贝萨谈一谈。"}, [16]={npc="塔贝萨", tgt="塔贝萨"}, [17]={npc="塔贝萨", tgt="塔贝萨", desc="塔贝萨驱魔后接。要求小组清除后门哨兵。", preText="驱除魔鬼"}, [18]={hint="从奥达曼南部大厅的箱子中找到加勒特的家族宝藏，然后把它交给幽暗城的帕特里克·加瑞特。"}, [19]={hint="给荒芜之地的里格弗兹带去8块德提亚姆能量石和8块安纳洛姆能量石。"}, [20]={hint="把雷乌纳石板带给迷失者塞尔杜林。"}, [21]={npc="德兰·杜佛斯", tgt="德兰·杜佛斯", desc="可选链条。从挖掘地点或地牢矮人中拾取破碎的项链。"}, [22]={hint="在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。"}, [23]={npc="德兰·杜佛斯", tgt="德兰·杜佛斯"}, [24]={npc="德兰·杜佛斯", tgt="德兰·杜佛斯", desc="如果运行奥达曼一次，则跳过此链。 搜寻项链 转交后从 Dran 接载。", preText="搜寻项链"}, [25]={text="奥达曼 入口"}, [26]={hint="收集12颗紫色蘑菇，把它们交给卡加斯的加卡尔。", desc="紫色蘑菇生长在副本门外。位置：在大门外采集蘑菇，然后沿着挖掘隧道完成任务。", spot="在大门外采集蘑菇，然后沿着挖掘隧道完成任务。"}, [27]={hint="找到一个黑曜石能量源，将其交给尘泥沼泽的塔贝萨。", desc="位置：从后门进去。 黑曜石哨兵就在附近。", spot="从后门进去。 黑曜石哨兵就在附近。"}, [28]={hint="在奥达曼里找寻宝石的线索。", desc="位置：走主入口。在鲁维罗什过去的房间里找到尸体。顺序：离开地牢前往步骤 30 和 33。", spot="走主入口。在鲁维罗什过去的房间里找到尸体。"}, [29]={npc="圣骑士的遗体", tgt="圣骑士的遗体", tag="需要游戏内检查", spot="雷弗洛什身后房间的圣骑士遗体"}, [30]={npc="圣骑士的遗体", tgt="圣骑士的遗体", tag="需要游戏内检查", desc="在尸体处捡起日记，返回卡加斯即可解锁下一次旅程。", preText="搜寻项链，再来一次"}, [31]={hint="在荒芜之地的卡加斯哨所里寻找一个可以帮你翻译圣骑士日记的人。"}, [32]={npc="加卡尔", tgt="加卡尔"}, [33]={npc="加卡尔", tgt="加卡尔", preText="翻译日记"}, [34]={hint="将项链借给加卡尔。作为交换，他将帮你翻译日记。"}, [35]={npc="加卡尔", tgt="加卡尔"}, [36]={npc="加卡尔", tgt="加卡尔", desc="收到卡加斯的翻译后接受。第二次运行完全清晰。", preText="翻译日记"}, [37]={hint="从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。", desc="位置：检查第二个挖掘地点的瓮，然后是 Galgann、格瑞姆洛克和最后的 Boss。顺序：首先取出黄玉，然后是红宝石和蓝宝石，最后是电源。", spot="检查第二个挖掘地点的瓮，然后是 Galgann、格瑞姆洛克和最后的 Boss。"}, [38]={npc="诺甘农圆盘", npcObj=true, tag="需要游戏内检查", desc="在 40 级以上，杀死阿扎达斯并点击最后一个房间中的诺甘农圆盘。"}, [39]={hint="和石头守护者交谈，从他那里了解更多古代的知识。一旦你了解到了所有的内容之后就激活诺甘农圆盘。", desc="位置：杀死阿扎达斯并使用他身后金库中的诺甘农圆盘。顺序：聆听石头看守者，然后单击光盘。", spot="杀死阿扎达斯并使用他身后金库中的诺甘农圆盘。"}, [40]={npc="诺甘农圆盘", npcObj=true, tag="需要游戏内检查", spot="阿扎达斯后方宝库的诺甘农圆盘"}, [41]={npc="诺甘农圆盘", npcObj=true, tag="需要游戏内检查", desc="使用相同的光盘接受部落交货。 返回雷霆崖。", preText="白金圆盘"}, [42]={npc="加卡尔", tgt="加卡尔"}, [43]={npc="里格弗兹", tgt="里格弗兹"}, [44]={npc="迷失者塞尔杜林", tgt="迷失者塞尔杜林"}, [45]={npc="帕特里克·加瑞特", tgt="帕特里克·加瑞特"}, [46]={npc="塔贝萨", tgt="塔贝萨"}, [47]={hint="把迷你版的诺甘农圆盘带到雷霆崖的贤者那里。"}, [48]={npc="圣者图希克", tgt="圣者图希克"}, [49]={npc="加卡尔", tgt="加卡尔"}, [50]={npc="加卡尔", tgt="加卡尔", preText="寻找宝贝"}, [51]={hint="把项链和宝石送到奥格瑞玛的德兰·杜佛斯那里。"}, [52]={npc="德兰·杜佛斯", tgt="德兰·杜佛斯"}, [53]={npc="德兰·杜佛斯", tgt="德兰·杜佛斯", preText="交付宝石"}, [54]={hint="去卡加斯看看加卡尔是否成功了。"}, [55]={npc="加卡尔", tgt="加卡尔"}}},
    ["03-26"] = {name="荆棘谷", tips={{k="取捨", text="在第二次藏宝海湾访问时，上交已完成的任务，例如 水下宝藏、 风险投资公司 和 刨花皮靴。在海岸附近进行血帆 血帆海盗 → 血帆海盗 → 血帆海盗，然后将 血帆海盗 与 海盗的眼睛 和 鼻烟 配对。 血帆海盗 为三位队长解锁 血帆海盗。交任务 吓唬病鬼 → 向马克基雷回报 以解锁 讨债行动。返回城镇以解锁这些内容。"}, {k="取捨", text="在血帆船上接载科泰罗的谜题 ，并在经过斯通纳德时完成路线的第一部分。如果需要避免再次飞行，请沿途完成 刨花皮靴 和 风险投资公司。登船前先上岸办理讨债行动。"}, {k="提醒", text="藏宝海湾和博尔德罗克 / 爆破引线港腿一起带你到45级。如果你在这里很短，在三艘船之后杀死岸上的普通血帆海盗（大约32、79）。", s={{"藏宝海湾和博尔德罗克 / 爆破引线港腿一起带你到45级"}, {"如果你在这里很短，在三艘船之后杀死岸上的普通血帆海盗（大约32、79）"}}}}, danger={[1]="莫什奥格食人魔山有多种食人魔类型，包括精英。对于格罗姆高计划，从山脚下撤出并远离营地。", [2]="血帆船的楼梯很窄，出口也很少。登船前清理海岸，然后在离开前清理各个甲板。"}, grind={[1]={mob="血帆流氓", note="藏宝海湾外面的海滩上有密集的普通小怪。首先清除岸上并观察执行血帆任务的玩家。完成飞船任务后在这里磨练。"}, [2]={mob="血帆术士", note="血帆南部海岸上有密集的普通脚轮。先清除附近的近战小怪，然后拉术士。循环上岸以节省登船时间。"}}, supply={[1]={npc="格林戈"}, [2]={npc="旅店老板斯金德"}, [3]={npc="祖塔克"}, [4]={npc="尼克拉克斯·菲拉莫格"}, [5]={npc="哈伦·坎麦尔"}, [6]={npc="塞斯塔"}, [7]={npc="旅店老板苏贝克"}, [8]={npc="克拉克"}, [9]={npc="纳加特"}}, steps={[1]={text="抵达格罗姆戈尔后，飞往藏宝海湾执行下一批任务。如果您在附近开始，请先接营地任务。"}, [2]={hint="把精灵宝石样本交给藏宝海湾的舰队指挥官海角。"}, [3]={npc="舰队指挥官卡拉·海角", tgt="舰队指挥官卡拉·海角"}, [4]={npc="舰队指挥官卡拉·海角", tgt="舰队指挥官卡拉·海角", tag="以后顺路做、可选"}, [5]={npc="大副克拉兹", tgt="大副克拉兹"}, [6]={npc="海狼马克基雷", tgt="海狼马克基雷"}, [7]={npc="海盗布劳兹", tgt="海盗布劳兹"}, [8]={npc="克兰克·菲兹巴布", tgt="克兰克·菲兹巴布"}, [9]={npc="科博克", tgt="科博克"}, [10]={npc="崔斯里克", tgt="崔斯里克"}, [11]={npc="崔斯里克", tgt="崔斯里克"}, [12]={npc="码头管理员罗兹基尔", tgt="码头管理员罗兹基尔", tag="需要祖尔昆达护卫、可选"}, [13]={npc="克拉兹克", tgt="克拉兹克", tag="在悲伤沼泽中的斯通纳德进行、可选", desc="在闪光平地做棘齿城和 侏儒的货物 中的 给克拉维尔的零件，然后在藏宝海湾中交 车手的传闻。"}, [14]={text="侦察北海滩，然后解锁藏宝海湾中的血帆任务"}, [15]={hint="大副克拉兹要求你去侦察一下藏宝海湾北边的海滩。"}, [16]={npc="血帆海盗的信件", npcObj=true}, [17]={npc="血帆海盗的信件", npcObj=true}, [18]={hint="将你的发现报告给藏宝海湾的大副克拉兹。"}, [19]={npc="大副克拉兹", tgt="大副克拉兹"}, [20]={npc="大副克拉兹", tgt="大副克拉兹"}, [21]={hint="把血帆海盗的计划报告给舰队指挥官海角。"}, [22]={npc="舰队指挥官卡拉·海角", tgt="舰队指挥官卡拉·海角"}, [23]={npc="舰队指挥官卡拉·海角", tgt="舰队指挥官卡拉·海角"}, [24]={npc="独眼迪兹", tgt="独眼迪兹"}, [25]={npc="迪格", tgt="迪格"}, [26]={text="对于额外的营地任务，从藏宝海湾飞往格罗姆戈尔，然后向南飞向港口。"}, [27]={hint="把兽人的头颅带到荆