    ["03-27"] = {name="悲伤沼泽", nameA="悲伤沼泽 {a:75}", tips={{k="取捨", text="打开笼子之前，清理加林的逃亡 的路径。将其交给护送人员末端的保险箱。"}, {k="取捨", text="保存缺乏补给 ( →)、海中的威胁 ( → → 1427 →) 和新鲜的螃蟹腿 用于东南海岸水平返回47+。视频在 30:50 左右播放。"}, {k="提醒", text="上交西侧的科泰罗的卷轴，然后前往农田避难所。一起完成水晶任务和两个失落者链。需要一点经验吗？杀死泪水之池周围的普通小怪（大约 60、55），或者在东风海岸追上。", s={{"上交西侧的科泰罗的卷轴，然后前往农田避难所"}, {"一起完成水晶任务和两个失落者链"}, {"需要一点经验吗？"}, {"杀死泪水之池周围的普通小怪（大约 60、55），或者在东风海岸追上"}}}}, danger={[1]="在与盖伦交谈之前清理笼子区域和营地出口。打开笼子后拉扯会让你们俩都更难活下去。"}, grind={[1]={note="泪水之池以北的普通小怪密度适中。从干燥的土地上拉出来以避免绿龙。使用这个途中地点来一点经验。"}, [2]={mob="沼泽喷墨鱼人", note="斯通纳德东南方的正常鱼人密度中等。一次将一名敌人从营地外拉出来，而无需追赶成群。擅长42-43。"}, [3]={mob="沼泽食腐鱼人", note="同一鱼人营地南边的普通生物密度适中。 44 岁之前注意更高级别的神谕者并与 Inkspitters 交替。"}}, supply={[1]={npc="布雷依克"}, [2]={npc="旅店老板卡拉库尔"}, [3]={npc="卡尔拉什"}, [4]={npc="索尔塔什"}, [5]={npc="苏塔佐尔"}}, steps={[1]={text="检查布雷依克的斯通纳德飞行点是否已解锁 (46.07, 54.83)。"}, [2]={hint="把尼卡的报告带给斯通纳德的赫格拉姆。"}, [3]={npc="赫格拉姆", tgt="赫格拉姆"}, [4]={npc="费泽鲁尔", tgt="费泽鲁尔"}, [5]={text="西桥下和港口处"}, [6]={hint="解开这道迷题！"}, [7]={npc="浸水的卷轴", npcObj=true}, [8]={npc="浸水的卷轴", npcObj=true, tag="以后顺路做"}, [9]={npc="玛格图尔", tgt="玛格图尔"}, [10]={npc="卡拉纳", tgt="卡拉纳"}, [11]={npc="佩卢克", tgt="佩卢克"}, [12]={hint="为藏宝海湾的克拉兹克收集10份梦境之尘。", tag="可选"}, [13]={hint="继续和吉尔吉斯部族保持良好的关系，并把德莱尼水晶碎片交给凄凉之地吉尔吉斯村的智者乌泰克。", tag="可选"}, [14]={hint="在农田避难所消灭10名失落者。"}, [15]={hint="找到偷走佩卢克鱼饵的失落者渔夫，并将鱼饵夺回来。"}, [16]={hint="给悲伤沼泽避难营地里的玛格图尔带去6块德莱尼水晶。"}, [17]={npc="诺博鲁的木棒", npcObj=true, tag="如果掉落，请执行以下操作、可选", desc="杀死巡逻的木棒诺博鲁并右键单击他的棍子开始。"}, [18]={hint="把诺博鲁的木棒交到悲伤沼泽中的避难营领导人手中。", tag="如果掉落，请执行以下操作、可选"}, [19]={npc="玛格图尔", tgt="玛格图尔", tag="如果掉落，请执行以下操作、可选"}, [20]={text="东北护航及泪水之池"}, [21]={npc="加林·古瓦德", tgt="加林·古瓦德"}, [22]={hint="护送加林逃出困境，然后打开他放在悲伤沼泽营地里的保险箱。", desc="清理笼子并退出。护送盖伦并在最后到他的保险箱处交还。"}, [23]={npc="加林的保险箱", npcObj=true}, [24]={npc="玛格图尔", tgt="玛格图尔"}, [25]={npc="卡拉纳", tgt="卡拉纳"}, [26]={npc="佩卢克", tgt="佩卢克"}, [27]={hint="斯通纳德的费泽鲁尔要求你收集10件阿塔莱神器。"}, [28]={npc="费泽鲁尔", tgt="费泽鲁尔"}, [29]={npc="费泽鲁尔", tgt="费泽鲁尔", tag="用沉没的神庙做、可选"}, [30]={npc="欧文·萨德", tgt="欧文·萨德", tag="可选", desc="获得所有室外和地牢材料后，返回图书馆。"}, [31]={hint="找到并收集图书管理员所要求的法术书材料。", tag="可选", desc="获得所有室外和地牢材料后，返回图书馆。"}, [32]={npc="欧文·萨德", tgt="欧文·萨德", tag="可选", desc="获得所有室外和地牢材料后，返回图书馆。"}, [33]={text="从斯通纳德乘坐河林飞往洛格玛。没有飞行点就中途加入？沿着公路跑到那里并在到达时解锁。"}}},
    ["03-28"] = {tips={{k="取捨", text="北环链和暮光之帷链可选。如果您已完成暮光 No More!，请返回博尔德罗克。上交克鲁格菲斯特的法令，然后在洛格玛处领取任性的战士。在第一个爆破引线港海盗循环中掠夺走私货物。第二步，收集小桶，杀死庞巴迪人，并在破坏船只之前交付走私者的包裹。海怪是一个山洞绕道。仅当经验短缺且 NPC 提供时才做这个任务。"}, {k="提醒", text="45级以下？沿着东风海岸杀死东海海盗和火枪手（大约 84、35-43）。到港口补货。在 40-45 分，在洛格玛中服用 莫格之眼 和 暮光宝典 后，与一组一起跑克罗多克要塞。", s={{"45级以下？"}, {"沿着东风海岸杀死东海海盗和火枪手（大约 84、35-43）"}, {"到港口补货"}, {"在 40-45 分，在洛格玛中服用 莫格之眼 和 暮光宝典 后，与一组一起跑克罗多克要塞"}}}, {k="交通", text="45级，从爆破引线港（80.60, 54.60）乘坐中立船到热砂港（68.60, 23.00），然后前往加基森。留在东部王国，返回洛格玛飞行点。如果从塔纳利斯到达，请走陆路解锁。"}}, danger={[1]="斥候长瓦加斯是精英。等待你的队伍靠近之前，并分别拉动附近的巡逻队。", [2]="东海火枪手可以从远程加入。在破坏船只之前，沿着海滩拉海盗并清理登船路径。"}, grind={[1]={mob="东海冒险家", note="爆破引线港以北的东风海岸处有密集的普通生物。一次将一名敌人拉到海滩上的火枪手中间。与 恶性竞争 配对。"}, [2]={mob="东海火枪手", note="东风海岸中部海盗中密集的正常范围小怪。近战可以利用地形将他们吸引到岸上。研磨至45。"}}, supply={[1]={npc="格拉克纳"}, [2]={npc="旅店老板吉兹普林克"}, [3]={npc="米卡·达比"}, [4]={npc="旅店老板吉兹普林克"}, [5]={npc="格里泽克"}, [6]={npc="克里克香克"}}, steps={[1]={text="上交暮光后才可乘坐北环线前往克鲁格菲斯特不再！并占领巨人之地。携带克鲁格菲斯特的法令返回洛格玛，然后向西前往暮光之帷。如果跳过链条，请从洛格玛向东走到爆破引线港。", tag="可选"}, [2]={npc="克鲁格菲斯特", tgt="克鲁格菲斯特", tag="需要北方先决条件、可选"}, [3]={npc="克鲁格菲斯特", tgt="克鲁格菲斯特", tag="需要北方先决条件、可选"}, [4]={hint="为博尔德罗克的克鲁格菲斯特消灭7名暮光虐待者和7名暮光唤火者。", tag="需要北方先决条件、可选、目标：暮光虐待者/暮光唤火者"}, [5]={hint="从克朗克那里为博尔德罗克的克鲁格菲斯特收回颅骨重锤。", tag="需要北方先决条件、可选、目标：克朗克"}, [6]={npc="乔姆-乔姆", tgt="乔姆-乔姆", tag="如果通过就做、可选"}, [7]={hint="护送乔姆-乔姆前往博尔德罗克，将其交给克鲁格菲斯特。", tag="如果通过就做、可选"}, [8]={npc="克鲁格菲斯特", tgt="克鲁格菲斯特", tag="如果通过就做、可选"}, [9]={npc="克鲁格菲斯特", tgt="克鲁格菲斯特", tag="需要北方先决条件、可选"}, [10]={npc="克鲁格菲斯特", tgt="克鲁格菲斯特", tag="需要北方先决条件、可选"}, [11]={npc="克鲁格菲斯特", tgt="克鲁格菲斯特", tag="需要北方先决条件、可选"}, [12]={hint="向洛格玛的克罗姆罗什复命。", tag="需要北方先决条件、可选"}, [13]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="需要北方先决条件、可选"}, [14]={text="暮光洛格玛以西营地"}, [15]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="可选"}, [16]={hint="在洛格玛以西的丘陵地带找到达格罗什。", tag="可选"}, [17]={npc="达格罗什", tgt="达格罗什", tag="可选"}, [18]={npc="达格罗什", tgt="达格罗什", tag="可选"}, [19]={npc="达格罗什", tgt="达格罗什", tag="可选"}, [20]={hint="为达格罗什击败暮光之帷内的8名暮光狂热者、8名暮光腐蚀者和8名暮光勇士。", tag="目标：暮光狂热者/暮光腐蚀者/暮光勇士、可选"