    ["05-d19"] = {name="Krol'dok Stronghold", nameA="{a:17780}", entrance="河林 48.60, 26.30", pickup="在洛格玛，执行特兰古尔的阳光林地和棍趾任务，然后执行博尔德罗克先决条件。从洛格玛向西前往暮光营地，找到达格罗什和Crag'rog。上交洛格玛的信件即可解锁眼睛和书本任务。飞到洛格玛或者从卡加斯步行，然后在阳光林地北边的高地上找到传送门。带上4根厚皮和12根铁棒，用于模具跟进。", pickupS={{"在洛格玛，执行特兰古尔的阳光林地和棍趾任务，然后执行博尔德罗克先决条件"}, {"从洛格玛向西前往暮光营地，找到达格罗什和Crag'rog"}, {"上交洛格玛的信件即可解锁眼睛和书本任务"}, {"飞到洛格玛或者从卡加斯步行，然后在阳光林地北边的高地上找到传送门"}, {"带上4根厚皮和12根铁棒，用于模具跟进"}}, tips={{k="動線", text="矿洞 ： 碎奴者格罗克斯 → 暮光指挥官扎尔莫克 → 阿什卡铁匠铺的模具 → 暮光宝典的纳古克 → 桥上的 Bossman Toof → 莫格之眼的霸王马克杯。沿途掠夺邪教徒的耳朵。"}, {k="取捨", text="在分组之前完成洛格玛、 博尔德罗克和爆破引线港先决条件，以便您可以在一次运行中完成所有三个任务。把模具材料带过来，如果模具掉下来就交回去。"}, {k="說明", text="入口在阳光林地正北，城门旁另有要塞传送门。", s={{"入口在阳光林地正北，城门旁另有要塞传送门"}}}}, steps={[1]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="副本前置链"}, [2]={hint="消灭12名草甸溪农场雇农，然后带着你胜利的消息向克罗姆罗什复命。", tag="副本前置链"}, [3]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="副本前置链"}, [4]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="副本前置链"}, [5]={hint="从草甸溪的联盟农场偷取6个饲料袋，然后向克罗姆罗什复命。", tag="副本前置链"}, [6]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="副本前置链"}, [7]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="副本前置链"}, [8]={hint="在河流以南消灭8个法霍德牧师和12个法霍德斥候。", tag="副本前置链"}, [9]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="副本前置链"}, [10]={npc="特兰古尔", tgt="特兰古尔"}, [11]={npc="特兰古尔", tgt="特兰古尔"}, [12]={hint="为洛格玛的特兰古尔消灭阳光林地中的8名暮光袭击者和8名暮光新教徒。", tag="目标：暮光袭击者/暮光暗影法师/暮光新教徒"}, [13]={hint="为洛格玛的特兰古尔从阳光林地的暮光暗影法师身上夺取3封暮光信件。", tag="目标：暮光暗影法师"}, [14]={npc="特兰古尔", tgt="特兰古尔"}, [15]={npc="特兰古尔", tgt="特兰古尔"}, [16]={npc="特兰古尔", tgt="特兰古尔", preText="暮光逼近、暮光信件"}, [17]={hint="说服阳光林地的一名暮光之锤矿工，让他泄露秘密。"}, [18]={npc="棍趾", tgt="棍趾"}, [19]={npc="棍趾", tgt="棍趾", preText="挖掘答案"}, [20]={hint="为棍趾在阳光林地下方的洞穴中寻找失踪的食人魔。"}, [21]={npc="强化蛮兵", tgt="暮光蛮兵"}, [22]={npc="强化蛮兵", tgt="暮光蛮兵", preText="紫色的家伙"}, [23]={npc="棍趾", tgt="棍趾", preText="紫色的家伙"}, [24]={hint="消灭5名强化蛮兵和10名暮光仪式师，然后回到阳光林地的棍趾那里。", tag="目标：强化蛮兵/暮光仪式师"}, [25]={hint="摧毁在阳光林地下方洞穴中发现的5个暮光仪式法阵。", desc="沿洞穴寻找。"}, [26]={npc="棍趾", tgt="棍趾"}, [27]={npc="棍趾", tgt="棍趾"}, [28]={npc="棍趾", tgt="棍趾", desc="精英。请您的小组提供帮助。", preText="紫色的家伙、令人作呕的光"}, [29]={hint="在阳光林地的洞穴中消灭乔