[71]={hint="从克罗多克要塞内的暮光之锤成员身上收集15只教徒的耳朵。", desc="首先清除扎尔莫克附近的邪教徒，然后检查你的人数。地下城地图：扎尔莫克（39.10, 69.40）是耳朵的来源之一。位置：在地雷之后清理扎尔莫克周围。在要塞通道中掠夺更多耳朵。", spot="在地雷之后清理扎尔莫克周围。在要塞通道中掠夺更多耳朵。"}, [72]={npc="克罗多克铸件", npcObj=true, tag="可选、需要游戏内检查", desc="从图克那里拾取模具并右键单击它以开始任务。在 War 驯兽师阿什卡的铁匠铺找到 Tunk。掠夺并右键单击模具。"}, [73]={hint="从克罗多克要塞中寻回暮光宝典。", desc="地下城地图：纳古克 (34.70, 50.30)。位置：经过阿什卡并在暮光脚轮区域寻找纳古克。", spot="经过阿什卡并在暮光脚轮区域寻找纳古克。"}, [74]={hint="潜入克罗多克要塞，带着其头目已死的罪证向克罗姆罗什复命。", desc="地下城地图：Mugg (71.00, 14.30)。位置：穿过博斯曼图夫的桥。在最后一个房间杀死霸王马格。", spot="穿过博斯曼图夫的桥。在最后一个房间杀死霸王马格。"}, [75]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [76]={npc="特兰古尔", tgt="特兰古尔"}, [77]={hint="在洛格玛营地寻找懂得辨认此铸件的人。", tag="可选"}, [78]={npc="古尔多克", tgt="克雷扎·暗棘", tag="可选"}, [79]={npc="古尔多克", tgt="克雷扎·暗棘", tag="可选", desc="提前在拍卖行购买材料。", preText="克罗多克铸件"}, [80]={hint="将4张厚皮和12块铁锭交给克雷扎·暗棘。", tag="可选", desc="提前在拍卖行购买材料。"}, [81]={npc="古尔多克", tgt="克雷扎·暗棘", tag="可选", desc="提前在拍卖行购买材料。"}, [82]={npc="达格罗什", tgt="达格罗什", desc="从洛格玛出发，向西返回达格罗什。"}}},
    ["04-29"] = {name="塔纳利斯", nameA="塔纳利斯 {a:977}／{a:976}", shortA="塔纳利斯 {a:977} +", tips={{k="取捨", text="第一次访问热砂港时，一起完成海盗帽、杀戮、赏金和箱子。 TUGs 首先执行菲拉斯，然后返回给海盗。现在从爆破引线港乘船并清理海岸以保持视频的停止命令。"}, {k="取捨", text="保存 尖啸者的灵魂 为莫沙彻营地，砂槌欠款 为砂槌营地，给马克基雷的货物 为藏宝海湾，在前往悲伤沼泽的途中上交。"}, {k="提醒", text="下一站需要经验吗？在废土营地（59.40, 24.71）或落帆海湾入口（70.90, 42.48）杀死普通小怪。如果您有祖尔法拉克团体，请携带 圣甲虫的壳、 探水棒 和 巨魔调和剂，然后上交加基森和 Dunemaul 腿。", s={{"下一站需要经验吗？"}, {"在废土营地（59.40, 24.71）或落帆海湾入口（70.90, 42.48）杀死普通小怪"}, {"如果您有祖尔法拉克团体，请携带 圣甲虫的壳、 探水棒 和 巨魔调和剂，然后上交加基森和 Dunemaul 腿"}}}}, danger={[1]="哈里发巡逻并可能有警卫。清除附近的废土强盗，并在他到达空地时拉他。"}, grind={[1]={mob="南海海盗", note="落帆海湾入口处有密集的普通小怪。其他玩家可能正在执行海盗任务。沿着边缘清理到海滩并收集它们的水滴。"}, [2]={mob="南海流氓", note="码头外的普通怪物。如果海盗入口繁忙，请切换至此处。从边缘拉动以避开码头防护装置。"}}, supply={[1]={npc="布科雷克·怒拳"}, [2]={npc="旅店老板菲兹格瑞博"}, [3]={npc="乌林克·古德斯迪尔"}, [4]={npc="旅店老板菲兹格瑞博"}, [5]={npc="布雷兹里克·巴克舒特"}, [6]={npc="吉科希斯"}}, steps={[1]={text="在河林（80.60, 54.60）的爆破引线港上船，在塔纳利斯（68.60, 23.00）的热砂港下船。如果加基森已解锁，请从奥格瑞玛起飞。第一次访问时，您还可以从乱风岗出发，穿过微光平原，然后沿着南坡道到达加基森。"}, [2]={text="在港口接载，然后在城镇补给"}, [3]={npc="傲慢的店主", tgt="傲慢的店主"}, [4]={npc="安全主管吉罗姆·比格维兹", tgt="安全主管吉罗姆·比格维兹"}, [5]={npc="通缉：卡利夫·斯科比斯汀", npcObj=true}, [6]={npc="通缉：卡利夫·斯科比斯汀", npcObj=true}, [7]={npc="斯杜雷", tgt="斯杜雷"}, [8]={npc="叶基亚", tgt="叶基亚", desc="做在菲拉斯。在塔纳利斯访问期间，请在热砂港上交。"}, [9]={npc="安全主管吉罗姆·比格维兹", tgt="安全主管吉罗姆·比格维兹", tag="可选", desc="在砂槌营地进行。上交处：热砂港。"}, [10]={text="沿路向西行驶至加基森。从布科雷克·怒拳 (51.60, 25.44) 学习部落飞行点并将您的炉石与旅店老板菲兹格瑞博 (52.51, 27.91) 绑定。稍后在莫沙彻营地中重新绑定。"}, [11]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹"}, [12]={npc="操作员鲁格伦克", tgt="操作员鲁格伦克"}, [13]={npc="特兰雷克", tgt="特兰雷克", tag="可选", desc="仅在运行祖尔法拉克时才拾取。"}, [14]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹", tag="可选", desc="在祖尔法拉克的楼梯事件中拾取此物品。", star={"石工兄弟会之戒", {"ROGUE", "HUNTER", "DRUID"}}}, [15]={npc="特伦顿·轻锤", tgt="特伦顿·轻锤", tag="可选", desc="仅在运行祖尔法拉克时才拾取。"}, [16]={text="废土营地和落帆海湾"}, [17]={hint="去加基森的东面杀掉10个废土窃贼和10个废土强盗，然后向总工程师比格维兹复命。"}, [18]={hint="收集5只废土水袋，把它们交给加基森的鲁格伦克。"}, [19]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹"}, [20]={npc="操作员鲁格伦克", tgt="操作员鲁格伦克"}, [21]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹"}, [22]={hint="杀死10个废土暗法师、8个废土游荡者和6个废土刺客，然后向加基森的总工程师比格维兹报告。", desc="进入加基森东南方的废土营地。"}, [23]={hint="将卡利夫·斯科比斯汀的头颅交给加基森的首席工程师沙克斯·比格维兹。", desc="他可能有一个护卫。等到他到达营地边缘后再拉。"}, [24]={hint="塔纳利斯热砂港的安全主管吉罗姆·比格维兹要你去干掉10个南海海盗、10个南海劫掠者、10个南海码头工人和10个南海流氓。"}, [25]={hint="塔纳利斯热砂港的傲慢的店主要你去帮他收集20顶南海海盗帽。", desc="执行 南海复仇 时，掠夺每一次击杀。"}, [26]={hint="将安德雷的头颅交给热砂港的安全主管吉罗姆·比格维兹。"}, [27]={hint="将斯杜雷的货物交给热砂港的斯杜雷。"}, [28]={npc="船运时刻表", npcObj=true, tag="可选", desc="抢劫海盗的储物柜，然后右键单击里面的时间表开始任务。"}, [29]={hint="把船运时刻表交给热砂港的某个官员。", tag="可选"}, [30]={text="沿着海岸向北到达热砂港，一起交海盗和货物任务。"}, [31]={npc="安全主管吉罗姆·比格维兹", tgt="安全主管吉罗姆·比格维兹"}, [32]={npc="傲慢的店主", tgt="傲慢的店主"}, [33]={npc="安全主管吉罗姆·比格维兹", tgt="安全主管吉罗姆·比格维兹"}, [34]={npc="斯杜雷", tgt="斯杜雷"}, [35]={npc="安全主管吉罗姆·比格维兹", tgt="安全主管吉罗姆·比格维兹", tag="可选"}, [36]={npc="斯杜雷", tgt="斯杜雷", desc="保留斯通纳德 / 东风海岸航段。在藏宝海湾上交。"}, [37]={text="返回加基森获取第二批废土和通缉任务。壁炉如果绑定在那里。"}, [38]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹"}, [39]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹"}}},
    ["04-30"] = {name="菲拉斯", nameA="菲拉斯 {a:1099}", tips={{k="取捨", text="沿着木爪豺狼人链条穿过 作战计划，解锁莫沙彻营地东南部两个重叠的 Zukk'ash 任务。"}, {k="取捨", text="如果 OOX-22/FE定位器掉落，请将其保留。保存护卫队、沿海巨人和水元素，等待莫沙彻营地的回归。"}, {k="提醒", text="47级以下？杀死深痕谷 (55.29, 53.76) 的雪人或莫沙彻营地 (75.13, 34.86) 北部的戈杜尼食人魔，然后返回营地交任务。", s={{"47级以下？"}, {"杀死深痕谷 (55.29, 53.76) 的雪人或莫沙彻营地 (75.13, 34.86) 北部的戈杜尼食人魔，然后返回营地交任务"}}}}, danger={[1]="莫沙彻营地以北的戈杜尼营地既有施法者，也有野兽。在挖掘钴之前先清理出口，并远离营地后面。"}, grind={[1]={mob="深痕雪人", note="正常的雪人集群位于深痕谷的外坡。如果探索者位于洞穴入口处，则绕斜坡寻找雪人藏身之处。"}, [2]={mob="暴怒的巨型深痕雪人", note="深痕谷西南方向稍高一级的正常雪人。从外面拉近战小怪并避开拥挤的洞口。"}}, supply={[1]={npc="夏恩"}, [2]={npc="旅店老板格鲁尔"}, [3]={npc="卡温德"}, [4]={npc="旅店老板格鲁尔"}, [5]={npc="卡温德"}, [6]={npc="塔霍斯"}}, steps={[1]={text="如果解锁，请从加基森飞往莫沙彻营地。第一次访问时，向北进入微光平原，然后沿西路穿过千针石林进入菲拉斯。", tag="尚未解锁这个飞行点，第一次请走过去。"}, [2]={nodeA="{a:1099}", desc="解锁、飞行点和夏恩。"}, [3]={text="将您的炉石与旅店老板格鲁尔 (74.80, 45.18) 绑定。"}, [4]={npc="克鲁伊格·碎颅", tgt="克鲁伊格·碎颅"}, [5]={npc="奥尔文·吉兹米克", tgt="奥尔文·吉兹米克"}, [6]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [7]={npc="杉多尔·迅蹄", tgt="杉多尔·迅蹄"}, [8]={npc="巫医尤克里", tgt="巫医尤克里"}, [9]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [10]={text="营地周围和北方的第一个戈杜尼任务"}, [11]={hint="将10份木爪豺狼人的鬃毛交给莫沙彻营地的哈杜肯·迅蹄。"}, [12]={hint="莫沙彻营地的洛卡·奥赫要你杀掉10个戈杜尼食人魔、10个戈杜尼食人魔法师和5个戈杜尼蛮兵。"}, [13]={hint="莫沙彻营地的奥尔文·吉兹米克需要12块戈杜尼钴矿石的样本。", desc="使用 Gordunni 营地蓝色土堆旁边的任务铲子。"}, [14]={npc="戈杜尼卷轴", npcObj=true, desc="单击北端地面上的戈杜尼卷轴。"}, [15]={hint="将戈杜尼卷轴交给莫沙彻营地的洛克·奥汉。"}, [16]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [17]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [18]={npc="奥尔文·吉兹米克", tgt="奥尔文·吉兹米克"}, [19]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [20]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [21]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [22]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [23]={hint="在1个小时内杀死5个木爪突击队员，并向哈杜肯·迅蹄汇报。", desc="一小时定时器。在南边的木爪岭杀死五个，然后立即返回。"}, [24]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [25]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [26]={hint="在莫沙彻营地以南的豺狼人营地中寻找豺狼人的战斗计划。"}, [27]={npc="木爪作战地图", npcObj=true}, [28]={npc="木爪作战地图", npcObj=true}, [29]={hint="把木爪豺狼人的作战计划交给莫沙彻营地的哈杜肯·迅蹄。"}, [30]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [31]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [32]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [33]={text="精灵龙在中间，然后向西到深痕谷"}, [34]={hint="给莫沙彻营地的克鲁伊格·碎颅带去10个闪光的小精灵翅膀。"}, [35]={hint="在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。", desc="经过加基森 / 砂槌营地航段后，在热砂港处折返。"}, [36]={hint="给莫沙彻营地的杉多尔·迅蹄带去十张厚重的雪人皮。", desc="杀死洞穴内及其周围的怒疤雪人，获得厚重的雪人皮。"}, [37]={text="深痕谷后，炉至莫沙彻营地并交。"}, [38]={npc="克鲁伊格·碎颅", tgt="克鲁伊格·碎颅"}, [39]={npc="杉多尔·迅蹄", tgt="杉多尔·迅蹄"}, [40]={npc="克鲁伊格·碎颅", tgt="克鲁伊格·碎颅"}, [41]={npc="杉多尔·迅蹄", tgt="杉多尔·迅蹄"}, [42]={hint="收集20支恐怖图腾之角，把它们交给千针石林的克鲁伊格·碎颅。", desc="在莫沙彻营地西北的恐怖图腾营地取得号角，然后返回。"}, [43]={npc="克鲁伊格·碎颅", tgt="克鲁伊格·碎颅"}, [44]={npc="克鲁伊格·碎颅", tgt="克鲁伊格·碎颅"}, [45]={text="在前往悲伤沼泽的途中在奥格瑞玛停留，进行菲拉斯后续航班"}, [46]={text="从莫沙彻营地飞往奥格瑞玛，通常经过陶拉祖营地或其他未上锁的停靠点。在东部悲伤沼泽循环之后保留您的莫沙彻营地壁炉。"}, [47]={hint="将皱缩的头颅交给奥格瑞玛的尼尔鲁·火刃。"}, [48]={hint="将一箱恐怖图腾之角交给奥格瑞玛的贝尔戈洛姆·石槌。"}, [49]={npc="尼尔鲁·火刃", tgt="尼尔鲁·火刃"}, [50]={npc="贝尔戈洛姆·石槌", tgt="贝尔戈洛姆·石槌"}, [51]={npc="尼尔鲁·火刃", tgt="尼尔鲁·火刃", desc="保留怒痕堡腿。上交处：莫沙彻营地。"}}},
    ["04-31"] = {name="悲伤沼泽", nameA="悲伤沼泽 {a:75}", tips={{k="取捨", text="北方失落者和护航已经完成。这一次，坚持到海边。交出缺乏补给和缺乏补给来解锁鱼人链。出去的时候收集蟹腿，回来的时候把它们交回去。"}, {k="提醒", text="运行沉没的神庙吗？从斯通纳德开始 阿塔莱流放者。它在辛特兰交接，因此请保留恶齿村和辛萨罗路段。 47级以下，杀死东风海岸（91.00, 70.80）附近的普通巨蟹。接近49级时，在下一站磨掉更高等级的怒痕雪人。", s={{"运行沉没的神庙吗？"}, {"从斯通纳德开始 阿塔莱流放者"}, {"它在辛特兰交接，因此请保留恶齿村和辛萨罗路段"}, {"47级以下，杀死东风海岸（91.00, 70.80）附近的普通巨蟹"}, {"接近49级时，在下一站磨掉更高等级的怒痕雪人"}}}}, danger={[1]="鱼人在东风海岸上站得很近，墨水喷射者和神谕者可以从后面添加。一次将一名敌人从岸上拉出来，不要追入水中。"}, grind={[1]={mob="巨型淤泥蟹", note="悲伤沼泽东部海岸有密集的正常螃蟹。边走边剥皮。最好在抵达时或在沿海任务的同时进行小额经验充值。"}, [2]={mob="老年怒痕雪人", note="如果您接近 49，请等到菲拉斯。 怒痕堡的普通雪人是一个更好的水平。在外坡上一次拉一名敌人并避开繁忙的洞穴入口。"}}, supply={[1]={npc="布雷依克"}, [2]={npc="旅店老板卡拉库尔"}, [3]={npc="卡尔拉什"}, [4]={npc="索尔塔什"}, [5]={npc="苏塔佐尔"}}, steps={[1]={text="从奥格瑞玛飞到棘齿城，然后坐船到藏宝海湾。保留您的莫沙彻营地壁炉。"}, [2]={text="藏宝海湾沿途任务交接"}, [3]={hint="将斯杜雷的瓶子交给藏宝海湾的\"海狼\"马克基雷。"}, [4]={npc="海狼马克基雷", tgt="海狼马克基雷"}, [5]={npc="克拉兹克", tgt="克拉兹克", tag="可选", desc="只有当您拥有所有梦境之尘后，才能在斯通纳德上交。"}, [6]={npc="威士忌斯利姆", tgt="威士忌斯利姆", desc="在辛特兰海岸捡起烈酒。当您再次访问藏宝海湾时上交。"}, [7]={text="斯通纳德至东南沿海"}, [8]={text="从藏宝海湾飞往斯通纳德。如果锁定，则向北穿过荆棘谷，然后沿着东部暮色森林穿过逆风小径。从布雷依克 (46.07, 54.83) 学习飞行点。"}, [9]={npc="达尔", tgt="达尔"}, [10]={npc="达尔", tgt="达尔"}, [11]={hint="给悲伤沼泽的托克卡尔带去8块新鲜的盐齿鳄鱼肉。", desc="杀死泪水之池西南方向的盐颚鳄鱼。检查海岸以了解更多信息。"}, [12]={hint="给悲伤沼泽的达尔带去10条巨大的螃蟹腿。", desc="沿着北部海岸杀死螃蟹。在向南前进之前收集十条腿。"}, [13]={npc="托克卡尔", tgt="托克卡尔"}, [14]={npc="托克卡尔", tgt="托克卡尔"}, [15]={hint="给悲伤沼泽的托克卡尔带去6只盐齿钳嘴鳄的爪子。"}, [16]={npc="托克卡尔", tgt="托克卡尔"}, [17]={npc="托克卡尔", tgt="托克卡尔"}, [18]={hint="与悲伤沼泽的卡塔尔谈一谈。"}, [19]={npc="卡塔尔", tgt="卡塔尔"}, [20]={npc="卡塔尔", tgt="卡塔尔", desc="在东南海滩杀死三种鱼人各十个。返回卡塔尔。"}, [21]={hint="杀掉10个沼泽鱼人、10个沼泽喷墨鱼人和10个沼泽食腐鱼人，然后向悲伤沼泽的卡塔尔回报。", desc="在东南海滩杀死三种鱼人各十个。返回卡塔尔。"}, [22]={npc="卡塔尔", tgt="卡塔尔", desc="在东南海滩杀死三种鱼人各十个。返回卡塔尔。"}, [23]={npc="卡塔尔", tgt="卡塔尔"}, [24]={hint="与悲伤沼泽的托克卡尔谈一谈。"}, [25]={npc="托克卡尔", tgt="托克卡尔"}, [26]={npc="卡塔尔", tgt="卡塔尔", desc="1427 之后，请参见卡塔尔。在更北的地方寻找神谕者。检查所有三个杀戮计数。"}, [27]={hint="杀掉10名沼泽喷墨鱼人、10名沼泽食腐鱼人和10名沼泽鱼人智者，然后向悲伤沼泽的卡塔尔回报。", desc="1427 之后，请参见卡塔尔。在更北的地方寻找神谕者。检查所有三个杀戮计数。"}, [28]={npc="卡塔尔", tgt="卡塔尔", desc="1427 之后，请参见卡塔尔。在更北的地方寻找神谕者。检查所有三个杀戮计数。"}, [29]={text="向西折回路线至斯通纳德，然后将蟹腿翻至达尔。"}, [30]={npc="达尔", tgt="达尔"}, [31]={text="上交后使用您的炉石返回莫沙彻营地。否则飞往藏宝海湾，乘坐棘齿城船再飞往莫沙彻营地。"}}},
    ["04-32"] = {name="菲拉斯 厄运之槌", nameA="菲拉斯 {a:1099}／厄运之槌", shortA="菲拉斯 {a:1099} +", tips={{k="取捨", text="狂怒疤痕雪人和深痕谷雪人是不同的目标。在莫沙彻营地处上交 质量的保证，然后执行 更高的品质。仅当物品掉落时才上交 完美的雪人毛皮。"}, {k="取捨", text="回到炉边后，鱼人链救了一个路口。在辛特兰地区收集 测试容器 的枭兽精华。将 角鹰兽灵魂精华 - 灵魂武器 保存为莫沙彻营地。"}, {k="提醒", text="视频返回到第49关附近的菲拉斯。如果经验短，请在从55.73, 33.05到54.39, 33.10的外环上杀死愤怒疤痕雪人。一次拉一个敌人。", s={{"视频返回到第49关附近的菲拉斯"}, {"如果经验短，请在从55.73, 33.05到54.39, 33.10的外环上杀死愤怒疤痕雪人"}, {"一次拉一个敌人"}}}}, danger={[1]="雪人洞的入口很窄。 老年怒痕雪人雪人可以跟小怪拉到嘴边。进入前请清理外部。"}, grind={[1]={mob="狂暴的怒痕雪人", note="怒痕堡外坡上的正常雪人。如果洞穴很繁忙，则绕着斜坡寻找雪人藏身之处。"}, [2]={mob="老年怒痕雪人", note="同一阵营中的高级普通雪人。将它们混合到49。首先清除入口以避免在狭窄的洞穴中双重拉动。"}}, supply={[1]={npc="夏恩"}, [2]={npc="旅店老板格鲁尔"}, [3]={npc="卡温德"}, [4]={npc="旅店老板格鲁尔"}, [5]={npc="卡温德"}, [6]={npc="塔霍斯"}}, steps={[1]={hint="将尼尔鲁的草药包送给菲拉斯的巫医尤克里。"}, [2]={npc="巫医尤克里", tgt="巫医尤克里"}, [3]={npc="巫医尤克里", tgt="巫医尤克里", desc="在辛特兰枭兽尸体上使用容器。在莫沙彻营地上交。"}, [4]={npc="巫医尤克里", tgt="巫医尤克里", tag="可选", desc="保存天然材料即可。收集完毕并交到莫沙彻营地。"}, [5]={npc="巫医尤克里", tgt="巫医尤克里", desc="在塔纳利斯的破碎石柱处向 Marvon 求助。"}, [6]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", desc="除了费伍德森林的熊和猛禽。下次访问时请在莫沙彻营地上交。"}, [7]={hint="把20块祖卡什虫壳交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。"}, [8]={hint="击败痛苦深渊中的毒刺鞭笞者，把它的腺体交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。"}, [9]={hint="莫沙彻营地的洛卡·奥赫要你去杀掉十个戈杜尼萨满祭司、10个戈杜尼术士和5个戈杜尼虐待者。"}, [10]={hint="莫沙彻营地的洛卡·奥赫希望你找到一颗戈杜尼之宝珠。"}, [11]={text="沿着路返回莫沙彻营地，找到菲拉斯的食人魔和祖卡什的入侵。把北方雪人留到下一个循环。"}, [12]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [13]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [14]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [15]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [16]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄", desc="当您在塔纳利斯路段上通过奥格瑞玛时，请与其他任务一起上交。"}, [17]={npc="洛卡·奥赫", tgt="洛卡·奥赫", desc="节省奥格瑞玛在塔纳利斯航段上交的费用。"}, [18]={text="愤怒之疤雪人和回程"}, [19]={hint="把10块怒痕雪人的毛皮交给菲拉斯莫沙彻营地的杉多尔·迅蹄。", desc="沿路向西行驶至怒痕堡 (55.73, 33.05)。收集十张毛皮。"}, [20]={npc="完美的雪人毛皮", npcObj=true, tag="可选", desc="仅当狂暴的怒痕雪人掉落原始雪人毛皮时才接。"}, [21]={hint="把完美的雪人毛皮交给菲拉斯莫沙彻营地的杉多尔·迅蹄。", tag="可选"}, [22]={text="当雪人完成后，使用炉石返回莫沙彻营地，或沿主路返回。转机飞往加基森。"}, [23]={npc="杉多尔·迅蹄", tgt="杉多尔·迅蹄"}, [24]={npc="杉多尔·迅蹄", tgt="杉多尔·迅蹄", tag="可选"}}},
    ["05-d20"] = {name="玛拉顿", entrance="凄凉之地 29.10, 62.50", pickup="在第 39 级，在葬影村之前的奥格瑞玛中从尤塞尔奈中取出暗影残片。从莫沙彻营地出发，前往葬影村，参观瓦鲁格和瑟琳德拉，然后参观维洛和半人马贱民。对于永远的水瓶链，在东南辛德拉进行水晶塔和魔导师导入，然后在遗忘花园采取 林中传言 → 腐朽与懊悔。辛德拉任务最低 35 级。从橙色传送门前的凯雯德拉接载。", pickupS={{"在第 39 级，在葬影村之前的奥格瑞玛中从尤塞尔奈中取出暗影残片"}, {"从莫沙彻营地出发，前往葬影村，参观瓦鲁格和瑟琳德拉，然后参观维洛和半人马贱民"}, {"对于永远的水瓶链，在东南辛德拉进行水晶塔和魔导师导入，然后在遗忘花园采取 林中传言 → 腐朽与懊悔"}, {"辛德拉任务最低 35 级"}, {"从橙色传送门前的凯雯德拉接载"}}, tips={{k="動線", text="橙色：诺克赛恩和锐刺鞭笞者。紫色：维利塔恩。收集雕像、可汗宝石和其他任务战利品→在路口的塞勒布拉斯，然后按照他的权杖仪式→地歌瀑布→公主→洛特格里普的池（如果需要）。"}, {k="取捨", text="同时使用橙色和紫色翅膀即可在第一次运行时获得权杖。如果你只想要公主和鳄鱼，请使用党员的权杖进入内翼。如果您需要外面的影子小怪或另一个翼中的目标，请跳过捷径。"}, {k="說明", text="外洞位于29.10, 62.50。沿着橙色或紫色的隧道到达其传送门。两条路线均在毒瀑布处交汇。", s={{"外洞位于29.10, 62.50"}, {"沿着橙色或紫色的隧道到达其传送门"}, {"两条路线均在毒瀑布处交汇"}}}}, steps={[1]={npc="尤塞尔奈", tgt="尤塞尔奈"}, [2]={npc="瓦克·战痕", tgt="瓦克·战痕"}, [3]={npc="瑟琳德拉", tgt="瑟琳德拉"}, [4]={npc="维洛", tgt="维洛"}, [5]={npc="半人马贱民", tgt="半人马贱民", desc="半人马贱民在凄凉之地南部巡逻。"}, [6]={npc="辛德拉水晶塔", npcObj=true, tag="可选"}, [7]={hint="探索辛德拉，设法寻找与你所见相似的其他水晶塔。", tag="可选"}, [8]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选"}, [9]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选", preText="奇怪的水晶塔"}, [10]={hint="取回那些在玛格拉姆村和吉尔吉斯村受到严密看守的水晶塔碎片与残片。将它们交给莫丹特·永影。", tag="可选", desc="图钉按顺序标记了马格拉姆和吉尔基斯半人马村庄中的两个物品。"}, [11]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选"}, [12]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选", desc="检查任务日志了解您需要的法力值。", preText="水晶塔碎片"}, [13]={hint="从辛德拉神殿内取得法力过滤网，并用它来收集远古魔力水晶。收集到足够的法力后，即刻为水晶塔充能，然后向莫丹特·永影复命。", tag="可选、需要游戏内检查", desc="检查任务日志了解您需要的法力值。到上层神殿最高一层取筛子，共收集 8 份法力，每塔 4 份。西塔与东塔可在潜行状态下互动。"}, [14]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选", desc="检查任务日志了解您需要的法力值。"}, [15]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选、需要游戏内检查", preText="为晶塔供能"}, [16]={hint="与辛德拉的莫丹特·永影交谈，了解关于你修复的那些水晶的信息。", tag="可选、需要游戏内检查"}, [17]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选、需要游戏内检查"}, [18]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选、需要游戏内检查", preText="简短的历史课"}, [19]={hint="在辛德拉神殿内找到魔导师基兰迪斯。", tag="可选、需要游戏内检查"}, [20]={npc="魔导师基兰迪斯", tgt="魔导师基兰迪斯", tag="可选、需要游戏内检查"}, [21]={npc="米瑟拉", tgt="米瑟拉", tag="副本前置链"}, [22]={npc="米瑟拉", tgt="米瑟拉", tag="副本前置链"}, [23]={npc="米瑟拉", tgt="米瑟拉", tag="可选、需要游戏内检查", preText="会见魔导师"}, [24]={hint="在凄凉之地辛德拉的荒弃花园找到林地怪。", tag="可选、需要游戏内检查"}, [25]={npc="林地怪", tgt="林地怪", tag="可选、需要游戏内检查"}, [26]={npc="林地怪", tgt="林地怪", tag="可选、需要游戏内检查", desc="先上交林中传言。将其放入内部玛拉顿中。", preText="林中传言"}, [27]={npc="凯雯德拉", tgt="凯雯德拉", desc="凯雯德拉在橙色传送门外。从双方首领处掠夺一件物品。"}, [28]={hint="从玛拉顿收集10块暗影残片，然后把它们交给奥格瑞玛的尤塞尔奈。"}, [29]={text="玛拉顿 入口"}, [30]={text="橙色面：毒菇洞穴 (45-53)。寻找橙色晶体和洞穴深处的水池。在进入门户之前填充小瓶。"}, [31]={hint="在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。", desc="位置：在橙色传送门外的水池里装满瓶子。找到里面的藤蔓。", spot="在橙色传送门外的水池里装满瓶子。找到里面的藤蔓。"}, [32]={text="紫色方：邪恶石窟 (45-53)。走三岔路口的紫色水晶通道。从维利塔恩中掠夺钻石。"}, [33]={hint="为凄凉之地的维洛收集25个瑟莱德丝水晶雕像。", desc="数量以任务日志为准。位置：边走边杀死传送门外的半人马并掠夺雕像。", spot="边走边杀死传送门外的半人马并掠夺雕像。"}, [34]={hint="阅读贱民的指引，然后从玛拉顿得到联合坠饰，将其交给凄凉之地南部的半人马贱民。", desc="三个可汗在岔路口和外部隧道巡逻。每个传送门内都有一个。位置：在岔路口和外部洞穴找到三名可汗，然后在每个入口内找到一名可汗。", spot="在岔路口和外部洞穴找到三名可汗，然后在每个入口内找到一名可汗。"}, [35]={hint="找回塞雷布拉斯节杖的两个部分：塞雷布拉斯魔棒和塞雷布拉斯钻石。", desc="位置：将棒子放在橙色上，将钻石放在紫色上。在塞莱布拉斯相遇的地方杀死他们。顺序：走橙色和紫色路径。材料齐全后上交。", spot="将棒子放在橙色上，将钻石放在紫色上。在塞莱布拉斯相遇的地方杀死他们。"}, [36]={npc="赎罪的塞雷布拉斯", tgt="赎罪的塞雷布拉斯", tag="需要游戏内检查", desc="击败Boss后与赎罪的塞雷布拉斯对话。击败后向房内的赎罪者交付。", spot="塞雷布拉斯首领房内，赎罪者"}, [37]={npc="赎罪的塞雷布拉斯", tgt="赎罪的塞雷布拉斯", tag="需要游戏内检查", desc="赎罪者在首领房内；仪式中跟随他。", preText="玛拉顿的传说"}, [38]={hint="帮助赎罪的塞雷布拉斯制作塞雷布拉斯节杖。", desc="赎罪者在首领房内；仪式中跟随他。位置：跟随赎罪的塞雷布拉斯在他的老板房间里完成仪式。", spot="跟随赎罪的塞雷布拉斯在他的老板房间里完成仪式。"}, [39]={npc="赎罪的塞雷布拉斯", tgt="赎罪的塞雷布拉斯", tag="需要游戏内检查", desc="赎罪者在首领房内；仪式中跟随他。", spot="塞雷布拉斯首领房内，赎罪者"}, [40]={text="内线：地歌瀑布 (48-57)。从橙色/紫色交汇处下降或让持有权杖的玩家打开快捷方式。"}, [41]={hint="深入玛拉顿，取回一瓶大地之歌水。将其带回凄凉之地，交给荒弃花园的林地怪。", tag="可选、需要游戏内检查", desc="洛特格里普在水池巡游；小喷泉在同一水池的水面上。位置：落入洛特格里普下方的公主池中。找到表面的弹簧。顺序：潜水前执行步骤 39。", spot="落入洛特格里普下方的公主池中。找到表面的弹簧。"}, [42]={hint="杀死瑟莱德丝公主，然后回到凄凉之地葬影村附近的瑟琳德拉那里复命。", desc="位置：跟随地歌瀑布进入扎尔塔的洞穴并到达公主的平台。", spot="跟随地歌瀑布进入扎尔塔的洞穴并到达公主的平台。"}, [43]={npc="扎尔塔的灵魂", tgt="扎尔塔的灵魂", tag="需要游戏内检查", desc="扎尔塔的灵魂在公主死亡后出现。现在拿起并在外面上交。"}, [44]={npc="瑟琳德拉", tgt="瑟琳德拉"}, [45]={npc="瓦克·战痕", tgt="瓦克·战痕"}, [46]={npc="维洛", tgt="维洛"}, [47]={npc="半人马贱民", tgt="半人马贱民"}, [48]={npc="尤塞尔奈", tgt="尤塞尔奈"}, [49]={hint="深入玛拉顿，取回一瓶大地之歌水。将其带回凄凉之地，交给荒弃花园的林地怪。", tag="可选、需要游戏内检查"}, [50]={npc="林地怪", tgt="林地怪", tag="可选、需要游戏内检查"}, [51]={hint="到月光林地去找到雷姆洛斯，将生命之种交给他。", desc="当您经过月光林地时保存。"}, [52]={npc="守护者雷姆洛斯", tgt="守护者雷姆洛斯", desc="保存为月光林地。"}}},
    ["04-33"] = {name="塔纳利斯 沙怒营地", nameA="塔纳利斯 {a:976}／沙怒营地", shortA="塔纳利斯 {a:976} +", tips={{k="取捨", text="在北部水池处上交可解锁 82。上交 82 可解锁 10，然后一圈完成沙槌、灌木谷和南部蜂巢目标。"}, {k="取捨", text="如果您有一个团队并一起完成所有四个地下城任务，请运行祖尔法拉克。否则，跳过它们和 远古之卵。"}, {k="取捨", text="先上交32和祖卡什报告。任务 异种蝎的远征 需要等级 50。一旦符合条件，请检查暗影裂口，并保存加基森和破碎石柱支线的完整后续信息。"}, {k="提醒", text="50级以下？在砂槌营地 (40.75, 50.67) 处研磨聚集的普通食人魔以获得布料。如果你想敲灼热峡谷，就给自己留一个小的经验间隙。", s={{"50级以下？"}, {"在砂槌营地 (40.75, 50.67) 处研磨聚集的普通食人魔以获得布料"}, {"如果你想敲灼热峡谷，就给自己留一个小的经验间隙"}}}}, danger={[1]="Centipaar 蜂巢入口很容易被拉倒。在蜂巢外的空地上战斗，不要将怪物赶入狭窄的隧道。"}, grind={[1]={mob="砂槌蛮兵", note="砂槌营地外面密集的普通近战小怪。收集布料并完成食人魔任务。如果营地很忙，请继续沿着边缘移动。"}, [2]={mob="森提帕尔群居蝎", note="西部异种虫蜂巢外有密集的高级普通生物。一次将一名敌人拉到入口附近。避免在狭窄的隧道中聚集。"}}, supply={[1]={npc="布科雷克·怒拳"}, [2]={npc="旅店老板菲兹格瑞博"}, [3]={npc="乌林克·古德斯迪尔"}, [4]={npc="旅店老板菲兹格瑞博"}, [5]={npc="布雷兹里克·巴克舒特"}}, steps={[1]={text="从莫沙彻营地飞往加基森并在那里绑定您的炉石。"}, [2]={text="在加基森接载，然后向西寻找水样和有毒巢穴"}, [3]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [4]={npc="马林·诺格弗格", tgt="马林·诺格弗格"}, [5]={npc="安迪·利恩", tgt="安迪·利恩"}, [6]={npc="特兰雷克", tgt="特兰雷克"}, [7]={npc="奎因", tgt="奎因", tag="可选", desc="如果你经过沙漠碎片，就可以掠夺它们。"}, [8]={hint="用未使用的寻水器在流沙岗哨旁边的池中采集水样。一旦你收集到水样，就尽快将其交给加基森的高级勘探员菲兹杜瑟。", desc="在流沙岗哨池中使用未使用的寻水器。带着样品返回。"}, [9]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [10]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [11]={hint="从腐化之巢找5个森提帕尔昆虫肢体，把它们交给加基森的炼金师匹斯特苏格。"}, [12]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格"}, [13]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [14]={text="向南到达 Sandfury 和灌木谷，然后沿着山麓到达蜂巢"}, [15]={hint="加基森的安迪·利恩想要你攻入砂槌营地，杀死10个砂槌蛮兵、10个砂槌执行者，以及掠夺者格玛洛克。"}, [16]={hint="塔纳利斯热砂港的保安主管图拉·比尔吉维兹要你找回一只格外闪亮的手镯，它遗失在砂槌食人魔营地附近。", tag="可选", desc="仅当您在热砂港和加基森腿上拾取它时才做这个任务。"}, [17]={hint="找到1个饱满的露水腺，把它交给加基森的马林·诺格弗格。", desc="杀死灌木谷中的露水收集者。抢夺一件饱满的露水腺。"}, [18]={hint="加基森的特兰雷克要你杀掉8只长瘤的灌木兽和8只灌木塑根者。"}, [19]={hint="寻找初级勘探员谢申克的下落，把他或者他的勘探设备交给加基森的高级勘探员菲兹杜瑟。", desc="前往南部裂谷的地下寻找谢申克的勘探设备。"}, [20]={hint="奎因要你找回7块沙漠废料，并在加基森交还给她。", tag="可选", desc="大头针标记已确认的生成。 联盟任务会掉落碎片。检查外部加基森。"}, [21]={text="返回加基森进行任务交接。如果准备好，请准备好，并在到达时拿起好味道和昆虫研究。"}, [22]={npc="安迪·利恩", tgt="安迪·利恩"}, [23]={npc="特兰雷克", tgt="特兰雷克"}, [24]={npc="马林·诺格弗格", tgt="马林·诺格弗格"}, [25]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [26]={npc="奎因", tgt="奎因", tag="可选"}, [27]={npc="马林·诺格弗格", tgt="马林·诺格弗格"}, [28]={hint="马林·诺格弗格让你与加基森的斯普琳科谈一谈。"}, [29]={npc="斯普琳科", tgt="斯普琳科"}, [30]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [31]={hint="到加基森的炼金师匹斯特苏格那里去了解关于昆虫的研究有没有新的进展。"}, [32]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格"}, [33]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格"}, [34]={hint="把这份报告带给加基森的高级勘探员菲兹杜瑟，让他按照炼金师匹斯特苏格的要求为你复制一份报告。"}, [35]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [36]={npc="斯普琳科", tgt="斯普琳科", desc="在辛特兰的瓦罗温湖处收集紫色水生菇。在加基森上交。"}, [37]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟", desc="在奥格瑞玛的暗影裂口处上交。使用 祖卡什报告 满足先决条件。"}, [38]={text="可选热砂港和祖尔法拉克"}, [39]={npc="叶基亚", tgt="叶基亚", desc="需要莫沙彻营地支路中的三个尖啸者的灵魂。"}, [40]={npc="安全主管吉罗姆·比格维兹", tgt="安全主管吉罗姆·比格维兹", tag="可选"}, [41]={npc="叶基亚", tgt="叶基亚", tag="可选", desc="先上交尖啸者的灵魂。一旦您拥有祖尔法拉克群组，请选择此选项。"}, [42]={hint="将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。", tag="可选"}, [43]={hint="给加基森的特兰雷克带去5个完整的圣甲虫壳。", tag="可选", desc="清除祖尔法拉克墓地中的圣甲虫。"}, [44]={hint="把探水棒交给加基森的首席工程师沙克斯·比格维兹。", tag="可选", desc="完成楼梯事件。从布莱中士处获取杆。"}, [45]={hint="收集20瓶巨魔调和剂，把它们交给加基森的特伦顿·轻锤。", tag="可选"}, [46]={npc="叶基亚", tgt="叶基亚", tag="可选"}, [47]={npc="叶基亚", tgt="叶基亚", tag="可选", desc="在 摩沙鲁的预言 之后，在辛特兰获得远古之卵。在热砂港上交。"}, [48]={npc="特兰雷克", tgt="特兰雷克", tag="可选"}, [49]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹", tag="可选", star={"石工兄弟会之戒", {"ROGUE", "HUNTER", "DRUID"}}}, [50]={npc="特伦顿·轻锤", tgt="特伦顿·轻锤", tag="可选"}, [51]={text="从加基森飞往奥格瑞玛。在拖拽区看到基尔兹宾·鼓眼，然后在黑荆棘小屋交回戈杜尼宝珠。"}, [52]={hint="把报告带给奥格瑞玛的基尔兹宾·鼓眼。"}, [53]={hint="把莫沙彻营地祖卡什报告交给奥格瑞玛暗巷区的基尔兹宾·鼓眼。"}, [54]={hint="将戈杜尼宝珠交给奥格瑞玛暗木小屋里的尤塞尔奈。"}, [55]={npc="基尔兹宾·鼓眼", tgt="基尔兹宾·鼓眼"}, [56]={npc="基尔兹宾·鼓眼", tgt="基尔兹宾·鼓眼"}, [57]={npc="尤塞尔奈", tgt="尤塞尔奈"}}},
    ["05-d21"] = {name="祖尔法拉克", entrance="塔纳利斯 38.70, 20.00", pickup="接加基森的三个本地任务，然后在热砂港的叶基亚接尖啸者的灵魂。收集菲拉斯中的灵魂。返回热砂港交回 尖啸者的灵魂 并领取 摩沙鲁的预言，然后在加基森与您的团队会合。经过微光平原时拿起 加兹瑞拉。法师可以在悲伤沼泽之前完成塔贝萨的尘泥任务。", pickupS={{"接加基森的三个本地任务，然后在热砂港的叶基亚接尖啸者的灵魂"}, {"收集菲拉斯中的灵魂"}, {"返回热砂港交回 尖啸者的灵魂 并领取 摩沙鲁的预言，然后在加基森与您的团队会合"}, {"经过微光平原时拿起 加兹瑞拉"}, {"法师可以在悲伤沼泽之前完成塔贝萨的尘泥任务"}}, tips={{k="動線", text="安图苏尔的小路 → 第一个 Mosh'aru 石板的 Theka → Zum'rah 的墓地 → 探水棒的金字塔楼梯活动 → 第二块石板的 Velratha → 池中可选的加兹瑞拉 → Chief Ukorz。拾取圣甲虫壳和巨魔调和剂。"}, {k="取捨", text="优先完成三个加基森任务和莫沙鲁石板。如果你有木槌，请与加兹瑞拉战斗。保存塔贝萨参观尘泥沼泽。"}, {k="說明", text="在热砂港和加基森腿上运行一次。如果做叶基亚的全链，请等到加基森和 Dunemaul 访问。莫沙鲁石板也是哈卡链的先决条件。", s={{"在热砂港和加基森腿上运行一次"}, {"如果做叶基亚的全链，请等到加基森和 Dunemaul 访问"}, {"莫沙鲁石板也是哈卡链的先决条件"}}}}, steps={[1]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹"}, [2]={npc="特兰雷克", tgt="特兰雷克"}, [3]={npc="特伦顿·轻锤", tgt="特伦顿·轻锤"}, [4]={npc="叶基亚", tgt="叶基亚", desc="在热砂港中拾取，然后执行菲拉斯。交完后取出摩沙鲁的预言。"}, [5]={hint="在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。"}, [6]={npc="叶基亚", tgt="叶基亚"}, [7]={npc="叶基亚", tgt="叶基亚", preText="尖啸者的灵魂"}, [8]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓", tag="可选", desc="带上祖尔法拉克之槌。在祖尔的祭坛上获得神圣之槌，在辛萨罗处使用。"}, [9]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="直接从塔贝萨领取。 40 级幽暗城引导任务 (塔贝萨的任务) 是可选的。"}, [10]={text="祖尔法拉克 入口"}, [11]={hint="给加基森的特兰雷克带去5个完整的圣甲虫壳。", desc="位置：杀死殉教者塞卡房间周围的圣甲虫。顺序：在此取出第 15 步的第一块平板电脑。", spot="杀死殉教者塞卡房间周围的圣甲虫。"}, [12]={hint="收集20瓶巨魔调和剂，把它们交给加基森的特伦顿·轻锤。", desc="在逃跑前就战利品达成一致。一件清除可能掉落不够。位置：从入口处沿主干道清除沙怒巨魔。", spot="从入口处沿主干道清除沙怒巨魔。"}, [13]={hint="将深渊皇冠交给尘泥沼泽的塔贝萨。", tag="可选", desc="位置：经过金字塔并在水池边找到维拉萨。顺序：取出第二块药片用于此处的步骤 15。", spot="经过金字塔并在水池边找到维拉萨。"}, [14]={hint="把加兹瑞拉的鳞片交给闪光平原的维兹尔·铜栓。", tag="可选", desc="位置：在 Velratha 的水池边敲响锣来召唤加兹瑞拉。顺序：在敲锣之前杀死水占师维蕾萨。", spot="在 Velratha 的水池边敲响锣来召唤加兹瑞拉。"}, [15]={hint="把探水棒交给加基森的首席工程师沙克斯·比格维兹。", desc="打开楼梯活动的笼子。在变得敌对之前清除下面的波浪。位置：打开金字塔顶上的笼子。走下台阶，挡住海浪。顺序：防御海浪，然后挑战布莱中士。", spot="打开金字塔顶上的笼子。走下台阶，挡住海浪。"}, [16]={hint="将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。", desc="位置：拾取圣甲虫房间里的 Theka 和泳池边的 Velratha。顺序：在甲虫室执行步骤 10，在水池执行步骤 12-13。", spot="拾取圣甲虫房间里的 Theka 和泳池边的 Velratha。"}, [17]={npc="特兰雷克", tgt="特兰雷克"}, [18]={npc="特伦顿·轻锤", tgt="特伦顿·轻锤"}, [19]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹"}, [20]={npc="叶基亚", tgt="叶基亚"}, [21]={npc="叶基亚", tgt="叶基亚", desc="立即拿起。在阿塔尔神庙哈卡前的辛萨罗中拾取蛋。", preText="摩沙鲁的预言"}, [22]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓", tag="可选"}, [23]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}}},
    ["04-34"] = {name="灼热峡谷", nameA="灼热峡谷 {a:1446}", tips={{k="交通", text="解锁、部落、飞行点和瑟银哨塔。飞往幽暗城或落锤镇，然后继续前往辛特兰。"}, {k="取捨", text="在一个循环中清除四个杀戮目标。如果您缺少 被盗：鼓风机和望远镜 的掉落物，请先上交其他人。如果您有团体，请在同一个洞穴中进行 悬赏：工头玛托留斯 和 绝密配方！。"}, {k="取捨", text="任务交到50级后就离开瑟银哨塔。后面的火炬任务和东南部的木制厕所都需要回溯。仅当您需要经验时才执行这些操作。"}, {k="提醒", text="需要一点经验吗？杀死大锅东边的重型战争傀儡 (44.76, 38.72) 或北坡的普通黑铁工头 (41.21, 23.33)。", s={{"需要一点经验吗？"}, {"杀死大锅东边的重型战争傀儡 (44.76, 38.72) 或北坡的普通黑铁工头 (41.21, 23.33)"}}}}, danger={[1]="工头玛托留斯位于矿渣坑旁的黑铁矿深处。与你的团队一起清理隧道。如果单独的话跳过赏金。"}, grind={[1]={mob="重型作战傀儡", note="大锅东缘的普通傀儡。沿着篮筐保持高位并计算任务的击杀数。如果有其他玩家在场，请避开场地。"}, [2]={mob="黑铁工头", note="瑟银哨塔以南的普通黑铁生物。在返回飞行点之前拾取击杀和任务掉落。留意营地内的补充。"}}, supply={[1]={npc="格瑞沙"}, [2]={npc="大铁匠博恩奈特"}, [3]={npc="大铁匠博恩奈特"}, [4]={npc="大铁匠博恩奈特"}}, steps={[1]={text="从奥格瑞玛飞往棘齿城。在码头接安戈洛入口，然后乘船前往藏宝海湾。飞往卡加斯。"}, [2]={npc="莉芙·雷兹菲克斯", tgt="莉芙·雷兹菲克斯", desc="需要 49. 在安戈洛的火羽山做。上交处：棘齿城。"}, [3]={text="从卡加斯出来沿西南路进入灼热峡谷，然后沿北路行驶至瑟银哨塔。"}, [4]={nodeA="{a:1446}", desc="解锁、部落、飞行点和格瑞沙。"}, [5]={text="在瑟银哨塔接载，然后循环穿过大锅和渣坑"}, [6]={npc="通缉/寻物/招领", npcObj=true}, [7]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [8]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [9]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [10]={npc="通缉/寻物/招领", npcObj=true, tag="可选", desc="当你清除小怪时，掠夺两滴东西。"}, [11]={npc="通缉/寻物/招领", npcObj=true, tag="可选", desc="马多留斯是精英。仅接受团体。"}, [12]={npc="大铁匠博恩奈特", tgt="大铁匠博恩奈特", tag="可选", desc="在 Martorius 小组跑步中选择这个。"}, [13]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [14]={hint="听威拉罗克·温布雷讲述他的故事。"}, [15]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [16]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [17]={hint="汉瑟尔·重拳要你在灼热峡谷杀死20只灼热熔岩蜘蛛。你可以在灼热峡谷的高地和熔岩池附近找到它们。"}, [18]={hint="杀死15个黑铁工头和15个黑铁奴隶贩子。完成任务之后就回去找监工斯克兰格。"}, [19]={hint="汉瑟尔·重拳让你杀掉20个重型作战傀儡。"}, [20]={hint="收集4份烈焰之心和4份傀儡之油，然后把这些东西交给威拉罗克·温布雷。", desc="杀死大锅周围的傀儡和火元素。"}, [21]={hint="找到冶炼鼓风机和侦查员的望远镜，把它们还给灼热峡谷的监工斯克兰格。", tag="可选"}, [22]={hint="汉瑟尔·重拳让你去杀掉20个熏火龙。", desc="在渣坑中与黑铁小怪一起杀死火龙。"}, [23]={hint="在大熔炉的熔渣之池中的某个地方，你可以找到工头玛托留斯偷走的秘密设计图：炽热助熔剂。找到这些设计图，把它们还给灼热峡谷的大铁匠博恩奈特。", tag="可选", desc="在矿渣坑深处的马多留斯附近寻找平面图。安全时抢劫。"}, [24]={hint="那个叫做工头玛托留斯的黑铁矮人叛徒就藏在大熔炉的熔渣之池深处。", tag="可选"}, [25]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [26]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选", desc="如果您需要经验并且愿意再次前往大锅，请接受。"}, [27]={hint="给威拉罗克·温布雷带去8把瑟银匕首。", tag="可选", desc="从渣坑中的黑铁工头和奴隶贩子身上掉落。"}, [28]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选"}, [29]={text="返回瑟银哨塔并一起交所有大锅任务。"}, [30]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [31]={npc="监工斯克兰格", tgt="监工斯克兰格"}, [32]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [33]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [34]={npc="监工斯克兰格", tgt="监工斯克兰格", tag="可选"}, [35]={npc="大铁匠博恩奈特", tgt="大铁匠博恩奈特", tag="可选"}, [36]={npc="侦查队长洛洛尔", tgt="侦查队长洛洛尔", tag="可选"}, [37]={text="额外的经验或手电筒（如果您仍然需要）"}, [38]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选", desc="完成 铸造火炬杆. 杀死西洞中的暮光怪物以获得拉格纳罗斯符记。"}, [39]={hint="找到一个拉格纳罗斯符记，把它交给威拉罗克·温布雷。", tag="可选", desc="完成 铸造火炬杆. 杀死西洞中的暮光怪物以获得拉格纳罗斯符记。"}, [40]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选", desc="完成 铸造火炬杆. 杀死西洞中的暮光怪物以获得拉格纳罗斯符记。"}, [41]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选"}, [42]={hint="等待威拉罗克·温布雷完成惩戒火炬。", tag="可选"}, [43]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选"}, [44]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选"}, [45]={hint="拿起惩戒火炬。", tag="可选"}, [46]={npc="惩戒火炬", npcObj=true, tag="可选"}, [47]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选"}, [48]={hint="与侍卫玛特拉克谈一谈。", tag="可选"}, [49]={npc="侍卫玛特拉克", tgt="侍卫玛特拉克", tag="可选"}, [50]={npc="侍卫玛特拉克", tgt="侍卫玛特拉克", tag="可选", desc="在点燃所有四座塔之前先把守卫拉开。"}, [51]={hint="使用惩戒火炬点燃北部、南部、东部和西部的哨塔。", tag="可选", desc="在点燃所有四座塔之前先把守卫拉开。"}, [52]={npc="侍卫玛特拉克", tgt="侍卫玛特拉克", tag="可选", desc="在点燃所有四座塔之前先把守卫拉开。"}, [53]={npc="黑龙的财宝", npcObj=true, tag="可选"}, [54]={hint="打开箱子。", tag="可选"}, [55]={npc="黑龙的财宝", npcObj=true, tag="可选"}, [56]={npc="木制厕所", npcObj=true, tag="可选", desc="如果向东南行驶或短途行驶经验，请绕道木制厕所。带15个丝绸。"}, [57]={hint="杀掉8个黑铁地质学家，并将15块丝绸交给灼热峡谷里那个被锁在厕所中的矮人。", tag="可选", desc="如果向东南行驶或短途行驶经验，请绕道木制厕所。带15个丝绸。"}, [58]={npc="木制厕所", npcObj=true, tag="可选", desc="如果向东南行驶或短途行驶经验，请绕道木制厕所。带15个丝绸。"}}},
    ["05-d22"] = {name="Alcaz Prison", entrance="尘泥沼泽 75.30, 14.10", pickup="48级以下？ 解锁蕨墙村正在前往悲伤沼泽的途中。在灼热峡谷之前，从智慧谷（34.28, 39.35）的萨尔的房间中的伊崔格中取出库卡隆失联。飞往蕨墙村并查看纳泽尔·血矛。 游泳从东北海岸到奥卡兹岛。将精锐中的精锐和阴差阳错交给岛边的中士，然后在进入塔下之前拿一个兽人都不能少。将 大酋长必须知情 保存为奥格瑞玛。", pickupS={{"48级以下？"}, {"解锁蕨墙村正在前往悲伤沼泽的途中"}, {"在灼热峡谷之前，从智慧谷（34.28, 39.35）的萨尔的房间中的伊崔格中取出库卡隆失联"}, {"飞往蕨墙村并查看纳泽尔·血矛"}, {"游泳从东北海岸到奥卡兹岛"}, {"将精锐中的精锐和阴差阳错交给岛边的中士，然后在进入塔下之前拿一个兽人都不能少"}, {"将 大酋长必须知情 保存为奥格瑞玛"}}, tips={{k="動線", text="在上层牢房中找到司令 Folkar→杀死狱监雷克斯获取钥匙→清除质问者和海潮主母卡扎斯，掠夺头巾→打开下层牢房以获得清道夫卡特琳娜和烈焰咆哮者→阅读隐藏房间中的注释并返回楼上的Folkar。"}, {k="取捨", text="优先考虑从 库卡隆失联 到 大酋长必须知情 的库卡隆救援链。如果你在一次跑步后缺少头巾，请保存该上交。"}, {k="說明", text="避免使用塞拉摩。从蕨墙村往东北海岸游过去。中士在岛边，地下城的入口在塔下的走廊里。", s={{"避免使用塞拉摩"}, {"从蕨墙村往东北海岸游过去"}, {"中士在岛边，地下城的入口在塔下的走廊里"}}}}, steps={[1]={npc="伊崔格", tgt="伊崔格", desc="48号，在智慧谷的萨尔大厅找到伊崔格。"}, [2]={hint="与蕨墙村的纳泽尔·血矛谈一谈。"}, [3]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛"}, [4]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛", preText="库卡隆失联"}, [5]={hint="搜寻失踪的库卡隆精锐。"}, [6]={npc="乌尔卡中士", tgt="乌尔卡中士"}, [7]={npc="乌尔卡中士", tgt="乌尔卡中士", preText="精锐中的精锐"}, [8]={hint="与乌尔卡军士交谈，了解奥卡兹岛上的严峻局势。"}, [9]={npc="乌尔卡中士", tgt="乌尔卡中士"}, [10]={npc="乌尔卡中士", tgt="乌尔卡中士", preText="阴差阳错"}, [11]={npc="乌尔卡中士", tgt="乌尔卡中士", tag="可选", desc="从奥格瑞玛做库卡隆失联 - 阴差阳错到岛上，然后检查中士的任务。"}, [12]={npc="乌尔卡中士", tgt="乌尔卡中士", tag="可选", desc="中士在游戏中提供了这个。 解锁未确认；先做库卡隆失联 - 阴差阳错。"}, [13]={text="Alcaz Prison 入口"}, [14]={hint="进入奥卡兹监狱，寻找指挥官福尔卡。", desc="位置：进入上层大厅并在牢房中找到司令 Folkar。", spot="进入上层大厅并在牢房中找到司令 Folkar。"}, [15]={npc="Commander Folkar", tag="需要游戏内检查", spot="上层走廊的牢房，指挥官 Folkar"}, [16]={npc="Commander Folkar", tag="需要游戏内检查", preText="一个兽人都不能少"}, [17]={hint="进入奥卡兹监狱，消灭15名斯塔莎兹士兵与8名斯塔莎兹女巫，并将海潮主母卡扎斯的徽记带给乌尔卡中士。", tag="可选", desc="位置：通过上面的单元格找到海潮主母卡扎斯。沿着大厅清除纳迦。", spot="通过上面的单元格找到海潮主母卡扎斯。沿着大厅清除纳迦。"}, [18]={hint="进入奥卡兹监狱，从人类守卫的尸体上收集8条血红头巾。", tag="可选", desc="您可能需要再跑一次。离开地牢之前检查一下你的计数。位置：沿着上层监狱大厅杀死人类守卫，直到获得所有掉落物。", spot="沿着上层监狱大厅杀死人类守卫，直到获得所有掉落物。"}, [19]={hint="深入奥卡兹监狱，寻找国王瓦里安·乌瑞恩的下落。", desc="位置：打开下面的门并杀死最后一个老板。在隐藏的房间里找到纸条。顺序：先从典狱长那里拿到钥匙。", spot="打开下面的门并杀死最后一个老板。在隐藏的房间里找到纸条。"}, [20]={npc="任务物件", npcObj=true, tag="需要游戏内检查", spot="尾王后方密室的地板纸条"}, [21]={npc="任务物件", npcObj=true, tag="需要游戏内检查", preText="库卡隆的荣耀"}, [22]={hint="向指挥官福尔卡复命。", desc="位置：从最后一个 Boss 的隐藏房间回到上层牢房的指挥官身边。顺序：首先阅读步骤 18 中的注释。", spot="从最后一个 Boss 的隐藏房间回到上层牢房的指挥官身边。"}, [23]={npc="Commander Folkar", tag="需要游戏内检查", spot="上层走廊的牢房，指挥官 Folkar"}, [24]={npc="Commander Folkar", tag="需要游戏内检查", preText="给福尔卡的坏消息"}, [25]={npc="乌尔卡中士", tgt="乌尔卡中士", tag="可选"}, [26]={hint="前往奥格瑞玛，将瓦里安·乌瑞恩的死讯呈报给萨尔。"}, [27]={npc="萨尔", tgt="萨尔"}, [28]={npc="伊崔格", tgt="伊崔格", tag="可选"}}},
    ["04-35"] = {name="辛特兰", nameA="辛特兰 {a:3317}／{a:354}", shortA="辛特兰 {a:3317} +", tips={{k="取捨", text="在与海龟任务相同的海滩上做 威士忌斯利姆的酒。一起杀死野蛮的枭兽和测试容器的枭兽。"}, {k="取捨", text="任务 职位空缺：恶齿村卫兵队长 需要 80 名精英击杀。没有组就跳过它。如果辛萨罗太难单人，请先做沿海和内陆任务。"}, {k="取捨", text="在藏宝海湾上交 威士忌斯利姆的酒，在莫沙彻营地上交 测试容器。将 斯普琳科的秘密佐料 和 远古之卵 保存为加基森和破碎石柱支线。"}, {k="提醒", text="52级以下？在辛特兰磨碎海龟或枭兽，或者与团队一起清除辛萨罗。", s={{"52级以下？"}, {"在辛特兰磨碎海龟或枭兽，或者与团队一起清除辛萨罗"}}}}, danger={[1]="精英邪枝巨魔和治疗者套装上层辛萨罗。与一组一起清除一层。如果独自一人，请坚持到海岸。", [2]="加莫里塔是一只在海岸巡逻的精英海龟。在磨普通海龟时要留意她，如果你独自一人，请给她空间。"}, grind={[1]={mob="海水钳嘴龟", note="恶齿村以北海滩上的普通海龟。沿着海岸，剥皮，并与海龟肉探索者分享海滩。跳过辛萨罗精英。"}}, supply={[1]={npc="格卡斯"}, [2]={npc="拉尔德"}, [3]={npc="铁匠斯拉提"}, [4]={npc="拉尔德"}, [5]={npc="雷艾"}, [6]={npc="秘法师雅尔金"}}, steps={[1]={text="从灼热峡谷飞往恶齿村。如果锁定，请飞往塔伦米尔并使用敦霍尔德城堡以北的通行证。沿着辛特兰路向东行驶，然后沿着海岸向南行驶。", tag="尚未解锁这个飞行点，第一次请走过去。"}, [2]={nodeA="{a:3317}", desc="解锁、飞行点和格卡斯。"}, [3]={text="您可以将您的炉石绑定到恶齿村上。"}, [4]={text="恶齿村接载 → 海岸"}, [5]={npc="钓鱼者卡图姆", tgt="钓鱼者卡图姆"}, [6]={npc="钓鱼者卡图姆", tgt="钓鱼者卡图姆"}, [7]={npc="猎户马克霍尔", tgt="猎户马克霍尔"}, [8]={npc="猎户马克霍尔", tgt="猎户马克霍尔"}, [9]={npc="拉尔德", tgt="拉尔德"}, [10]={npc="猎户马克霍尔", tgt="猎户马克霍尔"}, [11]={npc="断齿族长", tgt="断齿族长"}, [12]={npc="断齿族长", tgt="断齿族长"}, [13]={npc="猎户马克霍尔", tgt="猎户马克霍尔", tag="可选", desc="仅当您发现稀有的刀喙狮鹫时才这样做。"}, [14]={npc="铁匠斯拉提", tgt="铁匠斯拉提", tag="可选", desc="绕道东北方向前往寺庙。"}, [15]={npc="作战公告！", npcObj=true, tag="可选", desc="在辛萨罗的上层平台上为精英们集结。"}, [16]={npc="作战公告！", npcObj=true, tag="可选", desc="仅当您计划在辛萨罗中杀死 80 名精英时才选择。", star={"卫兵队长符文", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}}, [17]={hint="辛特兰恶齿村的钓鱼者卡图姆要你去杀掉15只海水钳嘴龟。完成任务之后回到他那里去复命。"}, [18]={hint="辛特兰恶齿村的钓鱼者卡图姆要你去杀掉加莫里塔，并从它的尸体上找到卡图姆的超级鱼饵。", desc="使用 钳嘴龟！ 和 威士忌斯利姆的酒 进行操作。如果发现目标，请将其杀死。"}, [19]={hint="藏宝海湾的威士忌斯利姆想要你帮他找回弄丢的紫葡萄酒。", desc="在斯通纳德 / 东风海岸站接受。沿着海滩向北走去寻找瓶子。"}, [20]={hint="辛特兰恶齿村的拉尔德要求你去找到拉尔德的午餐。完成任务之后就回到他那里去。"}, [21]={hint="解开这道迷题！", tag="可选", desc="需要 科泰罗的谜题 已开启且 科泰罗的谜题 处于活动状态。在桥下的卷轴处交出科泰罗的谜题。"}, [22]={npc="科泰罗的宝藏", npcObj=true, tag="可选", desc="如果您的任务日志中没有 科泰罗的谜题，请跳过。"}, [23]={text="内陆枭兽和银鬃兽 → 辛萨罗祭坛"}, [24]={hint="辛特兰恶齿村的猎户马克霍尔要求你去杀掉15头银鬃捕猎者和15头银鬃嗥狼。完成任务之后就回到他那里复命。"}, [25]={hint="辛特兰恶齿村的猎户马克霍尔要求你去杀掉20头野蛮的枭兽。完成任务之后就回到他那里复命。"}, [26]={hint="到辛特兰去杀掉10头枭兽，然后使用灵魂精华容器捕获它们的灵魂。", desc="在莫沙彻营地 / 怒痕堡腿上拾取。稍后上交菲拉斯。"}, [27]={hint="辛特兰恶齿村的猎户马克霍尔要求你杀掉一头翱翔的锋喙狮鹫，并将它的狮鹫长羽拿回去交给他。", tag="可选", desc="如果你看到它就杀死它。"}, [28]={hint="辛特兰恶齿村的铁匠斯拉提要你去找到斯拉提的工具。完成任务之后就回到他那里去。", tag="可选"}, [29]={hint="加基森的斯普琳科要你去给她找到一颗紫色水生菇。", desc="在第一次加基森 /Dunemaul 访问时接受。上交处：加基森。"}, [30]={hint="辛特兰恶齿村的断齿族长要你在辛萨罗找到10瓶腐化之血。任务完成之后就回到断齿族长那里。", desc="与断齿长者的任务一起完成。留意楼梯上的巡逻人员。"}, [31]={hint="辛特兰恶齿村的猎户马克霍尔要你去找回他的双胞胎兄弟的尸体。找到它，然后把猎户莫克霍尔的头颅和猎户莫克霍尔的骨头交给猎户马克霍尔。", desc="抢劫这两项物品。它们位于不同的地点。"}, [32]={hint="辛特兰恶齿村的断齿族长要求你到辛萨罗去拯救她的爱人，断齿长者。"}, [33]={npc="断齿长者", tgt="断齿长者"}, [34]={npc="断齿长者", tgt="断齿长者"}, [35]={hint="辛萨罗的断齿长者要求你杀掉守护者希坦亚，并用她身上的镣铐钥匙打开他的镣铐。当你找到钥匙之后就回到他那里去。"}, [36]={npc="断齿长者", tgt="断齿长者"}, [37]={npc="断齿长者", tgt="断齿长者"}, [38]={hint="将远古之卵交给塔纳利斯的叶基亚。", tag="可选", desc="如果在 Dunemaul 停留期间接受，请做这个任务。在热砂港上交。"}, [39]={hint="你必须杀掉邪恶祭司海克斯和20名邪枝精英守卫。任务完成之后回到辛特兰的恶齿村，向断齿族长报告。", tag="可选"}, [40]={hint="你必须消灭20个邪枝狂战士、20个邪枝暗影猎手、20个邪枝饮血者和20个邪枝噬魂者。", tag="可选"}, [41]={text="使用您的炉石返回恶齿村以获得所有任务交接（如果绑定在那里）。"}, [42]={hint="辛萨罗的断齿长者要求你将他已经被营救的消息带给恶齿村的断齿族长。"}, [43]={npc="断齿族长", tgt="断齿族长"}, [44]={npc="猎户马克霍尔", tgt="猎户马克霍尔"}, [45]={npc="断齿族长", tgt="断齿族长"}, [46]={npc="钓鱼者卡图姆", tgt="钓鱼者卡图姆"}, [47]={npc="钓鱼者卡图姆", tgt="钓鱼者卡图姆"}, [48]={npc="猎户马克霍尔", tgt="猎户马克霍尔"}, [49]={npc="猎户马克霍尔", tgt="猎户马克霍尔"}, [50]={npc="拉尔德", tgt="拉尔德"}, [51]={npc="猎户马克霍尔", tgt="猎户马克霍尔", tag="可选"}, [52]={npc="铁匠斯拉提", tgt="铁匠斯拉提", tag="可选"}, [53]={npc="断齿族长", tgt="断齿族长", tag="可选"}, [54]={npc="断齿族长", tgt="断齿族长", tag="可选", star={"卫兵队长符文", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}}, [55]={npc="克里斯托弗·沃克", tgt="克里斯托弗·沃克", tag="可选", desc="在辛特兰之前的幽暗城中接受克里斯托弗·沃克。上交诅咒之地。"}, [56]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="在AH上买四种材料。从塔伦米尔向北行驶 元素掌握 到达巴斯拉 (Bath'rah)。"}, [57]={hint="将土元素、空气元素、火元素和水元素交给捕风者巴斯拉。", tag="可选", desc="在AH上买四种材料。从塔伦米尔向北行驶 元素掌握 到达巴斯拉 (Bath'rah)。"}, [58]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="在AH上买四种材料。从塔伦米尔向北行驶 元素掌握 到达巴斯拉 (Bath'rah)。"}, [59]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="执行 元素掌握 或 控制元素。收集西瘟疫之地中的材料。"}, [60]={npc="迈尔斯·迪克斯特", tgt="迈尔斯·迪克斯特", tag="可选", desc="在您第一次前往辛特兰时，请在幽暗城的潜行者区中接受。"}, [61]={hint="前往拉文霍德庄园，和乔拉齐·拉文霍德公爵谈一谈。", tag="可选", desc="在您第一次前往辛特兰时，请在幽暗城的潜行者区中接受。"}, [62]={npc="乔拉齐·拉文霍德公爵", tgt="乔拉齐·拉文霍德公爵", tag="可选", desc="在您第一次前往辛特兰时，请在幽暗城的潜行者区中接受。"}, [63]={npc="乔拉齐·拉文霍德公爵", tgt="乔拉齐·拉文霍德公爵", tag="可选", desc="接受拉文霍德庄园。将其保存为艾萨拉。"}}},
    ["04-36"] = {name="诅咒之地", tips={{k="取捨", text="一起完成所有五个收集任务。带来 5 个下颌、6 个野猪肺、6 个钳子、11 个蛇怪大脑和 14 个秃鹫砂囊。每次上交都会消耗其材料。"}, {k="取捨", text="先交掉落速度较快的任务。如果与秃鹫或蛇怪发生争斗，请保存未完成的 石化蜥蜴的大脑 或 秃鹫的活力 并前往藏宝海湾。"}, {k="提醒", text="需要经验吗？在北坡磨碎野兽（46-53、15-27）。高级生物在更南边。", s={{"需要经验吗？"}, {"在北坡磨碎野兽（46-53、15-27）"}, {"高级生物在更南边"}}}}, danger={[1]="血法师营地以南的怪物等级比北坡的怪物要高。坚持到外坡进行北部收集任务。"}, grind={[1]={mob="厚甲毒刺蝎", note="血法师营地东边的普通蝎子。收集钳子并剥皮。拥挤时请远离道路，并留意精英巡逻队。"}}, supply={[1]={npc="布雷依克"}, [2]={npc="旅店老板卡拉库尔"}, [3]={npc="卡尔拉什"}, [4]={npc="索尔塔什"}, [5]={npc="苏塔佐尔"}}, steps={[1]={text="从恶齿村飞往斯通纳德，然后沿路向南进入诅咒之地。拜访北方的两个血法师（50.55, 14.20 和 50.64, 14.30）。"}, [2]={npc="血法师德拉吉亚", tgt="血法师德拉吉亚"}, [3]={npc="血法师德拉吉亚", tgt="血法师德拉吉亚"}, [4]={npc="血法师德拉吉亚", tgt="血法师德拉吉亚"}, [5]={npc="血法师莱诺雷", tgt="血法师莱诺雷"}, [6]={npc="血法师莱诺雷", tgt="血法师莱诺雷"}, [7]={hint="收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。"}, [8]={hint="收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。"}, [9]={hint="收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。"}, [10]={hint="收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。"}, [11]={hint="收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。"}, [12]={npc="血法师德拉吉亚", tgt="血法师德拉吉亚"}, [13]={npc="血法师德拉吉亚", tgt="血法师德拉吉亚"}, [14]={npc="血法师德拉吉亚", tgt="血法师德拉吉亚"}, [15]={npc="血法师莱诺雷", tgt="血法师莱诺雷"}, [16]={npc="血法师莱诺雷", tgt="血法师莱诺雷"}, [17]={npc="收藏家库米沙", tgt="收藏家库米沙", tag="可选", desc="如果物品没有掉落则跳过它。"}, [18]={hint="在你探索诅咒之地的旅程中，如果碰巧发现了无暇的德莱尼水晶球，就把它交给收藏家库米沙。", tag="可选", desc="如果物品没有掉落则跳过它。"}, [19]={npc="收藏家库米沙", tgt="收藏家库米沙", tag="可选", desc="如果物品没有掉落则跳过它。"}, [20]={npc="收藏家库米沙", tgt="收藏家库米沙", tag="可选", desc="如果物品没有掉落则跳过它。"}, [21]={hint="将有瑕疵的德莱尼水晶碎片交给库米沙，你就可以得到相应的回报。", tag="可选", desc="如果物品没有掉落则跳过它。"}, [22]={npc="收藏家库米沙", tgt="收藏家库米沙", tag="可选", desc="如果物品没有掉落则跳过它。"}, [23]={hint="到诅咒之地的入口去，与部落英雄的灵魂谈一谈。", tag="可选"}, [24]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选"}, [25]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选", desc="与鲜血法师的野猪肺任务配对。杀死北方的两组目标。"}, [26]={hint="杀死7头地狱野猪，然后回到部落英雄的灵魂那儿。", tag="可选", desc="与鲜血法师的野猪肺任务配对。杀死北方的两组目标。"}, [27]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选", desc="与鲜血法师的野猪肺任务配对。杀死北方的两组目标。"}, [28]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选", desc="一次从营地边缘拉出一个怪物。"}, [29]={hint="杀死诅咒之地的魔誓者，然后回到部落英雄的灵魂那儿。", tag="可选", desc="一次从营地边缘拉出一个怪物。"}, [30]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选", desc="一次从营地边缘拉出一个怪物。"}, [31]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选", desc="立即与团体一起参加或节省前往圣光之愿礼拜堂的东部王国之旅。", star={"钻石水瓶", {"WARRIOR"}}}, [32]={text="返回至斯通纳德的航线并飞往藏宝海湾。"}}},
    ["04-37"] = {name="荆棘谷（回访）", nameA="荆棘谷 {a:35}（回访）", tips={{k="取捨", text="先交50级任务威士忌斯利姆的酒。较低级别的荆棘谷任务被分配在早期的访问中。如果完成，请上交日志中的任何静止图像。"}, {k="取捨", text="没有辛特兰烈酒或已完成的任务？就坐船吧。 船长的箱子 和荆棘谷热疫 需要城外往返。为额外的经验或团体保存它们。"}, {k="提醒", text="藏宝海湾是中性端口。登上前往棘齿城的客船，并确保您在正确的渡轮上。", s={{"藏宝海湾是中性端口"}, {"登上前往棘齿城的客船，并确保您在正确的渡轮上"}}}}, grind={[1]={mob="血精灵搜寻者", note="使用藏宝海湾进行任务交接和船只。如果低于53，则改为杀死艾萨拉中的正常血精灵。如果有探索者，就沿着营地边缘拉。"}}, supply={[1]={npc="格林戈"}, [2]={npc="旅店老板斯金德"}, [3]={npc="祖塔克"}, [4]={npc="尼克拉克斯·菲拉莫格"}, [5]={npc="哈伦·坎麦尔"}}, steps={[1]={npc="威士忌斯利姆", tgt="威士忌斯利姆", desc="在斯通纳德 / 东风海岸站接受。在辛特兰收集烈酒。"}, [2]={npc="海克拜瑞·斯莫特船长", tgt="海克拜瑞·斯莫特船长", tag="可选", desc="可选的 47 级任务。如果您需要经验但尚未完成，请接受。"}, [3]={npc="芬·菲兹拉克", tgt="芬·菲兹拉克", tag="可选", desc="先分组吧几波大猩猩的攻击。"}, [4]={hint="将斯莫特的箱子交给藏宝海湾的海克拜瑞·斯莫特。", tag="可选"}, [5]={npc="巫医安巴格瓦", tgt="巫医安巴格瓦", tag="可选", desc="在上交象牙之前接受 荆棘谷热疫 以触发事件。"}, [6]={hint="掉落自：迷雾谷猩猩、丛林大猩猩、暴怒的银背猩猩", tag="可选", desc="在上交象牙之前接受 荆棘谷热疫 以触发事件。"}, [7]={npc="巫医安巴格瓦", tgt="巫医安巴格瓦", tag="可选", desc="在上交象牙之前接受 荆棘谷热疫 以触发事件。"}, [8]={hint="找到巫医安巴格瓦并要求他召唤出野人莫克，然后将野人莫克的心脏交给芬·菲兹拉克。", tag="可选", desc="在象牙上交活动期间生成 荆棘谷热疫。"}, [9]={npc="海克拜瑞·斯莫特船长", tgt="海克拜瑞·斯莫特船长", tag="可选"}, [10]={npc="芬·菲兹拉克", tgt="芬·菲兹拉克", tag="可选"}, [11]={text="坐船到棘齿城，再飞到奥格瑞玛。您可以从 Belgrom 领取 叛徒，然后前往艾萨拉中的瓦罗莫克。"}}},
    ["04-38"] = {name="艾萨拉 阿克科兰神殿", nameA="艾萨拉 {a:1237}／阿克科兰神殿", shortA="艾萨拉 {a:1237} +", tips={{k="取捨", text="做一圈萨拉斯营地、三个标记和 Rimtori。收集埃达拉斯废墟中的所有四块石板和纳迦符文。"}, {k="取捨", text="视频跳过了两个小组任务。永远将大地魔网 (Ley of the Land) 和致命捕获 (Deadliest Catch) 列为精英候选人。这次访问请跳过这两个步骤。"}, {k="取捨", text="在圣光之愿礼拜堂转账期间，将 安德隆·甘特的石版 转入幽暗城 (54.81, 76.33) 中的安德隆·甘特。跳过将您带回艾萨拉的后续操作。"}, {k="提醒", text="53级以下？在埃达拉斯废墟处磨掉纳迦，或者在萨拉斯营地处磨掉血精灵，同时寻找任务掉落物。", s={{"53级以下？"}, {"在埃达拉斯废墟处磨掉纳迦，或者在萨拉斯营地处磨掉血精灵，同时寻找任务掉落物"}}}}, danger={[1]="纳迦脚轮包装在埃达拉斯废墟内部。收集药片时拥抱外墙。 中断脚轮并将其拉出房间。"}, grind={[1]={mob="血精灵搜寻者", note="萨拉斯营地的普通血精灵对于经验和任务掉落来说是一个很好的水平。沿着边缘拉动以避免连接内部脚轮。"}, [2]={mob="恶鞭侍从", note="普通纳迦在埃达拉斯废墟。与纳迦任务配对。沿着外墙一次拉一个敌人，并避免里面有密集的施法者包。"}}, supply={[1]={npc="克隆姆"}, [2]={npc="格鲁尔·黑刃"}, [3]={npc="库尔"}, [4]={npc="旅店老板格雷什卡"}, [5]={npc="卡加"}, [6]={npc="霍苏斯"}}, steps={[1]={npc="贝尔戈洛姆·石槌", tgt="贝尔戈洛姆·石槌", desc="接受在奥格瑞玛的荣誉谷中。启动更新的叛徒链。"}, [2]={npc="杰斯雷蒙", tgt="杰斯雷蒙", tag="可选", desc="可选。现在就拿起，然后杀死安戈洛的掠龙。"}, [3]={text="如果您已解锁艾萨拉飞行点，请从奥格瑞玛飞往瓦罗莫克。第一次访问时，从碎木岗哨向东行驶，在罗哈图停留，然后继续前往瓦罗莫克。", tag="尚未解锁这个飞行点，第一次请走过去。"}, [4]={text="西边的罗哈图 → 瓦罗莫克的皮卡"}, [5]={npc="罗哈图", tgt="罗哈图"}, [6]={npc="罗哈图", tgt="罗哈图"}, [7]={hint="杀掉6个上层精灵的幻影和6个上层精灵鬼巫，然后向艾萨拉的罗哈图复命。"}, [8]={hint="杀掉6个哈达尔萨特、2个哈达尔欺诈者和2个哈达尔魔仆，然后向灰谷与艾萨拉交界处的罗哈图复命。"}, [9]={npc="罗哈图", tgt="罗哈图"}, [10]={npc="罗哈图", tgt="罗哈图"}, [11]={nodeA="{a:1237}", desc="解锁、飞行点和克隆姆。"}, [12]={hint="把这封给阿格图的密信交给艾萨拉的阿格图·血拳。"}, [13]={npc="阿格图·血拳", tgt="阿格图·血拳"}, [14]={npc="阿格图·血拳", tgt="阿格图·血拳"}, [15]={npc="杰迪加", tgt="杰迪加"}, [16]={text="萨拉斯营地 → 镜腿和埃达拉斯废墟 → 瓦罗莫克"}, [17]={npc="基姆加尔", tgt="基姆加尔"}, [18]={hint="搜索萨拉斯营地，找到基姆加尔的指南针、望远镜、烧鸡和花生，然后把它们交给艾萨拉的基姆加尔。"}, [19]={npc="基姆加尔", tgt="基姆加尔"}, [20]={npc="基姆加尔", tgt="基姆加尔"}, [21]={hint="杀死10个血精灵搜寻者和10个血精灵勘测员，并找到大法师雷姆托里的营地。一旦你发现了营地，就去找到某个对她极为重要的东西，以用于激怒她，让她与你战斗。", desc="数量以任务日志为准。"}, [22]={npc="卡多雷召唤宝典", npcObj=true, tag="需要游戏内检查"}, [23]={npc="Sin'dorei Tome of Summoning", tgt="Sin'dorei Tome of Summoning", tag="需要游戏内检查", desc="永远的叛徒链条。首先完成 ，然后收集每个印章一个。"}, [24]={hint="掉落自：Lieutenant Suncr