    ["04-39"] = {name="菲拉斯（回访）", nameA="菲拉斯 {a:1099}（回访）", tips={{k="取捨", text="在莫沙彻营地处交出 测试容器，然后执行 角鹰兽灵魂精华 -山岭巨人灵魂精华。上交每一步以获得下一个容器。"}, {k="取捨", text="如果您缺少材料，请跳过 天然材料。如果你有时间的话，将北方春天的支线任务与西方巨人配对。"}, {k="提醒", text="需要一点经验吗？在 69.45, 44.95 杀死精灵飞镖，或者前往西北方向的鹰身女妖营地。", s={{"需要一点经验吗？"}, {"在 69.45, 44.95 杀死精灵飞镖，或者前往西北方向的鹰身女妖营地"}}}}, grind={[1]={mob="北泉杀戮者", note="北泉鹰身女妖营地外的普通生物。如果您正在执行北泉任务，请收集掉落物。单独经验，跳过回程，下一站磨。"}, [2]={mob="格罗多克大猩猩", note="如果鹰身女妖被抓住，杀死东南方的普通大猩猩。利用空地撤退并从外面拉单打。"}}, supply={[1]={npc="夏恩"}, [2]={npc="旅店老板格鲁尔"}, [3]={npc="卡温德"}, [4]={npc="旅店老板格鲁尔"}, [5]={npc="卡温德"}, [6]={npc="塔霍斯"}}, steps={[1]={text="如果解锁，则飞往莫沙彻营地。没有飞行点就加入这里吗？飞往乱风岗，沿着山谷向西进入菲拉斯，并从夏恩学习莫沙彻营地飞行点。"}, [2]={npc="巫医尤克里", tgt="巫医尤克里", desc="在莫沙彻营地 / 厄运之槌站接受。 陷阱辛特兰的枭兽灵魂。"}, [3]={npc="巫医尤克里", tgt="巫医尤克里", desc="返回巫医处进行下一个任务。"}, [4]={hint="杀掉10只任意种类的乱羽角鹰兽，然后用灵魂精华容器捕获它们的灵魂。", desc="返回巫医处进行下一个任务。"}, [5]={npc="巫医尤克里", tgt="巫医尤克里", desc="返回巫医处进行下一个任务。"}, [6]={npc="巫医尤克里", tgt="巫医尤克里"}, [7]={hint="杀掉8只精龙或小精龙，然后用灵魂精华容器捕获它们的灵魂。"}, [8]={npc="巫医尤克里", tgt="巫医尤克里"}, [9]={npc="巫医尤克里", tgt="巫医尤克里"}, [10]={hint="杀掉3个森林漫游者，然后用灵魂精华容器捕获它们的灵魂。"}, [11]={npc="巫医尤克里", tgt="巫医尤克里"}, [12]={npc="巫医尤克里", tgt="巫医尤克里"}, [13]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", tag="可选", desc="如果您能对付精英，则在前往北泉鹰身女妖时接受。"}, [14]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", tag="可选"}, [15]={hint="杀掉7个大地行者或者峭壁巨人，然后用灵魂精华容器捕获它们的灵魂。"}, [16]={hint="塔罗·刺蹄让你杀掉4个北泉鹰身人、4个北泉游荡者、4个北泉唤风者和4个北泉杀戮者。", tag="可选"}, [17]={hint="莫沙彻营地的塔罗·刺蹄要你给他拿去艾丹娜·邪爪的黑心。", tag="可选", desc="召唤在北泉祭坛。"}, [18]={hint="为莫沙彻营地的巫医尤克里收集2根断裂的原木、6颗包壳矿石、20片有弹性的肌腱和40块金属碎片。", tag="可选", desc="在莫沙彻营地 / 厄运之槌站接受。边走边收集。跳过额外的回溯。"}, [19]={npc="巫医尤克里", tgt="巫医尤克里"}, [20]={npc="巫医尤克里", tgt="巫医尤克里", tag="可选"}, [21]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", tag="可选"}, [22]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", tag="可选"}, [23]={npc="巫医尤克里", tgt="巫医尤克里", tag="可选", desc="完成 山岭巨人灵魂精华 和 天然材料 后接受。"}, [24]={hint="巫医尤克里希望你在他准备武器的时候稍等一会儿。", tag="可选", desc="完成 山岭巨人灵魂精华 和 天然材料 后接受。"}, [25]={npc="巫医尤克里", tgt="巫医尤克里", tag="可选", desc="完成 山岭巨人灵魂精华 和 天然材料 后接受。"}, [26]={text="从莫沙彻营地乘