    ["04-40"] = {name="塔纳利斯", nameA="塔纳利斯 {a:976}／{a:1938}", shortA="塔纳利斯 {a:976} +", tips={{k="取捨", text="交出加基森中从斯普琳科的秘密佐料到诺格弗格药剂的三个任务。在前往破碎石柱之前接受安戈洛任务。"}, {k="取捨", text="任务 将您带回棘齿城。如果您愿意，请在本次访问中仅使用 沉没的神庙 和 加兹瑞迪安。如果您将 用于地下城链，请在棘齿城中获取石环并在另一次旅行中将其上交。"}, {k="取捨", text="完成 擒虫先擒王 的先决条件后，在马绍尔营地处执行 极度粘稠的沥青 和 擒虫先擒王。在烈焰峰和黑石山腿上上交 尤卡·斯库比格特。"}, {k="提醒", text="需要经验吗？通过破碎石柱执行 加兹瑞迪安 并杀死沙槌食人魔，或者在塔纳利斯中找到祖尔法拉克小组。", s={{"需要经验吗？"}, {"通过破碎石柱执行 加兹瑞迪安 并杀死沙槌食人魔，或者在塔纳利斯中找到祖尔法拉克小组"}}}}, grind={[1]={mob="哈扎里群居蝎", note="大裂谷外有密集、水平合适的正常蝎子。留在地面上以避免入口附近产生额外的拉力。"}, [2]={mob="晶鳞石化蜥蜴", note="沿着破碎石柱或安戈洛之前的南部道路杀死普通蜥蜴。分散的生成点比砂槌营地的竞争要少。"}}, supply={[1]={npc="布科雷克·怒拳"}, [2]={npc="旅店老板菲兹格瑞博"}, [3]={npc="乌林克·古德斯迪尔"}, [4]={npc="旅店老板菲兹格瑞博"}, [5]={npc="布雷兹里克·巴克舒特"}}, steps={[1]={npc="斯普琳科", tgt="斯普琳科", desc="接受塔纳利斯。在辛特兰采集蘑菇。先到加基森交。"}, [2]={npc="斯普琳科", tgt="斯普琳科", desc="先上交斯普琳科的秘密佐料。"}, [3]={hint="斯普琳科让你把紫色粉末交给加基森的马林·诺格弗格。", desc="先上交斯普琳科的秘密佐料。"}, [4]={npc="马林·诺格弗格", tgt="马林·诺格弗格", desc="先上交斯普琳科的秘密佐料。"}, [5]={npc="马林·诺格弗格", tgt="马林·诺格弗格"}, [6]={hint="马林·诺格弗格让你在他制成药剂之后再去找他。"}, [7]={npc="马林·诺格弗格", tgt="马林·诺格弗格"}, [8]={hint="与加基森的炼金师匹斯特苏格谈一谈。", tag="可选", desc="在离开奥格瑞玛前往瓦罗莫克之前，请参阅 32 或 祖卡什报告 之后的 Zilzibin。"}, [9]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格", tag="可选"}, [10]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格", tag="可选", desc="首先交部落任务 异种蝎的远征。保留安戈洛的后续行动。"}, [11]={npc="特兰雷克", tgt="特兰雷克", desc="杀死安戈洛马绍尔营地路段上的焦油怪。"}, [12]={text="如果您有远古之卵，请在东边的热砂港处上交。否则直接向南前往破碎石柱。"}, [13]={npc="叶基亚", tgt="叶基亚", tag="可选", desc="接受塔纳利斯。获取彩蛋：辛萨罗。 叶基亚位于热砂港中。"}, [14]={npc="尤尔巴·斯库比格特", tgt="尤尔巴·斯库比格特", tag="可选", desc="于热砂港领取。在前往黑石深渊的路上，在烈焰峰处转车。"}, [15]={hint="到塔纳利斯找到玛尔冯·瑞文斯克。", desc="在怒痕堡环路之前的莫沙彻营地处接载。"}, [16]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克"}, [17]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克"}, [18]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", tag="可选", desc="先上交。如果您计划运行沉没的神庙，请在棘齿城中获取石环。"}, [19]={hint="塔纳利斯的玛尔冯·瑞文斯克要你收集30件加兹瑞迪安饰物。", desc="先在破碎石柱周围搜索，然后扫查周边。"}, [20]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克"}, [21]={hint="到棘齿城去，从玛尔冯·瑞文斯克的车间里取回石环。", tag="可选", desc="在稍后的任何棘齿城停靠站抓住它。"}, [22]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", tag="可选"}, [23]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", tag="可选", desc="仅在运行沉没的神庙时接受。"}, [24]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选", desc="在安戈洛的东南入口找到托尔瓦·寻路者。聚集在下一条腿上。"}, [25]={text="从破碎石柱沿塔纳利斯路向南行驶，然后向西进入安戈洛环形山。"}}},
    ["05-d23"] = {name="阿塔哈卡神庙", entrance="悲伤沼泽（1435）、69.50, 52.50。标记寺庙的外部。", pickup="在斯通纳德完成1424并保留阿塔莱流放者。从恶齿村步行到南部辛特兰的流放地。上交阿塔莱流放者并拿走1444和1446。如果你完成了祖尔法拉克平板电脑链，可以在辛萨罗获得鸡蛋。取菲拉斯中的沉没的神庙。在加基森和 Dunemaul 腿上，与 Marvon 一起开始石环任务，获取棘齿城中的物品，然后返回 Marvon 完成这两个神庙任务。在热砂港处交入鸡蛋。飞加基森→棘齿城，坐船到藏宝海湾，再飞到斯通纳德交1444，再乘1445进入。", pickupS={{"在斯通纳德完成1424并保留阿塔莱流放者"}, {"从恶齿村步行到南部辛特兰的流放地"}, {"上交阿塔莱流放者并拿走1444和1446"}, {"如果你完成了祖尔法拉克平板电脑链，可以在辛萨罗获得鸡蛋"}, {"取菲拉斯中的沉没的神庙"}, {"在加基森和 Dunemaul 腿上，与 Marvon 一起开始石环任务，获取棘齿城中的物品，然后返回 Marvon 完成这两个神庙任务"}, {"在热砂港处交入鸡蛋"}, {"飞加基森→棘齿城，坐船到藏宝海湾，再飞到斯通纳德交1444，再乘1445进入"}}, tips={{k="動線", text="走右边的入口路径到下环→检查祭坛，激活雕像并杀死阿塔拉利恩→清除六个上层阳台→从牺牲的坑向东前往Jammal'an→可选的哈卡事件向西→四个龙族→Eranikus和精华之泉。从阿塔莱巨魔手中掠夺神像。"}, {k="取捨", text="优先考虑斯通纳德和 Hinterlands 链。如果您已经运行过祖尔法拉克并访问过辛萨罗，请执行 Mosh'aru 链。在加基森和 Dunemaul 航段期间为石环计划一次棘齿城行程。"}, {k="說明", text="该图钉标记了泪水之池外部的建筑物。沿着南楼梯进入寺庙，经过面具大厅和仪式大厅，到达白骨大厅中层的门户。", s={{"该图钉标记了泪水之池外部的建筑物"}, {"沿着南楼梯进入寺庙，经过面具大厅和仪式大厅，到达白骨大厅中层的门户"}}}}, steps={[1]={npc="费泽鲁尔", tgt="费泽鲁尔", desc="如果您已经在主路线上这样做过，请从 阿塔莱流放者 开始。"}, [2]={hint="斯通纳德的费泽鲁尔要求你收集10件阿塔莱神器。"}, [3]={npc="费泽鲁尔", tgt="费泽鲁尔"}, [4]={npc="费泽鲁尔", tgt="费泽鲁尔", preText="泪水之池"}, [5]={hint="将一捆阿塔莱神器交给辛特兰的阿塔莱流放者。"}, [6]={npc="阿塔莱流放者", tgt="阿塔莱流放者"}, [7]={npc="阿塔莱流放者", tgt="阿塔莱流放者", preText="阿塔莱流放者"}, [8]={npc="阿塔莱流放者", tgt="阿塔莱流放者"}, [9]={hint="向斯通纳德的费泽鲁尔回报。"}, [10]={npc="费泽鲁尔", tgt="费泽鲁尔"}, [11]={npc="费泽鲁尔", tgt="费泽鲁尔", preText="向费泽鲁尔复命"}, [12]={npc="巫医尤克里", tgt="巫医尤克里"}, [13]={hint="到塔纳利斯找到玛尔冯·瑞文斯克。"}, [14]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克"}, [15]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", preText="沉没的神庙"}, [16]={hint="到棘齿城去，从玛尔冯·瑞文斯克的车间里取回石环。"}, [17]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克"}, [18]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", preText="石环"}, [19]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", preText="石环"}, [20]={npc="叶基亚", tgt="叶基亚", desc="在热砂港中拾取，然后执行菲拉斯。交完后取出摩沙鲁的预言。"}, [21]={hint="在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。"}, [22]={npc="叶基亚", tgt="叶基亚"}, [23]={npc="叶基亚", tgt="叶基亚", preText="尖啸者的灵魂"}, [24]={hint="将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。", desc="保存后续 远古之卵 来完成沉没神庙任务 神灵哈卡。"}, [25]={npc="叶基亚", tgt="叶基亚"}, [26]={npc="叶基亚", tgt="叶基亚", desc="辛萨罗有精英包。通过恶牙和辛萨罗任务来完成此操作。", preText="摩沙鲁的预言"}, [27]={hint="将远古之卵交给塔纳利斯的叶基亚。"}, [28]={npc="叶基亚", tgt="叶基亚"}, [29]={npc="叶基亚", tgt="叶基亚", preText="远古之卵"}, [30]={text="阿塔哈卡神庙 入口"}, [31]={hint="在悲伤沼泽沉没的神庙中找到哈卡祭坛。", desc="位置：下楼走右平路。找到戒指上的哈卡祭坛。顺序：在接受第 32 步之前，请到祭坛上交。", spot="下楼走右平路。找到戒指上的哈卡祭坛。"}, [32]={npc="哈卡祭坛", npcObj=true, tag="需要游戏内检查", spot="环廊下层的哈卡祭坛"}, [33]={hint="到沉没的神庙去，揭开雕像群中隐藏的秘密。", desc="使用正确的顺序以避免触发陷阱。位置：激活下环的六个雕像，然后杀掉中间的boss。顺序：南→北→西南→东南→西北→东北。", spot="激活下环的六个雕像，然后杀掉中间的boss。"}, [34]={npc="哈卡神像", npcObj=true, tag="需要游戏内检查", spot="下层中央的哈卡塑像"}, [35]={hint="收集20个哈卡神像，把它们带给斯通纳德的费泽鲁尔。", desc="位置：沿着下环和上阳台杀死阿塔莱巨魔。", spot="沿着下环和上阳台杀死阿塔莱巨魔。"}, [36]={hint="辛特兰的阿塔莱流放者要你给他带回迦玛兰的头。", desc="位置：清理掉上面的六个阳台，然后从牺牲坑里走东大厅。顺序：杀死所有六名阳台守卫以移除障碍物。", spot="清理掉上面的六个阳台，然后从牺牲坑里走东大厅。"}, [37]={hint="将装满的哈卡之卵交给塔纳利斯的叶基亚。", desc="走西边的通道到哈卡的房间。开始之前让所有人都进去。位置：从牺牲坑走西大厅。使用鸡蛋之前先分组。顺序：西厅：哈卡。东厅：Jamma'an。", spot="从牺牲坑走西大厅。使用鸡蛋之前先分组。"}, [38]={npc="伊兰尼库斯精华", npcObj=true, tag="需要游戏内检查", desc="杀死伊兰尼库斯的阴影并右键单击它的掉落物以开始任务。"}, [39]={hint="把伊兰尼库斯精华放在精华之泉里，精华之泉就在沉没的神庙中，伊兰尼库斯的巢穴里。", desc="位置：杀死四个龙族首领。使用梦想家房间中的字体。顺序：掠夺最终首领的精华。接受并在同一个房间上交。", spot="杀死四个龙族首领。使用梦想家房间中的字体。"}, [40]={npc="精华之泉", npcObj=true, tag="需要游戏内检查", spot="伊兰尼库斯房，尾王旁的精华之泉"}, [41]={npc="费泽鲁尔", tgt="费泽鲁尔"}, [42]={npc="阿塔莱流放者", tgt="阿塔莱流放者"}, [43]={npc="叶基亚", tgt="叶基亚"}}},
    ["04-41"] = {name="安戈洛环形山", nameA="安戈洛环形山 {a:541}", tips={{k="取捨", text="边走边收集能量水晶、恐龙零件、焦油和血瓣花花朵。留意火山口中部附近巡逻的魔龙。"}, {k="取捨", text="将 无人知晓的秘密 保存为冬泉谷和 火山的活动，将 玛尔冯的车间 保存为棘齿城。保存 拉克维的诱饵、三个塔、大猩猩、火羽山救援和结伴而行为马绍尔营地。"}, {k="取捨", text="如果您收集了 骨刃武器 的爪子，下次经过时，请在奥格瑞玛 (55.52, 34.08) 中交给杰斯雷蒙。如果你不想孵化蛋并与南方的boss战斗，请跳过捕捉皇后。"}, {k="提醒", text="还差54级？研磨北部的焦油怪（51.77, 25.14）或马绍尔营地东部的双齿龙（50.78, 19.90）。", s={{"还差54级？"}, {"研磨北部的焦油怪（51.77, 25.14）或马绍尔营地东部的双齿龙（50.78, 19.90）"}}}}, danger={[1]="54-55级精英魔龙在安戈洛巡逻。沿着东边向北扎营，与他们保持距离。"}, grind={[1]={mob="焦油潜伏者", note="营地以南的普通焦油怪。边走边拿起极度粘稠的沥青。一次将一名敌人从水边拉出来，并留意魔暴龙的巡逻。"}, [2]={mob="安戈洛大猩猩", note="东北洞穴外的正常大猩猩。与大猩猩任务配对。避免内部产生额外的拉力。如果外面很忙，请返回焦油坑。"}}, supply={[1]={npc="格莱菲"}, [2]={npc="吉波尔特"}, [3]={npc="奈尔加"}, [4]={npc="奈尔加"}}, steps={[1]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [2]={hint="找到拉克维刚刚猎杀的动物的尸体，从尸体上偷取一块蛇颈龙肉块，然后回到安戈洛环形山的托尔瓦·寻路者那里。"}, [3]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [4]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [5]={hint="将2份暴掠龙信息素交给安戈洛尔环形山入口附近的托尔瓦·寻路者。"}, [6]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [7]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", desc="保存返回安戈洛的马绍尔营地。"}, [8]={hint="将8只白色暴掠龙爪交给奥格瑞玛的杰斯雷蒙。", tag="可选", desc="仅当您在奥格瑞玛中领取时才在瓦罗莫克进行。"}, [9]={npc="破碎的木筏", npcObj=true}, [10]={hint="在池塘附近查找与搁浅的小艇有关的线索。"}, [11]={npc="小背包", npcObj=true}, [12]={npc="小背包", npcObj=true}, [13]={hint="查看袋子里的东西，然后将它们交给物主。", desc="保留袋子里的东西。"}, [14]={text="沿着东部边缘向北行驶至马绍尔营地。避开中间的魔暴龙。"}, [15]={nodeA="{a:541}", desc="解锁、飞行点和格莱菲。"}, [16]={npc="林克", tgt="林克"}, [17]={npc="林克", tgt="林克", desc="保存并在冬泉谷中交给多诺瓦。"}, [18]={npc="威利德·马绍尔", tgt="威利德·马绍尔"}, [19]={npc="斯巴克·尼米尔", tgt="斯巴克·尼米尔"}, [20]={npc="希兹尔", tgt="希兹尔"}, [21]={npc="拉瑞安", tgt="拉瑞安"}, [22]={npc="科琳", tgt="科琳"}, [23]={text="北部焦油暴徒→绕过营地→返回营地"}, [24]={hint="帮加基森的特兰雷克收集12块极度粘稠的沥青。", desc="在加基森 / 破碎石柱腿上拾取。"}, [25]={hint="将8根恐龙骨头交给安戈洛环形山的斯巴克·尼米尔。"}, [26]={hint="为马绍尔营地的希兹尔收集8块精细的双帆龙鳞片和8块精细的翼手龙鳞片。"}, [27]={hint="为马绍尔营地里的拉瑞安杀掉5个血瓣花鞭笞者、5个血瓣花捕兽者、5个血瓣花掠夺者和5个血瓣花猛击者。"}, [28]={hint="将食物箱和研究设备交给安戈洛环形山的威利德·马绍尔。"}, [29]={hint="到安戈洛环形山的火山中去，从那里的元素身上收集9份安戈洛灰烬，把它们交给棘齿城的莉芙·雷兹菲克斯。", desc="如果在瑟银哨塔之前在棘齿城中拾取，则做这个任务。打开棘齿城返回。"}, [30]={npc="被撕破的日记", npcObj=true, tag="可选", desc="从一滴开始。如果不掉落就继续移动。"}, [31]={hint="将日记还给安戈洛环形山中的威利德·马绍尔。", tag="可选", desc="从一滴开始。如果不掉落就继续移动。"}, [32]={npc="威利德·马绍尔", tgt="威利德·马绍尔", tag="可选", desc="从一滴开始。如果不掉落就继续移动。"}, [33]={hint="把一份格里什信息素和5份安戈洛的泥土样本交给加基森的炼金师匹斯特苏格。", tag="可选", desc="如果之前在塔纳利斯中接受，则做这个任务。出发前转一圈南线。"}, [34]={hint="收集红色能量水晶、蓝色能量水晶、黄色能量水晶和绿色能量水晶各7块，把它们交给马绍尔营地里的科琳。"}, [35]={npc="威利德·马绍尔", tgt="威利德·马绍尔"}, [36]={npc="斯巴克·尼米尔", tgt="斯巴克·尼米尔"}, [37]={npc="希兹尔", tgt="希兹尔"}, [38]={npc="拉瑞安", tgt="拉瑞安"}, [39]={npc="科琳", tgt="科琳"}, [40]={npc="科琳", tgt="科琳"}, [41]={npc="科琳", tgt="科琳"}, [42]={npc="科琳", tgt="科琳"}, [43]={npc="拉瑞安", tgt="拉瑞安", desc="在棘齿城上交。"}, [44]={text="从马绍尔营地飞往加基森并在那里交出任何采集任务。"}, [45]={npc="特兰雷克", tgt="特兰雷克"}, [46]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格", tag="可选"}, [47]={hint="收集一些血帽和格里什钉刺，然后向托尔瓦·寻路者复命。", tag="可选", desc="与南部蜂巢和花朵任务一起进行。"}, [48]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选"}, [49]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选", desc="使用任务物品并离开。你可以跳过精英。"}, [50]={hint="将魔暴龙之刺扎入一只魔暴龙的体内。", tag="可选", desc="使用任务物品并离开。你可以跳过精英。"}, [51]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选", desc="使用任务物品并离开。你可以跳过精英。"}, [52]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选", desc="组团参加下一次东部王国行程的沉没的神庙。", star={"斑白毛皮", {"DRUID"}}}, [53]={text="从加基森飞到棘齿城，再乘船到藏宝海湾，再转乘荒芜之地飞往卡加斯。在返回幽暗城的途中，将白暴掠龙爪子保存到奥格瑞玛中。"}}},
    ["04-42"] = {name="燃烧平原 黑石山", nameA="燃烧平原 {a:251}／黑石山", shortA="燃烧平原 {a:251} +", tips={{k="取捨", text="在卡加斯中拾取和机器的崛起。 解锁烈焰峰飞行点在循环巨槌石和索瑞森废墟之前。"}, {k="取捨", text="立即接受 菲诺克 并保存永望镇的上交。"}, {k="取捨", text="如果时间紧迫，请跳过 不和谐的烈焰 和 机器的崛起。它们需要进入黑石山或另一次荒芜之地运行。如果您运行的是黑石深渊，请单独进行后续操作。"}, {k="提醒", text="需要经验吗？杀死索瑞森废墟周围的黑铁矮人和傀儡。如果与团队一起运行黑石深渊，请先接卡加斯和烈焰峰中的地下城任务。", s={{"需要经验吗？"}, {"杀死索瑞森废墟周围的黑铁矮人和傀儡"}, {"如果与团队一起运行黑石深渊，请先接卡加斯和烈焰峰中的地下城任务"}}}}, danger={[1]="通往黑石深渊的采石场通道狭窄，征服者派隆在其中巡逻。在拉他之前清除入口处的普通小怪。", [2]="索瑞森废墟中的脚轮和巡逻人员可以齐心协力。从断墙外驶出，远离巡逻路口。"}, grind={[1]={mob="战争掠夺者", note="索瑞森废墟之外的普通傀儡。沿着外墙并计算废墟任务的击杀数。留意瓦砾中的脚轮。"}, [2]={mob="索瑞森驭火者", note="同一个废墟中的普通矮人。收集布料并计算击杀数。从断墙外拉，以避免增加脚轮和巡逻队。"}}, supply={[1]={npc="瓦格鲁克"}, [2]={npc="尤卡·斯库比格特"}, [3]={npc="格鲁纳"}, [4]={npc="旅店老板舒尔卡"}, [5]={npc="斯兰达"}, [6]={npc="格劳尔"}}, steps={[1]={npc="萨特拉克", tgt="萨特拉克", desc="接受卡加斯。在巨槌石向东转弯。"}, [2]={npc="塞朵拉·穆瓦丹尼", tgt="塞朵拉·穆瓦丹尼", desc="接受卡加斯。杀死燃烧平原中的傀儡和元素。"}, [3]={npc="桑德哈特", tgt="桑德哈特", tag="可选", desc="仅当您前往黑石山时才接受卡加斯。"}, [4]={text="如果解锁，请从卡加斯飞往烈焰峰。否则，取黑石山经灼热峡谷进入燃烧平原，然后沿北侧向东行驶。", tag="尚未解锁这个飞行点，第一次请走过去。"}, [5]={hint="到黑石山脉的采石场去干掉征服者派隆，然后向桑德哈特回报。", tag="可选", desc="留意地牢入口外的巡逻队。"}, [6]={nodeA="{a:251}", desc="解锁、飞行点和瓦格鲁克。"}, [7]={hint="与燃烧平原的尤卡·斯库比格特谈一谈。", tag="可选", desc="仅当您在塔纳利斯航段的热砂港中领取时才需上交。"}, [8]={npc="尤卡·斯库比格特", tgt="尤卡·斯库比格特", tag="可选"}, [9]={npc="麦克斯沃特·尤博格林", tgt="麦克斯沃特·尤博格林"}, [10]={npc="丁奇·斯迪波尔", tgt="丁奇·斯迪波尔"}, [11]={text="东边巨槌石→索瑞森废墟→卡加斯"}, [12]={hint="到燃烧平原去找到沙妮·长齿。"}, [13]={npc="沙妮·长齿", tgt="沙妮·长齿"}, [14]={npc="沙妮·长齿", tgt="沙妮·长齿"}, [15]={hint="从克罗格鲁尔手中拿回沙妮的鼻环，把它还给卡加斯的萨特拉克。搜寻巨槌石的每一处山洞和矿井。"}, [16]={hint="将龙灵采集器900型和8份雏龙精华交给燃烧平原烈焰峰的丁奇·斯迪波尔。", desc="首先使用任务物品。杀死目标并掠夺其留下的精华。"}, [17]={hint="把石板拓文交给燃烧平原的麦克斯沃特·尤博格林。"}, [18]={hint="到燃烧平原去为塞朵拉·穆瓦丹尼收集10块断裂的元素碎片。", desc="在与平板电脑相同的行程中杀死目标。"}, [19]={npc="麦克斯沃特·尤博格林", tgt="麦克斯沃特·尤博格林"}, [20]={npc="丁奇·斯迪波尔", tgt="丁奇·斯迪波尔"}, [21]={npc="丁奇·斯迪波尔", tgt="丁奇·斯迪波尔", desc="保存后转入永望镇中的菲诺克。"}, [22]={text="从烈焰峰飞往卡加斯。上交沙妮的鼻环和碎片。如果您已完成征服者派隆任务，请上交它。"}, [23]={npc="萨特拉克", tgt="萨特拉克"}, [24]={npc="塞朵拉·穆瓦丹尼", tgt="塞朵拉·穆瓦丹尼"}, [25]={npc="塞朵拉·穆瓦丹尼", tgt="塞朵拉·穆瓦丹尼", tag="可选", desc="向东只为黑石深渊后续。"}, [26]={hint="将元素碎片样本交给鲁特维尔·沃拉图斯。", tag="可选", desc="向东只为黑石深渊后续。"}, [27]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯", tag="可选", desc="向东只为黑石深渊后续。"}, [28]={npc="桑德哈特", tgt="桑德哈特", tag="可选"}, [29]={text="从卡加斯飞往幽暗城，然后穿过西瘟疫之地进入东瘟疫之地。"}}},
    ["05-d24"] = {name="黑石深渊", entrance="灼热峡谷（1427）、34.80, 85.30。标记为黑石山的方法。", pickup="解锁瑟银哨塔。在烈焰峰拜访 Yuka 和 Maxwort，然后飞往卡加斯寻找通缉海报桑德哈特和 Vivian。在黑石深渊外面杀死征服者派隆，然后返回卡加斯交出不和谐的烈焰并拿走不和谐的火焰和最后的元素。从瑟银哨塔或烈焰峰重新进入黑石山。", pickupS={{"解锁瑟银哨塔"}, {"在烈焰峰拜访 Yuka 和 Maxwort，然后飞往卡加斯寻找通缉海报桑德哈特和 Vivian"}, {"在黑石深渊外面杀死征服者派隆，然后返回卡加斯交出不和谐的烈焰并拿走不和谐的火焰和最后的元素"}, {"从瑟银哨塔或烈焰峰重新进入黑石山"}}, tips={{k="動線", text="外部可选征服者派隆→禁闭室和秩序竞技场中的铁怒矮人→黑铁砧中的Incendius→工艺之厅中的Fineous和暗炉钥匙中的纪念碑→金库中的心脏和Ribbly以及Grim Guzzler中的配方，按任意顺序→通过七号桥和熔岩桥前往熔核碎片。到处掠夺元素和傀儡。"}, {k="取捨", text="第一次运行时优先执行卡加斯和烈焰峰任务。如果有时间的话，可以去金库或者熔火之心入口。"}, {k="說明", text="从北侧进入黑石山。沿中央锁链下行，经过碾石场和征服者派隆，就能到达副本入口。也可从燃烧平原（29.40, 38.30）进山。", s={{"从北侧进入黑石山"}, {"沿中央锁链下行，经过碾石场和征服者派隆，就能到达副本入口"}, {"也可从燃烧平原（29.40, 38.30）进山"}}}}, steps={[1]={npc="尤卡·斯库比格特", tgt="尤卡·斯库比格特"}, [2]={npc="麦克斯沃特·尤博格林", tgt="麦克斯沃特·尤博格林", tag="可选", desc="收集 12 个古物宝库钥匙。仅当您的团队计划进行跳马时才选择。"}, [3]={npc="通缉", npcObj=true}, [4]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷"}, [5]={npc="桑德哈特", tgt="桑德哈特", desc="从北进入黑石山。 征服者派隆位于磨矿场。"}, [6]={hint="到黑石山脉的采石场去干掉征服者派隆，然后向桑德哈特回报。"}, [7]={npc="桑德哈特", tgt="桑德哈特"}, [8]={npc="桑德哈特", tgt="桑德哈特", preText="不和谐的烈焰"}, [9]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷", preText="不和谐的烈焰"}, [10]={npc="弗兰克罗恩·铸铁", tgt="弗兰克罗恩·铸铁", desc="以幽灵的身份前往黑石山的悬墓寻找 Forgewright。"}, [11]={hint="如果你想要得到进入这座城市主城区的钥匙，就去和弗兰克罗恩·铸铁谈一谈。", desc="该图钉标记了位于黑石山的 Franclorn 坟墓。作为幽灵来访。"}, [12]={npc="弗兰克罗恩·铸铁", tgt="弗兰克罗恩·铸铁"}, [13]={npc="弗兰克罗恩·铸铁", tgt="弗兰克罗恩·铸铁", preText="黑铁的遗产"}, [14]={npc="洛索斯·天痕", tgt="洛索斯·天痕", tag="可选", desc="55级以上。在经过七号到达熔火之心门户的路上做这个任务。"}, [15]={text="黑石深渊 入口"}, [16]={hint="到黑石深渊去消灭那些邪恶的侵略者！", desc="位置：进入禁闭室并清除秩序竞技场方向的守卫。", spot="进入禁闭室并清除秩序竞技场方向的守卫。"}, [17]={hint="进入黑石深渊并找到伊森迪奥斯。杀掉它，然后把你找到的信息汇报给桑德哈特。", desc="位置：沿着黑铁大道向下到达黑铁砧。杀死火烧迪斯。", spot="沿着黑铁大道向下到达黑铁砧。杀死火烧迪斯。"}, [18]={hint="杀掉弗诺斯·达克维尔并拿回战锤铁胆。把铁胆之锤拿到索瑞森神殿去，将其放在弗兰克罗恩·铸铁的雕像上。", desc="位置：在工艺之厅中获取锤子。把它带到索瑞森神殿。顺序：杀死弗诺斯·达克维尔，然后点击纪念碑。", spot="在工艺之厅中获取锤子。把它带到索瑞森神殿。"}, [19]={npc="弗兰克罗恩·铸铁的雕像", npcObj=true, tag="需要游戏内检查", spot="索瑞森神殿里的铸铁纪念碑"}, [20]={hint="前往黑石深渊，找回10份元素精华。你首先想到的是搜查魔像和魔像制造者。你还记得薇薇安·拉格雷含糊地提到过元素生物。", desc="位置：沿着黑铁大道杀死元素和傀儡。 征服者派隆在外面。", spot="沿着黑铁大道杀死元素和傀儡。 征服者派隆在外面。"}, [21]={hint="把雷布里的头颅交给燃烧平原的尤卡·斯库比格特。", desc="与酒桌旁的雷布里·斯库比格特交谈开始战斗。位置：越过暗炉城前往冷酷的酒鬼。在桌子旁边找到 Ribbly。", spot="越过暗炉城前往冷酷的酒鬼。在桌子旁边找到 Ribbly。"}, [22]={hint="把遗失的雷酒秘方交给卡加斯的薇薇安·拉格雷。", desc="在开始战斗之前，与你的团队一起清除酒吧周围的小怪。两个阵营都由同一敌人掉落秘方。位置：在冷酷酒鬼的后面房间打碎三个小桶，然后等待赫尔利。", spot="在冷酷酒鬼的后面房间打碎三个小桶，然后等待赫尔利。"}, [23]={hint="把山脉之心交给燃烧平原的麦克斯沃特·尤博格林。", tag="可选", desc="位置：打开黑 Vault 中的 12 个遗物保险箱，然后掠夺隐藏房间中的心。", spot="打开黑 Vault 中的 12 个遗物保险箱，然后掠夺隐藏房间中的心。"}, [24]={hint="进入黑石深渊，在通往熔火之心的传送门附近找到一块熔火碎片，然后回到黑石山脉的洛索斯·天痕那里。", tag="可选", desc="位置：经过七号桥并穿过熔岩桥。该片段来自核心门户。", spot="经过七号桥并穿过熔岩桥。该片段来自核心门户。"}, [25]={npc="桑德哈特", tgt="桑德哈特"}, [26]={npc="军官高图斯", tgt="军官高图斯"}, [27]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷"}, [28]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷"}, [29]={npc="尤卡·斯库比格特", tgt="尤卡·斯库比格特"}, [30]={npc="麦克斯沃特·尤博格林", tgt="麦克斯沃特·尤博格林", tag="可选"}, [31]={npc="洛索斯·天痕", tgt="洛索斯·天痕", tag="可选"}}},
    ["04-43"] = {name="东瘟疫之地 圣光之愿礼拜堂", tips={{k="取捨", text="解锁圣光之愿礼拜堂首次访问东瘟疫之地并在那里领取书籍。保存主要的提里奥、纳萨诺斯和达隆郡任务以供日后使用。"}, {k="取捨", text="任务奥古斯图斯的收据册是恐惧谷的绕道。如果您只是路过，请跳过它。如果视频显示教堂内有这本书，那就是《永远的任务 A Study of the Light》。"}, {k="提醒", text="54级以下？杀死圣光之愿外道路上的普通瘟疫小怪，或下一段费尔斯通农场（大约 38、56）处的普通不死生物。", s={{"54级以下？"}, {"杀死圣光之愿外道路上的普通瘟疫小怪，或下一段费尔斯通农场（大约 38、56）处的普通不死生物"}}}}, danger={[1]="当你寻找账本时，房子里和楼梯上的不死生物会聚集在一起。先把楼下清理干净。"}, grind={[1]={mob="腐肉虫", note="圣光之愿礼拜堂西南方向的普通腐肉幼虫。沿路一次拉一名敌人，并为提里奥收集腐肉虫肉片。避开北方的高级不死族群。"}, [2]={mob="毒性瘟疫蝙蝠", note="圣光之愿礼拜堂西侧空地中的普通蝙蝠。与瘟疫蝙蝠任务配对并返回补给。如果该地区繁忙，请向南移动。"}}, supply={[1]={npc="乔吉亚"}, [2]={npc="杰希卡·查伯斯"}, [3]={npc="工匠威尔海姆"}, [4]={npc="杰希卡·查伯斯"}, [5]={npc="护理者奥林"}}, steps={[1]={hint="将玛科里石板交给幽暗城的安德隆·甘特。", tag="可选"}, [2]={npc="安德隆·甘特", tgt="安德隆·甘特", tag="可选"}, [3]={text="从幽暗城外面向东穿过壁垒和西瘟疫之地。沿南路向东行驶，穿过东瘟疫之地，并远离斯坦索姆。"}, [4]={npc="被感动的奥古斯图斯", tgt="被感动的奥古斯图斯", tag="可选", desc="远离主干道。如果您仅解锁圣光之愿飞行点，请跳过。"}, [5]={hint="把奥古斯图斯的收据册交给恶蛛隧道中的被感动的奥古斯图斯。", tag="可选", desc="远离主干道。如果您仅解锁圣光之愿飞行点，请跳过。"}, [6]={npc="被感动的奥古斯图斯", tgt="被感动的奥古斯图斯", tag="可选", desc="远离主干道。如果您仅解锁圣光之愿飞行点，请跳过。"}, [7]={node="圣光之愿礼拜堂", desc="解锁、部落、飞行点和乔吉亚。"}, [8]={npc="书籍", tgt="詹妮亚·坎农", npcObj=true, desc="《永远的书》位于教堂的左后方。上交幽暗城。"}, [9]={hint="使用／收集：书籍"}, [10]={text="从圣光之愿礼拜堂飞往幽暗城。如果有图书馆任务，请上交。"}, [11]={npc="奥兰·斯内克威瑟", tgt="奥兰·斯内克威瑟", desc="奥兰与欧文·萨德（73.40, 33.00）都在幽暗城法师区；先依游戏的可交付提示。"}, [12]={hint="将你从沉没的神庙的巨魔身上得到的巫毒羽毛交给部落英雄的灵魂。", tag="可选、目标：加什尔 / 祖罗尔 / 加什尔 / 胡库 / 米杉 / 胡库 / 祖罗 / 洛若尔 / 洛若尔", desc="将此与沉没的神庙的其他悲伤沼泽任务一起带来。"}, [13]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选", desc="在北入口转入诅咒之地。 钻石水瓶是奖励选择。", star={"钻石水瓶", {"WARRIOR"}}}, [14]={hint="将摩弗拉斯的牙齿交给艾萨拉的奥汀克。他住在埃达拉斯废墟东北部悬崖的顶端。", tag="可选", desc="在斯通纳德组团获得沉没的神庙。找到摩弗拉斯，绿龙。"}, [15]={hint="从摩弗拉斯身上取回奥术碎片，然后返回大法师克希雷姆那儿。", tag="可选", desc="在斯通纳德组团获得沉没的神庙。找到摩弗拉斯，绿龙。"}, [16]={hint="将碧蓝钥匙交给乔拉齐·拉文霍德公爵。", tag="可选", desc="在斯通纳德组团获得沉没的神庙。找到摩弗拉斯，绿龙。"}, [17]={npc="乔拉齐·拉文霍德公爵", tgt="乔拉齐·拉文霍德公爵", tag="可选", desc="乘坐斯通纳德飞往塔伦米尔，然后在庄园转机。 乌黑面具是奖励选项。", star={"暗色蝠斗篷", {"ROGUE"}}}, [18]={hint="从沉没的神庙底部的守卫身上得到一些腐烂藤蔓，把它们交给托尔瓦·寻路者。", tag="可选", desc="组为沉没的神庙。告诉队伍你需要楼下的蛇雕像。"}, [19]={hint="前往沉没的阿塔哈卡神庙，杀死绿龙摩弗拉斯，将他的血液交给费伍德森林中的格雷塔·苔蹄。沉没的神庙的入口就在悲伤沼泽中。", tag="可选", desc="在斯通纳德组团获得沉没的神庙。找到摩弗拉斯，绿龙。"}, [20]={text="入住东部王国。下一站从幽暗城向东前往 Bulwark。"}}},
    ["04-44"] = {name="西瘟疫之地", nameA="西瘟疫之地 {a:813}", tips={{k="交通", text="步行至壁垒。向西前往提瑞斯法林地或幽暗城，然后在幽暗城外面乘坐齐柏林飞艇返回奥格瑞玛。"}, {k="取捨", text="费尔斯通农场大锅和包装位于同一个农场。回到城镇后，将 迟到总比不到好 和 杰雷米亚的忧伤 一起上交。"}, {k="取捨", text="现在做第一个大锅。将 目标：达尔松之泪 保存在达尔松之泪并将通灵学院任务保存在安多哈尔以进行下一个循环。返回西瘟疫之地时执行好运护符 ( / 两半合一)。"}, {k="提醒", text="55级以下？杀死费尔斯通农场周围的普通骷髅和食尸鬼（大约38、56）。避开安多哈尔的高层精英。", s={{"55级以下？"}, {"杀死费尔斯通农场周围的普通骷髅和食尸鬼（大约38、56）"}, {"避开安多哈尔的高层精英"}}}}, danger={[1]="召唤者阿拉基是安多哈尔中部的61级精英。标记塔楼时要呆在城镇边缘，并远离广场。"}, grind={[1]={mob="骷髅剥皮者", note="普通不死生物位于炼锅环费尔斯通农场处。驶出田野，远离建筑物，如果有任务者就继续前进。"}, [2]={mob="被奴役的食尸鬼", note="同一个农场的普通食尸鬼。在骷髅重生之间杀死他们。不要将小怪追赶到安多哈尔。"}}, supply={[1]={npc="银色黎明军需官哈萨娜"}, [2]={npc="迈克尔·加勒特"}, [3]={npc="旅店老板诺曼"}, [4]={npc="旅店老板诺曼"}, [5]={npc="艾林诺尔·拉斯克"}, [6]={npc="托马斯·莫丹"}, [7]={npc="艾泽基尔·格瑞乌斯"}}, steps={[1]={text="离开幽暗城，沿着东路穿过提瑞斯法林地到达壁垒 (83.13, 68.94)。请将幽暗城飞行点放在手边，以便在本段结束时进行城市任务交接。"}, [2]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", desc="从德林顿的箱子里取出瓶装火焰。也带上天灾战旗。"}, [3]={hint="到血色十字军建在费尔斯通农场和达尔松之泪之间的营地去，摧毁他们的指挥帐篷。", desc="燃烧帐篷里有瓶装火焰，然后使用旗帜。"}, [4]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", desc="燃烧帐篷里有瓶装火焰，然后使用旗帜。"}, [5]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [6]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [7]={hint="与西瘟疫之地亡灵壁垒的暗影牧师范蒂丝谈一谈。"}, [8]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [9]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [10]={text="从壁垒向东前往费尔斯通农场。获取瘟疫之锅样本，然后检查Janice的房子和马厩。"}, [11]={hint="到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。", desc="检查您是否有任务提供者提供的空瓶子。"}, [12]={npc="瘟疫之锅", npcObj=true}, [13]={npc="瘟疫之锅", npcObj=true, desc="收集样本，然后在同一个坩埚中接受返回任务。"}, [14]={npc="詹妮丝·费尔斯通", tgt="詹妮丝·费尔斯通"}, [15]={hint="这个女人的幽灵告诉你她要送出一只包裹。她说那只包裹就在她的马旁边。至于马在哪里或者包裹要送到哪里去，她却根本没有说。", desc="与马厩内的包裹互动。"}, [16]={npc="詹妮丝的包裹", npcObj=true}, [17]={npc="詹妮丝的包裹", npcObj=true, desc="选择部落任务迟到总比不到好。在这里收集包裹并在幽暗城上交。"}, [18]={text="从费尔斯通农场向东至达尔松之泪。现在就做农舍日记和钥匙吧。保存瘟疫之锅以供下次使用。"}, [19]={npc="达尔松夫人的日记", npcObj=true}, [20]={hint="完成任务目标。"}, [21]={npc="达尔松夫人的日记", npcObj=true}, [22]={npc="厕所", npcObj=true, desc="阅读日志，然后找到游荡的骷髅。打开外屋来生成农民。"}, [23]={hint="掉落自：游荡的骷髅", desc="阅读日志，然后找到游荡的骷髅。打开外屋来生成农民。"}, [24]={npc="厕所", npcObj=true, desc="阅读日志，然后找到游荡的骷髅。打开外屋来生成农民。"}, [25]={npc="锁住的柜橱", npcObj=true, desc="清理外屋周围。打开缓存并立即上交。"}, [26]={hint="掉落自：农夫达尔松", desc="清理外屋周围。打开缓存并立即上交。"}, [27]={npc="锁住的柜橱", npcObj=true, desc="清理外屋周围。打开缓存并立即上交。"}, [28]={text="绕安多哈尔一圈，参观每座塔楼，然后返回壁垒。等高级警卫巡逻走后，再靠近门口。"}, [29]={hint="使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。", desc="在门口使用手电筒。你可以把守卫留在里面。"}, [30]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [31]={hint="把费尔斯通农场的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"}, [32]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [33]={text="返回幽暗城并在公会注册处附近上交包裹。"}, [34]={hint="与幽暗城的皇家管理人巴哈乌斯协商，查找杰雷米亚·费尔斯通的下落。通常在公会注册处附近会有一个人口普查官。"}, [35]={npc="皇家管理人巴哈乌斯", tgt="皇家管理人巴哈乌斯"}, [36]={npc="皇家管理人巴哈乌斯", tgt="皇家管理人巴哈乌斯"}, [37]={hint="在幽暗城找到杰雷米亚·派森并查明他是否就是你要找的杰雷米亚·费尔斯通。如果他是的话，那么他可能会想要拿到詹妮丝·费尔斯通寄给他的包裹。"}, [38]={npc="杰雷米亚·派森", tgt="杰雷米亚·派森"}, [39]={npc="杰雷米亚·派森", tgt="杰雷米亚·派森", desc="保留半护身符。参观壁垒时，请在费尔斯通农场上交。"}, [40]={npc="哀恸骑士", tag="可选、需要游戏内检查", desc="幽暗城任务交接后，在登机前向西南方向看。骑士有多个重生点。"}, [41]={hint="Speak with the Knight of Mourning to learn more about his unfinished quest.", tag="可选、需要游戏内检查", desc="幽暗城任务交接后，在登机前向西南方向看。骑士有多个重生点。"}, [42]={npc="哀恸骑士", tag="可选、需要游戏内检查", desc="幽暗城任务交接后，在登机前向西南方向看。骑士有多个重生点。"}, [43]={npc="哀恸骑士", tag="可选、需要游戏内检查", desc="完成The Knight of Mourning。穿越到奥格瑞玛后运行黑喉要塞。保留提瑞斯法的圣物。", star={"Sword of Mourning", {"PALADIN"}}}, [44]={hint="将灵魂图腾所需的材料交给捕风者巴斯拉。", tag="可选", desc="在完成瘟疫之地农场任务时杀死蜘蛛、熊和秃鹰。"}, [45]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="飞往塔伦米尔，转机飞往巴斯拉，然后离开幽暗城。"}, [46]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="通过沉没的神庙组接受。完成下一次东部王国访问。", star={"被迷惑的水之魂", {"SHAMAN"}}}, [47]={text="从幽暗城外面的塔楼乘坐奥格瑞玛齐柏林飞艇。"}}},
    ["04-45"] = {name="费伍德森林 南段", nameA="费伍德森林 南段／{a:1997}", short="费伍德森林 南段 +", tips={{k="交通", text="解锁 Bloodvenom 现在发布并从那里出发进行下一站。如果经过碎木岗哨，请沿着联盟城镇及其守卫周围的主要道路行驶。"}, {k="取捨", text="杀死南部的朽木熊怪，开始赢得木喉声望。在一个循环中完成加德纳尔、南方传说任务和碧火月亮井。"}, {k="取捨", text="接受 净化费伍德 并向北收集血琥珀。为您下次南下旅行保留上交处。"}, {k="提醒", text="55级以下？杀死碎痕谷（大约 41、42）边缘的普通元素或枯木熊怪以获得木喉声望。", s={{"55级以下？"}, {"杀死碎痕谷（大约 41、42）边缘的普通元素或枯木熊怪以获得木喉声望"}}}}, danger={[1]="碎痕谷元素沿着坑成对生成。从坡道顶部拉出并远离底部，以避免下一个包。"}, grind={[1]={mob="热能野兽", note="碎痕谷周围的普通元素计入击杀任务。如果入口处很拥挤，请从边缘向内进行工作。"}, [2]={mob="热能恐兽", note="将高级普通元素与其他元素混合在同一地点。留意狭窄地形中成对的生成点。"}}, supply={[1]={npc="布拉卡尔"}, [2]={npc="奥索巴·狂怒图腾"}, [3]={npc="拜尔"}, [4]={npc="拜尔"}, [5]={npc="旅店老板凯利斯克"}, [6]={npc="旅店老板凯利斯克"}}, steps={[1]={npc="杰斯雷蒙", tgt="杰斯雷蒙", tag="可选", desc="接受瓦罗莫克。 农场白暴掠龙安戈洛的利爪。"}, [2]={text="飞往碎木岗哨，沿路向西行驶，然后沿北路进入费伍德森林。首先停在翡翠圣地。"}, [3]={npc="格拉兹", tgt="格拉兹"}, [4]={npc="梅贝丝·河风", tgt="梅贝丝·河风", desc="在北面收集血琥珀费伍德森林。接下来杀树人。折返南边。"}, [5]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [6]={npc="塔诺恩·红羽", tgt="塔诺恩·红羽"}, [7]={hint="格拉兹要你去杀死6个死木战士、6个死木探路者以及6个死木园丁。", desc="赢得木喉代表。如果仍然敌对，稍后再去北营地磨练。"}, [8]={npc="格拉兹", tgt="格拉兹"}, [9]={npc="格拉兹", tgt="格拉兹", desc="现在接受。在下一段路段的费伍德森林北端转入。"}, [10]={text="沿着主干道向北穿过加德纳尔到达血毒哨站。"}, [11]={nodeA="{a:1997}", desc="解锁、飞行点和布拉卡尔。"}, [12]={hint="到加德纳尔去杀掉4个加德纳尔恶犬、4个加德纳尔守护者、6个加德纳尔精兵和6个加德纳尔祭司，然后向费伍德森林的格雷塔·苔蹄复命。"}, [13]={npc="温娜·哈萨德", tgt="温娜·哈萨德"}, [14]={npc="德雷卡苏", tgt="德雷卡苏"}, [15]={text="沿着道路向北前往碎痕谷进行腐败调查。通过西部萨特月亮井和南部兽人营地循环回到翡翠圣地。"}, [16]={hint="杀掉2个热能野兽和2个热能恐兽，并探索碎痕谷。然后查看凹坑中是否仍然充满了堕落的恶臭之水，完成这些任务之后，向费伍德森林中的塔诺恩·红羽复命。", desc="也访问调查区域。仅杀死元素并不能完成它。"}, [17]={hint="从碧火萨特的月亮井中收集一份被腐化的水的样本，把它交给血毒哨所的温娜·哈萨德。", desc="这个月亮井和中央加德纳尔的月亮井是不同的目标。"}, [18]={hint="杀死主宰洛尔，把他的爪子交给费伍德森林血毒岗哨的德雷卡苏。", desc="目标在南营深处。拉动前请先清理坡道。"}, [19]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [20]={npc="塔诺恩·红羽", tgt="塔诺恩·红羽"}, [21]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", desc="下次访问时，请填补中央加德纳尔月亮井的空食堂。"}, [22]={text="返回血毒站交出水样和雷尔的爪子。如果需要的话重新进货。"}, [23]={npc="温娜·哈萨德", tgt="温娜·哈萨德"}, [24]={npc="德雷卡苏", tgt="德雷卡苏"}, [25]={npc="奥汀克", tgt="奥汀克", tag="可选", desc="在艾萨拉中先于费伍德森林转入奥汀克。 魔暴龙眼是奖励选项。", star={"魔暴龙眼", {"HUNTER"}}}, [26]={npc="大法师克希雷姆", tgt="大法师克希雷姆", tag="可选", desc="在费伍德森林之前转到艾萨拉的赛莱默。 火焰宝石是奖励选项。", star={"火焰宝石", {"MAGE"}}}, [27]={npc="万能的尼比", tgt="万能的尼比", tag="可选"}, [28]={hint="与费伍德森林的伊普斯谈一谈。", tag="可选"}, [29]={npc="伊普斯", tgt="伊普斯", tag="可选"}, [30]={npc="伊普斯", tgt="伊普斯", tag="可选", desc="首先获得加德纳尔精华。经奥格瑞玛飞往艾萨拉或经斯通纳德飞往诅咒之地。"}, [31]={npc="伊普斯", tgt="伊普斯", tag="可选", desc="如果您从培训师那里拿到了 小鬼的要求，请先将其上交，然后接受 奇怪的材料。"}, [32]={hint="将一块恶魔布交给费伍德森林的伊普斯。", tag="可选", desc="如果您从培训师那里拿到了 小鬼的要求，请先将其上交，然后接受 奇怪的材料。"}, [33]={npc="伊普斯", tgt="伊普斯", tag="可选", desc="如果您从培训师那里拿到了 小鬼的要求，请先将其上交，然后接受 奇怪的材料。"}, [34]={npc="伊普斯", tgt="伊普斯", tag="可选"}, [35]={hint="将10块腐烂的木头和4个血毒精华交给费伍德森林的伊普斯。", tag="可选"}, [36]={npc="伊普斯", tgt="伊普斯", tag="可选"}, [37]={npc="伊普斯", tgt="伊普斯", tag="可选", desc="如果您计划在东部王国路段期间运行沉没的神庙，请接受。", star={"灵魂收割者", {"WARLOCK"}}}, [38]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", tag="可选", desc="请参阅翡翠圣地的 Greta。 祝福珠串是奖励选择。", star={"祝福珠串", {"PRIEST"}}}}},
    ["04-46"] = {name="费伍德森林 木喉要塞", nameA="费伍德森林 {a:1997}至木喉要塞", shortA="费伍德森林 {a:1997} +", tips={{k="交通", text="在血毒哨所补给，然后沿着主路向北行驶。在隧道内的岔路口，从冬泉谷出口出去。"}, {k="取捨", text="在铁木森林北部一起做血琥珀和Irontree力量任务。最后杀死戴德伍德声望。"}, {k="取捨", text="如果完成，请保留 净化费伍德 的物品。在您下次访问翡翠圣地时提交。将 水之魂的帮助 保存为棘齿城。"}, {k="提醒", text="使用木喉要塞到达不友好的位置，安全通过隧道。如果仍然敌对或低于 56 级，请在死木村北部（大约 62、8）磨掉熊怪。", s={{"使用木喉要塞到达不友好的位置，安全通过隧道"}, {"如果仍然敌对或低于 56 级，请在死木村北部（大约 62、8）磨掉熊怪"}}}}, danger={[1]="如果你仍然对木喉要塞怀有敌意，隧道守卫可以拉团。在通过之前杀死外面的朽木熊怪直到不友好。"}, grind={[1]={mob="死木复仇者", note="北部的普通熊怪死木村。在木喉要塞之前研磨代表并收集羽毛。首先清理帐篷周围以避免添加。"}, [2]={mob="死木守卫", note="同一个村庄的主干道附近的普通熊怪。如果有代表小组的话，就在路边挑选单身人士。别管木喉守卫。"}}, supply={[1]={npc="布拉卡尔"}, [2]={npc="奥索巴·狂怒图腾"}, [3]={npc="拜尔"}, [4]={npc="拜尔"}}, steps={[1]={npc="温娜·哈萨德", tgt="温娜·哈萨德"}, [2]={npc="特鲁尔·法贝恩", tgt="特鲁尔·法贝恩", desc="杀死冬泉谷中的枭兽，然后在血毒哨所上交。"}, [3]={text="向南前往加德纳尔的中央月亮井，收集水并将其交给翡翠圣地。之后将小猫释放到碧火月亮井。"}, [4]={hint="把空壶拿到加德纳尔中心的月亮井去，装满井水之后再回到费伍德森林的格雷塔·苔蹄那里。"}, [5]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [6]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", desc="保存棘齿城以南的水之先知伊斯伦的上交。"}, [7]={hint="把温娜的小猫带到堕落的月亮井旁边，把猫放出来，然后把它还给温娜。", desc="和小猫一起散步。上交前，温娜点击它。"}, [8]={npc="温娜·哈萨德", tgt="温娜·哈萨德"}, [9]={text="从血毒哨站沿主干道向北行驶，穿过铁木森林和死木村。在木喉入口处找到纳菲恩。"}, [10]={hint="收集15颗血琥珀，把它们交给费伍德森林的梅贝丝·河风。", desc="当您下次访问南费伍德森林时，请为 Maybess 保存这些物品。"}, [11]={hint="菲拉斯莫沙彻营地的塔罗·刺蹄要你去费伍德森林杀掉12头怒爪灰熊和12头魔爪掠夺者。", tag="如果已经接受", desc="需要在莫沙彻营地取货。进去那里。"}, [12]={hint="沿着路去费伍德森林，和名叫纳菲恩的熊怪谈一谈。他站在木喉要塞的入口处。"}, [13]={npc="纳菲恩", tgt="纳菲恩"}, [14]={npc="纳菲恩", tgt="纳菲恩"}, [15]={hint="格拉兹要你去杀死6个死木守卫、6个死木复仇者和6个死木萨满祭司。", desc="在北营地后检查木喉代表。如果有敌意，则杀死戴德伍德直到不友善。"}, [16]={npc="纳菲恩", tgt="纳菲恩"}, [17]={npc="纳菲恩", tgt="纳菲恩", desc="从洞穴的冬泉谷出口出来，在外面找到萨尔法。"}, [18]={text="在与木喉要塞不友好处，进入隧道并从冬泉谷出口出去。避免攻击木喉熊怪。"}}},
    ["04-47"] = {name="冬泉谷", nameA="冬泉谷 {a:2255}", tips={{k="交通", text="解锁永望镇的飞行点并设置您的炉石。接下来飞往莫沙彻营地。如果其飞行点被锁定，请飞往乱风岗并沿路向西到达菲拉斯以将其解锁。"}, {k="取捨", text="在冰火温泉上交多诺瓦的任务并杀死枭兽。在同一个循环中执行永望镇雪人和奇美拉。"}, {k="取捨", text="尤西乌斯是精英，冬泉熊怪的活动 会带你回到西边的洞穴。如果您有团体或仍然需要经验，请执行这些操作。"}, {k="取捨", text="将永望镇报告和尼古拉斯公爵的书保存在您的任务日志中。在下一个东部王国循环中将两者都打开。"}, {k="提醒", text="56级以下？杀死永望镇以东的普通雪人（大约 64、40）或寒水村以外的熊怪。避开精英巡逻队。", s={{"56级以下？"}, {"杀死永望镇以东的普通雪人（大约 64、40）或寒水村以外的熊怪"}, {"避开精英巡逻队"}}}}, danger={[1]="尤西乌斯，一只精英碎齿熊，在永望镇以北巡逻。在碾压普通熊时与他保持距离。和一群人一起完成他的任务。", [2]="萨满和熊怪巡逻队可以在寒水村中齐心协力。如果你需要经验，干掉外面的孤独守卫。"}, grind={[1]={mob="冰蓟雪人", note="正常雪人位于永望镇以东，靠近补给处。边走边收集毛皮。如果洞口繁忙，就从山脚开始。"}, [2]={mob="冬泉巢穴守卫", note="寒水村之外的正常熊怪可获得木喉声望并掉落。避免精英巡逻队和内部连动的脚轮。"}}, supply={[1]={npc="尤格雷克"}, [2]={npc="旅店老板维兹奇"}, [3]={npc="尼克撒克"}, [4]={npc="旅店老板维兹奇"}, [5]={npc="维撒克"}}, steps={[1]={hint="穿过木喉要塞去冬泉谷。和萨尔法谈谈，他就在木喉要塞另一头的出口处。", tag="如果在 Bloodvenom Post/木喉要塞腿上接受"}, [2]={npc="萨尔法", tgt="萨尔法", tag="如果在 Bloodvenom Post/木喉要塞腿上接受"}, [3]={npc="萨尔法", tgt="萨尔法", tag="可选", desc="做在寒水村永望镇以东。下一次向西行驶前往隧道。"}, [4]={text="从隧道向南前往冰火温泉，接取多诺瓦的熊怪任务，然后前往西部的冬泉营地。"}, [5]={hint="把林克的剑交给冬泉谷的多诺瓦·雪山。", tag="如果在马绍尔营地腿上接受"}, [6]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", tag="如果在马绍尔营地腿上接受"}, [7]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", desc="在北边得到灵药菲拉斯。返回冰火温泉时上交。"}, [8]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [9]={hint="冬泉谷的多诺瓦·雪山要你去杀死8个冬泉探路者、8个冬泉巢穴守卫和8个冬泉图腾师。"}, [10]={npc="空的火酒瓶", npcObj=true, tag="如果掉落就接受", desc="右键单击空的火酒瓶启动链。 农场冬泉熊怪（如果需要）。"}, [11]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [12]={hint="将空的火酒瓶交给冬泉谷的多诺瓦·雪山。", tag="如果你有消防水瓶"}, [13]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", tag="如果你有消防水瓶"}, [14]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", desc="为下次北上费伍德森林之旅存钱。在朽木帐篷内找到大锅。"}, [15]={text="向东前往永望镇，并清除途中的两种枭兽。"}, [16]={nodeA="{a:2255}", desc="解锁、飞行点和尤格雷克。"}, [17]={text="将您的炉石与旅店老板维兹奇 (61.36, 38.83) 绑定。"}, [18]={hint="费伍德森林的特鲁尔·法贝恩要你去冬泉谷猎杀15头狂怒的枭兽和15头蓬毛枭兽。", tag="如果在 Bloodvenom Post/木喉要塞腿上接受", desc="保存好下次访问血毒哨站时的上交记录。"}, [19]={hint="把丁奇的信交给菲诺克。", tag="如果烈焰峰 / 黑石山支线接受"}, [20]={npc="菲诺克", tgt="菲诺克", tag="如果烈焰峰 / 黑石山支线接受"}, [21]={npc="菲诺克", tgt="菲诺克", tag="需要任务 菲诺克"}, [22]={npc="乌米", tgt="乌米"}, [23]={npc="格雷戈·格雷斯通", tgt="格雷戈·格雷斯通", desc="下次在 Bulwark 转向银色黎明军官加鲁什。"}, [24]={npc="格雷戈·格雷斯通", tgt="格雷戈·格雷斯通", desc="将圣光之愿礼拜堂的上交保存在东瘟疫之地中。"}, [25]={npc="杰希卡·雷德帕斯", tgt="杰希卡·雷德帕斯", desc="也带上永望镇报告。将其交到东瘟疫之地中的达隆郡处。"}, [26]={npc="斯托姆·影蹄", tgt="斯托姆·影蹄", tag="精英、可选"}, [27]={text="清理永望镇以东的雪人洞穴和周边区域，然后根据需要向北和向东循环。"}, [28]={hint="为永望镇的乌米收集10张厚雪人毛皮。", desc="为下一个任务带上雪人号角。在稍后的行程中领取 雪怪计划！。"}, [29]={npc="乌米", tgt="乌米"}, [30]={hint="将8支完整的冰风奇美拉角交给菲诺克。", tag="需要任务 菲诺克"}, [31]={npc="菲诺克", tgt="菲诺克", tag="需要任务 菲诺克"}, [32]={npc="菲诺克", tgt="菲诺克", tag="可选", desc="下次经过燃烧平原时向 Tinkee 报告。"}, [33]={hint="永望镇的斯托姆·影蹄想要你去杀死尤西乌斯。", tag="精英、可选", desc="56级精英组队。"}, [34]={npc="斯托姆·影蹄", tgt="斯托姆·影蹄", tag="精英、可选"}, [35]={hint="萨尔法要你去击杀8个冬泉萨满祭司、8个冬泉巢穴守卫，以及8个冬泉巨熊怪。萨尔法就在冬泉谷的木喉要塞入口外。", tag="返回洞口、可选"}, [36]={npc="萨尔法", tgt="萨尔法", tag="返回洞口、可选"}}},
    ["05-d25"] = {name="黑石塔下层", entrance="灼热峡谷（1427）、34.80, 85.30。标记为黑石山的方法。", pickup="解锁烈焰峰并在 55 级返回基布雷尔的两个任务。参见永望镇中的基尔拉姆。穿越到东部王国后，飞往卡加斯接受军官高图斯、神射手贾拉玛弗和雷克斯洛特的任务。从灼热峡谷或烈焰峰接近黑石山，并使用上东阳台上的共用入口。将 高图斯的命令 交入卡加斯中，然后取出并保留 伊崔格的智慧。", pickupS={{"解锁烈焰峰并在 55 级返回基布雷尔的两个任务"}, {"参见永望镇中的基尔拉姆"}, {"穿越到东部王国后，飞往卡加斯接受军官高图斯、神射手贾拉玛弗和雷克斯洛特的任务"}, {"从灼热峡谷或烈焰峰接近黑石山，并使用上东阳台上的共用入口"}, {"将 高图斯的命令 交入卡加斯中，然后取出并保留 伊崔格的智慧"}}, tips={{k="動線", text="下层入口→奥莫克→沃什加金→比修和她的物品走下坡道→沃恩→鸡蛋和烟网蛛后→哈雷肯和吉兹鲁尔→维姆萨拉克。掠夺奥莫克、沃恩和维姆萨拉克的宝石。"}, {k="取捨", text="优先考虑三个boss的文件，座狼，蛋，比修。如果有人可以打开上面的门，请跳过密封链。"}, {k="說明", text="较低的黑石塔在发布时即可使用。对于表面入口，使用燃烧平原 (29.40, 38.30)。沿着内侧的上坡路线到达东壁架。进去后往右走。", s={{"较低的黑石塔在发布时即可使用"}, {"对于表面入口，使用燃烧平原 (29.40, 38.30)"}, {"沿着内侧的上坡路线到达东壁架"}, {"进去后往右走"}}}}, steps={[1]={npc="基尔拉姆", tgt="基尔拉姆"}, [2]={npc="基布雷尔", tgt="基布雷尔"}, [3]={npc="基布雷尔", tgt="基布雷尔"}, [4]={npc="军官高图斯", tgt="军官高图斯", desc="如果没有任务窗口打开，请与 NPC 交谈并使用包里的命令。"}, [5]={npc="神射手贾拉玛弗", tgt="神射手贾拉玛弗"}, [6]={npc="雷克斯洛特", tgt="雷克斯洛特"}, [7]={text="黑石塔下层 入口"}, [8]={npc="裂盾渗透者", tgt="裂盾渗透者", tag="可选、需要游戏内检查", desc="57级以上。与上层阳台上的裂盾渗透者交谈：那是维埃兰。"}, [9]={hint="到黑石塔去查明比修的下落。", desc="位置：从沃什加金的房间走下坡道。在侧平台上寻找比修。", spot="从沃什加金的房间走下坡道。在侧平台上寻找比修。"}, [10]={npc="比修", tgt="比修", tag="需要游戏内检查", spot="沃什加斯房外大斜坡下，侧台的比修"}, [11]={npc="比修", tgt="比修", tag="需要游戏内检查", preText="狡猾的比修"}, [12]={hint="找到比修的装置并把它们还给她。你记得她说过她把装置藏在城市的最底层。", desc="位置：从比修的平台返回中心，然后搜索下层。", spot="从比修的平台返回中心，然后搜索下层。"}, [13]={npc="比修", tgt="比修", tag="需要游戏内检查", spot="比修所在的侧台"}, [14]={npc="比修", tgt="比修", tag="需要游戏内检查", preText="比修的装置"}, [15]={hint="到黑石塔去为基布雷尔收集15枚尖塔蜘蛛卵。", desc="位置：沿着网状隧道掠夺鸡蛋。首先清除每个离合器周围的蜘蛛。", spot="沿着网状隧道掠夺鸡蛋。首先清除每个离合器周围的蜘蛛。"}, [16]={hint="到黑石塔去杀死暗影猎手沃什加斯，将沃什加斯的菊石交给基尔拉姆。", desc="位置：经过 Omokk 并沿着隧道前往暗影猎手沃什加斯。顺序：杀死指挥官沃恩，然后走他房间里的坡道到比修。", spot="经过 Omokk 并沿着隧道前往暗影猎手沃什加斯。"}, [17]={hint="到黑石塔去找到血斧座狼幼崽。使用笼子来捕捉这些凶猛的小野兽，然后把笼中的座狼幼崽交给基布雷尔。", desc="告诉大家让一只座狼幼崽活着。让它远离 AoE。位置：经过蜘蛛和巨魔叉子，进入狼室并关进一只小狗。", spot="经过蜘蛛和巨魔叉子，进入狼室并关进一只小狗。"}, [18]={hint="杀死血斧座狼的领袖，哈雷肯。", desc="位置：在蜘蛛后面的岔路口向右走。从左边进入狼穴。", spot="在蜘蛛后面的岔路口向右走。从左边进入狼穴。"}, [19]={hint="杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。", desc="文档可以移动。当你到达前三个房间时，检查每个房间。文件可能出现在任一首领房间，逐间查看。位置：检查三个老板的房间和乌罗克的贡品堆中是否有文件。顺序：奥莫克 → 沃恩 → 维姆萨拉克。", spot="检查三个老板的房间和乌罗克的贡品堆中是否有文件。"}, [20]={hint="找到三块命令宝石：燃棘宝钻、尖石宝钻和血斧宝钻。把它们和原始晋升印章一起交给维埃兰。", tag="可选", desc="首先就宝石和封印战利品达成一致。对于 UBRS，只有一名玩家需要完成印章。文件可能出现在任一首领房间，逐间查看。位置：从每个老板那里掠夺一颗宝石。检查垃圾中是否有朴素的印章。顺序：奥莫克 → 沃恩 → 维姆萨拉克。", spot="从每个老板那里掠夺一颗宝石。检查垃圾中是否有朴素的印章。"}, [21]={npc="裂盾渗透者", tgt="裂盾渗透者", tag="可选、需要游戏内检查"}, [22]={npc="裂盾渗透者", tgt="裂盾渗透者", tag="可选、需要游戏内检查", preText="晋升印章"}, [23]={hint="把比修的侦查报告交给卡加斯的雷克斯洛特。"}, [24]={npc="军官高图斯", tgt="军官高图斯"}, [25]={npc="神射手贾拉玛弗", tgt="神射手贾拉玛弗"}, [26]={npc="雷克斯洛特", tgt="雷克斯洛特"}, [27]={npc="基布雷尔", tgt="基布雷尔"}, [28]={npc="基布雷尔", tgt="基布雷尔"}, [29]={npc="基尔拉姆", tgt="基尔拉姆"}, [30]={npc="军官高图斯", tgt="军官高图斯", desc="保存为奥格瑞玛。请参阅智慧谷中的伊崔格。", preText="高图斯的命令"}, [31]={hint="到尘泥沼泽中的巨龙沼泽去。找到上古老龙埃博斯塔夫，对他发起无情的攻击，直到他的意志被摧毁。", tag="可选", desc="精英团体。在控制龙之前停止伤害。"}, [32]={npc="裂盾渗透者", tgt="裂盾渗透者", tag="可选、需要游戏内检查", desc="在下层黑石塔入口内找到维埃兰。"}}},
    ["04-48"] = {name="菲拉斯（短访）", nameA="菲拉斯 {a:1099}（短访）", tips={{k="交通", text="飞行永望镇→莫沙彻营地→棘齿城。如果您要在藏宝海湾交船，请从棘齿城乘船。"}, {k="取捨", text="在莫沙彻营地和厄运之槌航段接受 堕落的力量，在费伍德森林中进行，然后在返回营地时将其上交。"}, {k="取捨", text="沿海任务位于营地西边。如果信标还没有掉落，就不要去找它。仅当您需要经验或计划参观双子巨像时才添加海岸。"}, {k="提醒", text="这里没有单独的级别目标。如果你仍然低于56级，请先完成下一站的任务交接，然后在小怪上赶上你的等级。", s={{"这里没有单独的级别目标"}, {"如果你仍然低于56级，请先完成下一站的任务交接，然后在小怪上赶上你的等级"}}}}, danger={[1]="在与被遗忘海岸的巨人战斗之前，对他们使用索尔宾的超级压缩器。等待水元素走开，一次拉一个。"}, grind={[1]={mob="北泉唤风者", note="如果你已经在北泉上交，清除外面的普通鹰身女妖以获得任务掉落。如果您距离下一个级别还很远，请在冬泉谷中进行磨练。"}, [2]={mob="冰蓟雪人", note="如果低于56，就在离开永望镇之前在这里磨。正常的雪人聚集在这里，外坡比洞口更容易拉动。"}}, supply={[1]={npc="夏恩"}, [2]={npc="旅店老板格鲁尔"}, [3]={npc="卡温德"}, [4]={npc="旅店老板格鲁尔"}, [5]={npc="卡温德"}, [6]={npc="塔霍斯"}}, steps={[1]={text="从永望镇飞往莫沙彻营地。交出您在莫沙彻营地和怒痕堡支线中拾取的费伍德森林支线任务。如果您拾到了视灵药剂，请向北行驶。"}, [2]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", tag="如果在血毒柱/ 木喉要塞腿上完成"}, [3]={text="如果你有 视灵药剂，沿着路向西走到岔路口，然后朝双子巨人和鸦风废墟走。"}, [4]={hint="去菲拉斯找格雷甘·山酒。从他那里问到获取视灵药剂的方法，然后向冬泉谷的多诺瓦·雪山复命。", tag="如果在永望镇中接受", desc="用 视灵药剂 获得格雷根的灵药。不要喝它。把它带到冬泉谷的多诺瓦。"}, [5]={text="仅访问被遗忘的海岸来完成可选任务。如果您有菲拉斯信标，请在途中接取深痕谷洞穴护卫。", tag="可选"}, [6]={npc="OOX-22/FE定位器", npcObj=true, tag="可选", desc="仅当您从暴徒手中抢夺定位器时才接。"}, [7]={hint="把定位器带到深痕谷附近山洞中的奥格索普的导航机器人旁边。", tag="可选", desc="仅当您从暴徒手中抢夺定位器时才接。"}, [8]={npc="自动导航机器人OOX-22/FE", tgt="自动导航机器人OOX-22/FE", tag="可选", desc="仅当您从暴徒手中抢夺定位器时才接。"}, [9]={npc="自动导航机器人OOX-22/FE", tgt="自动导航机器人OOX-22/FE", tag="可选", desc="留意伏击。如果您走棘齿城船路，请在藏宝海湾上交。"}, [10]={hint="将OOX-22/FE护送到被遗忘的海岸上的码头，然后向藏宝海湾的奥格索普·奥布诺提斯报告。", tag="可选", desc="留意伏击。如果您走棘齿城船路，请在藏宝海湾上交。"}, [11]={npc="索尔宾·范达瑟", tgt="索尔宾·范达瑟", tag="可选"}, [12]={npc="索尔宾·范达瑟", tgt="索尔宾·范达瑟", tag="可选"}, [13]={hint="使用索尔宾的超级压缩器，把菲拉斯的任意巨人缩小到便于对付的体型。从缩小后的巨人身上收集15份微缩残渣，交给菲拉斯被遗忘的海岸码头上的索尔宾·范达瑟。", tag="可选", desc="缩小在杀死巨人之前先杀死他们，否则他们不会掉落任务物品。"}, [14]={npc="索尔宾·范达瑟", tgt="索尔宾·范达瑟", tag="可选"}, [15]={hint="从菲拉斯被遗忘的海岸那里的海元素和巨型海元素身上获取10块水元素核心，把它们交给码头附近的索尔宾·范达瑟。", tag="可选"}, [16]={npc="索尔宾·范达瑟", tgt="索尔宾·范达瑟", tag="可选"}, [17]={text="返回莫沙彻营地并飞往棘齿城。如果您已完成 拯救OOX-22/FE！ 并想要将其交还，请乘船前往藏宝海湾并返回。否则，请在棘齿城中提交任务。"}}},
    ["04-49"] = {name="贫瘠之地（短访）", nameA="贫瘠之地 {a:392}（短访）", tips={{k="交通", text="从棘齿城飞往奥格瑞玛，然后乘坐城外的幽暗城齐柏林飞艇。在提瑞斯法林地中，沿路向东前往壁垒。"}, {k="取捨", text="如果完成，请将安戈洛灰烬和工坊任务交给丽芙。从海岸的伊斯伦领取费伍德森林的信。"}, {k="取捨", text="如果您没有棘齿城任务交接，请直接从菲拉斯飞往奥格瑞玛并乘坐齐柏林飞艇。"}, {k="提醒", text="棘齿城怪物等级较低。低于56？在占领齐柏林飞艇之前杀死永望镇以东（大约 64、40）的普通雪人，或者在壁垒腿上的费尔斯通农场（大约 38、56）处杀死普通不死生物。", s={{"棘齿城怪物等级较低"}, {"低于56？"}, {"在占领齐柏林飞艇之前杀死永望镇以东（大约 64、40）的普通雪人，或者在壁垒腿上的费尔斯通农场（大约 38、56）处杀死普通不死生物"}}}}, grind={[1]={mob="骷髅巫师", note="棘齿城仅用于任务交接和运输。如果低于 56，乘坐飞艇并杀死费尔斯通农场处的普通骷髅。从场地边缘驶出并避开猩红巡逻队。"}}, supply={[1]={npc="布拉高克"}, [2]={npc="旅店老板维尔雷"}, [3]={npc="格拉利克斯"}, [4]={npc="旅店老板维尔雷"}, [5]={npc="加吉克"}, [6]={npc="霍苏斯"}}, steps={[1]={npc="奥格索普·奥布诺提斯", tgt="奥格索普·奥布诺提斯", tag="如果通过藏宝海湾乘船、可选"}, [2]={text="在棘齿城交任务，然后沿着海岸向南到达水之先知伊斯伦。"}, [3]={npc="莉芙·雷兹菲克斯", tgt="莉芙·雷兹菲克斯", tag="如果您收集了马绍尔营地腿上的所有灰烬"}, [4]={hint="到棘齿城去，在玛尔冯·瑞文斯克的车间里找到他。", tag="如果在马绍尔营地腿上接受"}, [5]={npc="莉芙·雷兹菲克斯", tgt="莉芙·雷兹菲克斯", tag="如果在马绍尔营地腿上接受"}, [6]={hint="把腐化的月亮井水交给贫瘠之地的水之先知伊斯伦。", tag="如果在 Bloodvenom Post/木喉要塞腿上接受"}, [7]={npc="水之先知伊斯伦", tgt="水之先知伊斯伦", tag="如果在 Bloodvenom Post/木喉要塞腿上接受"}, [8]={npc="水之先知伊斯伦", tgt="水之先知伊斯伦", tag="需要任务 水之魂的帮助", desc="稍后将给 Greta 的纯净水保存在翡翠圣地处。"}, [9]={text="从棘齿城飞往奥格瑞玛并乘坐提瑞斯法林地齐柏林飞艇。抵达后，沿东路前往 Bulwark。"}}},
    ["04-50"] = {name="西瘟疫之地", tips={{k="交通", text="第 1 步，从齐柏林飞艇塔前往壁垒。经过盖罗恩农场后，沿主路向东行驶至东瘟疫之地。"}, {k="取捨", text="按顺序做大锅任务。在通过扭动鬼影缠身的同时完成两项野生动物任务。"}, {k="取捨", text="保存 返回亡灵壁垒 给壁垒。在圣光之愿礼拜堂腿上做 瘟疫与你 并在壁垒处将其转回。"}, {k="提醒", text="继续到 56-57 级范围内的圣光之愿礼拜堂。在收集骸骨碎片之前，先在壁垒处拾取 。如果你想要自己的通灵学院钥匙，请上交它，拿走 昂贵的模具，并在进入安戈洛之前将 2 个瑟银锭带到加基森处。", s={{"继续到 56-57 级范围内的圣光之愿礼拜堂"}, {"在收集骸骨碎片之前，先在壁垒处拾取"}, {"如果你想要自己的通灵学院钥匙，请上交它，拿走 昂贵的模具，并在进入安戈洛之前将 2 个瑟银锭带到加基森处"}}}}, danger={[1]="猩红巡逻队在达尔松之泪北部巡逻。从场地边缘拉出骷髅，同时收集大锅材料。不要从营地向北走。"}, grind={[1]={mob="恐惧骸骨", note="在大锅循环中杀死达尔松之泪处的普通骷髅以获得骸骨碎片。呆在外面，注意北方的猩红巡逻队。"}, [2]={mob="冰冷的食尸鬼", note="扭动鬼影缠身附近的普通食尸鬼已经达到了不错的等级，正在前往下一个坩埚的路上。从场地边缘开始，以避免拥挤的门口。"}}, supply={[1]={npc="银色黎明军需官哈萨娜"}}, steps={[1]={text="从棘齿城飞往奥格瑞玛，然后乘坐齐柏林飞艇前往提瑞斯法林地。从幽暗城外沿着主干道向东前往 Bulwark。"}, [2]={hint="把永望镇报告送给西瘟疫地亡灵壁垒的银色黎明军官加鲁什。"}, [3]={npc="银色黎明军官加鲁什", tgt="银色黎明军官加鲁什"}, [4]={npc="米克·莱文", tgt="米克·莱文"}, [5]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [6]={hint="和西瘟疫之地亡灵壁垒的药剂师迪瑟斯谈一谈。"}, [7]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [8]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [9]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [10]={hint="到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带达尔松之泪的空瓶来采集瘟疫之锅中的毒药样本。", desc="清除大锅周围的正常不死生物。生成守护者的方法。"}, [11]={npc="瘟疫之锅", npcObj=true}, [12]={npc="瘟疫之锅", npcObj=true}, [13]={hint="把装满的达尔松眼泪之瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"}, [14]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [15]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [16]={hint="到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带嚎哭鬼屋的空瓶来采集瘟疫之锅中的毒药样本。", desc="清除大锅周围的正常不死生物。生成守护者的方法。"}, [17]={npc="瘟疫之锅", npcObj=true}, [18]={npc="瘟疫之锅", npcObj=true}, [19]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [20]={hint="消灭8只生病的狼，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。"}, [21]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [22]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [23]={hint="消灭8只生病的灰熊，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。"}, [24]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [25]={hint="将15块骸骨碎片交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。", desc="在两个坩埚环上收集。将样品交给壁垒。"}, [26]={hint="把嚎哭鬼屋的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"}, [27]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [28]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [29]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [30]={hint="到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。", desc="清除大锅周围的正常不死生物。生成守护者的方法。"}, [31]={npc="瘟疫之锅", npcObj=true}, [32]={npc="瘟疫之锅", npcObj=true}, [33]={hint="将巫毒羽毛交给捕风者巴斯拉。", tag="可选、目标：加什尔 / 祖罗尔 / 加什尔 / 胡库 / 米杉 / 胡库 / 祖罗 / 洛若尔 / 洛若尔", desc="从幽暗城飞往斯通纳德与您的团队会合。"}, [34]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="转向奥特兰克的巴斯拉。 被迷惑的水之魂是奖励选择。", star={"被迷惑的水之魂", {"SHAMAN"}}}, [35]={hint="到沉没的神庙去，从巨魔们身上获得6支巫毒羽毛。", tag="可选、目标：加什尔 / 祖罗尔 / 加什尔 / 胡库 / 米杉 / 胡库 / 祖罗 / 洛若尔 / 洛若尔", desc="从幽暗城飞往斯通纳德。将伊普斯的上交保存为铁木森林。"}}},
    ["04-51"] = {name="东瘟疫之地", tips={{k="交通", text="交回尼古拉斯·瑟伦霍夫公爵并拿起达隆郡的保卫者，然后解锁教堂飞行点。最后一步，飞往幽暗城并转乘飞艇。"}, {k="取捨", text="返回壁垒时上交 瘟疫与你 和 玛莱恩姑妈。"}, {k="取捨", text="暗翼蝠是东瘟疫之地中的精英巡逻队。跳过暗翼蝠 ，如视频所示。"}, {k="取捨", text="如果您赶时间，请跳过 哈米亚的请求。它会将您传送到地穴和祖玛沙尔之间。对于 遗忘的记忆，点击坟墓泥土会产生一群雇佣兵。"}, {k="提醒", text="经验落后？杀死病木林边缘的普通蝙蝠、猎犬和食尸鬼（29、28 左右）。您可以等到乱羽高地赛段之前达到 57。", s={{"经验落后？"}, {"杀死病木林边缘的普通蝙蝠、猎犬和食尸鬼（29、28 左右）"}, {"您可以等到乱羽高地赛段之前达到 57"}}}}, danger={[1]="更高级别的缝合憎恶和巡逻队在病木林的斯坦索姆一侧漫游。收集白蚁或杀死食尸鬼时要靠近边缘。"}, grind={[1]={mob="吃人的食尸鬼", note="病木林之外的普通亡灵。与对居民灵魂的追求相结合。避免更高级别的缝合憎恶和巡逻。"}, [2]={mob="狂怒的瘟疫犬", note="正常的瘟疫猎犬在同一区域的道路上。它们的水平很好，很容易在空旷的地方拉动。如果不死族忙的话就切换到外循环。"}}, supply={[1]={npc="乔吉亚"}, [2]={npc="杰希卡·查伯斯"}, [3]={npc="工匠威尔海姆"}, [4]={npc="杰希卡·查伯斯"}, [5]={npc="护理者奥林"}}, steps={[1]={text="穿过西部边境，沿着索多里尔河找到提里奥。接受他的任务，然后向南前往主干道。"}, [2]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [3]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [4]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [5]={npc="纳萨诺斯·凋零者", tgt="纳萨诺斯·凋零者"}, [6]={npc="纳萨诺斯·凋零者", tgt="纳萨诺斯·凋零者"}, [7]={hint="在达隆郡里找到帕米拉·雷德帕斯。"}, [8]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [9]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [10]={hint="找到帕米拉的洋娃娃。", desc="先清理入口。当你抢劫零件时，幽灵可能会出现。"}, [11]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [12]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [13]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [14]={hint="到东边的考林路口去屠杀镇里的亡灵天灾。在10分钟内收集7块生命腐质，使用研钵和捣杵将其研磨成凝固腐质。", desc="腐烂持续约10分钟。一旦够了就当场研磨。"}, [15]={hint="找到卡林·瑞德巴思。"}, [16]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯"}, [17]={hint="将《灵语研究》这本书交给东瘟疫之地圣光之愿礼拜堂的尼古拉斯·瑟伦霍夫公爵。"}, [18]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵"}, [19]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯"}, [20]={text="如果需要，解锁圣光之愿礼拜堂和乔吉亚 (70.53, 47.55)。然后向北绕一圈穿过病木林。"}, [21]={hint="在东瘟疫之地的蚁丘上使用空的白蚁瓶。当你收集了100只瘟疫白蚁之后，就回到提瑞斯法林地的亡灵壁垒去找米克·莱文。", desc="检查病木林边缘的白蚁丘。通过斯坦索姆避开精英。"}, [22]={hint="杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。"}, [23]={hint="杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。"}, [24]={hint="在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。"}, [25]={hint="杀掉20只毒性瘟疫蝙蝠和10只巨型瘟疫蝙蝠，然后回到纳萨诺斯·凋零者那里。"}, [26]={hint="释放15个达隆郡居民的灵魂，然后返回卡林·雷德帕斯身边。", desc="击杀后点击每个生成的灵魂。光是杀戮是不算数的。"}, [27]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯"}, [28]={npc="纳萨诺斯·凋零者", tgt="纳萨诺斯·凋零者"}, [29]={npc="纳萨诺斯·凋零者", tgt="纳萨诺斯·凋零者"}, [30]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [31]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [32]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [33]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="完成提里奥的三项狩猎任务即可解锁这一任务。"}, [34]={hint="听听提里奥·弗丁要说什么。", desc="完成提里奥的三项狩猎任务即可解锁这一任务。"}, [35]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="完成提里奥的三项狩猎任务即可解锁这一任务。"}, [36]={text="环路结束后，从圣光之愿礼拜堂飞往幽暗城，然后乘坐奥格瑞玛齐柏林飞艇。"}}},
    ["05-d27"] = {name="斯坦索姆 亡灵区", entrance="东瘟疫之地（遗失的补给品）、亡灵侧门，约43.50, 19.40。", pickup="访问圣光之愿礼拜堂的 Betina、Leonid 和护理者奥林。向西行驶，在恐惧谷中看到埃根，然后从侧门进入。如果您的小组已从前门清除，请保存本次运行的后续 活跃的探子。", pickupS={{"访问圣光之愿礼拜堂的 Betina、Leonid 和护理者奥林"}, {"向西行驶，在恐惧谷中看到埃根，然后从侧门进入"}, {"如果您的小组已从前门清除，请保存本次运行的后续 活跃的探子"}}, tips={{k="動線", text="服务门→教堂中的奥里克斯→三座神塔中的安娜丝塔丽男爵夫人、奈鲁布恩坎和Maleki。检查数据→屠宰场的吞咽者拉姆斯登→瑞文戴尔男爵，然后与奥里克斯交谈。途中掠夺肉体和神圣水以及免费的光谱公民。"}, {k="取捨", text="一次收集神圣水的肉体、埃根的灵魂。如果只做一个机翼，请跳过首先需要信仰奖章的奥里克斯链。"}, {k="說明", text="五人地下城。为仆从入口带来城市大门钥匙。第一次跑步时，从前门进去，从巴瑟拉斯那里拿到钥匙。", s={{"五人地下城"}, {"为仆从入口带来城市大门钥匙"}, {"第一次跑步时，从前门进去，从巴瑟拉斯那里拿到钥匙"}}}, {k="提醒", text="五人地下城。为仆从入口带来城市大门钥匙。第一次跑步时，从前门进去，从巴瑟拉斯那里拿到钥匙。", s={{"五人地下城"}, {"为仆从入口带来城市大门钥匙"}, {"第一次跑步时，从前门进去，从巴瑟拉斯那里拿到钥匙"}}}}, steps={[1]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克", desc="如果您已上交此内容，请在此运行中接受 活跃的探子。"}, [2]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克", desc="先上交血肉不会撒谎。如果尚未解锁，请将其保存以供下次运行。", preText="血肉不会撒谎"}, [3]={npc="莱尼德·巴萨罗梅", tgt="莱尼德·巴萨罗梅"}, [4]={npc="护理者奥林", tgt="护理者奥林"}, [5]={hint="找到埃根。你只知道他在斯坦索姆附近。"}, [6]={npc="埃根", tgt="埃根"}, [7]={npc="埃根", tgt="埃根", desc="获取埃根的冲击器。", preText="永不安息的灵魂"}, [8]={text="斯坦索姆 亡灵区 入口"}, [9]={hint="从斯坦索姆找回20个瘟疫肉块，并把它们交给贝蒂娜·比格辛克。你觉得斯坦索姆中的生灵都不大可能长着肉……", desc="位置：进入服务门并从街道上的不死生物身上掠夺血肉。", spot="进入服务门并从街道上的不死生物身上掠夺血肉。"}, [10]={hint="到斯坦索姆去探索那里的通灵塔。找到新的天灾军团档案，把它交给贝蒂娜·比格辛克。", desc="位置：搜索所有三个金字形神塔。数据位于其中一个的一个小盒子中。顺序：击败守卫入口的头目后检查每个塔。", spot="搜索所有三个金字形神塔。数据位于其中一个的一个小盒子中。"}, [11]={hint="到北方的斯坦索姆去，寻找散落在城市中的补给箱，并收集5瓶斯坦索姆圣水。当你找到足够的圣水之后就回去向莱尼德·巴萨罗梅复命。", desc="位置：检查街道沿线的木制补给箱。先清除附近的小怪。", spot="检查街道沿线的木制补给箱。先清除附近的小怪。"}, [12]={hint="对斯坦索姆城中的鬼魂使用埃根的冲击器。当那些永不安息的灵魂挣脱他们的外壳时，再次使用埃根的冲击器——他们就可以获得自由了！", desc="位置：找到幽灵公民并对每个目标使用冲击波两次。", spot="找到幽灵公民并对每个目标使用冲击波两次。"}, [13]={npc="奥里克斯", tgt="奥里克斯", tag="需要游戏内检查", desc="从玛洛尔的保险箱中拾取奖章，然后前往服务门教堂。"}, [14]={hint="使用／收集：玛洛尔的保险箱", desc="位置：进入服务门。寻找入口处燃烧的教堂。", spot="进入服务门。寻找入口处燃烧的教堂。"}, [15]={npc="奥里克斯", tgt="奥里克斯", tag="需要游戏内检查", spot="亡灵区入口旁的燃烧小教堂"}, [16]={npc="奥里克斯", tgt="奥里克斯", tag="需要游戏内检查", desc="在与瑞文戴尔男爵战斗之前给他奖章并接受任务。", preText="信仰奖章"}, [17]={hint="完成任务目标。", desc="击败后在同一房间与奥里克斯交谈。位置：清除金字形神塔和屠宰场。在瑞文戴尔的房间里找到奥里克斯。顺序：击杀后，在同一个房间找到奥里克斯。", spot="清除金字形神塔和屠宰场。在瑞文戴尔的房间里找到奥里克斯。"}, [18]={npc="奥里克斯", tgt="奥里克斯", tag="需要游戏内检查", desc="完成时奥里克斯会移到尾王房间；接取仍在亡灵区入口旁的小教堂。", spot="瑞文戴尔房，奥里克斯会移到房内"}, [19]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克"}, [20]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克"}, [21]={npc="莱尼德·巴萨罗梅", tgt="莱尼德·巴萨罗梅"}, [22]={npc="埃根", tgt="埃根"}}},
    ["05-d26"] = {name="斯坦索姆 血色区", entrance="东瘟疫之地 (遗失的补给品)，主门户，关于27.10, 10.70。", pickup="在圣光之愿礼拜堂参观公爵和烟雾缭绕，然后沿着西北主干道到达前门。对于提里奥的画，先完成狩猎任务。继续穿过南部的地窖和北部的山谷，在凯尔达隆上见到画家，然后返回东瘟疫之地。", pickupS={{"在圣光之愿礼拜堂参观公爵和烟雾缭绕，然后沿着西北主干道到达前门"}, {"对于提里奥的画，先完成狩猎任务"}, {"继续穿过南部的地窖和北部的山谷，在凯尔达隆上见到画家，然后返回东瘟疫之地"}}, tips={{k="動線", text="正门→市场区烟草店→血色十字军堡垒。如果需要，请跳过炮手威利。在档案管理员加尔福特的房间里，取回画作并烧毁记录。击杀巴纳扎尔即可完全通关。"}, {k="取捨", text="接起烟草和档案任务。如果您已经完成了提里奥的早期链条，请添加爱与家庭。如果您只想运行一次，请在开始之前先了解先决条件。"}, {k="說明", text="五人地下城。带上坚城门的猩红钥匙。 58级以下，接任务然后组队。使用仆从入口作为不死之翼。", s={{"五人地下城"}, {"带上坚城门的猩红钥匙"}, {"58级以下，接任务然后组队"}, {"使用仆从入口作为不死之翼"}}}, {k="提醒", text="五人地下城。带上坚城门的猩红钥匙。 58级以下，接任务然后组队。使用仆从入口作为不死之翼。", s={{"五人地下城"}, {"带上坚城门的猩红钥匙"}, {"58级以下，接任务然后组队"}, {"使用仆从入口作为不死之翼"}}}}, steps={[1]={npc="烟鬼拉鲁恩", tgt="烟鬼拉鲁恩"}, [2]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵", desc="在同一回合中杀死档案管理员并烧毁记录。"}, [3]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="可选的提里奥链条。如果在圣光之愿礼拜堂腿上完成，则跳过。"}, [4]={hint="杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。"}, [5]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [6]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="可选的提里奥链条。如果在圣光之愿礼拜堂腿上完成，则跳过。"}, [7]={hint="杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。"}, [8]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [9]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="可选的提里奥链条。如果在圣光之愿礼拜堂腿上完成，则跳过。"}, [10]={hint="在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。"}, [11]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [12]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="可选的提里奥链条。如果在圣光之愿礼拜堂腿上完成，则跳过。", preText="恶魔之犬、血染的天空、腐肉虫"}, [13]={hint="听听提里奥·弗丁要说什么。"}, [14]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [15]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="可选的提里奥链条。如果在圣光之愿礼拜堂腿上完成，则跳过。", preText="救赎"}, [16]={hint="到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。"}, [17]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [18]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="可选的提里奥链条。如果在圣光之愿礼拜堂腿上完成，则跳过。", preText="遗忘的记忆"}, [19]={hint="到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。"}, [20]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [21]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="可选的提里奥链条。如果在圣光之愿礼拜堂腿上完成，则跳过。", preText="失落的荣耀"}, [22]={hint="到凯尔达隆岛去，寻找关于那副画的线索。凯尔达隆岛在瘟疫之地南部的湖中央。"}, [23]={npc="画家瑞弗蕾", tgt="画家瑞弗蕾"}, [24]={npc="画家瑞弗蕾", tgt="画家瑞弗蕾", preText="爱与家庭"}, [25]={text="斯坦索姆 血色区 入口"}, [26]={hint="找到艾兹拉·格里姆在斯坦索姆的烟草店，并从中找回一盒格里姆的优质香烟，把它交给烟鬼拉鲁恩。", desc="位置：进入正门并打开市场区中烟草店的板条箱。", spot="进入正门并打开市场区中烟草店的板条箱。"}, [27]={hint="在斯坦索姆城中找到血色十字军的档案管理员加尔福特，杀掉他，然后烧毁血色十字军档案。", desc="血色档案位于档案管理员所在的档案室。位置：杀死血色十字军堡垒档案中的加尔福德，然后烧毁记录。", spot="杀死血色十字军堡垒档案中的加尔福德，然后烧毁记录。"}, [28]={hint="到瘟疫之地北部的斯坦索姆去。你可以在血色十字军堡垒中找到\"爱与家庭\"这幅画，它被隐藏在另一幅描绘两个月亮的画之后。", desc="双月画就在档案室首领所在的房间。位置：检查猩红档案馆墙上的两个月亮的画作。", spot="检查猩红档案馆墙上的两个月亮的画作。"}, [29]={npc="烟鬼拉鲁恩", tgt="烟鬼拉鲁恩"}, [30]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵"}, [31]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}}},
    ["04-52"] = {name="月光林地", tips={{k="交通", text="在步骤 2 中，飞往雷霆崖。在步骤 7 中，飞往费伍德森林并经过木喉要塞。 解锁飞行点在月光林地西南，然后走进冬泉谷。"}, {k="取捨", text="首先接受废土和净化之匣。 南风村的后续任务共享同一区域。"}, {k="取捨", text="在永望镇上交 神秘的粘液。在塞纳里奥要塞领取 净化之匣 并保存永夜港的上交。"}, {k="提醒", text="如果木喉熊怪仍然攻击你，请在外面杀死枯木熊怪，或者通过永望镇完成翡翠圣地和血毒哨站的声望任务。通过隧道后领取永望镇任务。", s={{"如果木喉熊怪仍然攻击你，请在外面杀死枯木熊怪，或者通过永望镇完成翡翠圣地和血毒哨站的声望任务"}, {"通过隧道后领取永望镇任务"}}}}, danger={[1]="在从月光林地前往冬泉谷的隧道之前检查您的木喉声誉。如果有敌意，请绕过或返回费伍德森林来举起它。"}, grind={[1]={mob="死木复仇者", note="永夜港任务交接后，穿过木喉要塞到达费伍德森林入口。研磨密集的普通枯木熊怪作为代表。避免木喉守卫和拉人进入帐篷。"}, [2]={mob="冬泉巢穴守卫", note="如果你通过了要塞，请沿着冬泉谷道路杀死普通熊怪。在多诺瓦附近磨一点，或者在永望镇以东找到主包。"}}, supply={[1]={npc="法斯托恩"}, [2]={npc="梅里"}, [3]={npc="达尔贡"}, [4]={npc="黛欧琳·夏叶"}}, steps={[1]={npc="塞纳里奥使者托尔·黑蹄", tgt="塞纳里奥使者托尔·黑蹄"}, [2]={text="从奥格瑞玛飞往雷霆崖。在基地拾取信使的导入口，然后在长者高地上找到拱门德鲁伊。"}, [3]={npc="雷霆崖信使斯塔德尔", tgt="雷霆崖信使斯塔德尔", desc="部落引导任务至永夜港。如果您已完成 新的边疆 或 新的边疆，请直接前往 Hamuul。"}, [4]={hint="与雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈一谈关于议会号召部落成员探索卡利姆多大陆的事情。", desc="部落引导任务至永夜港。如果您已完成 新的边疆 或 新的边疆，请直接前往 Hamuul。"}, [5]={npc="大德鲁伊哈缪尔·符文图腾", tgt="大德鲁伊哈缪尔·符文图腾", desc="部落引导任务至永夜港。如果您已完成 新的边疆 或 新的边疆，请直接前往 Hamuul。"}, [6]={npc="大德鲁伊哈缪尔·符文图腾", tgt="大德鲁伊哈缪尔·符文图腾"}, [7]={text="飞往血毒哨所。向北穿过死木村到达大锅（60.20, 5.84），然后走木喉要塞岔路到达月光林地。"}, [8]={hint="搜寻费伍德森林北部的死木熊怪的营帐，继续寻找线索。"}, [9]={npc="死木蒸锅", npcObj=true}, [10]={npc="死木蒸锅", npcObj=true}, [11]={hint="与月光林地永夜港的拉比恩·萨图纳谈一谈。月光林地在费伍德森林和冬泉谷之间，可以从木喉要塞中的一条通道抵达那里。"}, [12]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [13]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [14]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [15]={node="月光林地", desc="解锁、部落、飞行点与法斯托恩西南方向的月光林地。"}, [16]={hint="Travel to Blackmaw Hold in Kalimdor, and recover the Reliquary of Tyr.", tag="可选、需要游戏内检查", desc="55-60 级。从北艾萨拉洞穴进入。保存提瑞斯法的圣物。"}, [17]={text="再次越过木喉要塞到达冬泉谷。"}}},
    ["04-53"] = {name="冬泉谷", tips={{k="交通", text="在步骤 1 中，离开木喉要塞后停在冰火温泉处。最后一步，根据您是否绕道乱羽高地选择航班路线。"}, {k="取捨", text="在加基森中执行 墓地相见。 农场铁木森林中剧毒之水的物品，然后在冰火温泉上交。"}, {k="取捨", text="Quest 雪怪计划！ 将带您沿着这条路线穿过三个区域。首先使用永望镇中的机械雪人。"}, {k="提醒", text="57级以下？杀死冰蓟岭上的普通雪人（大约 66、43）或乱羽高地上的角鹰兽。", s={{"57级以下？"}, {"杀死冰蓟岭上的普通雪人（大约 66、43）或乱羽高地上的角鹰兽"}}}}, danger={[1]="冰蓟岭洞很窄。 57-58 级的雪人可以齐心协力度过难关。如果您只需要经验，请在入口外磨。"}, grind={[1]={mob="冰蓟雪人女王", note="冰蓟岭洞穴外的普通雪人会掉落任务角。如果繁忙，请使用外坡。注意内部的额外拉力。"}, [2]={mob="冰蓟雪人王", note="同一区域的高级普通雪人可以通过57。让队友清理狭窄的通道以避免双重拉动。"}}, supply={[1]={npc="尤格雷克"}, [2]={npc="旅店老板维兹奇"}, [3]={npc="尼克撒克"}, [4]={npc="旅店老板维兹奇"}, [5]={npc="维撒克"}}, steps={[1]={text="从木喉要塞向东行驶。在进入永望镇之前先参观位于冰火温泉的多诺瓦 (Donova)。"}, [2]={hint="将你的发现报告给多诺瓦·雪山。"}, [3]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [4]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [5]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [6]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [7]={npc="乌米", tgt="乌米"}, [8]={hint="为永望镇的乌米收集2支完美的雪人角。", desc="只有洞穴里的成年女族长和族长才会掉落它。跳过较低级别的雪人。"}, [9]={npc="乌米", tgt="乌米"}, [10]={npc="乌米", tgt="乌米", desc="在永望镇 (61.54, 38.61) 中使用机械雪人对莱加奇进行操作，然后在安戈洛中对两个进行操作。"}, [11]={text="飞往莫沙彻营地仅适用于可选鸡蛋或现成的厄运之槌团体。否则直接从永望镇飞往加基森。"}}},
    ["04-54"] = {name="菲拉斯", tips={{k="交通", text="第 1 步是鸡蛋在南行途中的停留。在第 2 步飞往加基森。"}, {k="取捨", text="如果您已经完成了超级蛋-O-马蒂克的一次性交接任务，或者如果您已经达到 57 级并且想要节省出行时间，请跳过该任务。直飞加基森。"}, {k="提醒", text="57级以下？在乱羽高地中杀死普通角鹰兽（大约 57、76），或者在飞行前用永望镇杀死冰蓟雪人。", s={{"57级以下？"}, {"在乱羽高地中杀死普通角鹰兽（大约 57、76），或者在飞行前用永望镇杀死冰蓟雪人"}}}}, grind={[1]={mob="冰蓟雪人女王", note="菲拉斯站仅用于角鹰兽蛋。如果低于57，则在离开永望镇之前磨掉更高级别的冰蓟雪人。洞口可能很忙。"}}, supply={[1]={npc="夏恩"}, [2]={npc="旅店老板格鲁尔"}, [3]={npc="卡温德"}, [4]={npc="旅店老板格鲁尔"}, [5]={npc="卡温德"}, [6]={npc="塔霍斯"}}, steps={[1]={text="从莫沙彻营地走南路至乱羽高地。拾取一张角鹰兽的蛋（55.91, 76.03或58.62, 75.53），然后返回给飞行大师。", tag="可选"}, [2]={text="如果您收集了鸡蛋，请返回莫沙彻营地并飞往加基森。如果您跳过了菲拉斯，请从加基森开始马绍尔营地支路。"}}},
    ["05-d30"] = {name="厄运之槌 北", entrance="菲拉斯（1444）、62.50, 24.90。北翼门户。", pickup="在莫沙彻营地集合并收集材料，然后向西前进。大多数北翼任务都在里面。在东翼获取月牙钥匙或带一个有它的人。如果需要，请在拍卖行购买课程书籍。", pickupS={{"在莫沙彻营地集合并收集材料，然后向西前进"}, {"大多数北翼任务都在里面"}, {"在东翼获取月牙钥匙或带一个有它的人"}, {"如果需要，请在拍卖行购买课程书籍"}}, tips={{k="動線", text="全清除：卫兵摩尔达 → 践踏者克雷格 → 卫兵芬古斯 → 结陷阱 → 克罗卡斯 → 戈多克大王。致敬：让守卫活着，找到结并修复陷阱，然后在杀死国王后见到克雷格。庭院侧门通向图书馆课本。"}, {k="取捨", text="练级时，优先选择能够一次性完成任务的队伍。如果您正在等待贡品材料，请继续探索。"}, {k="說明", text="为了进行致敬，让守卫和克雷格活着。杀死戈多克大王后与他们交谈。如果您想要标准的完全清晰，请先告诉团队。", s={{"为了进行致敬，让守卫和克雷格活着"}, {"杀死戈多克大王后与他们交谈"}, {"如果您想要标准的完全清晰，请先告诉团队"}}}, {k="提醒", text="为了进行致敬，让守卫和克雷格活着。杀死戈多克大王后与他们交谈。如果您想要标准的完全清晰，请先告诉团队。", s={{"为了进行致敬，让守卫和克雷格活着"}, {"杀死戈多克大王后与他们交谈"}, {"如果您想要标准的完全清晰，请先告诉团队"}}}}, steps={[1]={text="厄运之槌 北 入口"}, [2]={npc="诺特·希姆加克", tgt="诺特·希姆加克", tag="需要游戏内检查", desc="带上 4 个符文布、8 个硬甲皮和 2 个符文线螺栓。战利品 1 食人魔鞣酸。"}, [3]={hint="把4份符文布卷、8块硬甲皮、2卷符文线和一份食人魔鞣酸交给诺特·希姆加克。他现在被拴在厄运之槌的戈多克食人魔那边。", desc="位置：掠夺楼上芬格斯旁边的单宁。找到陷阱旁的结。", spot="掠夺楼上芬格斯旁边的单宁。找到陷阱旁的结。"}, [4]={npc="诺特·希姆加克", tgt="诺特·希姆加克", tag="需要游戏内检查", spot="芬古斯后，陷阱旁的诺特"}, [5]={npc="诺特·希姆加克", tgt="诺特·希姆加克", tag="需要游戏内检查", desc="仅适用于戈多克镣铐钥匙。致敬会跳过可以掉落它的守卫。"}, [6]={hint="掉落自：戈多克蛮兵、戈多克大法师、戈多克领主", desc="位置：穿过芬古斯的庭院，使用破损陷阱旁边的结上的钥匙。", spot="穿过芬古斯的庭院，使用破损陷阱旁边的结上的钥匙。"}, [7]={npc="诺特·希姆加克", tgt="诺特·希姆加克", tag="需要游戏内检查", spot="芬古斯庭院的破损陷阱旁，诺特"}, [8]={npc="践踏者克雷格", tgt="践踏者克雷格", tag="需要游戏内检查", desc="在贡品跑中获得戈多克之王，然后与践踏者克雷格交谈。践踏者克雷格在戈多克平民区；取得国王状态后才与他对话。"}, [9]={hint="完成任务目标。", desc="践踏者克雷格在戈多克平民区；取得国王状态后才与他对话。位置：成为国王，然后原路返回入口附近的践踏者克雷格。顺序：致敬活动结束后回去说话。", spot="成为国王，然后原路返回入口附近的践踏者克雷格。"}, [10]={npc="践踏者克雷格", tgt="践踏者克雷格", tag="需要游戏内检查", desc="致敬活动结束后，呆在里面向克雷格求助。践踏者克雷格在戈多克平民区；取得国王状态后才与他对话。", spot="戈多克平民区的践踏者克雷格"}, [11]={npc="迦罗娜：潜行与诡计研究", npcObj=true, tag="需要游戏内检查", desc="从老板或书堆中掠夺课堂书籍，或者购买一本。在图书馆之前使用它。"}, [12]={hint="将这本典籍交给它的主人。", desc="位置：进入北院。走上锁的侧门并通过隧道到达图书馆。", spot="进入北院。走上锁的侧门并通过隧道到达图书馆。"}, [13]={npc="博学者基尔达斯", tgt="博学者基尔达斯", tag="需要游戏内检查", spot="图书馆里的博学者基尔达斯"}, [14]={npc="防御宝典", npcObj=true, tag="需要游戏内检查", desc="从老板或书堆中掠夺课堂