    ["05-d29"] = {name="厄运之槌 西", entrance="菲拉斯（1444）、60.30, 30.20。门户位于庭院西侧。", pickup="在莫沙彻营地访问先知科鲁拉克，并在 54 层接取 精灵的传说。飞往营地，沿着主路向西行驶。检查是否有人拥有月牙钥匙，或者先跑东翼。", pickupS={{"在莫沙彻营地访问先知科鲁拉克，并在 54 层接取 精灵的传说"}, {"飞往营地，沿着主路向西行驶"}, {"检查是否有人拥有月牙钥匙，或者先跑东翼"}}, tips={{k="動線", text="西门→清除花园塔楼→特迪斯·扭木→看到楼上的古代并清除剩余的塔楼，与卡兰德里斯和伊莉安娜可选→伊莫塔尔在监狱→托塞德林王子在图书馆。转向远古遗迹，然后返回图书馆获取宝箱和遗骸。"}, {k="取捨", text="一次运行 精灵的传说、 伊莫塔尔的疯狂 和 辛德拉的宝藏。保存结界材料和更长的多地下城链条以供齿轮运行。"}, {k="說明", text="五人地下城。从东翼的普希林获得月牙钥匙。在伊莫塔尔之前清除所有五个塔。请参阅北翼的图书馆课堂书籍注释。", s={{"五人地下城"}, {"从东翼的普希林获得月牙钥匙"}, {"在伊莫塔尔之前清除所有五个塔"}, {"请参阅北翼的图书馆课堂书籍注释"}}}, {k="提醒", text="五人地下城。从东翼的普希林获得月牙钥匙。在伊莫塔尔之前清除所有五个塔。请参阅北翼的图书馆课堂书籍注释。", s={{"五人地下城"}, {"从东翼的普希林获得月牙钥匙"}, {"在伊莫塔尔之前清除所有五个塔"}, {"请参阅北翼的图书馆课堂书籍注释"}}}}, steps={[1]={npc="先知科鲁拉克", tgt="先知科鲁拉克", desc="在莫沙彻营地领取。通过西或北捷径到达图书馆。"}, [2]={text="厄运之槌 西 入口"}, [3]={npc="辛德拉古灵", tgt="辛德拉古灵", tag="需要游戏内检查", desc="首先与厄运之槌西上层的辛德拉古灵对话。"}, [4]={hint="你必须干掉5座水晶塔周围的守卫，那5座水晶塔维持着关押伊莫塔尔的监狱。一旦水晶塔的能量被削弱，伊莫塔尔周围的能量力场就会消散。", desc="先清除五座水晶塔。位置：清除五个塔，然后穿过上锁的门找到伊莫塔尔和王子。顺序：五座塔→伊莫塔尔→图书馆里的王子。", spot="清除五个塔，然后穿过上锁的门找到伊莫塔尔和王子。"}, [5]={npc="辛德拉古灵", tgt="辛德拉古灵", tag="需要游戏内检查", spot="图书馆里的辛德拉古灵"}, [6]={npc="辛德拉古灵", tgt="辛德拉古灵", tag="需要游戏内检查", desc="转向远古，然后接受后续行动。在与 伊莫塔尔的疯狂 相同的运行中做这个任务。", preText="伊莫塔尔的疯狂"}, [7]={hint="返回图书馆去找到辛德拉的宝藏。拿取你的奖励吧！", desc="位置：从伊莫塔尔的笼子到图书馆。检查楼梯下面是否有箱子。", spot="从伊莫塔尔的笼子到图书馆。检查楼梯下面是否有箱子。"}, [8]={npc="辛德拉的宝藏", npcObj=true, tag="需要游戏内检查", spot="图书馆楼梯下的辛德拉宝箱"}, [9]={hint="到厄运之槌去寻找泰尔米乌斯·探梦者。向莫沙彻营地的先知科鲁拉克报告你所找到的信息。", desc="位置：从笼子沿着大厅来到图书馆。寻找架子上的残留物。", spot="从笼子沿着大厅来到图书馆。寻找架子上的残留物。"}, [10]={npc="先知科鲁拉克", tgt="先知科鲁拉克"}}},
    ["05-d28"] = {name="厄运之槌 东", entrance="菲拉斯（1444）、64.80, 30.20。竞技场东墙凹陷处的传送门。", pickup="在第 54 层，经过瓦罗莫克路段上的奥格瑞玛时，从公告员高拉克取 。转入 Talo，并在莫沙彻营地乘坐 蕾瑟塔蒂丝的网。飞往莫沙彻营地并在拉瑞斯小亭访问埃斯托尔迪。对于 净化之匣，请在月光林地中拾取它，在南风村处收集圣物箱，然后在永夜港处将其上交以解锁 魔藤碎片。保存该链以供以后运行（如果需要）。", pickupS={{"在第 54 层，经过瓦罗莫克路段上的奥格瑞玛时，从公告员高拉克取"}, {"转入 Talo，并在莫沙彻营地乘坐 蕾瑟塔蒂丝的网"}, {"飞往莫沙彻营地并在拉瑞斯小亭访问埃斯托尔迪"}, {"对于 净化之匣，请在月光林地中拾取它，在南风村处收集圣物箱，然后在永夜港处将其上交以解锁 魔藤碎片"}, {"保存该链以供以后运行（如果需要）"}}, tips={{k="動線", text="从入口追普希林并在最后与他战斗→小路蕾瑟塔蒂丝和海多斯博恩→色狼祭坛瑟雷姆·刺蹄→奥兹恩。从西或北输入图书馆。"}, {k="取捨", text="在厄运之槌 East 获取月牙钥匙。 Talo 和普希林的任务是最快配对的。如果魔藤碎片仍然被锁定，不要跨越两个区域来获取圣物箱。"}, {k="說明", text="五人地下城。使用东入口。不要在 Boss 跑中跳过普希林。保留西翼和北翼的钥匙。", s={{"五人地下城"}, {"使用东入口"}, {"不要在 Boss 跑中跳过普希林"}, {"保留西翼和北翼的钥匙"}}}, {k="提醒", text="五人地下城。使用东入口。不要在 Boss 跑中跳过普希林。保留西翼和北翼的钥匙。", s={{"五人地下城"}, {"使用东入口"}, {"不要在 Boss 跑中跳过普希林"}, {"保留西翼和北翼的钥匙"}}}}, steps={[1]={npc="公告员高拉克", tgt="公告员高拉克", desc="直接从 Thalo 乘坐 蕾瑟塔蒂丝的网 即可跳过城市引导任务导航。"}, [2]={hint="和菲拉斯莫沙彻营地的塔罗·刺蹄谈一谈。"}, [3]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄"}, [4]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", desc="部落任务。 莫沙彻营地 引入线是可选的。"}, [5]={npc="埃斯托尔迪", tgt="埃斯托尔迪", desc="找到莫沙彻营地以北的拉瑞斯小亭。"}, [6]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳", desc="已经在主干道上的 52、56 和 59 号车站。如果转入，请跳过。"}, [7]={hint="到希利苏斯的南风村去寻找净化之匣。然后将其交给月光林地永夜港的拉比恩·萨图纳。"}, [8]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [9]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳", desc="带上净化之匣。如果 未完成，请将其保存以供下次运行。", preText="净化之匣"}, [10]={text="厄运之槌 东 入口"}, [11]={hint="到厄运之槌去找到小鬼普希林。你可以使用任何手段从小鬼那里得到埃斯托尔迪的咒术之书。", desc="依次与普希林交谈，追到最后一站。位置：在东入口与普希林对话并追到底。顺序：在每一站与他们交谈以开始战斗。", spot="在东入口与普希林对话并追到底。"}, [12]={hint="把蕾瑟塔蒂丝的网交给非拉斯莫沙彻营地的塔罗·刺蹄。", desc="位置：从花园走上层通道到蕾瑟塔蒂丝的平台。", spot="从花园走上层通道到蕾瑟塔蒂丝的平台。"}, [13]={hint="在厄运之槌中找到魔藤，然后从它上面采集一块碎片。只有干掉了奥兹恩之后，你才能进行采集工作。使用净化之匣安全地封印碎片，然后将其交给月光林地永夜港的拉比恩·萨图纳。", desc="魔藤碎片就在奥茨恩附近。位置：沿着最后一条隧道前往阿尔津。杀死他，然后掠夺并密封碎片。", spot="沿着最后一条隧道前往阿尔津。杀死他，然后掠夺并密封碎片。"}, [14]={npc="博学者莱德罗斯", tgt="博学者莱德罗斯", tag="需要游戏内检查", desc="60 点后，乘坐图书馆向西或向北行驶，从 Lydros 出发，然后向东行驶。"}, [15]={hint="到厄运之槌的扭木广场去杀掉水元素海多斯博恩。把海多斯博恩精华交给图书馆的博学者莱德罗斯。", desc="位置：走厄运之槌东下游水道。在水池边杀死海多斯博恩。", spot="走厄运之槌东下游水道。在水池边杀死海多斯博恩。"}, [16]={npc="埃斯托尔迪", tgt="埃斯托尔迪"}, [17]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄"}, [18]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [19]={npc="博学者莱德罗斯", tgt="博学者莱德罗斯", tag="需要游戏内检查", desc="返回图书馆并上交以了解造水术的最高等级。"}}},
    ["04-55"] = {name="安戈洛环形山", tips={{k="交通", text="在步骤 1 和 11 处经过加基森，并沿途使用机械雪人。最后一步，将西北坡带入希利苏斯。"}, {k="取捨", text="在冰火温泉上交 新的泉水，在永望镇上交 雪怪计划！。将 林克的记忆 保存为铁木森林。"}, {k="取捨", text="仅当您拿起鸡蛋并且仍可以将其上交时，才选择 超级测蛋器。否则，请勿原路返回。"}, {k="提醒", text="这条腿仍然适用于 57-59 级。如果在经验落后，则杀死火羽山上的普通元素或北方的大猩猩。留意平地上的魔暴龙。", s={{"这条腿仍然适用于 57-59 级"}, {"如果在经验落后，则杀死火羽山上的普通元素或北方的大猩猩"}, {"留意平地上的魔暴龙"}}}}, danger={[1]="54-56级精英魔暴龙在火羽山以南的平地巡逻。护送林格前先勘察路线，并紧贴斜坡。"}, grind={[1]={mob="有生烈焰", note="高级普通元素位于火羽山。与火山任务配对。沿着斜坡行驶，避开平原上的魔暴龙巡逻队。"}, [2]={mob="焦油兽王", note="马绍尔营地附近的普通焦油生物。为经验的最后一点跑几圈。一次从池边拉出一名敌人。"}}, supply={[1]={npc="格莱菲"}, [2]={npc="吉波尔特"}, [3]={npc="奈尔加"}, [4]={npc="奈尔加"}, [5]={npc="旅店老板菲兹格瑞博"}}, steps={[1]={text="首先完成加基森中的墓地任务交接。如果你正在进行机械雪人任务，请在走南路之前在城镇中使用它。"}, [2]={npc="测蛋器", npcObj=true, tag="可选", desc="在菲拉斯中使用乱羽高地中的鸡蛋。如果已经完成则跳过。"}, [3]={hint="使用／收集：角鹰兽的蛋", tag="可选"}, [4]={npc="测蛋器", npcObj=true, tag="可选"}, [5]={hint="在加基森镇外的墓地中使用视灵药剂，然后按照多诺瓦的指示找到加里杨。", desc="喝水它会杀了你。死后说话，然后在墓地复活。"}, [6]={npc="加里杨", tgt="加里杨"}, [7]={npc="加里杨", tgt="加里杨"}, [8]={hint="复活，然后寻找加里杨让你去找的那块墓碑。"}, [9]={npc="明显的墓碑", npcObj=true}, [10]={npc="明显的墓碑", npcObj=true}, [11]={text="在加基森（51.06, 26.87）的斯普琳科上使用机械雪人，然后沿南路进入安戈洛。"}, [12]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [13]={hint="在安戈洛尔环形山找到东部水晶塔。"}, [14]={hint="使用托尔瓦的麻袋中的东西召唤拉克维并打败它。将拉克维的头颅交给安戈洛环形山入口处的托尔瓦·寻路者。", desc="打开托尔瓦的袋子。放下肉，然后用信息素引诱拉克维。"}, [15]={hint="将2块安戈洛猩猩的皮、2块安戈洛大猩猩的皮和2块安戈洛巨猩猩的皮交给安戈洛环形山入口处的托尔瓦·寻路者。", tag="目标：安戈洛猩猩 / 安戈洛猩猩 / 安戈洛巨猩猩 / 安戈洛大猩猩"}, [16]={hint="在安戈洛尔环形山找到北部水晶塔。"}, [17]={hint="把林克的强化之剑交给安戈洛尔环形山的林克。"}, [18]={npc="林克", tgt="林克"}, [19]={npc="林克", tgt="林克"}, [20]={hint="到马绍尔营地那里的山洞中去找科琳。"}, [21]={npc="科琳", tgt="科琳"}, [22]={npc="科琳", tgt="科琳"}, [23]={npc="斯普拉格·弗劳克", tgt="斯普拉格·弗劳克"}, [24]={hint="带着乌米的机械雪人去吓唬她的朋友：", desc="在前两个目标之后，在奎克希尔上使用雪人。上交处：霜语峡谷。"}, [25]={hint="在安戈洛尔环形山找到西部水晶塔。"}, [26]={npc="克拉兰克", tgt="克拉兰克"}, [27]={hint="安戈洛尔环形山的克拉兰克要你去找到火羽山中温度最高的地方。", desc="等待反应计数。远离熔岩。"}, [28]={hint="在火羽山找到林格。"}, [29]={npc="林格", tgt="林格"}, [30]={npc="林格", tgt="林格", desc="在护送之前清理洞穴入口。使用斯普拉格的水壶唤醒林格。"}, [31]={hint="把林格带回马绍尔营地的斯普拉格·弗劳克身边。"}, [32]={npc="斯普拉格·弗劳克", tgt="斯普拉格·弗劳克"}, [33]={npc="科琳", tgt="科琳"}, [34]={npc="科琳", tgt="科琳"}, [35]={npc="科琳", tgt="科琳"}, [36]={npc="科琳", tgt="科琳"}, [37]={hint="过一会再和科琳说话。"}, [38]={npc="科琳", tgt="科琳"}, [39]={npc="克拉兰克", tgt="克拉兰克"}, [40]={npc="克拉兰克", tgt="克拉兰克"}, [41]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [42]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [43]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [44]={hint="把尤尔查的毛皮交给安戈洛环形山入口处的托尔瓦·寻路者。", desc="清除洞穴入口处的大猩猩。 尤尔查是一个普通生物。"}, [45]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [46]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选", desc="从东南入口转向托尔瓦。选择皮甲或法杖。", star={"斑白毛皮", {"DRUID"}}}, [47]={text="使用安戈洛的西北坡道进入希利苏斯。沿着塞纳里奥要塞路走。"}}},
    ["05-d31"] = {name="塑造者之台", entrance="安戈洛环形山（去辛特兰的旅程）、48.10, 6.10。标记泰坦结构。确切的传送门坐标未知。", pickup="前往月光林地的途中，经过雷霆崖时，在莫高雷西北的玛耶娜·寻地者停留。回到马绍尔营地，走石阶向北到达泰坦建筑。其他两个任务的拾取 NPC 未经验证。", pickupS={{"前往月光林地的途中，经过雷霆崖时，在莫高雷西北的玛耶娜·寻地者停留"}, {"回到马绍尔营地，走石阶向北到达泰坦建筑"}, {"其他两个任务的拾取 NPC 未经验证"}}, tips={{k="動線", text="入口→通过泰坦废墟收集四种颜色的水晶→用无色水晶处理水池目标。泰坦龙霹雳、翠鳞和娜娜亚的完整订单尚未得到确认。"}, {k="取捨", text="先拿起Crystalline Elements。如果营地没有其他任务，请与您的团队一起进入。"}, {k="說明", text="永恒版新增五人地下城。从马绍尔营地以北上坡。在泰坦之门使用安戈洛的能量水晶。外入口地标位于48.10, 6.10周围。确切的传送门位置尚未得到验证。", s={{"永恒版新增五人地下城"}, {"从马绍尔营地以北上坡"}, {"在泰坦之门使用安戈洛的能量水晶"}, {"外入口地标位于48.10, 6.10周围"}, {"确切的传送门位置尚未得到验证"}}}, {k="提醒", text="永恒版新增五人地下城。从马绍尔营地以北上坡。在泰坦之门使用安戈洛的能量水晶。外入口地标位于48.10, 6.10周围。确切的传送门位置尚未得到验证。", s={{"永恒版新增五人地下城"}, {"从马绍尔营地以北上坡"}, {"在泰坦之门使用安戈洛的能量水晶"}, {"外入口地标位于48.10, 6.10周围"}, {"确切的传送门位置尚未得到验证"}}}}, steps={[1]={npc="玛耶娜·寻地者", tgt="玛耶娜·寻地者", desc="在雷霆崖的西部悬崖上接载。 NPC 来自玩家记录。"}, [2]={npc="化学家弗雷", tgt="化学家弗雷", tag="需要游戏内检查"}, [3]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", tag="需要游戏内检查"}, [4]={text="塑造者之台 入口"}, [5]={hint="Bring Mayena Earthseeker a Moist Crystal, a Charged Crystal, a Noxious Crystal and a Fiery Crystal from Shaper's Terrace.", tag="需要游戏内检查", desc="位置：跟随泰坦废墟并从元素中掠夺所有四种颜色的水晶。", spot="跟随泰坦废墟并从元素中掠夺所有四种颜色的水晶。"}, [6]={hint="Gather 8 Seeping Slime Essence in the Shaper's Terrace.", tag="需要游戏内检查", desc="位置：找到里面渗出的史莱姆。他们的确切泳池位置尚未确认。", spot="找到里面渗出的史莱姆。他们的确切泳池位置尚未确认。"}, [7]={hint="Gather a colorless Drained Crystal Fragment near the Achromatic Crystal in the Shaper's Terrace.", desc="位置：查看无色水晶周围的地面是否有耗尽的碎片。", spot="查看无色水晶周围的地面是否有耗尽的碎片。"}, [8]={npc="玛耶娜·寻地者"}, [9]={npc="化学家弗雷", tgt="化学家弗雷", tag="需要游戏内检查"}, [10]={tag="需要游戏内检查"}}},
    ["04-56"] = {name="希利苏斯", tips={{k="交通", text="步骤 1 中的解锁塞纳里奥要塞飞行点。在最后一步，将飞艇带回东部王国。"}, {k="取捨", text="保存 净化之匣 和 档案管理员阿姆伯尔 以用于月光林地上交。"}, {k="取捨", text="如果您正在升级，请跳过 诺格的背包 和 通缉：死亡弯钩。任务 诺格的背包 将您送回遥远的南方，而 通缉：死亡弯钩 则需要精英击杀。"}, {k="取捨", text="视频的暗翼蝠任务 位于东瘟疫之地中。也跳过希利苏斯中的精英组任务。"}, {k="提醒", text="即使低于 59 级，也要前往壁垒。首先，杀死塞纳里奥要塞东北部的普通蝎子和蜘蛛（大约 55、29）或暮光西南边的邪教徒（大约 38、44）。", s={{"即使低于 59 级，也要前往壁垒"}, {"首先，杀死塞纳里奥要塞东北部的普通蝎子和蜘蛛（大约 55、29）或暮光西南边的邪教徒（大约 38、44）"}}}}, danger={[1]="到达南风村塔顶会触发异种虫群。首先清理塔楼和楼梯，这样你就有了出去的路。"}, grind={[1]={mob="暮光复仇者", note="营地外的正常暮光信徒是好的经验并掉落暮光装备。与邪教任务配对。如果其他人是农具，请从边缘清除。"}, [2]={mob="掘泥打击者", note="塞纳里奥要塞东北空地的普通生物等级稍低但密集。 如果暮光营地繁忙，则农场在物资收集路线上。"}}, supply={[1]={npc="鲁克·驯风者"}, [2]={npc="卡兰德拉斯"}, [3]={npc="瓦古斯"}, [4]={npc="卡兰德拉斯"}, [5]={npc="卡兰德拉斯"}, [6]={npc="库尔·锐角"}}, steps={[1]={nodeA="{a:3425}", desc="解锁、部落、飞行点和鲁克·驯风者以及塞纳里奥要塞。"}, [2]={text="如果你想在勇气休息后使用你的炉石，请在旅馆（51.89，39.16）绑定它。"}, [3]={hint="与希利苏斯塞纳里奥要塞的唤风者梅恩·长角谈一谈。"}, [4]={npc="唤风者梅恩·长角", tgt="唤风者梅恩·长角"}, [5]={npc="比提克斯·斯巴格", tgt="比提克斯·斯巴格"}, [6]={npc="唤风者梅恩·长角", tgt="唤风者梅恩·长角"}, [7]={npc="地质学家拉克斯班", tgt="地质学家拉克斯班"}, [8]={npc="鲍尔·蛮鬃", tgt="鲍尔·蛮鬃"}, [9]={hint="希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你带8个石鞭蝎之刺和8个掠沙蜘蛛的牙齿给他。"}, [10]={hint="希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死15只掘泥打击者。"}, [11]={hint="在希利苏斯的勇士之墓附近找莱耶·星击谈谈，把拉比恩的信交给他。"}, [12]={npc="莱耶·星击", tgt="莱耶·星击"}, [13]={npc="莱耶·星击", tgt="莱耶·星击"}, [14]={hint="希利苏斯塞纳里奥要塞的地质学家拉克斯班要你去收集8块暮光石板碎片。"}, [15]={hint="把10片暮光密文信交给塞纳里奥要塞的鲍尔·蛮鬃。"}, [16]={npc="比提克斯·斯巴格", tgt="比提克斯·斯巴格"}, [17]={npc="唤风者梅恩·长角", tgt="唤风者梅恩·长角"}, [18]={npc="地质学家拉克斯班", tgt="地质学家拉克斯班"}, [19]={npc="鲍尔·蛮鬃", tgt="鲍尔·蛮鬃"}, [20]={npc="比提克斯·斯巴格", tgt="比提克斯·斯巴格"}, [21]={npc="唤风者梅恩·长角", tgt="唤风者梅恩·长角"}, [22]={npc="地质学家拉克斯班", tgt="地质学家拉克斯班"}, [23]={hint="希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死20只掘泥摧毁者。"}, [24]={hint="希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你给他带去3个石鞭巨钳蝎之刺、3个石鞭掠夺者之刺和3个石行蜘蛛的牙齿。"}, [25]={hint="把复原的石板带给希利苏斯的隐士奥泰尔。"}, [26]={npc="隐士奥泰尔", tgt="隐士奥泰尔"}, [27]={hint="到希利苏斯的南风村去寻找净化之匣。然后将其交给月光林地永夜港的拉比恩·萨图纳。"}, [28]={hint="在南风村释放8个被折磨的德鲁伊和8个被折磨的哨兵的灵魂，然后向希利苏斯勇士之墓的莱耶·星击复命。", desc="亡灵被杀死时可以生成异种蜥蜴。在下次拉动之前杀死它。"}, [29]={npc="莱耶·星击", tgt="莱耶·星击"}, [30]={npc="莱耶·星击", tgt="莱耶·星击"}, [31]={hint="爬上南风村的塔，找寻激活异种蝎群的方法。把任何你认为不寻常的东西交给希利苏斯勇士之墓的莱耶·星击。", desc="打开物体之前先清理塔楼楼梯。注意你的视线。"}, [32]={npc="莱耶·星击", tgt="莱耶·星击"}, [33]={npc="莱耶·星击", tgt="莱耶·星击"}, [34]={text="返回塞纳里奥要塞。壁炉如果绑定在这里。"}, [35]={npc="比提克斯·斯巴格", tgt="比提克斯·斯巴格"}, [36]={npc="唤风者梅恩·长角", tgt="唤风者梅恩·长角"}, [37]={text="从塞纳里奥要塞飞往奥格瑞玛，然后从杜隆塔尔乘坐提瑞斯法飞艇。"}}},
    ["04-57"] = {name="西瘟疫之地", tips={{k="交通", text="在第 1 步进入壁垒。在最后一步，在幽暗城外面乘坐齐柏林飞艇。"}, {k="取捨", text="在同一个循环中执行费尔斯通农场和 Andorhal。回来的路上交白蚁任务。"}, {k="取捨", text="克罗米的剩余任务会将您送回东瘟疫之地。把它们留到回程时用。"}, {k="提醒", text="59级以下？在前往费伍德森林之前，杀死安多哈尔东部以外（大约 46、64）或受瘟疫农场的普通不死生物。", s={{"59级以下？"}, {"在前往费伍德森林之前，杀死安多哈尔东部以外（大约 46、64）或受瘟疫农场的普通不死生物"}}}}, danger={[1]="安多哈尔议政厅接近召唤者阿拉基，61 级精英。寻找达隆郡的历史时，请沿着外墙寻找。"}, grind={[1]={mob="灼热的食尸鬼", note="安多哈尔东部边缘的普通不死生物。返回农场之前先在这里磨碎。避开建筑物中的精英和群体。"}, [2]={mob="亡鬼幻象", note="高级普通幽灵在盖罗恩农场。如果您还在东部，请使用这个位置。环绕边缘以避免在室内连接小怪。"}}, supply={[1]={npc="银色黎明军需官哈萨娜"}, [2]={npc="迈克尔·加勒特"}, [3]={npc="旅店老板诺曼"}, [4]={npc="旅店老板诺曼"}, [5]={npc="艾林诺尔·拉斯克"}, [6]={npc="托马斯·莫丹"}, [7]={npc="艾泽基尔·格瑞乌斯"}}, steps={[1]={text="从提瑞斯法飞艇塔前往壁垒，然后穿过费尔斯通农场、安多哈尔和北山伐木场。"}, [2]={hint="把盖罗恩农场的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"}, [3]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [4]={npc="米克·莱文", tgt="米克·莱文"}, [5]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", star={"英勇短剑", {"PALADIN", "MAGE", "WARLOCK"}}}, [6]={hint="完成任务目标。"}, [7]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", star={"英勇短剑", {"PALADIN", "MAGE", "WARLOCK"}}}, [8]={npc="米克·莱文", tgt="米克·莱文"}, [9]={hint="把半个好运护符还给西瘟疫之地的詹妮丝·费尔斯通。"}, [10]={npc="詹妮丝·费尔斯通", tgt="詹妮丝·费尔斯通"}, [11]={npc="詹妮丝·费尔斯通", tgt="詹妮丝·费尔斯通"}, [12]={hint="在西瘟疫之地的费尔斯通农场某地找到另外一半好运护符，并把两半护符合并。", desc="食尸鬼在农场巡逻。首先检查南边。"}, [13]={npc="詹妮丝·费尔斯通", tgt="詹妮丝·费尔斯通"}, [14]={hint="与安多哈尔废墟南边的玛莱恩谈一谈。"}, [15]={npc="玛莱恩·雷德帕斯", tgt="玛莱恩·雷德帕斯"}, [16]={npc="玛莱恩·雷德帕斯", tgt="玛莱恩·雷德帕斯"}, [17]={hint="把约瑟夫的结婚戒指交给安多哈尔的克罗米。", desc="安多哈尔中部有一名精英巫妖。前往旅馆的途中留在郊区。"}, [18]={npc="克罗米", tgt="克罗米"}, [19]={npc="克罗米", tgt="克罗米"}, [20]={npc="克罗米", tgt="克罗米"}, [21]={hint="把《达隆郡的历史》交给安多哈尔的克罗米。", desc="检查盖子。假书会产生敌人。避开中心的精英。"}, [22]={hint="在安多哈尔的一处仓库附近使用时光置换器，使时光寄生虫现身。"}, [23]={npc="克罗米", tgt="克罗米"}, [24]={npc="克罗米", tgt="克罗米"}, [25]={npc="克罗米", tgt="克罗米"}, [26]={hint="在安多哈尔城中四处散落的保险箱里找到5只安多哈尔怀表，然后把它们交给西瘟疫之地安多哈尔旅店里的克罗米。"}, [27]={npc="克罗米", tgt="克罗米"}, [28]={hint="到西瘟疫之地的北山伐木场去找个合适的地方，在那里放下一桶瘟疫白蚁。"}, [29]={npc="白蚁桶", npcObj=true}, [30]={npc="白蚁桶", npcObj=true}, [31]={hint="使用北山伐木场里的铁棍放出那里的瘟疫白蚁，然后向提瑞斯法林地亡灵壁垒的米克·莱文报告。", desc="打开枪管吸引敌人。打开后立即离开。"}, [32]={npc="米克·莱文", tgt="米克·莱文"}, [33]={npc="哀恸骑士", tag="可选、需要游戏内检查", desc="参见位于提瑞斯法西南部的哀恸骑士。哀悼之剑是一个奖励选择。", star={"Sword of Mourning", {"PALADIN"}}}, [34]={text="返回幽暗城齐柏林飞艇塔。乘坐奥格瑞玛齐柏林飞艇继续前往费伍德森林。"}}},
    ["05-d32"] = {name="通灵学院", entrance="西瘟疫之地（海中的威胁），关于68.90, 72.80。地下入口位于凯尔达隆。", pickup="在壁垒处，从 Alexi 处拿走 巴罗夫家族的宝藏 并启动钥匙链。在圣光之愿礼拜堂领取 瘟疫之龙。沿着Bulwark的南边道路到达凯尔达隆，在进入之前看到Eva。要制作自己的钥匙，请在壁垒上交骸骨碎片，接受模具任务，然后访问加基森和火羽山，然后返回壁垒。", pickupS={{"在壁垒处，从 Alexi 处拿走 巴罗夫家族的宝藏 并启动钥匙链"}, {"在圣光之愿礼拜堂领取 瘟疫之龙"}, {"沿着Bulwark的南边道路到达凯尔达隆，在进入之前看到Eva"}, {"要制作自己的钥匙，请在壁垒上交骸骨碎片，接受模具任务，然后访问加基森和火羽山，然后返回壁垒"}}, tips={{k="動線", text="入口桥→第一个大厅的契约→另一个经过召唤室→血骨傀儡和幼体的骨库→莱斯·霜语房间的契约→楼下的最后契约和克拉斯蒂诺夫→黑暗院长加丁。"}, {k="取捨", text="完成这四件事，一次性消灭瘟疫幼体和教授。如果有人能打开门，其他人就可以跳过钥匙材料链。"}, {k="說明", text="五人地下城。让钥匙扣打开外门。教授 卡斯迪诺夫的恐惧之袋 和 传令官基尔图诺斯 之后的任务需要重复运行。将它们保存为可以再次运行的组。", s={{"五人地下城"}, {"让钥匙扣打开外门"}, {"教授 卡斯迪诺夫的恐惧之袋 和 传令官基尔图诺斯 之后的任务需要重复运行"}, {"将它们保存为可以再次运行的组"}}}, {k="提醒", text="五人地下城。让钥匙扣打开外门。教授 卡斯迪诺夫的恐惧之袋 和 传令官基尔图诺斯 之后的任务需要重复运行。将它们保存为可以再次运行的组。", s={{"五人地下城"}, {"让钥匙扣打开外门"}, {"教授 卡斯迪诺夫的恐惧之袋 和 传令官基尔图诺斯 之后的任务需要重复运行"}, {"将它们保存为可以再次运行的组"}}}}, steps={[1]={npc="阿莱克斯·巴罗夫", tgt="阿莱克斯·巴罗夫", desc="达到 52 级后，尽早前往壁垒接载。"}, [2]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克", desc="在圣光之愿礼拜堂找到贝蒂娜。"}, [3]={npc="艾瓦·萨克霍夫", tgt="艾瓦·萨克霍夫", desc="在凯尔达隆门外找到 Eva。"}, [4]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", desc="仅当您需要自己的通灵学院密钥时才这样做。如果在壁垒完成则跳过。"}, [5]={hint="到血色十字军建在费尔斯通农场和达尔松之泪之间的营地去，摧毁他们的指挥帐篷。"}, [6]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [7]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", desc="已经在西瘟疫之地的壁垒的主路上了。", preText="误导血色十字军"}, [8]={hint="使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。"}, [9]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [10]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", desc="你可以提前在壁垒上交。", preText="标记哨塔"}, [11]={hint="和西瘟疫之地亡灵壁垒的药剂师迪瑟斯谈一谈。"}, [12]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [13]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯", desc="如果在壁垒完成，请跳过这三个。如果自己制作钥匙，请使用模具。", preText="通灵学院"}, [14]={hint="将15块骸骨碎片交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。"}, [15]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [16]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯", desc="在离开加基森前往马绍尔营地之前带上两块瑟银锭。", preText="骸骨碎片"}, [17]={hint="把灌魔的骸骨碎片和15枚金币交给加基森的克林科·古德斯迪尔。"}, [18]={npc="克林科·古德斯迪尔", tgt="克林科·古德斯迪尔"}, [19]={npc="克林科·古德斯迪尔", tgt="克林科·古德斯迪尔", desc="通过马绍尔营地支线的火羽山任务来完成此任务。", preText="昂贵的模具"}, [20]={hint="把骷髅钥匙模具和2块瑟银锭带到安戈洛尔环形山地区的火羽山顶部。在熔岩湖旁使用骷髅钥匙模具，铸造出一把未完工的骷髅钥匙。"}, [21]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [22]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯", desc="如果您有团体，请在从壁垒出发的安多哈尔行程期间进行此活动。", preText="火羽山"}, [23]={hint="杀掉召唤者阿拉基，并将阿拉基的圣甲虫交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。"}, [24]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [25]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", preText="阿拉基的圣甲虫"}, [26]={hint="完成任务目标。"}, [27]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [28]={text="通灵学院 入口"}, [29]={hint="到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到阿莱克斯·巴罗夫那儿去。", desc="位置：搜索第一个大厅，经过召唤室，然后是拉斯和巴罗夫的房间。顺序：南海镇 → 塔伦米尔 → 布瑞尔 → 凯尔达隆.", spot="搜索第一个大厅，经过召唤室，然后是拉斯和巴罗夫的房间。"}, [30]={hint="杀掉20只瘟疫龙崽，然后向圣光之愿礼拜堂的贝蒂娜·比格辛克复命。", desc="位置：通过召唤室并杀死血骨傀儡骨库中的幼体。", spot="通过召唤室并杀死血骨傀儡骨库中的幼体。"}, [31]={hint="在通灵学院中找到瑟尔林·卡斯迪诺夫教授。杀死他，并烧毁艾瓦·萨克霍夫和卢森·萨克霍夫的遗体。任务完成后就回到艾瓦·萨克霍夫那儿。", desc="艾瓦与卢森的遗骸在教授房内。位置：在最后六个房间中找到克拉斯蒂诺夫。 燃烧两组遗骸都在他的房间里。顺序：遗骸都在同一个房间里。", spot="在最后六个房间中找到克拉斯蒂诺夫。 燃烧两组遗骸都在他的房间里。"}, [32]={npc="艾瓦·萨克霍夫", tgt="艾瓦·萨克霍夫", desc="下次从伊娃那里拿走恐怖袋。第一次运行时，只需上交即可。"}, [33]={npc="阿莱克斯·巴罗夫", tgt="阿莱克斯·巴罗夫"}, [34]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克"}}},
    ["04-58"] = {name="费伍德森林", tips={{k="交通", text="在步骤 1 中，从灰谷向北行驶。最后一步，从木喉要塞到月光林地。"}, {k="取捨", text="任务 最终一击 需要再次深入暗影堡来完成三个目标。如果单独运行不值得花时间，请跳过它。"}, {k="取捨", text="将剧毒之水带到冬泉谷中的冰火温泉上交。"}, {k="提醒", text="60级以下？在铁木森林杀死剧毒之水和铁树树人（大约 49、25），或者在冬泉谷追上。", s={{"60级以下？"}, {"在铁木森林杀死剧毒之水和铁树树人（大约 49、25），或者在冬泉谷追上"}}}}, danger={[1]="暗影堡中的火盆分散在狭窄的隧道中。在浇灭火盆之前清理每个部分。原路返回。"}, grind={[1]={mob="剧毒之水", note="铁木森林池中的普通元素。边走边收集剧毒之水水滴。它们适合较小的经验间隙。如果池繁忙，请转到冬泉谷。"}, [2]={mob="曲木撕裂者", note="北路旁的普通树人。如果泳池繁忙，请切换至此处，然后继续沿路前往木喉要塞。注意营地内的脚轮。"}}, supply={[1]={npc="旅店老板凯利斯克"}, [2]={npc="旅店老板凯利斯克"}, [3]={npc="布拉卡尔"}, [4]={npc="奥索巴·狂怒图腾"}, [5]={npc="拜尔"}, [6]={npc="拜尔"}}, steps={[1]={text="从奥格瑞玛飞往碎木岗哨。沿着主干道向北进入费伍德森林，并在翡翠圣地处停下并沿着附近的道路行驶。"}, [2]={npc="梅贝丝·河风", tgt="梅贝丝·河风"}, [3]={hint="把净化过的月亮井水交给费伍德森林的格雷塔·苔蹄。"}, [4]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [5]={hint="到费伍德森林去找艾瑞丹·蓝风。"}, [6]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [7]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [8]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [9]={hint="使用净化过的月亮井水熄灭暗影堡内部的四座火盆的火焰，从而破除其保护效果，然后向翡翠圣地的格雷塔·苔蹄复命。", desc="先清理通道。地图图钉可能会在洞穴内重叠。"}, [10]={hint="为费伍德森林的艾瑞丹·蓝风收集11只银爪和1颗铁树之心。", desc="从狼和熊身上掠夺银爪。杀死铁树树人以获得心脏。"}, [11]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [12]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [13]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", tag="可选", desc="与伙伴一起返回暗影堡深处，或者如果你可以一次拉出一个小怪。"}, [14]={hint="杀掉米莱恩和萨莉亚，并把暗影领主费尔丹的头颅交给费伍德森林的格雷塔·苔蹄。", tag="可选", desc="侍卫离主很近。先清理掉附近的巡逻队。"}, [15]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", tag="可选"}, [16]={npc="特鲁尔·法贝恩", tgt="特鲁尔·法贝恩"}, [17]={hint="为冬泉谷的多诺瓦·雪山收集3份剧毒水滴。"}, [18]={npc="伊普斯", tgt="伊普斯", tag="可选", desc="灵魂收割者是奖励选择之一。", star={"灵魂收割者", {"WARLOCK"}}}, [19]={hint="费伍德的伊普斯要求你从三个不同的地区收集三块无暇的恶魔精华，然后把它们交给他。", tag="可选", desc="如果您在第 45、52 和 57 站收集了腿上的所有物品，请返回伊普斯。"}, [20]={npc="伊普斯", tgt="伊普斯", tag="可选"}, [21]={npc="伊普斯", tgt="伊普斯", tag="可选", desc="为精英而组团。交给 Niby 解锁地狱火。"}, [22]={hint="在费伍德森林的碎痕谷中搜寻克罗苏斯的尸体。当你找到尸体后，在他身上使用魔火，并等待克罗苏斯复生。当这个地狱火被唤醒之后，干掉他，从他的身上拿取克罗苏斯的恶魔之核。", tag="可选", desc="为精英而组团。交给 Niby 解锁地狱火。"}, [23]={npc="万能的尼比", tgt="万能的尼比", tag="可选", desc="为精英而组团。交给 Niby 解锁地狱火。"}, [24]={text="向北进入木喉要塞，并从月光林地出口驶出。"}}},
    ["04-59"] = {name="月光林地", tips={{k="交通", text="在第 1 步步行至永夜港。在最后一步，根据您的任务前往冰火温泉或永望镇。"}, {k="取捨", text="在一次村庄访问中完成两次永夜港 NPC 交接。"}, {k="取捨", text="将 魔藤碎片 保存为厄运之槌 East 运行。"}, {k="提醒", text="这条腿仍然适用于 59-60 级。完成后直接转到霜语峡谷。", s={{"这条腿仍然适用于 59-60 级"}, {"完成后直接转到霜语峡谷"}}}}, danger={[1]="在从月光林地进入冬泉谷之前检查木喉声望。如果仍然敌对，请在进入隧道之前提高费伍德森林一方的声望。"}, grind={[1]={mob="疯狂的碎齿熊", note="月光林地任务交接后，穿过要塞并杀死霜语峡谷北口附近的普通熊。他们已经接近60岁了。避开下面的精英。"}}, supply={[1]={npc="梅里"}, [2]={npc="达尔贡"}, [3]={npc="黛欧琳·夏叶"}, [4]={npc="法斯托恩"}}, steps={[1]={text="离开木喉要塞，沿着主路前往永夜港。上交希利苏斯中的两项。"}, [2]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [3]={hint="将异种蝎粘液包裹的物体交给月光林地永夜港的阿姆伯尔，他是塞纳里奥议会的档案管理员。"}, [4]={npc="阿姆伯尔", tgt="阿姆伯尔"}, [5]={npc="阿姆伯尔", tgt="阿姆伯尔"}, [6]={hint="与月光林地永夜港的拉比恩·萨图纳谈一谈。"}, [7]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [8]={npc="阿姆伯尔", tgt="阿姆伯尔"}, [9]={hint="完成任务目标。"}, [10]={npc="阿姆伯尔", tgt="阿姆伯尔"}, [11]={text="乘坐新的泉水或剧毒之水，穿过木喉要塞回到冬泉谷温泉。如果您两者都没有并且要跳过多诺瓦，请从法斯托恩 (32.09, 66.61) 飞往永望镇。"}}},
    ["04-60"] = {name="冬泉谷", tips={{k="交通", text="先停在冰火温泉。交完永望镇雪人任务后，向南走，在峡谷北入口外磨砺。"}, {k="取捨", text="寻找 冬泉信使 的孤独信使。探索任务 奇怪的源头 正在前往视频的研磨点。"}, {k="取捨", text="Quest 冬泉酋长 有一个精英目标。如果单独杀死普通熊。"}, {k="提醒", text="未满 60 级就照视频在霜语峡谷北侧打熊，打一般的疯狂的裂齿熊（约 57.63, 70.83／66.68, 70.57），避开谷底精英。", s={{"未满 60 级就照视频在霜语峡谷北侧打熊，打一般的疯狂的裂齿熊（约 57.63, 70.83／66.68, 70.57），避开谷底精英"}}}}, danger={[1]="59-60级精英霜槌巨人漫游霜语峡谷。沿着北入口的斜坡一次拉一只熊，不要把它们拖进峡谷。", [2]="57-60级精英赫德琳杀手漫游暗语峡谷。 引爆奇怪的源头在北入口处，然后返回道路。"}, grind={[1]={mob="疯狂的碎齿熊", note="普通近战熊霜语峡谷北口以西。一次拉一个敌人并剥皮。清除后向东旋转。避开下面的精英。"}, [2]={mob="疯狂的碎齿熊", note="峡谷北口以东的普通熊。如果西侧繁忙或尚未重生，请切换至此处。把车开上坡，到远离精英的路上。"}}, supply={[1]={npc="尤格雷克"}, [2]={npc="旅店老板维兹奇"}, [3]={npc="尼克撒克"}, [4]={npc="旅店老板维兹奇"}, [5]={npc="维撒克"}}, steps={[1]={text="从木喉要塞出发，在温泉处观赏多诺瓦 (Donova)。交出马绍尔营地和铁木森林任务，然后前往永望镇和南部山谷。如果您直接飞往永望镇并且跳过温泉任务，请从 Umi 开始。"}, [2]={hint="到冬泉谷去和多诺瓦·雪山谈一谈。"}, [3]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [4]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [5]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [6]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [7]={hint="找到冬泉信使，阻止他们向冬泉村运送物品。", desc="在木喉入口或朽木大锅附近找到一名孤独的信使。"}, [8]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [9]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", tag="可选", desc="为 59 级精英和附近的熊怪集结。"}, [10]={hint="冬泉谷的多诺瓦·雪山要你去击败冬泉酋长。", tag="可选", desc="先清掉外面的小怪。如果信件掉落并且您需要链条，请跟进。"}, [11]={npc="潦草的日志", npcObj=true, tag="可选", desc="如果冬泉酋长掉落了日志，请右键单击该日志。"}, [12]={hint="把潦草的日志交给冬泉谷的多诺瓦·雪山。", tag="可选"}, [13]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", tag="可选"}, [14]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", tag="可选"}, [15]={npc="乌米", tgt="乌米"}, [16]={hint="根据多诺瓦·雪山的指示行动，然后回到她那里报告。", desc="停在峡谷入口处。避开内心深处的精英。"}, [17]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [18]={text="60级以下？杀死峡谷北入口外的普通癫狂碎齿熊。"}}},
    ["05-d34"] = {name="黑石塔上层", entrance="灼热峡谷（1427）、34.80, 85.30。标记为黑石山的方法。", pickup="在 55 级，从永望镇飞往奥格瑞玛，然后乘坐齐柏林飞艇前往东部王国。做降低黑石塔任务高图斯的命令，然后从卡加斯的军官高图斯拿走伊崔格的智慧。 棘齿城之后，在智慧谷中看到伊崔格和萨尔并保留为部落而战！。在57级时，在幽暗城药房中取得薇薇安·拉格雷和黑暗石板，然后飞往卡加斯交给Vivian并取得黑暗石板。至少有一名党员完成晋升印章→晋升印章并带上印章。如果有人已经拥有，请直接前往上层黑石塔。", pickupS={{"在 55 级，从永望镇飞往奥格瑞玛，然后乘坐齐柏林飞艇前往东部王国"}, {"做降低黑石塔任务高图斯的命令，然后从卡加斯的军官高图斯拿走伊崔格的智慧"}, {"棘齿城之后，在智慧谷中看到伊崔格和萨尔并保留为部落而战！"}, {"在57级时，在幽暗城药房中取得薇薇安·拉格雷和黑暗石板，然后飞往卡加斯交给Vivian并取得黑暗石板"}, {"至少有一名党员完成晋升印章→晋升印章并带上印章"}, {"如果有人已经拥有，请直接前往上层黑石塔"}}, tips={{k="動線", text="通关七个符文 → 烈焰卫士艾博希尔 → 巢穴碑记 → 黑手大厅 → 竞技场撕裂和盖斯 → 锻造，其中比斯巨兽可选 → 达基萨斯将军位于王座，身后有他的烙印。"}, {k="取捨", text="首先接卡加斯和奥格瑞玛任务。仅当您需要团队协调时才执行黑手的命令。"}, {k="說明", text="使用与下层黑石塔共用的入口。向左走，找到上锁的门。带上晋升印章的人。 起飞指南显示门顺序。如果跳跃挡住了您的道路，请使用外侧的上部走道。", s={{"使用与下层黑石塔共用的入口"}, {"向左走，找到上锁的门"}, {"带上晋升印章的人"}, {"起飞指南显示门顺序"}, {"如果跳跃挡住了您的道路，请使用外侧的上部走道"}}}}, steps={[1]={npc="军官高图斯", tgt="军官高图斯", desc="如果没有任务窗口打开，请与 NPC 交谈并使用包里的命令。"}, [2]={hint="杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。", desc="文档可以移动。当你到达前三个房间时，检查每个房间。文件可能出现在任一首领房间，逐间查看。"}, [3]={npc="军官高图斯", tgt="军官高图斯"}, [4]={npc="军官高图斯", tgt="军官高图斯", preText="高图斯的命令"}, [5]={hint="和奥格瑞玛的伊崔格谈一谈。讨论完毕后，咨询萨尔的意见。"}, [6]={npc="萨尔", tgt="萨尔"}, [7]={npc="萨尔", tgt="萨尔", preText="伊崔格的智慧"}, [8]={npc="药剂师金格", tgt="药剂师金格", tag="可选", desc="57 号在幽暗城的药剂室接载。如果您有 黑暗石板，请跳过此线索。"}, [9]={hint="与卡加斯的暗法师薇薇安·拉格雷谈一谈。", tag="可选"}, [10]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷", tag="可选"}, [11]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷", desc="如果有的话，可以从维维安那里接。否则从幽暗城中的 薇薇安·拉格雷和黑暗石板 开始。"}, [12]={npc="黑手的命令", npcObj=true, tag="可选", desc="掠夺并使用黑石塔外军需官的信件来访问 BWL。"}, [13]={text="黑石塔上层 入口"}, [14]={hint="去黑石塔杀死大酋长雷德·黑手，带着他的头颅返回奥格瑞玛。", desc="位置：穿过鸦巢前往黑手厅。进入竞技场北门触发撕裂。顺序：从竞技场前的孵化场取出平板电脑。", spot="穿过鸦巢前往黑手厅。进入竞技场北门触发撕裂。"}, [15]={hint="将黑暗石板交给卡加斯的暗法师薇薇安·拉格雷。", desc="留在路上并避开鸡蛋。 破碎者蛋生成幼龙。位置：烈焰卫士艾博希尔后，进入鸟巢。检查靠墙的地板。顺序：在步骤 13 中的竞技场之前做这个任务。", spot="烈焰卫士艾博希尔后，进入鸟巢。检查靠墙的地板。"}, [16]={hint="真是个愚蠢的兽人。看来你需要找到那枚烙印并获得达基萨斯徽记才可以使用命令宝珠。", tag="可选", desc="烙印在达基萨斯身后。位置：离开竞技场的南门并经过熔炉。品牌是老板的背后。顺序：杀死达基萨斯，然后点击他身后的烙印。", spot="离开竞技场的南门并经过熔炉。品牌是老板的背后。"}, [17]={npc="达基萨斯的烙印", npcObj=true, tag="可选、需要游戏内检查", spot="达基萨斯王座后方的烙印"}, [18]={npc="萨尔", tgt="萨尔"}, [19]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷"}}},
    ["05-d33"] = {name="Blackmaw Hold", entrance="冬泉谷 66.60, 84.40", pickup="从瓦罗莫克中的杰迪加中取出 Beneath Nordrassil，从奥汀克中取出 撕裂之爪，刺骨之牙。 55级返回艾萨拉找艾卡尔。经棘齿城返回卡利姆多后，飞到雷霆崖的长者高地，交出杰迪加的信，拿Get to the Roots of It。访问莫高雷的穆恩·大地之怒。飞往瓦罗莫克并通过艾萨拉隧道进入。保存 Get to the Roots of It 和 Blackmaw Magic 以便下次访问雷霆崖和莫高雷。", pickupS={{"从瓦罗莫克中的杰迪加中取出 Beneath Nordrassil，从奥汀克中取出 撕裂之爪，刺骨之牙"}, {"55级返回艾萨拉找艾卡尔"}, {"经棘齿城返回卡利姆多后，飞到雷霆崖的长者高地，交出杰迪加的信，拿Get to the Roots of It"}, {"访问莫高雷的穆恩·大地之怒"}, {"飞往瓦罗莫克并通过艾萨拉隧道进入"}, {"保存 Get to the Roots of It 和 Blackmaw Magic 以便下次访问雷霆崖和莫高雷"}}, tips={{k="動線", text="在入口隧道中掠夺黑喉袋→在地下收集诺达希尔根帽→用于枯颌和不屈的白骨之吻的树枝→用于仪式图腾的长者萨满血鬃。确切的分叉和老板订单尚未确认。"}, {k="取捨", text="通过时请做好奥汀克和埃达拉斯废墟的准备工作。在一次雷霆崖访问中完成部落 rootcap 链。"}, {k="說明", text="传送门图钉出现在冬泉谷地图上。进入艾萨拉 (38.70, 33.40) 中的熊怪隧道并跟随它到达传送门。不要在冬泉谷表面寻找它。", s={{"传送门图钉出现在冬泉谷地图上"}, {"进入艾萨拉 (38.70, 33.40) 中的熊怪隧道并跟随它到达传送门"}, {"不要在冬泉谷表面寻找它"}}}}, steps={[1]={npc="杰迪加", tgt="杰迪加", tag="需要游戏内检查"}, [2]={hint="Speak to Nara Wildmane at Elder Rise in Thunder Bluff.", tag="需要游戏内检查"}, [3]={npc="纳拉·蛮鬃", tgt="纳拉·蛮鬃", tag="需要游戏内检查"}, [4]={npc="纳拉·蛮鬃", tgt="纳拉·蛮鬃", tag="需要游戏内检查", preText="Beneath Nordrassil"}, [5]={npc="奥汀克", tgt="奥汀克"}, [6]={npc="阿拉娜·风暴行者", tgt="Muln Earthfury", desc="在雷霆崖的路径上使用莫高雷映射引脚。"}, [7]={npc="Ekkal", tgt="Ekkal"}, [8]={text="Blackmaw Hold 入口"}, [9]={hint="Gather 10 Nordrassil Root Caps inside Blackmaw Hold for Nara Wildmane in Thunder Bluff.", tag="需要游戏内检查", desc="位置：沿着通道到达地下根部并在那里收集根冠。", spot="沿着通道到达地下根部并在那里收集根冠。"}, [10]={hint="将巨熊之爪与不屈者之牙交给艾萨拉的奥汀克。", tag="目标：巨人小熊枯颌 / 不屈的白骨之吻、需要游戏内检查", desc="位置：在隧道中找到枯颌和不屈的白骨之吻。分叉未经确认。", spot="在隧道中找到枯颌和不屈的白骨之吻。分叉未经确认。"}, [11]={hint="Recover a Blackmaw Ritual Totem from Blackmaw Hold.", tag="需要游戏内检查", desc="位置：沿着 Boss 路线前往长者萨满血鬃并掠夺他的仪式图腾。", spot="沿着 Boss 路线前往长者萨满血鬃并掠夺他的仪式图腾。"}, [12]={hint="掉落自：Blackmaw Berserker、Blackmaw Thrall、Blackmaw Headhunter", desc="位置：清除生活区中腐化的黑喉熊怪和战利品袋。", spot="清除生活区中腐化的黑喉熊怪和战利品袋。"}, [13]={npc="奥汀克", tgt="奥汀克"}, [14]={npc="Ekkal", tgt="Ekkal"}, [15]={npc="纳拉·蛮鬃"}, [16]={npc="阿拉娜·风暴行者", tgt="Muln Earthfury"}}},
  },
  quests = {
    [2] = {n="沙普塔隆的爪子", d="将沙普塔隆的爪子交给灰谷碎木哨岗的塞娜尼·雷心。"},
    [10] = {n="谢申克的救赎", d="寻找初级勘探员谢申克的下落，把他或者他的勘探设备交给加基森的高级勘探员菲兹杜瑟。", objs={"谢申克的勘探设备"}},
    [23] = {n="乌萨苟斯的爪子", d="将乌萨苟斯的爪子交给灰谷碎木哨岗的的塞娜尼·雷心。"},
    [24] = {n="萨杜布拉的头颅", d="将萨杜布拉的头颅交给灰谷碎木哨岗的的塞娜尼·雷心。"},
    [25] = {n="石爪山的困境", d="清除位于碎木哨岗西南和石爪小径正东的密斯特拉湖一带的12个污浊的水元素。\n在密斯特拉湖上的眺望台中侦查联盟的前哨站。\n返回灰谷慰藉之林的碎木哨岗，向马斯托克·维尔西斯报告。", tgo={{"污浊的水元素"}}},
    [27] = {n="必修的课程", d="与月光林地永夜港的德迪利特·星焰谈一谈。"},
    [28] = {n="湖中试炼", d="在月神湖寻找神殿灵珠，把它带到月光林地西北部的雷姆洛斯神殿去。在神殿中使用神殿灵珠，然后与神殿中的塔加里谈话来完成试炼。", objs={"雷姆洛斯神殿"}},
    [30] = {n="海狮试炼", d="寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。\n在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。\n将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。", objs={"雷姆洛斯神殿"}},
    [31] = {n="水栖形态", d="回到雷霆崖，让图拉克·符文图腾看看你的海狮坠饰。"},
    [32] = {n="异种蝎的威胁", d="把报告带给奥格瑞玛的基尔兹宾·鼓眼。"},
    [63] = {n="水之召唤", d="击败堕落的水之魂，把堕落水之魂的护腕和剩余的最纯净的水放在银松森林的圣泉火盆上。", tgo={{"堕落的水之魂"}}},
    [82] = {n="腐化之巢", d="从腐化之巢找5个森提帕尔昆虫肢体，把它们交给加基森的炼金师匹斯特苏格。", tgo={{"森提帕尔异种蝎", "森提帕尔毒刺蝎", "森提帕尔群居蝎"}}},
    [96] = {n="水之召唤", d="把水灵碎片交给贫瘠之地的水之先知伊斯伦。"},
    [99] = {n="阿鲁高的愚行", d="给瑟伯切尔的达拉尔·道恩维沃尔带回6副焚木镣铐。", tgo={{"焚木村守卫", "月怒守卫", "月怒哨兵"}}},
    [100] = {n="水之召唤", d="和银松森林的水之魂谈一谈。"},
    [110] = {n="昆虫研究", d="到加基森的炼金师匹斯特苏格那里去了解关于昆虫的研究有没有新的进展。"},
    [113] = {n="昆虫研究", d="把这份报告带给加基森的高级勘探员菲兹杜瑟，让他按照炼金师匹斯特苏格的要求为你复制一份报告。"},
    [185] = {n="猎虎", d="奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只荆棘谷猛虎幼崽。", tgo={{"荆棘谷猛虎幼崽"}}},
    [186] = {n="猎虎", d="奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只荆棘谷猛虎。", tgo={{"荆棘谷猛虎"}}},
    [187] = {n="猎虎", d="奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只老年荆棘谷猛虎。", tgo={{"老年荆棘谷猛虎"}}},
    [188] = {n="猎虎", d="奈辛瓦里远征队的艾耶克·罗欧克要求你杀死辛达尔并带回它的爪子。", tgo={{"辛达尔"}}},
    [189] = {n="血顶巨魔的耳朵", d="给藏宝海湾的科博克带回15只血顶巨魔的耳朵。", tgo={{"血顶战士", "血顶斥候", "血顶猎人"}}},
    [190] = {n="猎豹", d="奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只猎豹幼崽。", tgo={{"猎豹幼崽"}}},
    [191] = {n="猎豹", d="奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只黑豹。", tgo={{"黑豹"}}},
    [192] = {n="猎豹", d="奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只深喉猎豹。", tgo={{"深喉猎豹"}}},
    [193] = {n="猎豹", d="奈辛瓦里远征队的埃尔加丁爵士要求你杀死巴尔瑟拉，并带回它的牙。", tgo={{"巴尔瑟拉"}}},
    [194] = {n="猎龙", d="赫米特·奈辛瓦里要求你杀死10只荆棘谷迅猛龙。", tgo={{"荆棘谷迅猛龙"}}},
    [195] = {n="猎龙", d="赫米特·奈辛瓦里要求你杀死10只鞭尾迅猛龙。", tgo={{"鞭尾迅猛龙"}}},
    [196] = {n="猎龙", d="赫米特·奈辛瓦里要求你杀死10只丛林捕猎者。", tgo={{"丛林捕猎者"}}},
    [197] = {n="猎龙", d="赫米特·奈辛瓦里要求你杀死荆棘谷中最危险最狡猾的迅猛龙泰希斯。", tgo={{"泰希斯"}}},
    [201] = {n="调查营地", d="找到猎人营地并向藏宝海湾的克拉兹克报告这个营地的位置。"},
    [208] = {n="王牌猎人", d="赫米特·奈辛瓦里要求你将虎王邦加拉什的头带回来给他。", tgo={{"虎王邦加拉什"}}, star={"狩猎高手的猎弓 / 狩猎高手的火枪"}},
    [209] = {n="劈颅巨魔的獠牙", d="给藏宝海湾的科博克带回18根劈颅巨魔的獠牙。", tgo={{"劈颅战士", "劈颅猎人", "劈颅巫医"}}},
    [213] = {n="恶性竞争", d="给藏宝海湾的科博克带回8块打磨过的水晶。", tgo={{"风险投资公司地质学家"}}},
    [216] = {n="蓟皮熊怪的麻烦", d="杀死12个蓟皮复仇者和12个蓟皮萨满祭司。他们大部分都位于佐拉姆海岸东部的蓟皮村里。任务完成后回到灰谷佐拉姆加前哨站的卡拉恩·阿玛卡那里复命。", tgo={{"蓟皮复仇者"}, {"蓟皮萨满祭司"}}},
    [220] = {n="水之召唤", d="把最纯净的水交给贫瘠之地的伊斯伦。"},
    [247] = {n="完成狩猎"},
    [264] = {n="至死方休", d="把克拉莉斯的坠饰放在银松森林尤瑞夫的坟墓上。"},
    [348] = {n="荆棘谷热疫", d="找到巫医安巴格瓦并要求他召唤出野人莫克，然后将野人莫克的心脏交给芬·菲兹拉克。", tgo={{"野蛮的莫克"}}},
    [349] = {n="荆棘谷热疫", d="掉落自：迷雾谷猩猩、丛林大猩猩、暴怒的银背猩猩", tgo={{"迷雾谷猩猩", "丛林大猩猩", "暴怒的银背猩猩"}}},
    [354] = {n="阿加曼德家族", d="把格里高的遗骸、妮萨的残骸和萨尔曼的遗骸交给布瑞尔的库勒曼·法席恩。", tgo={{"格里高·阿加曼德"}, {"妮萨·阿加曼德"}, {"萨尔曼·阿加曼德"}}},
