    [4737] = {n="寻找梅纳拉·沃伦德", d="与贫瘠之地的梅纳拉·沃伦德谈一谈。"},
    [4739] = {n="寻找梅纳拉·沃伦德", d="与贫瘠之地的梅纳拉·沃伦德谈一谈。"},
    [4742] = {n="晋升印章", d="找到三块命令宝石：燃棘宝钻、尖石宝钻和血斧宝钻。把它们和原始晋升印章一起交给维埃兰。\n可能携带者三块宝石的将军是：燃棘氏族的指挥官沃恩、尖石氏族的欧莫克大王，以及血斧氏族的维姆萨拉克。", tgo={{"欧莫克大王"}, {"指挥官沃恩"}, {"维姆萨拉克"}, {"裂盾步兵", "裂盾哨兵", "裂盾侍僧"}}},
    [4743] = {n="晋升印章", d="到尘泥沼泽中的巨龙沼泽去。找到上古老龙埃博斯塔夫，对他发起无情的攻击，直到他的意志被摧毁。\n此时，你必须尽快将未铸造的晋升印章放在这条龙面前，并使用龙力宝珠控制他的躯体，强迫他将黑龙的烈焰喷向未铸造的晋升印章！", objs={"晋升徽记"}},
    [4767] = {n="驭风者", d="将10颗双足飞龙的蛋交给乱风岗的艾鲁。", objs={"风巢双足飞龙的蛋"}},
    [4768] = {n="黑暗石板", d="将黑暗石板交给卡加斯的暗法师薇薇安·拉格雷。", objs={"黑暗石板"}},
    [4769] = {n="薇薇安·拉格雷和黑暗石板", d="与卡加斯的暗法师薇薇安·拉格雷谈一谈。"},
    [4770] = {n="回家", d="护送波卡·雨山走出风巢，然后和白沙岗哨的莫特加·火鬃谈一谈。"},
    [4781] = {n="魔化金线血袍", d="将一块金锭交给荆棘谷的希兹克·古斯提。", objs={"破碎的箱子", "坚固的箱子", "联盟保险箱"}},
    [4782] = {n="魔化金线血袍", d="回到贫瘠之地的梅纳拉·沃伦德那里。"},
    [4783] = {n="魔化金线血袍", d="将10瓶怨怒萨特之血和1块次级地狱火石交给贫瘠之地的梅纳拉·沃伦德。", tgo={{"怨怒潜行者", "怨怒欺诈者", "怨怒魔仆"}, {"次级地狱火", "恶魔之门的卫士"}}},
    [4784] = {n="魔化金线血袍", d="将一些优质金线、2块闷烧煤和一块灵魂碎片交给贫瘠之地的梅纳拉·沃伦德。", tgo={{"希兹克·古斯提"}, {"烈焰流放者"}, {}}},
    [4785] = {n="优质金线"},
    [4786] = {n="完成金线血袍", d="等待梅纳拉·沃伦德织好披风，然后跟她谈一谈。", tgo={{"梅纳拉·沃伦德"}}, star={"魔化金线血袍", {"WARLOCK"}}},
    [4787] = {n="远古之卵", d="将远古之卵交给塔纳利斯的叶基亚。", objs={"远古之卵"}},
    [4808] = {n="菲诺克", d="把丁奇的信交给菲诺克。"},
    [4809] = {n="冰风奇美拉角", d="将8支完整的冰风奇美拉角交给菲诺克。", tgo={{"冰风奇美拉幼兽", "冰风奇美拉", "冰风破坏者"}}},
    [4810] = {n="返回丁奇身边", d="把菲诺克的包裹交给燃烧平原的丁奇·斯迪波尔。"},
    [4821] = {n="异型卵", d="把异型卵交给乱风岗的哈加尔·雷蹄。", objs={"异型蛋"}},
    [4841] = {n="清除半人马", d="杀掉12个加拉克斥候、10个加拉克争斗者和6个加拉克逐风者，然后向乱风岗的峭壁卫兵图林·长角复命。", tgo={{"加拉克斥候"}, {"加拉克争斗者"}, {"加拉克逐风者"}}},
    [4842] = {n="奇怪的源头", d="根据多诺瓦·雪山的指示行动，然后回到她那里报告。"},
    [4862] = {n="蜘蛛卵", d="到黑石塔去为基布雷尔收集15枚尖塔蜘蛛卵。\n听说那些蜘蛛周围有许多这样的卵。", objs={"尖塔蜘蛛卵"}},
    [4865] = {n="狂热之蛇", d="向莫特加·火鬃汇报你的发现。"},
    [4881] = {n="暗杀计划", d="将暗杀计划通知给白沙岗哨的卡纳提·灰云。"},
    [4903] = {n="高图斯的命令", d="杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。", tgo={{"维姆萨拉克"}, {"欧莫克大王"}, {"指挥官沃恩"}, {}}, objs={"不显眼的文件"}},
    [4904] = {n="终获自由", d="护送拉克塔·风歌离开恐怖图腾营地，然后与乱风岗的萨利亚谈一谈。"},
    [4921] = {n="在战斗中失踪", d="找到曼科里克的妻子，然后回到十字路口找他。", tgo={{"血肉模糊的尸体"}}},
    [4941] = {n="伊崔格的智慧", d="和奥格瑞玛的伊崔格谈一谈。讨论完毕后，咨询萨尔的意见。\n你回忆起曾在萨尔的大厅中见过伊崔格。"},
    [4961] = {n="奥拉赫宝珠的净化", d="杀死宝珠之魔，然后与塔贝萨谈一谈。", tgo={{"宝珠之魔"}}},
    [4962] = {n="地狱犬的灵魂", d="带上地狱犬红宝石到凄凉之地去，用它捕获一只地狱犬的灵魂。成功之后，将地狱犬红宝石和被禁锢的地狱犬灵魂交给贫瘠之地的梅纳拉·沃伦德。", tgo={{"噬法魔犬"}}},
    [4963] = {n="地狱火的灵魂", d="带上地狱火绿宝石到凄凉之地去，用它捕获一个地狱火的灵魂。成功之后，将地狱火绿宝石和被禁锢的地狱火灵魂交给贫瘠之地的梅纳拉·沃伦德。", tgo={{"次级地狱火"}}},
    [4964] = {n="达奥拉赫宝珠", d="等待梅纳拉·沃伦德完成达奥拉赫宝珠，然后再与她谈一谈。", tgo={{"梅纳拉·沃伦德"}}},
    [4966] = {n="保护卡纳提·灰云", d="保护卡纳提·灰云免受半人马的袭击。", tgo={{"加拉克刺客"}}},
    [4967] = {n="奥拉赫宝珠", d="与贫瘠之地的梅纳拉·沃伦德谈一谈。"},
    [4969] = {n="奥拉赫宝珠", d="与贫瘠之地的梅纳拉·沃伦德谈一谈。"},
    [4971] = {n="时间问题", d="在安多哈尔的一处仓库附近使用时光置换器，使时光寄生虫现身。\n杀掉15只时光寄生虫，然后将时光置换器还给西瘟疫之地安多哈尔旅店的克罗米。", tgo={{"时光寄生虫"}}},
    [4972] = {n="找回时间", d="在安多哈尔城中四处散落的保险箱里找到5只安多哈尔怀表，然后把它们交给西瘟疫之地安多哈尔旅店里的克罗米。", objs={"小箱子"}},
    [4974] = {n="为部落而战！", d="去黑石塔杀死大酋长雷德·黑手，带着他的头颅返回奥格瑞玛。", tgo={{"大酋长雷德·黑手"}}},
    [4975] = {n="诺奥拉赫宝珠", d="等待梅纳拉·沃伦德完成诺奥拉赫宝珠，然后再与她谈一谈。", tgo={{"梅纳拉·沃伦德"}}},
    [4976] = {n="归还净化过的宝珠", d="将净化过的地狱火宝珠交给贫瘠之地的梅纳拉·沃伦德。"},
    [4981] = {n="狡猾的比修", d="到黑石塔去查明比修的下落。"},
    [4982] = {n="比修的装置", d="找到比修的装置并把它们还给她。你记得她说过她把装置藏在城市的最底层。", objs={"比修的装置"}},
    [4983] = {n="比修的侦察报告", d="把比修的侦查报告交给卡加斯的雷克斯洛特。"},
    [4984] = {n="大自然的苦楚", d="消灭8只生病的狼，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。", tgo={{"生病的狼"}}},
    [4985] = {n="大自然的苦楚", d="消灭8只生病的灰熊，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。", tgo={{"生病的灰熊"}}},
    [5021] = {n="迟到总比不到好", d="这个女人的幽灵告诉你她要送出一只包裹。她说那只包裹就在她的马旁边。至于马在哪里或者包裹要送到哪里去，她却根本没有说。"},
    [5023] = {n="迟到总比不到好", d="与幽暗城的皇家管理人巴哈乌斯协商，查找杰雷米亚·费尔斯通的下落。通常在公会注册处附近会有一个人口普查官。"},
    [5041] = {n="十字路口的补给品", d="找到十字路口的补给箱，把它还给贫瘠之地的索克。", objs={"十字路口的补给箱"}},
    [5049] = {n="杰雷米亚的忧伤", d="在幽暗城找到杰雷米亚·派森并查明他是否就是你要找的杰雷米亚·费尔斯通。如果他是的话，那么他可能会想要拿到詹妮丝·费尔斯通寄给他的包裹。"},
    [5050] = {n="好运护符", d="把半个好运护符还给西瘟疫之地的詹妮丝·费尔斯通。"},
    [5051] = {n="两半合一", d="在西瘟疫之地的费尔斯通农场某地找到另外一半好运护符，并把两半护符合并。\n把好运护符交给西瘟疫之地费尔斯通农场的詹妮丝·费尔斯通。"},
    [5052] = {n="阿迦玛甘的血岩碎片", d="给陶拉祖营地的碎牙带去一块血岩碎片。\n如果你想要他赐予你阿迦玛甘的力量，就搜集更多的血岩碎片。", tgo={{"刺背猎手", "刺背寻水者", "刺背织棘者"}}},
    [5054] = {n="碎齿熊尤西乌斯", d="永望镇的斯托姆·影蹄想要你去杀死尤西乌斯。", tgo={{"尤西乌斯"}}},
    [5058] = {n="达尔松夫人的日记"},
    [5059] = {n="被锁起来的农夫", d="掉落自：游荡的骷髅", tgo={{"游荡的骷髅"}}},
    [5060] = {n="被锁起来的农夫", d="掉落自：农夫达尔松", tgo={{"农夫达尔松"}}},
    [5062] = {n="神圣之火", d="收集10支火岩龙舌兰，然后去找雷霆崖长者高地的玛加萨·恐怖图腾。", objs={"火焰龙舌兰"}},
    [5064] = {n="恐怖图腾的密信", d="在黑云峰拿到三封密信。", objs={"文件箱"}},
    [5082] = {n="冬泉熊怪的威胁", d="冬泉谷的多诺瓦·雪山要你去杀死8个冬泉探路者、8个冬泉巢穴守卫和8个冬泉图腾师。", tgo={{"冬泉探路者"}, {"冬泉巢穴守卫"}, {"冬泉图腾师"}}},
    [5083] = {n="冬泉火酒", d="将空的火酒瓶交给冬泉谷的多诺瓦·雪山。"},
    [5084] = {n="堕落熊怪", d="搜寻费伍德森林北部的死木熊怪的营帐，继续寻找线索。"},
    [5085] = {n="神秘的粘液", d="将你的发现报告给多诺瓦·雪山。"},
    [5086] = {n="剧毒之水", d="为冬泉谷的多诺瓦·雪山收集3份剧毒水滴。", tgo={{"剧毒之水"}}},
    [5087] = {n="冬泉信使", d="找到冬泉信使，阻止他们向冬泉村运送物品。", tgo={{"冬泉信使"}}},
    [5096] = {n="误导血色十字军", d="到血色十字军建在费尔斯通农场和达尔松之泪之间的营地去，摧毁他们的指挥帐篷。\n将亡灵天灾的战旗插在营地中，然后回到西瘟疫之地亡灵壁垒的高级执行官德灵顿那儿。"},
    [5098] = {n="标记哨塔", d="使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。\n在做完了标记之后，将信号火炬还给西瘟疫之地亡灵壁垒的高级执行官德灵顿。", tgo={{"安多哈尔一号哨塔"}, {"安多哈尔二号哨塔"}, {"安多哈尔三号哨塔"}, {"安多哈尔四号哨塔"}}},
    [5121] = {n="冬泉酋长", d="冬泉谷的多诺瓦·雪山要你去击败冬泉酋长。", tgo={{"冬泉酋长"}}},
    [5122] = {n="信仰奖章", d="使用／收集：玛洛尔的保险箱", objs={"玛洛尔的保险箱"}},
    [5123] = {n="最后一片", d="把潦草的日志交给冬泉谷的多诺瓦·雪山。"},
    [5125] = {n="奥里克斯的清算"},
    [5147] = {n="通缉：阿纳克·恐怖图腾", d="杀死阿纳克·恐怖图腾，并向乱风岗的峭壁卫兵图林·长角出示证据。", tgo={{"阿纳克·恐怖图腾"}}},
    [5149] = {n="帕米拉的洋娃娃", d="找到帕米拉的洋娃娃。"},
    [5151] = {n="超适应齿轮", d="杀了那头野兽，把超适应齿轮和钥匙交给维兹罗。", tgo={{"被激怒的黑豹"}}},
    [5152] = {n="玛莱恩姑妈", d="与安多哈尔废墟南边的玛莱恩谈一谈。"},
    [5153] = {n="古怪的历史学家", d="把约瑟夫的结婚戒指交给安多哈尔的克罗米。", objs={"约瑟夫·雷德帕斯的纪念碑"}},
    [5154] = {n="达隆郡的历史", d="把《达隆郡的历史》交给安多哈尔的克罗米。", objs={"发霉的书籍"}},
    [5155] = {n="加德纳尔的势力", d="到加德纳尔去杀掉4个加德纳尔恶犬、4个加德纳尔守护者、6个加德纳尔精兵和6个加德纳尔祭司，然后向费伍德森林的格雷塔·苔蹄复命。", tgo={{"加德纳尔恶犬"}, {"加德纳尔守护者"}, {"加德纳尔精兵"}, {"加德纳尔祭司"}}},
    [5156] = {n="验证腐蚀", d="杀掉2个热能野兽和2个热能恐兽，并探索碎痕谷。然后查看凹坑中是否仍然充满了堕落的恶臭之水，完成这些任务之后，向费伍德森林中的塔诺恩·红羽复命。", tgo={{"热能野兽"}, {"热能恐兽"}}},
    [5157] = {n="收集堕落之水", d="把空壶拿到加德纳尔中心的月亮井去，装满井水之后再回到费伍德森林的格雷塔·苔蹄那里。", objs={"加德纳尔月亮井"}},
    [5158] = {n="水之魂的帮助", d="把腐化的月亮井水交给贫瘠之地的水之先知伊斯伦。"},
    [5159] = {n="净化过的水", d="把净化过的月亮井水交给费伍德森林的格雷塔·苔蹄。"},
    [5163] = {n="雪怪计划！", d="带着乌米的机械雪人去吓唬她的朋友：\n永望镇的莱加奇（冬泉谷）、加基森的斯普琳科（塔纳利斯），还有马绍尔营地的奎克希尔（安戈洛环形山）。\n当你完成任务之后，把机械雪人还给乌米。", tgo={{"莱加奇"}, {"斯普琳科"}, {"奎克希尔"}}},
    [5165] = {n="熄灭火焰", d="使用净化过的月亮井水熄灭暗影堡内部的四座火盆的火焰，从而破除其保护效果，然后向翡翠圣地的格雷塔·苔蹄复命。", objs={"痛苦火盆", "怨意火盆", "受难火盆", "仇恨火盆"}},
    [5211] = {n="达隆郡的保卫者", d="释放15个达隆郡居民的灵魂，然后返回卡林·雷德帕斯身边。", tgo={{"达隆郡居民的灵魂"}}},
    [5212] = {n="血肉不会撒谎", d="从斯坦索姆找回20个瘟疫肉块，并把它们交给贝蒂娜·比格辛克。你觉得斯坦索姆中的生灵都不大可能长着肉……", tgo={{"被毁坏的死尸", "被撕裂的死尸", "恶疫食尸鬼"}}},
    [5213] = {n="活跃的探子", d="到斯坦索姆去探索那里的通灵塔。找到新的天灾军团档案，把它交给贝蒂娜·比格辛克。", objs={"天灾军团档案"}},
    [5214] = {n="了不起的艾兹拉·格里姆", d="找到艾兹拉·格里姆在斯坦索姆的烟草店，并从中找回一盒格里姆的优质香烟，把它交给烟鬼拉鲁恩。", tgo={{"弗拉斯·希亚比"}}},
    [5228] = {n="瘟疫之锅", d="与西瘟疫之地亡灵壁垒的暗影牧师范蒂丝谈一谈。"},
    [5229] = {n="目标：费尔斯通农场", d="到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。", tgo={{"护锅者拜尔摩"}}},
    [5230] = {n="返回亡灵壁垒", d="把费尔斯通农场的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"},
    [5231] = {n="目标：达尔松之泪", d="到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带达尔松之泪的空瓶来采集瘟疫之锅中的毒药样本。", tgo={{"护锅者玛维诺斯"}}},
    [5232] = {n="返回亡灵壁垒", d="把装满的达尔松眼泪之瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"},
    [5233] = {n="目标：嚎哭鬼屋", d="到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带嚎哭鬼屋的空瓶来采集瘟疫之锅中的毒药样本。", tgo={{"护锅者拉扎奇"}}},
    [5234] = {n="返回亡灵壁垒", d="把嚎哭鬼屋的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"},
    [5235] = {n="目标：盖罗恩农场", d="到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。", tgo={{"护锅者索瓦斯"}}},
    [5236] = {n="返回亡灵壁垒", d="把盖罗恩农场的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"},
    [5238] = {n="任务完成！", star={"英勇短剑", {"PALADIN", "MAGE", "WARLOCK"}}},
    [5241] = {n="卡林叔叔", d="找到卡林·瑞德巴思。"},
    [5242] = {n="最终一击", d="杀掉米莱恩和萨莉亚，并把暗影领主费尔丹的头颅交给费伍德森林的格雷塔·苔蹄。", tgo={{"米莱恩"}, {"萨莉亚"}, {"暗影领主费尔丹"}}},
    [5243] = {n="神圣之屋", d="到北方的斯坦索姆去，寻找散落在城市中的补给箱，并收集5瓶斯坦索姆圣水。当你找到足够的圣水之后就回去向莱尼德·巴萨罗梅复命。", objs={"补给箱", "斯坦索姆物资箱"}},
    [5251] = {n="档案管理员", d="在斯坦索姆城中找到血色十字军的档案管理员加尔福特，杀掉他，然后烧毁血色十字军档案。", tgo={{"档案管理员加尔福特"}, {}}, objs={"血色十字军档案"}},
    [5281] = {n="永不安息的灵魂", d="找到埃根。你只知道他在斯坦索姆附近。"},
    [5282] = {n="永不安息的灵魂", d="对斯坦索姆城中的鬼魂使用埃根的冲击器。当那些永不安息的灵魂挣脱他们的外壳时，再次使用埃根的冲击器——他们就可以获得自由了！\n解放15个永不安息的灵魂，然后回到埃根那里去。", tgo={{"永不安息的灵魂"}}},
    [5306] = {n="沃什加斯的菊石", d="到黑石塔去杀死暗影猎手沃什加斯，将沃什加斯的菊石交给基尔拉姆。", tgo={{"暗影猎手沃什加斯"}}},
    [5341] = {n="巴罗夫家族的宝藏", d="到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到阿莱克斯·巴罗夫那儿去。", objs={"布瑞尔地契", "凯尔达隆地契", "南海镇地契", "塔伦米尔地契"}},
    [5361] = {n="兄弟", d="将峭壁卫兵图林·长角的报告交给凄凉之地幽灵岗哨的纳塔卡·长角。"},
    [5381] = {n="埃鲁索斯之手", d="在雷斧堡垒中找到恶魔之盒，把它和恶魔之锄一起交给葬影村的泰迦·慧鬃。", tgo={{"恶魔灵魂"}}},
    [5382] = {n="瑟尔林·卡斯迪诺夫教授", d="在通灵学院中找到瑟尔林·卡斯迪诺夫教授。杀死他，并烧毁艾瓦·萨克霍夫和卢森·萨克霍夫的遗体。任务完成后就回到艾瓦·萨克霍夫那儿。", tgo={{"瑟尔林·卡斯迪诺夫教授"}, {}, {}}, objs={"艾瓦·萨克霍夫的遗体", "卢森·萨克霍夫的遗体"}},
    [5386] = {n="食鱼度日", d="与葬影村的吉纳泽林谈话，然后将2条血肚鱼交给纳塔卡·长角。", tgo={{"吉纳泽林"}}},
    [5441] = {n="懒惰的苦工", d="在懒惰的苦工睡觉时，用工头的木棒敲他们。敲醒5个苦工，然后把工头的木棒还给试炼谷的工头塔兹利尔。", tgo={{"懒惰的苦工"}}},
    [5481] = {n="葛尔多的任务", d="收集3根阴暗草，把它们交给布瑞尔墓地的初级药剂师霍兰德。", objs={"阴暗草"}},
    [5482] = {n="末日草", d="收集10株末日草，把它们交给初级药剂师霍兰德。", objs={"末日草"}},
    [5501] = {n="集骨者", d="从科多墓地收集10根科多兽骨，把它们交给兽人小屋的比布里·弗斯巴克。", objs={"科多兽骨"}},
    [5511] = {n="通灵学院的钥匙"},
    [5514] = {n="昂贵的模具", d="把灌魔的骸骨碎片和15枚金币交给加基森的克林科·古德斯迪尔。"},
    [5518] = {n="戈多克食人魔装", d="把4份符文布卷、8块硬甲皮、2卷符文线和一份食人魔鞣酸交给诺特·希姆加克。他现在被拴在厄运之槌的戈多克食人魔那边。", objs={"Felsteel Chest", "食人魔鞣酸篮", "诺特·希姆加克的储物箱"}},
    [5525] = {n="逃出生天！", d="掉落自：戈多克蛮兵、戈多克大法师、戈多克领主", tgo={{"戈多克蛮兵", "戈多克大法师", "戈多克领主"}}},
    [5526] = {n="魔藤碎片", d="在厄运之槌中找到魔藤，然后从它上面采集一块碎片。只有干掉了奥兹恩之后，你才能进行采集工作。使用净化之匣安全地封印碎片，然后将其交给月光林地永夜港的拉比恩·萨图纳。"},
    [5527] = {n="净化之匣", d="到希利苏斯的南风村去寻找净化之匣。然后将其交给月光林地永夜港的拉比恩·萨图纳。", objs={"覆满灰尘的箱子"}},
    [5528] = {n="戈多克好酒"},
    [5529] = {n="瘟疫之龙", d="杀掉20只瘟疫龙崽，然后向圣光之愿礼拜堂的贝蒂娜·比格辛克复命。", tgo={{"瘟疫龙崽"}}},
    [5534] = {n="基姆加尔\"丢失\"的装备", d="寻找埃达拉斯废墟中的纳迦携带的那些符石，然后把它们交给艾萨拉的基姆加尔。", tgo={{"恶鞭海妖", "恶鞭侍从", "恶鞭军官"}}},
    [5535] = {n="永不安息的灵魂", d="杀掉6个上层精灵的幻影和6个上层精灵鬼巫，然后向艾萨拉的罗哈图复命。", tgo={{"上层精灵的幻影"}, {"上层精灵鬼巫"}}},
    [5536] = {n="充满仇恨的土地", d="杀掉6个哈达尔萨特、2个哈达尔欺诈者和2个哈达尔魔仆，然后向灰谷与艾萨拉交界处的罗哈图复命。", tgo={{"哈达尔萨特"}, {"哈达尔欺诈者"}, {"哈达尔魔仆"}}},
    [5542] = {n="恶魔之犬", d="杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。", tgo={{"瘟疫幼犬"}, {"瘟疫犬"}, {"狂怒的瘟疫犬"}}},
    [5543] = {n="血染的天空", d="杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。", tgo={{"瘟疫蝙蝠"}}},
    [5544] = {n="腐肉虫", d="在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。", tgo={{"腐肉虫", "腐肉吞噬者"}}},
    [5561] = {n="诱捕科多兽", d="将科多兽诱引器和5头被驯服的科多兽交给瑟卡布斯库的营地中的斯米德·瑟卡布斯库。"},
    [5581] = {n="燃烧军团的传送门", d="放逐6个玛诺洛克集会所的传送门，然后回到葬影村的泰迦·慧鬃那里。", tgo={{"恶魔之门的卫士"}}},
    [5601] = {n="小妹妹帕米拉", d="在达隆郡里找到帕米拉·雷德帕斯。"},
    [5648] = {n="灵魂之衣", d="找到步兵科雅，用次级治疗术（等级 2）治疗她，然后为她加上真言术：韧，最后向剃刀岭的泰金复命。", tgo={{"步兵科雅"}}},
    [5649] = {n="部族的传统", d="与杜隆塔尔的泰金谈一谈。"},
    [5650] = {n="黑暗之衣", d="找到亡灵士兵科尔并使用次级治疗术（等级 2）来治疗他。然后对他施放真言术：韧，最后向布瑞尔的黑暗牧师贝里尔复命。", tgo={{"亡灵卫兵科尔"}}},
    [5651] = {n="黑暗的恩赐", d="与提瑞斯法林地的黑暗牧师贝里尔谈一谈。"},
    [5652] = {n="虚弱妖术"},
    [5654] = {n="虚弱妖术", d="与奥格瑞玛的乌尔库谈一谈。"},
    [5658] = {n="虚弱之触"},
    [5679] = {n="黑暗献祭"},
    [5680] = {n="暗影守卫"},
    [5722] = {n="寻找背包", d="在怒焰裂谷搜寻玛尔·恐怖图腾的尸体以及他留下的东西。"},
    [5723] = {n="试探敌人", d="在奥格瑞玛找到怒焰裂谷，杀掉8个怒焰穴居人和8个怒焰萨满祭司，然后向雷霆崖的拉哈罗复命。", tgo={{"怒焰穴居人"}, {"怒焰萨满祭司"}}},
    [5724] = {n="归还背包", d="将恐怖图腾背包交给雷霆崖的拉哈罗。"},
    [5725] = {n="毁灭之力", d="将《暗影法术研究》和《扭曲虚空的魔法》这两本书交给幽暗城的瓦里玛萨斯。", tgo={{"燃刃信徒", "燃刃术士"}, {"燃刃信徒", "燃刃术士"}}},
    [5726] = {n="隐藏的敌人", d="将军官的徽章交给奥格瑞玛的萨尔。", tgo={{"火刃狂热者", "火刃学徒"}}},
    [5727] = {n="隐藏的敌人", d="将军官的徽章交给尼尔鲁·火刃并与他谈一谈，看看他是否相信你是火刃氏族中的一员，然后回到奥格瑞玛的萨尔那里。", tgo={{"尼尔鲁·火刃"}}},
    [5728] = {n="隐藏的敌人", d="杀死巴扎兰和祈求者耶戈什，然后回到奥格瑞玛的萨尔那里。", tgo={{"巴扎兰"}, {"祈求者耶戈什"}}},
    [5729] = {n="隐藏的敌人", d="与奥格瑞玛的尼尔鲁·火刃谈一谈。"},
    [5730] = {n="隐藏的敌人", d="与奥格瑞玛的萨尔谈一谈，告诉他你了解到的东西。"},
    [5741] = {n="圣光节杖", d="拿到圣光节杖，并将它交给艾瑟雷索塔里的阿佐尔·奥达蒙特。", tgo={{"火刃先知"}}},
    [5742] = {n="救赎", d="听听提里奥·弗丁要说什么。", tgo={{"提里奥·弗丁"}}},
    [5761] = {n="饥饿者塔拉加曼", d="进入怒焰裂谷，杀死饥饿者塔拉加曼，然后把他的心脏交给奥格瑞玛的尼尔鲁·火刃。", tgo={{"饥饿者塔拉加曼"}}},
    [5762] = {n="赫米特·奈辛瓦里", d="将克拉维尔的箱子送到荆棘谷的赫米特·奈辛瓦里那里。"},
    [5763] = {n="荆棘谷狩猎", d="将鲁恩的科多兽角送到荆棘谷的赫米特·奈辛瓦里那里。"},
    [5781] = {n="遗忘的记忆", d="到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。", tgo={{"米库提奥·污血"}}},
    [5802] = {n="火羽山", d="把骷髅钥匙模具和2块瑟银锭带到安戈洛尔环形山地区的火羽山顶部。在熔岩湖旁使用骷髅钥匙模具，铸造出一把未完工的骷髅钥匙。\n把未完工的骷髅钥匙交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。", objs={"火羽山熔岩湖"}},
    [5804] = {n="阿拉基的圣甲虫", d="杀掉召唤者阿拉基，并将阿拉基的圣甲虫交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。", objs={"阿拉基的护符匣"}},
    [5843] = {n="欢迎！", d="将试炼谷礼品券交给玛卡尔。"},
    [5844] = {n="欢迎！", d="将纳拉其营地礼品券交给沃恩·星眼。"},
    [5845] = {n="失落的荣耀", d="到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。", objs={"失落荣耀的象征"}},
    [5846] = {n="爱与家庭", d="到凯尔达隆岛去，寻找关于那副画的线索。凯尔达隆岛在瘟疫之地南部的湖中央。"},
    [5848] = {n="爱与家庭", d="到瘟疫之地北部的斯坦索姆去。你可以在血色十字军堡垒中找到\"爱与家庭\"这幅画，它被隐藏在另一幅描绘两个月亮的画之后。\n把这幅画还给提里奥·弗丁。", objs={"未完成的油画"}},
    [5863] = {n="砂槌食人魔", d="加基森的安迪·利恩想要你攻入砂槌营地，杀死10个砂槌蛮兵、10个砂槌执行者，以及掠夺者格玛洛克。", tgo={{"砂槌蛮兵"}, {"砂槌执行者"}, {"掠夺者格玛洛克"}}},
    [5881] = {n="召回卫兵", d="马格兰希望你将信送到贫瘠之地升降梯的瑞什·远行者手中。"},
    [5901] = {n="瘟疫与你", d="在东瘟疫之地的蚁丘上使用空的白蚁瓶。当你收集了100只瘟疫白蚁之后，就回到提瑞斯法林地的亡灵壁垒去找米克·莱文。", objs={"大白蚁丘"}},
    [5902] = {n="瘟疫与你", d="到西瘟疫之地的北山伐木场去找个合适的地方，在那里放下一桶瘟疫白蚁。"},
    [5922] = {n="月光林地", d="使用法术\"传送：月光林地\"抵达月光林地，在那里与永夜港的德迪利特·星焰谈一谈。"},
    [5926] = {n="响应召唤", d="与雷霆崖长者高地上的图拉克·符文图腾谈一谈。"},
    [5927] = {n="响应召唤", d="与雷霆崖长者高地上的图拉克·符文图腾谈一谈。"},
    [5928] = {n="响应召唤", d="与雷霆崖长者高地上的图拉克·符文图腾谈一谈。"},
    [5930] = {n="巨熊之灵", d="到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。", tgo={{"巨熊之灵"}}},
    [5932] = {n="返回雷霆崖", d="回到雷霆崖，与长者高地的图拉克·符文图腾谈一谈。"},
    [6002] = {n="身心之力", d="使用莫高雷与贫瘠之地交界处的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。\n任务完成之后，与雷霆崖的图拉克·符文图腾谈一谈。", tgo={{"月爪枭兽的灵魂"}}},
    [6022] = {n="杀戮的理由", d="到东边的考林路口去屠杀镇里的亡灵天灾。在10分钟内收集7块生命腐质，使用研钵和捣杵将其研磨成凝固腐质。"},
    [6027] = {n="上古之书", d="拿到上古之书，将其交给艾瑟雷索塔中的阿佐尔·奥达蒙特。", tgo={{"科拉加鲁"}}},
    [6029] = {n="永望镇报告", d="把永望镇报告送给西瘟疫地亡灵壁垒的银色黎明军官加鲁什。"},
    [6030] = {n="尼古拉斯·瑟伦霍夫公爵", d="将《灵语研究》这本书交给东瘟疫之地圣光之愿礼拜堂的尼古拉斯·瑟伦霍夫公爵。"},
    [6042] = {n="讨厌的蝙蝠", d="杀掉20只毒性瘟疫蝙蝠和10只巨型瘟疫蝙蝠，然后回到纳萨诺斯·凋零者那里。", tgo={{"毒性瘟疫蝙蝠"}, {"巨型瘟疫蝙蝠"}}},
    [6061] = {n="驯服野兽", d="使用驯兽棒驯服成年陆行鸟。练习你的技能，然后将驯兽棒还给血蹄村的雅文·刺鬃。", tgo={{"成年平原陆行鸟"}}},
    [6062] = {n="驯服野兽", d="使用驯兽棒驯服可怕的杂斑野猪。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。", tgo={{"可怕的杂斑野猪"}}},
    [6065] = {n="猎人之道", d="与血蹄村的雅文·刺鬃谈一谈。"},
    [6066] = {n="猎人之道", d="与血蹄村的雅文·刺鬃谈一谈。"},
    [6067] = {n="猎人之道", d="与血蹄村的雅文·刺鬃谈一谈。"},
    [6068] = {n="猎人之道", d="与剃刀岭的索塔尔谈一谈。"},
    [6069] = {n="猎人之道", d="与剃刀岭的索塔尔谈一谈。"},
    [6070] = {n="猎人之道", d="与剃刀岭的索塔尔谈一谈。"},
    [6081] = {n="训练野兽", d="与奥格瑞玛的奥玛克谈一谈。"},
    [6082] = {n="驯服野兽", d="使用驯兽棒驯服硬甲蝎。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。", tgo={{"硬甲蝎"}}},
    [6083] = {n="驯服野兽", d="使用驯兽棒驯服海浪蟹。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。", tgo={{"海浪蟹"}}},
    [6087] = {n="驯服野兽", d="使用驯兽棒驯服一只草原捕食者。练习你的技能，然后将驯兽棒还给血蹄村的雅文·刺鬃。", tgo={{"草原捕食者"}}},
    [6088] = {n="驯服野兽", d="使用驯兽棒驯服一只猛鹫。练习你的技能，然后将驯服法杖交还给血蹄村的雅文·刺鬃。", tgo={{"猛鹫"}}},
    [6089] = {n="训练野兽", d="与雷霆崖猎人高地的浩特·雷角谈一谈。"},
    [6126] = {n="新的课程", d="到月光林地去，与永夜港的德迪利特·星焰谈一谈。"},
    [6127] = {n="毒水之源", d="使用空的鬼雾峰取样器在山顶取水样。\n将盛满的鬼雾峰取样器送到贫瘠之地十字路口的图加·符文图腾那里。", objs={"Dreadmist Peak Pool"}},
    [6128] = {n="收集解药", d="收集5个地根草和5个科多兽角，把它们交给十字路口的图加·符文图腾，这样他就可以制作解药了。", tgo={{"鞭笞者幼苗", "怨毒之藤"}, {"落单的草原科多兽", "草原科多兽"}}},
    [6129] = {n="消除疾病", d="对贫瘠之地北部的10只生病的瞪羚使用动物医疗药膏，以此来治疗它们。在穿过十字路口的那条东西走向的大路北面到处都是生病的蹬羚。", tgo={{"生病的瞪羚"}}},
    [6130] = {n="解毒之术", d="回到雷霆崖长者高地的图拉克·符文图腾那里。"},
    [6134] = {n="幽灵电浆", d="把幽灵磁铁箱和8份幽灵电浆交给凄凉之地的霍恩尼兹。", tgo={{"半人马幽灵"}}},
    [6142] = {n="蚌肉鱼饵", d="找到10块软壳蚌肉，把它们交给葬影村的麦拉斯。", tgo={{"狂怒的暗礁蟹"}}},
    [6143] = {n="另一种鱼", d="杀死7个滑刃侍从、7个滑刃纳迦，以及5个滑刃巫师，然后与葬影村的杜泽加尔谈谈。", tgo={{"滑刃侍从"}, {"滑刃纳迦"}, {"滑刃巫师"}}},
    [6161] = {n="拉克摩尔的财宝！", d="找到拉克摩尔的银钥匙和金钥匙。找到并打开拉克摩尔的箱子。", tgo={{"枯钳龙虾人", "枯钳巨螯龙虾人"}, {"滑刃纳迦", "滑刃巫师", "滑刃战士"}}},
    [6162] = {n="最后一战", d="杀死主宰洛尔，把他的爪子交给费伍德森林血毒岗哨的德雷卡苏。", tgo={{"主宰洛尔"}}},
    [6164] = {n="奥古斯图斯的收据册", d="把奥古斯图斯的收据册交给恶蛛隧道中的被感动的奥古斯图斯。", objs={"奥古斯图斯的单据"}},
    [6282] = {n="鹰身人的威胁", d="烈日石居的马格兰要你去杀掉7个血怒鹰身人、7个血怒伏击者、7个血怒杀戮者和7个血怒游荡者。", tgo={{"血怒鹰身人"}, {"血怒伏击者"}, {"血怒杀戮者"}, {"血怒游荡者"}}},
    [6283] = {n="血怒一族", d="烈日石居的马格兰要你去杀掉血怒撕裂者，然后把她的遗体带回来作为证据。", tgo={{"血怒撕裂者"}}},
    [6284] = {n="贝瑟莱斯", d="杀掉贝瑟莱斯，然后把贝瑟莱斯的牙齿交给烈日石居的马格兰。", tgo={{"贝瑟莱斯"}}},
    [6301] = {n="生生不息", d="烈日石居的塔姆拉·荒原想让你去收集10枚盖亚之种。", objs={"盖亚之种"}},
    [6381] = {n="新的生命", d="将10枚盖亚之种种植在盖亚土堆中，然后与烈日石居的塔姆拉谈一谈。", objs={"盖亚土堆"}},
    [6382] = {n="灰谷狩猎", d="与灰谷碎木哨岗的塞娜尼·雷心谈一谈。"},
    [6383] = {n="灰谷狩猎"},
    [6390] = {n="瘟疫与你", d="使用北山伐木场里的铁棍放出那里的瘟疫白蚁，然后向提瑞斯法林地亡灵壁垒的米克·莱文报告。"},
    [6393] = {n="元素战争", d="将10块焚火余烬交给烈日石居的苏纳曼。", tgo={{"游荡的焰灵", "燃烧的掠夺者", "燃烧的破坏者"}}},
    [6394] = {n="塔兹利尔的镐", d="将塔兹利尔的镐还给塔兹利尔。", objs={"塔兹利尔的镐"}},
    [6395] = {n="玛拉的遗愿", d="将塞缪尔·菲普斯的遗骸带到玛拉的坟墓去，然后回到新兵艾尔雷斯那里。", objs={"玛拉的坟墓"}},
    [6421] = {n="滚岩峡谷", d="深入滚岩峡谷的洞穴中，为烈日石居的摩罗加尔取回10块共鸣水晶以供研究。", objs={"共鸣水晶"}},
    [6441] = {n="萨特之角", d="为碎木哨岗的皮克希尔收集16只萨特的角。", tgo={{"萨维亚潜行者", "萨维亚叛徒", "萨维亚魔仆"}}},
    [6442] = {n="佐拉姆海岸的纳迦", d="将20颗怒尾纳迦的头颅交给佐拉姆海岸的玛鲁凯。", tgo={{"怒尾侍从", "怒尾纳迦", "怒尾御浪者"}}},
    [6461] = {n="盗窃的蜘蛛", d="玛拉卡金的辛吉拉要求你杀死10只深苔爬行者和7只深苔毒蜘蛛。", tgo={{"深苔爬行者"}, {"深苔毒蜘蛛"}}},
    [6462] = {n="巨魔符咒", d="将8个巨魔符咒交给佐拉姆加前哨站的米苏瓦。", objs={"巨魔的箱子"}},
    [6481] = {n="土灵的觉醒", d="使用魔化共鸣水晶打开共鸣桶，然后杀死高戈罗克。将这个消息告诉摩罗加尔，并把魔化共鸣水晶还给他。", tgo={{"高戈罗克"}}},
    [6482] = {n="鲁尔的自由", d="护送鲁尔，然后与慰藉之林的雅玛·雪蹄谈一谈。"},
    [6503] = {n="灰谷先驱者", d="杀掉9个灰谷先驱者，然后回到碎木哨岗的库莱比那里。", tgo={{"灰谷先驱者"}}},
    [6504] = {n="丢失的书页", d="找到丢失的12页伐木机操作指南，把它们合并为第1、2、3章。然后带着这些书页回到碎木岗哨去找古尔达·怒痕。"},
    [6521] = {n="邪恶的盟友", d="把玛克林大使的头颅交给幽暗城的瓦里玛萨斯。", tgo={{"玛克林大使"}}},
    [6522] = {n="邪恶的盟友", d="把小卷轴交给幽暗城的瓦里玛萨斯。"},
    [6541] = {n="向卡德拉克报到", d="到贫瘠之地北部的卡德拉克那里报到。"},
    [6543] = {n="战歌报告", d="打开报告集，把战歌报告交给战歌斥候、战歌信使和战歌侦查骑兵。把他们的最新报告交给贫瘠之地北部哨塔上的卡德拉克。"},
    [6544] = {n="托雷克的突袭", d="保护在银翼哨站与杜瑞尔·月火作战的托雷克，然后向慰籍之林的埃尔托格·怒齿汇报胜利的消息。"},
    [6545] = {n="战歌信使的报告"},
    [6546] = {n="战歌侍从的报告"},
    [6547] = {n="战歌斥候的报告"},
    [6561] = {n="黑暗深渊中的邪恶", d="把暮光领主克尔里斯的头颅交给雷霆崖的巴珊娜·符文图腾。", tgo={{"梦游者克尔里斯"}}},
    [6562] = {n="帮助耶努萨克雷", d="与灰谷的耶努萨克雷谈一谈。"},
    [6563] = {n="阿库麦尔水晶", d="收集20颗阿库麦尔蓝宝石，把它们交给灰谷的耶努萨克雷。", objs={"阿库麦尔蓝宝石"}},
    [6564] = {n="上古之神的仆从", d="把潮湿的便笺交给灰谷的耶努萨克雷。"},
    [6565] = {n="上古之神的仆从", d="杀掉黑暗深渊里的洛古斯·杰特，然后向灰谷的耶努萨克雷复命。", tgo={{"洛古斯·杰特"}}},
    [6621] = {n="污林熊怪之王", d="把卡拉恩的旗子插到污林图腾堆中。不要让熊怪摧毁这面旗子。击败穆戈特酋长，将穆戈特的图腾交给佐拉姆加的卡拉恩·阿玛卡。", tgo={{"穆戈特酋长"}}},
    [6626] = {n="邪恶之地", d="杀掉8个剃刀沼泽护卫者、8个剃刀沼泽织棘者和8个亡首教徒，然后向剃刀高地入口处的麦雷姆·月歌复命。", tgo={{"剃刀沼泽护卫者"}, {"剃刀沼泽织棘者"}, {"亡首教徒"}}},
    [6627] = {n="知识试炼", d="成功回答布劳格·幽魂的问题，然后和他再次对话。他会一直在石爪山等你回答问题。"},
    [6641] = {n="鞭笞者沃尔沙", d="在穆格拉什寻找火盆的过程中保证他的安全。帮助他扑灭火盆，然后在与纳迦作战时保护他。\n如果你成功了，就回到佐拉姆加前哨站去，把鞭笞者沃尔沙的死讯通知给战歌信使。"},
    [6681] = {n="拉文霍德庄园", d="把拉文霍德徽记交给拉文霍德庄园的法拉德，庄园就坐落在希尔斯布莱德的群山之中。\n你的智慧将在这次旅途中得到考验。做好准备吧。", tgo={{"拉文霍德"}}},
    [6701] = {n="辛迪加徽章", d="掉落自：辛迪加刺客、辛迪咒术师、辛迪加劫匪", tgo={{"辛迪加刺客", "辛迪咒术师", "辛迪加劫匪"}}},
    [6844] = {n="档案管理员阿姆伯尔", d="将异种蝎粘液包裹的物体交给月光林地永夜港的阿姆伯尔，他是塞纳里奥议会的档案管理员。"},
    [6845] = {n="发现过去的秘密", d="与月光林地永夜港的拉比恩·萨图纳谈一谈。"},
    [6921] = {n="废墟之间", d="把深渊之核交给灰谷佐拉姆加前哨站里的耶努萨克雷。", objs={"深渊之石"}},
    [6922] = {n="阿奎尼斯男爵", d="把奇怪的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。"},
    [6981] = {n="发光的碎片", d="寻找更多有关这块噩梦碎片的信息。", tgo={{"斯布特瓦夫"}}},
    [7003] = {n="被缩小的巨人", d="使用索尔宾的超级压缩器，把菲拉斯的任意巨人缩小到便于对付的体型。从缩小后的巨人身上收集15份微缩残渣，交给菲拉斯被遗忘的海岸码头上的索尔宾·范达瑟。", tgo={{"大地行者", "峭壁巨人", "海岸巨人"}}},
    [7028] = {n="扭曲的邪恶", d="为凄凉之地的维洛收集25个瑟莱德丝水晶雕像。", tgo={{"被诅咒的半人马", "腐烂萨特", "腐烂欺骗者"}}},
    [7029] = {n="维利塔恩的污染", d="在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。\n在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。\n治疗8株植物并杀死那些诺克赛恩幼体，然后向葬影村的瓦克·战痕复命。", tgo={{"诺克赛恩幼体"}, {}}, objs={"玛拉顿橙色水晶池"}},
    [7044] = {n="玛拉顿的传说", d="找回塞雷布拉斯节杖的两个部分：塞雷布拉斯魔棒和塞雷布拉斯钻石。\n然后设法和塞雷布拉斯对话。", tgo={{"维利塔恩"}, {"诺克赛恩", "诺克赛恩产物"}}},
    [7046] = {n="塞雷布拉斯节杖", d="帮助赎罪的塞雷布拉斯制作塞雷布拉斯节杖。\n当仪式完成之后再和他谈谈。", objs={"Incantation of Celebras"}},
    [7064] = {n="大地的污染", d="杀死瑟莱德丝公主，然后回到凄凉之地葬影村附近的瑟琳德拉那里复命。", tgo={{"瑟莱德丝公主"}}},
    [7066] = {n="生命之种", d="到月光林地去找到雷姆洛斯，将生命之种交给他。"},
    [7067] = {n="贱民的指引", d="阅读贱民的指引，然后从玛拉顿得到联合坠饰，将其交给凄凉之地南部的半人马贱民。"},
    [7068] = {n="暗影残片", d="从玛拉顿收集10块暗影残片，然后把它们交给奥格瑞玛的尤塞尔奈。", tgo={{"暗影碎片巡游者", "暗影碎片击碎者", "暗影碎片雷鸣者"}}},
    [7201] = {n="最后的元素", d="前往黑石深渊，找回10份元素精华。你首先想到的是搜查魔像和魔像制造者。你还记得薇薇安·拉格雷含糊地提到过元素生物。", tgo={{"熔岩作战傀儡", "狂怒傀儡", "战斗傀儡"}}},
    [7441] = {n="普希林和埃斯托尔迪", d="到厄运之槌去找到小鬼普希林。你可以使用任何手段从小鬼那里得到埃斯托尔迪的咒术之书。\n找到咒术之书后，回到拉瑞斯小亭的埃斯托尔迪那里。", tgo={{"普希林"}}},
    [7461] = {n="伊莫塔尔的疯狂", d="你必须干掉5座水晶塔周围的守卫，那5座水晶塔维持着关押伊莫塔尔的监狱。一旦水晶塔的能量被削弱，伊莫塔尔周围的能量力场就会消散。\n进入伊莫塔尔的监狱，干掉站在中间的那个恶魔。最后，在图书馆挑战托塞德林王子。\n当任务完成之后，到庭院中去找辛德拉古灵。", tgo={{"伊莫塔尔"}, {"托塞德林王子"}}},
    [7463] = {n="久违的法师", d="到厄运之槌的扭木广场去杀掉水元素海多斯博恩。把海多斯博恩精华交给图书馆的博学者莱德罗斯。", tgo={{"海多斯博恩"}}},
    [7481] = {n="精灵的传说", d="到厄运之槌去寻找泰尔米乌斯·探梦者。向莫沙彻营地的先知科鲁拉克报告你所找到的信息。", objs={"泰尔米乌斯·探梦者的骸骨"}},
    [7489] = {n="蕾瑟塔蒂丝的网", d="把蕾瑟塔蒂丝的网交给非拉斯莫沙彻营地的塔罗·刺蹄。", tgo={{"蕾瑟塔蒂丝"}}},
    [7492] = {n="莫沙彻营地", d="和菲拉斯莫沙彻营地的塔罗·刺蹄谈一谈。"},
    [7498] = {n="迦罗娜：潜行与诡计研究", d="将这本典籍交给它的主人。"},
    [7499] = {n="防御宝典", d="将这本典籍交给它的主人。"},
    [7500] = {n="奥法师的食谱", d="将这本典籍交给它的主人。"},
    [7501] = {n="圣光之力", d="将这本典籍交给它的主人。"},
    [7502] = {n="束缚之影", d="将这本典籍交给它的主人。"},
    [7503] = {n="最伟大的猎手", d="将这本典籍交给它的主人。"},
    [7504] = {n="光明不会告诉你的事情", d="将这本典籍交给它的主人。"},
    [7505] = {n="你与冰霜震击", d="将这本典籍交给它的主人。"},
    [7506] = {n="翡翠梦境……", d="将这本典籍交给它的主人。"},
    [7601] = {n="尼比的助手", d="与费伍德森林的伊普斯谈一谈。"},
    [7602] = {n="无暇的恶魔精华", d="费伍德的伊普斯要求你从三个不同的地区收集三块无暇的恶魔精华，然后把它们交给他。\n艾萨拉的雷加斯萨特、费伍德森林的加德纳尔军团士兵和诅咒之地的地狱卫士斥候分别拥有一种无暇的恶魔精华。", tgo={{"雷加斯萨特", "雷加斯潜行者", "雷加斯唤魔者"}, {"加德纳尔军团士兵"}, {"地狱卫士斥候"}}},
    [7603] = {n="克罗苏斯的恶魔之核", d="在费伍德森林的碎痕谷中搜寻克罗苏斯的尸体。当你找到尸体后，在他身上使用魔火，并等待克罗苏斯复生。当这个地狱火被唤醒之后，干掉他，从他的身上拿取克罗苏斯的恶魔之核。\n把克罗苏斯的恶魔之核交给费伍德森林的尼比。", tgo={{"克罗苏斯"}, {"克罗苏斯"}}},
    [7701] = {n="悬赏：工头玛托留斯", d="那个叫做工头玛托留斯的黑铁矮人叛徒就藏在大熔炉的熔渣之池深处。\n杀死工头玛托留斯，将他的头颅交给灼热峡谷的侦查队长洛洛尔以换取你的奖励。", tgo={{"工头玛托留斯"}}},
    [7721] = {n="压缩器的动力", d="从菲拉斯被遗忘的海岸那里的海元素和巨型海元素身上获取10块水元素核心，把它们交给码头附近的索尔宾·范达瑟。", tgo={{"海元素", "巨型海元素"}}},
    [7722] = {n="绝密配方！", d="在大熔炉的熔渣之池中的某个地方，你可以找到工头玛托留斯偷走的秘密设计图：炽热助熔剂。找到这些设计图，把它们还给灼热峡谷的大铁匠博恩奈特。", objs={"秘密设计图：炽热助熔剂"}},
    [7723] = {n="该死的手指头！", d="汉瑟尔·重拳让你杀掉20个重型作战傀儡。\n重型作战傀儡就在灼热峡谷的大熔炉附近。当你杀死足够多的傀儡后，就回去找汉瑟尔·重拳。", tgo={{"重型作战傀儡"}}},
    [7724] = {n="熔岩蜘蛛的威胁！", d="汉瑟尔·重拳要你在灼热峡谷杀死20只灼热熔岩蜘蛛。你可以在灼热峡谷的高地和熔岩池附近找到它们。\n杀死足够多的灼热熔岩蜘蛛后，回去向灼热峡谷的汉瑟尔·重拳复命。", tgo={{"灼热熔岩蜘蛛"}}},
    [7727] = {n="熏火龙", d="汉瑟尔·重拳让你去杀掉20个熏火龙。\n熏火龙侵占了熔渣之池中的那些岩浆池。熔渣之池就在灼热峡谷的大熔炉中。\n当你杀死足够数量的熏火龙后，就回去找汉瑟尔·重拳。", tgo={{"熏火龙"}}},
    [7728] = {n="被盗：鼓风机和望远镜", d="找到冶炼鼓风机和侦查员的望远镜，把它们还给灼热峡谷的监工斯克兰格。\n你所知道的关于这些物品的惟一信息是：它们肯定是被黑铁矮人偷走的。冶炼鼓风机是铁匠用的锻造工具，侦查员的望远镜是侦查员所需的侦查工具。", tgo={{"黑铁锻造师"}, {"黑铁哨兵"}}},
    [7729] = {n="工作机会：肃清竞争对手", d="杀死15个黑铁工头和15个黑铁奴隶贩子。完成任务之后就回去找监工斯克兰格。", tgo={{"黑铁工头"}, {"黑铁奴隶贩子"}}},
    [7730] = {n="祖卡什的入侵", d="把20块祖卡什虫壳交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。", tgo={{"祖卡什毒刺蝎", "祖卡什异种蝎", "祖卡什工蝎"}}},
    [7731] = {n="毒刺鞭笞者", d="击败痛苦深渊中的毒刺鞭笞者，把它的腺体交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。", tgo={{"毒刺鞭笞者"}}},
    [7732] = {n="祖卡什报告", d="把莫沙彻营地祖卡什报告交给奥格瑞玛暗巷区的基尔兹宾·鼓眼。"},
    [7734] = {n="更高的品质", d="把10块怒痕雪人的毛皮交给菲拉斯莫沙彻营地的杉多尔·迅蹄。", tgo={{"狂暴的怒痕雪人", "老年怒痕雪人", "残忍的怒痕雪人"}}},
    [7738] = {n="完美的雪人毛皮", d="把完美的雪人毛皮交给菲拉斯莫沙彻营地的杉多尔·迅蹄。"},
    [7761] = {n="黑手的命令", d="真是个愚蠢的兽人。看来你需要找到那枚烙印并获得达基萨斯徽记才可以使用命令宝珠。\n你从信中获知，达基萨斯将军守卫着烙印。也许你应该就此进行更深入的调查。"},
    [7815] = {n="钳嘴龟！", d="辛特兰恶齿村的钓鱼者卡图姆要你去杀掉15只海水钳嘴龟。完成任务之后回到他那里去复命。", tgo={{"海水钳嘴龟"}}},
    [7816] = {n="加莫里塔！", d="辛特兰恶齿村的钓鱼者卡图姆要你去杀掉加莫里塔，并从它的尸体上找到卡图姆的超级鱼饵。\n卡图姆说加莫里塔和其它海龟都在海岸附近活动。", tgo={{"加莫里塔"}}},
    [7828] = {n="银鬃捕猎者", d="辛特兰恶齿村的猎户马克霍尔要求你去杀掉15头银鬃捕猎者和15头银鬃嗥狼。完成任务之后就回到他那里复命。\n马克霍尔说过那些狼都躲在辛特兰的野外。", tgo={{"银鬃捕猎者"}, {"银鬃嗥狼"}}},
    [7829] = {n="野蛮的枭兽", d="辛特兰恶齿村的猎户马克霍尔要求你去杀掉20头野蛮的枭兽。完成任务之后就回到他那里复命。\n马克霍尔说过那些野蛮的枭兽都躲在辛特兰的野外。", tgo={{"野蛮的枭兽"}}},
    [7830] = {n="死者的复仇", d="辛特兰恶齿村的猎户马克霍尔要求你杀掉一头翱翔的锋喙狮鹫，并将它的狮鹫长羽拿回去交给他。\n马克霍尔说过那些翱翔的锋喙狮鹫就躲在辛特兰的野外。", tgo={{"翱翔的锋喙狮鹫"}}},
    [7839] = {n="邪枝窃贼", d="辛特兰恶齿村的铁匠斯拉提要你去找到斯拉提的工具。完成任务之后就回到他那里去。\n你记得铁匠斯拉提说过，你可以在辛特兰东北部的某个邪枝巨魔神庙中找到它，要不然就是在隐匿石那边。", objs={"斯拉提的工具"}},
    [7840] = {n="拉尔德的午餐", d="辛特兰恶齿村的拉尔德要求你去找到拉尔德的午餐。完成任务之后就回到他那里去。\n拉尔德说他把午餐留在了北面的岛上。当心邪枝巨魔。", tgo={{"邪枝绑架者"}}},
    [7845] = {n="被绑架的断齿长者！", d="辛特兰恶齿村的断齿族长要求你到辛萨罗去拯救她的爱人，断齿长者。\n你听说他被关在辛萨罗顶部，辛萨罗位于辛特兰的南部地区，那里是邪枝巨魔的主城。"},
    [7846] = {n="找回钥匙！", d="辛萨罗的断齿长者要求你杀掉守护者希坦亚，并用她身上的镣铐钥匙打开他的镣铐。当你找到钥匙之后就回到他那里去。", tgo={{"守护者希坦亚"}}},
    [7847] = {n="向断齿族长复命", d="辛萨罗的断齿长者要求你将他已经被营救的消息带给恶齿村的断齿族长。"},
    [7848] = {n="熔火之心的传送门", d="进入黑石深渊，在通往熔火之心的传送门附近找到一块熔火碎片，然后回到黑石山脉的洛索斯·天痕那里。", objs={"熔核碎片"}},
    [7849] = {n="分离的痛苦", d="辛特兰恶齿村的猎户马克霍尔要你去找回他的双胞胎兄弟的尸体。找到它，然后把猎户莫克霍尔的头颅和猎户莫克霍尔的骨头交给猎户马克霍尔。\n马克霍尔说过，他兄弟的尸体被软泥怪和邪枝巨魔的狼群分食。他还提到在辛萨罗有个大坑，里面全都是软泥怪，那里还有个狼穴。这两个地方都在靠近辛萨罗神庙顶部的区域。", objs={"颅骨堆", "白骨堆"}},
    [7850] = {n="黑暗之瓶", d="辛特兰恶齿村的断齿族长要你在辛萨罗找到10瓶腐化之血。任务完成之后就回到断齿族长那里。", objs={"腐化之血"}},
    [7861] = {n="通缉：邪恶祭司海克斯和她的爪牙", d="你必须杀掉邪恶祭司海克斯和20名邪枝精英守卫。任务完成之后回到辛特兰的恶齿村，向断齿族长报告。\n你可以在辛特兰的邪枝巨魔城市辛萨罗的顶部找到他们。", tgo={{"邪恶祭司海克斯"}, {"邪枝精英卫兵"}}},
    [7862] = {n="职位空缺：恶齿村卫兵队长", d="你必须消灭20个邪枝狂战士、20个邪枝暗影猎手、20个邪枝饮血者和20个邪枝噬魂者。\n完成任务之后向辛特兰恶齿村的断齿族长复命。", tgo={{"邪枝狂战士"}, {"邪枝暗影猎手"}, {"邪枝饮血者"}, {"邪枝噬魂者"}}, star={"卫兵队长符文", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}},
    [7877] = {n="辛德拉的宝藏", d="返回图书馆去找到辛德拉的宝藏。拿取你的奖励吧！"},
    [8151] = {n="猎人的护符", d="跟艾萨拉的奥汀克谈一谈。"},
    [8153] = {n="苔蹄快步者的鹿角", d="将一副完好的苔蹄快步者鹿角交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶。", tgo={{"苔蹄快步者"}}},
    [8231] = {n="碎浪多头怪", d="将6块碎浪多头怪的鳞片交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶部。", tgo={{"幼年碎浪多头怪", "碎浪多头怪", "大型碎浪多头怪"}}},
    [8232] = {n="神庙中的绿龙", d="将摩弗拉斯的牙齿交给艾萨拉的奥汀克。他住在埃达拉斯废墟东北部悬崖的顶端。", tgo={{"摩弗拉斯"}}, star={"魔暴龙眼", {"HUNTER"}}},
    [8233] = {n="简单的要求", d="前往拉文霍德庄园，和乔拉齐·拉文霍德公爵谈一谈。"},
    [8234] = {n="密封的蓝袋子", d="从艾萨拉的木喉萨满祭司那儿取回密封的蓝袋子，将它交给艾萨拉的大法师克希雷姆。", tgo={{"木喉萨满祭司", "黑喉萨满祭司"}}},
    [8235] = {n="密文碎片", d="将10块密文碎片交给艾萨拉的大法师克希雷姆。", tgo={{"森林软泥怪"}}},
    [8236] = {n="碧蓝钥匙", d="将碧蓝钥匙交给乔拉齐·拉文霍德公爵。", tgo={{"摩弗拉斯"}}, star={"暗色蝠斗篷", {"ROGUE"}}},
    [8250] = {n="法师的会见", d="找到萨纳斯，让他将你传送到大法师克希雷姆那儿。"},
    [8251] = {n="魔法的尘埃", d="为大法师克希雷姆收集10份闪光尘埃。", tgo={{"血精灵勘测员", "血精灵搜寻者", "血精灵防御者"}}},
    [8252] = {n="纳迦的珊瑚", d="收集6块魔化珊瑚，然后把它们交给大法师克希雷姆。", tgo={{"恶鞭海妖"}}},
    [8253] = {n="毁灭摩弗拉斯", d="从摩弗拉斯身上取回奥术碎片，然后返回大法师克希雷姆那儿。", tgo={{"摩弗拉斯"}}, star={"火焰宝石", {"MAGE"}}},
    [8254] = {n="塞纳里奥议会的求助", d="找到艾萨拉的奥汀克。"},
    [8255] = {n="苔蹄快步者", d="收集4份健康的野鹿腺体，把它们交给艾萨拉的奥汀克。奥汀克住在埃达拉斯废墟东北部悬崖的顶部。", tgo={{"苔蹄快步者"}}},
    [8256] = {n="亡灵的腐液", d="为艾萨拉的奥汀克带回一份亡灵腐液。奥汀克住在埃达拉斯废墟东北部悬崖的顶端。", tgo={{"赞吉尔僵尸", "赞吉尔猎人", "骷髅剥皮者"}}},
    [8257] = {n="摩弗拉斯之血", d="前往沉没的阿塔哈卡神庙，杀死绿龙摩弗拉斯，将他的血液交给费伍德森林中的格雷塔·苔蹄。沉没的神庙的入口就在悲伤沼泽中。", tgo={{"摩弗拉斯"}}, star={"祝福珠串", {"PRIEST"}}},
    [8276] = {n="夺回希利苏斯", d="与希利苏斯塞纳里奥要塞的唤风者梅恩·长角谈一谈。"},
    [8277] = {n="沙漠中的剧毒", d="希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你带8个石鞭蝎之刺和8个掠沙蜘蛛的牙齿给他。", tgo={{"石鞭蝎"}, {"掠沙蜘蛛"}}},
    [8278] = {n="诺格的最后一线希望", d="希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你给他带去3个石鞭巨钳蝎之刺、3个石鞭掠夺者之刺和3个石行蜘蛛的牙齿。", tgo={{"石鞭掠夺者"}, {"石鞭巨钳蝎"}, {"石行蜘蛛"}}},
    [8280] = {n="保护补给线", d="希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死15只掘泥打击者。", tgo={{"掘泥打击者"}}},
    [8281] = {n="确保安全", d="希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死20只掘泥摧毁者。", tgo={{"掘泥摧毁者"}}},
